import { AC, setLeadInstr, applyFx, scheduleBend, leadCancel, leadOn, leadSet, leadOff, leadAllOff, leadHold,
         metroClick, chordOn, chordGlide, chordOff, chordHold,
         bassOn, bassSet, bassOff, bassHold, drumHit, droneOn, droneOff,
         fxCaptureChain, fxCaptureWalk, fxPlaySet, fxPlayPath, fxParamKeysOf, fxRestoreAim,
         fxParamMetaOf, fxDefaultsOf, makeFrozenBus,
         fxIsPerNote, fxNoteField, fxNoteFollows, fxPerm } from './audio.js';   // fxNoteFollows — гладкая автоматизация: писать ли ведения рампы внутри зажатой ноты   // fxPerm — VOL-0: постоянная запись цепи (громкость) — ни в сводке захвата, ни на полосе, ни в цепи дорожки редактора   // V4b: параметр «в ноте» (полоса читает и правит его В НОТАХ) и где он лежит в событии   // F4: makeFrozenBus — шина замороженной дорожки (гейн прямо в мастер)
import { leadIdx, chIdx, bassIdx, drumKitIdx, seventh, tonic, aRef, scaleIdx, tunedFrom, setLatchDeg, setLatchTy, chainOwners, fxChainOf, chainKeyOf, FX_VOL } from './state.js';   // FX_VOL — VOL-3: полоса громкости у каждой дорожки   // F5: tonic/aRef/scaleIdx — в ПОДПИСЬ СВЕЖЕСТИ замороженной дорожки (рендер их приколачивал, значит их смена делает буфер устаревшим)
import { leadFreq, chordFreqs, chordNotes, chordUnit, bassFreq, CUR, typedChords, chordFams, droneNonOct } from './scales.js';   // typedChords/chordFams — S2: тип вставленного аккорда. chordNotes — U2: ноты аккорда (для распада при правке одной ноты). chordUnit — U4: каноническая форма ноты на ряду (однонотный тип = сам корень)
import { buildArrangement } from './arrange.js';
import { REC_VOL_EPS, REC_REV_EPS, REC_FX_EPS, BEND_EPS_CENTS, SCHED_TICK_MS, SCHED_AHEAD, BEATS_PER_BAR, volFromOld, AUT_RAMP_BEAT, AUT_RAMP_EPS, REC_FINE_EPS, REC_AVG_S, REC_JUMP_EPS, REC_HIST_S, REC_PAUSE_S, REC_KNEE_F } from './config.js';   // volFromOld — VOL-2b: громкость вставленной ноты в новой шкале
import * as AUD from './audio.js';   // F3: ИМЕНОВАННОЕ ПРОСТРАНСТВО того же модуля — только чтобы makeENG могла получить ЛЮБУЮ копию движка (живую или рендерную). Именованные импорты выше остаются, это тот же самый модуль
import { hooks } from './hooks.js';
import { activeKind } from './clip.js';   // S5.0: редактор не открывается поверх идущей записи клипа. Отказ живёт ЗДЕСЬ, рядом с прочими (см. editOpen), а не в ui. Цикла нет: clip тянет audio/state/vision/i18n и НИКОГДА recorder

/* ================= ЗАПИСЬ И ЛИНЕЙНЫЙ ТРАНСПОРТ =================
   ⛳ ЗДЕСЬ ПРОИЗОШЛА СМЕНА МОДЕЛИ (слайс S3.3). Раньше приложение было ЛУПЕРОМ: время события
   сворачивалось в петлю (`t = e % loopBeats`), а всё поведение висело на ЗАВОРОТЕ. Теперь это
   ЛИНЕЙНЫЙ МНОГОДОРОЖЕЧНЫЙ РЕКОРДЕР: время события — АБСОЛЮТНЫЕ ДОЛИ ОТ НАЧАЛА ПЕСНИ, песня
   играет от позиции до конца материала и ОСТАНАВЛИВАЕТСЯ. Заворота НЕТ ВООБЩЕ.
   ⚠️ ПЕТЛИ СЕЙЧАС НЕТ НИ В КАКОМ ВИДЕ, и это ожидаемое состояние после этого слайса, а не потеря:
   зацикливание вернётся СЛЕДУЮЩИМ слайсом — как ОБЛАСТЬ на таймлайне («от такта до такта»), то есть
   с обратной полярностью: раньше петлёй было всё, теперь ею будет выбранный кусок.
   Событие — НАМЕРЕНИЕ, не кадр: время в АБСОЛЮТНЫХ ДОЛЯХ (t ≥ 0 от начала песни),
   высота — СТУПЕНЬ+ОКТАВА (deg/oct); частота выводится на исполнении через
   leadFreq/chordFreqs → запись перестраивается под текущий строй (§3.7).
   Пишем по изменению (дискретное — при смене, непрерывное — за мёртвой зоной),
   так кадровый лог (~60/с) схлопывается в горстку точек на ноту.
   Схема события: {t, layer, fn, a} — ПОЛЕЙ НЕ ПРИБАВИЛОСЬ И НЕ УБАВИЛОСЬ, сменился только СМЫСЛ t.
   ⚠️ S3.5d ПРИБАВИЛ ОДНО: tk — номер ВЗЯТОГО (см. takeSeq). Его несёт КАЖДОЕ событие.
   layer — дорожка (единица отмены).

   ТРАНСПОРТ. Один насос по часам AudioContext везёт позицию вперёд: доля = (now−t0)·bpm/60, где
   t0 — время НАЧАЛА ПЕСНИ (доля 0). Живой ввод идёт через W* (звук сразу + запись, если вооружено),
   переигровка зовёт ENG НАПРЯМУЮ — поэтому переигранное не пишется заново без всякого гейта. Овердаб:
   песня играет и одновременно пишется новая дорожка; дорожка, что пишется прямо сейчас,
   НЕ переигрывается (её слышно живьём) — иначе двойной триггер.
   ЗАПИСЬ ОСТАНАВЛИВАЮТ ЯВНО: ● начинает, ● заканчивает. Прежнего авто-закрытия «первого круга» по
   счётчику тактов больше нет — в линейной записи закрывать нечего и не по чему.
   ВЛАДЕЛЬЦЫ ГОЛОСОВ ПО СЛОЮ: живой аккорд — 'latch', переигранный — 'loop:N';
   живой бас — 'bass' (ведущий режим) или 'bass:L[:f]' (полифонический), переигранный — 'bassloop:N'. Поэтому один и тот же инструмент
   слоится сам на себя (аккорд поверх аккорда, бас поверх баса) — разные владельцы,
   разные голоса из пула.
   ⚠️ СОЛО ТЕПЕРЬ ТОЖЕ ПОЛИФОНИЧНО И ТОЖЕ РАЗВЕДЕНО ПО ВЛАДЕЛЬЦАМ: живая рука — 'lead:L'/'lead:R'
   (ключ строит soloKey в gestures, он же расширяется пальцем), переигранный слой — 'leadloop:N:v'.
   ЗДЕСЬ РАНЬШЕ БЫЛО НАПИСАНО «соло остаётся моно (один envGain): соло-поверх-соло делит голос,
   побеждает последний — это не баг». БОЛЬШЕ НЕ ТАК, и это была ровно та надпись, что отправляла
   искать не там: живая игра и переигранный соло-слой больше НЕ дерутся, две руки звучат вместе.
   v в событии — НОМЕР ОДНОВРЕМЕННОЙ НОТЫ внутри слоя (0,1,…): без него две руки, пишущие разом,
   не различить на переигровке (leadOff не с чем спарить). Старые события без v читаются как v=0 —
   один голос на слой, то есть старая петля играет БИТ-В-БИТ как играла. */
let recording=false;                                 // «вооружено»: пишем живой ввод
const events=[];                                     // стабильная ссылка (её читает визуализация в draw)
/* ⚠️ `bars` СМЕНИЛ СМЫСЛ (S3.3): это больше НЕ длина петли (длины у песни нет — см. songBeats),
   а ДЛИНА ПОДЛОЖКИ в тактах: сколько тактов занимает добавляемая аранжировка/«только ударные».
   ⛔ `first` УДАЛЁН вместе с авто-закрытием первого круга. */
/* ⛳ ОБЛАСТЬ ПОВТОРА (слайс S3.4) — `rgn:{on,from,to}`, ОДНО поле на существующем состоянии транспорта,
   без новых сущностей и модулей. Полярность обратная прежней петле: ЛИНЕЙНОЕ воспроизведение —
   умолчание, а повтор — ПОМЕЧЕННЫЙ участок. rgn.on=false → всё ровно как оставил S3.3.
   ⚠️ ДВА РОДА ДОЛЕЙ, И ИХ НЕЛЬЗЯ ПУТАТЬ (это и есть устройство, которое было у петли):
     МОНОТОННАЯ доля m = (now−t0)·bpm/60 — время, прошедшее с запуска транспорта; растёт ВСЕГДА;
     ПЕСЕННАЯ доля p = songAt(m) — где мы в МАТЕРИАЛЕ; при включённой области сворачивается в неё.
   t0 НЕ ДВИГАЕТСЯ на завороте (в отличие от перемотки): планировщик уходит вперёд на SCHED_AHEAD и
   обязан уметь расписать события ЗА границей, а он делает это проекцией монотонной доли, для которой
   нужна неподвижная опора. Двинь t0 — и окно опережения поехало бы под ним. */
const loop={ on:false, bars:2, metre:BEATS_PER_BAR, sub:4, bpm:84, t0:0, pos:-1e-9, sched:0, layer:0, clickBeat:0, quant:true, rgn:{on:false,from:0,to:0,user:false}, lead:0, cnt:false };   // rgn.user — скобу ПОСТАВИЛ человек (иначе следует за материалом, S3.5b); lead — МОНОТОННАЯ доля, с которой транспорт реально играет (до неё — отсчёт/разгон: ни звука лида, ни записи); cnt — был ли при запуске отсчёт (для щелчков и надписи)   // metre — долей в такте; sub — ДРОБЛЕНИЕ доли для квантизации ударных (4 = 16-е, 3 = триоли); pos — сыгранная ПЕСЕННАЯ доля (лид/дрон, почти-сейчас); sched — МОНОТОННАЯ доля, до которой СЛОИ (аккорд/бас/удар) уже запланированы вперёд; t0 — время AC для монотонной доли 0
const droneActive=()=>events.some(e=>e.fn==='drone');   // жив ли слой-дрон (для гашения при снятии/стопе)
let recCh=null, pumpTimer=null;
/* ⛳ P2: СОСТОЯНИЕ ЗАПИСИ БАСА — ПО ВЛАДЕЛЬЦУ, зеркало recLead (ниже). Прежде это была ОДНА открытая бас-нота на взятое
   (recBass=null|{…}): бас был моно, и «владелец» у него был один — последний щипок. Теперь на каждого владельца своя
   запись {deg,oct,vol,inst,q,layer,v}; v — номер одновременной бас-ноты в слое (bassSlot), он же хвост ключа владельца
   на переигровке (bassOwnerKey). В ВЕДУЩЕМ режиме (у баса — по умолчанию) владелец один ('bass'): в карте не больше одной
   записи, v всегда 0 и в событие НЕ пишется — события байт-в-байт прежние. В ПОЛИФОНИЧЕСКОМ (V2/V3) владельцы — ключи рук и
   пальцев 'bass:L[:f]', и одновременные ноты получают свои v. */
const recBass=new Map();     // ключ владельца баса ('bass' — ведущий режим; 'bass:L[:f]' — полифонический) → состояние открытой бас-ноты
/* ⚠️ СОСТОЯНИЕ ЗАПИСИ СОЛО — ПО ВЛАДЕЛЬЦУ, а не одно на всех. Раньше это были ОДИНОЧНЫЕ recLead /
   recLeadBend / noteStartBeat / bendLastC («та самая единственная открытая нота»), и с моно-соло так и
   было. С полифонией две руки, пишущие ОДНОВРЕМЕННО, слились бы в один поток leadOn/leadSet: сравнение
   «изменилось ли» шло бы между нотами РАЗНЫХ рук, и в петлю легла бы каша. Теперь на каждого владельца
   своя запись {deg,oct,vol,rev,inst,bend,t0,lastC,v}. Глиссандо-в-луп (кривая бенда, центы поверх
   ступени) лежит ПО ССЫЛКЕ в событии leadOn и копится только у терменвокса (гейт live!=null). */
const recLead=new Map();     // ключ владельца ('lead:L'/'lead:R') → состояние открытой ноты
const vSlots=new Map();      // ключ владельца → номер одновременной ноты v в СЛОЕ (для пары leadOn/leadOff на переигровке)
/* ⛳ СОСТОЯНИЕ ВЗЯТОГО — ПО СЛОЮ (слайс T1 дуги «одна роль на дорожку»). Прежде это были ОДИНОЧНЫЕ величины
   (vBase, vTop, takeK, chLastT, bsLastT): взятое писало ровно в один слой, loop.layer. Следующий слайс (T2)
   даст одному взятому писать в НЕСКОЛЬКО дорожек, а у каждой свои лежащие номера и свои ключи владельцев —
   поэтому здесь каждая из них стала полем записи слоя. T1 менял только форму данных (слой был один, события
   байт-в-байт прежние); маршрут по роли — T2, ниже (takeRoute): с ним у взятого по слою на каждую роль.
   Поля записи — прежние величины, прежний смысл:
     vBase   — первый номер v, свободный от УЖЕ ЛЕЖАЩИХ в слое соло-нот (S3.5a, см. layerSlotTop); поднимается на
               каждом шве прохода (S3.5a-fix);
     vTop    — первый номер ВЫШЕ всех, что выданы за это взятое в этот слой: до него поднимается vBase на шве;
     k       — суффикс владельца аккорда/баса (S3.5c, см. chOwnerKey); 0 — без суффикса; +1 на каждом шве (S3.5e);
     chLastT — t последнего записанного события ЖИВОГО ключа аккорда (S4.3, страж в push);
     bsLast  — то же для баса, но ПО НОМЕРУ НОТЫ v (P2: Map v → t; прежде одно bsLastT). Ключ владельца бас-ноты —
               слой + k + v, и при нескольких владельцах у каждого своя очередь; при одном — ровно прежнее.
   ⚠️ КЛЮЧИ КАРТЫ И ЕСТЬ «СЛОИ ВЗЯТОГО»: отдельного множества не заводим — одно место, нечему расходиться.
   Карта не чистится на остановке — её читатели все стоят за `recording`; чистит её старт следующего взятого. */
const takeSt=new Map();      // слой → {vBase, vTop, k, chLastT, bsLast}
/* Вписать слой во взятое: номера и суффикс — ВЫШЕ всего, что в слое уже лежит (тот же обход, что и прежде на ●). */
function takeJoin(layer){
  const vb=layerSlotTop(layer);
  const S={ vBase:vb, vTop:vb, k:layerTakeTop(layer), chLastT:-Infinity, bsLast:new Map() };
  takeSt.set(layer,S); return S;
}
/* Запись слоя взятого. ⚠️ Страховка, а не путь: слой вписывают ТОЛЬКО onRec (на ●) и takeMint (на рождении посреди
   дубля), и отсутствовать он не может. */
const ts=layer=> takeSt.get(layer) || takeJoin(layer);
/* ═══ ⛳ МАРШРУТ ПО РОЛИ (слайс T2): В ДОРОЖКЕ РОВНО ОДНА РОЛЬ ═══
   Смена роли посреди дубля начинает НОВУЮ дорожку; другая роль в вооружённую дорожку — тоже новая; сплит
   пишет две роли разом — значит две дорожки рождаются вместе. Одно ● — одно ⤺: все они несут tk взятого.
   takeSrc (ниже): слой взятого → ключ его ИСТОЧНИКА (noteSource; сегодня — роль). Кто в ней:
     • ВООРУЖЁННАЯ дорожка — со своим источником (по её событиям, laneSourceOf) с самого ●;
     • дорожка, рождённая на ● (как и прежде: onRec, loop.layer), — НИЧЬЯ, пока в неё не ЛЯЖЕТ первое «вкл»:
       чей источник первым сыграл, того она и есть. Поэтому запись одним источником без смены — ровно прежняя
       (тот же номер, тот же id, та же строка на полосе с самого ●);
     • дорожки, рождённые ПОСРЕДИ дубля (takeMint) — со своим источником с рождения.
   ⛔ Ведения и «выкл» маршрут не проходят никогда: они идут в слой СВОЕЙ ноты. */
/* ⛳ КЛЮЧ МАРШРУТА — «ИЗ КАКОГО ИСТОЧНИКА ЗВУКА ЭТА НОТА». ОДНА функция, и всё остальное (claim, рождение,
   состояние взятого по слою) ключуется ТЕМ, ЧТО ОНА ВЕРНЁТ, а не «ролью», выписанной руками.
   Правило пользователя — не «роль на дорожку», а «КАЖДЫЙ ИСТОЧНИК ЗВУКА ПИШЕТСЯ В СВОЮ ДОРОЖКУ, со своей цепью и
   своей автоматикой». Сегодня источник — РОЛЬ. T3 допишет к ответу ТЕМБР («роль:тембр», у ударных — набор);
   затем — тембр, НАЗНАЧЕННЫЙ ПАЛЬЦУ (полусплита, даже пальцы одной руки с разными тембрами — разные дорожки).
   ⛔ Меняться при этом должна ТОЛЬКО эта функция: маршрут, claim и рождение сравнивают её ответы на равенство
   и больше ничего о них не знают (ключ непрозрачен, как ключ владельца цепи — см. state.chainKeyOf).
   Зовут её ровно на «вкл» ноты и на ударе — в push (takeRoute) и у соло до push (takePeek), с ТЕМИ ЖЕ fn и a,
   поэтому оба ответа совпадают. Ведения и «выкл» маршрут не проходят. null — не нота источника (дрон). */
/* ⛳ T3: ИСТОЧНИК = РОЛЬ + ТЕМБР (у ударных — набор). Тембр читается из «вкл» ноты (a.inst) и из удара (a.kit) —
   ровно тех событий, что маршрут и видит. Тембра нет (старое событие) — '-', то есть свой отдельный источник. */
const noteSource=(fn,a)=>{ const r=evRole(fn); if(!r) return null;
  const x = r==='dr' ? (a&&a.kit) : (a&&a.inst);
  return r+':'+(x==null?'-':x); };
/* Источник дорожки — по её первому «вкл»/удару. Дорожка одного источника по построению (с T2), поэтому первый и
   есть её; null — ни одной ноты (например, слой дрона). */
/* ⚠️ T3: ТОЛЬКО «вкл» и удары. Ведения тембра не несут (у аккорда и баса его в них нет вовсе), и ключ по ведению
   вышел бы «роль:-». Это ЕДИНСТВЕННАЯ правка вне noteSource, которой потребовал T3, и она — изъян формы T2:
   laneSourceOf спрашивал ключ у ЛЮБОГО события, а ключ осмыслен только у начала ноты. */
const isNoteStart=fn=> fn==='leadOn'||fn==='chOn'||fn==='bassOn'||fn==='drum';
function laneSourceOf(layer){ for(const e of events) if(e.layer===layer&&isNoteStart(e.fn)){ const k=noteSource(e.fn,e.a); if(k) return k; } return null; }
const takeSrc=new Map();     // слой взятого → ключ его источника (noteSource). Нет записи — дорожка ● ещё ничья
/* ⛳ СЛЕДУЮЩИЙ СВОБОДНЫЙ НОМЕР СЛОЯ — ОДИН НА ВСЕ МЕСТА РОЖДЕНИЯ ПОСРЕДИ ПЕСНИ (T2). `maxLayer()+1` видит
   только слои, в которых уже ЕСТЬ события, а дорожка взятого до первой ноты пуста: две дорожки, рождённые
   в одном взятом, и подложка, положенная посреди записи, получили бы тот же номер — и laneNew переписал бы
   id уже пишущейся дорожки (правило #27 держится рождением, но номер-то один). Поэтому поверх него — все
   слои ТЕКУЩЕГО взятого. ⚠️ Подложка до T2 уже так ломалась: джем, положенный посреди записи до первой её
   ноты, ложился в слой пишущейся дорожки. */
function nextFreeLayer(){
  let n = events.length ? maxLayer()+1 : 0;
  if(recording) for(const ly of takeSt.keys()) if(ly+1>n) n=ly+1;
  return n;
}
/* ⛳ МЕСТО РОЖДЕНИЯ ДОРОЖКИ ПОСРЕДИ ДУБЛЯ (T2) — ЧЕТВЁРТОЕ после onRec, loadArrangement и самопочинки
   `?? laneNew`. ⛔ Правило #27: id выдаёт ТОЛЬКО laneNew, и зовётся он здесь РОВНО на рождении — из push,
   когда «вкл» роли без дорожки уже ТОЧНО ЛОЖИТСЯ (после отказа отсчёта), и больше нигде. Отказанное «вкл»
   дорожку не рождает. */
function takeMint(src){
  const ly=nextFreeLayer();
  laneNew(ly); takeJoin(ly); takeSrc.set(ly,src);
  hooks.rec && hooks.rec(true);   // подсказка ● перечислит новую дорожку (hooks.rec лишь перерисовывает кнопку — правило #5)
  return ly;
}
/* Куда ляжет новая нота роли: дорожка этой роли во взятом → иначе ещё ничья дорожка ● → иначе null («родится
   новая»). ЧИСТОЕ чтение — для соло, которому номер v нужен ДО push (у новой дорожки он 0: там пусто). */
function takePeek(src){
  for(const [ly,k] of takeSrc) if(k===src) return ly;
  for(const ly of takeSt.keys()) if(!takeSrc.has(ly)) return ly;
  return null;
}
/* То же, но ДЕЙСТВИЕМ: занять ничью дорожку или родить новую. Зовёт ТОЛЬКО push — после того, как событие
   прошло отказ отсчёта. */
function takeRoute(src){
  for(const [ly,k] of takeSrc) if(k===src) return ly;
  for(const ly of takeSt.keys()) if(!takeSrc.has(ly)){ takeSrc.set(ly,src); return ly; }   // ⛳ claim ПИШЕТСЯ ПОД КЛЮЧОМ ИСТОЧНИКА: второй источник эту дорожку уже не займёт
  return takeMint(src);
}
let pushLy=null;   // слой, куда легло последнее событие push (вызывающие «вкл» узнают так, в какую дорожку ушла нота)
/* Слои взятого — для полосы и стражей (прежде все они читали одиночный loop.layer). */
const recLayers=()=>[...takeSt.keys()];
const isRecLayer=layer=> recording && takeSt.has(layer);
let recLastT=-Infinity;      // последняя ПЕСЕННАЯ доля, которую видел путь записи соло (S3.5a-fix): время пошло НАЗАД относительно неё → был шов прохода. ⚠️ ОДНА на взятое, не по слою: это время записи, а оно у всех слоёв общее
let recHiT=-Infinity;        // S4.3: наибольшее t, записанное с последнего шва (или с ●). На НАСТОЯЩЕМ шве оно ≤ rgn.to всегда; больше — значит был ПРЫЖОК из-за конца скобы (см. recFoldRoll). Одна на взятое — по той же причине
/* ⛳ НОМЕР ВЗЯТОГО — ev.tk (слайс S3.5d).
   ЗАЧЕМ ПОЛЕ В СОБЫТИИ. ⤺ обязан снимать ПОСЛЕДНЕЕ ВЗЯТОЕ, а не слой с наибольшим номером: взятое, влитое
   в старую дорожку, лежит в её слое рядом со старым материалом, и отличить его можно только по метке на
   самом событии. a.k (суффикс S3.5c) для этого НЕ годится: его несут лишь аккорд/бас и лишь влитые взятые.
   ⛳ ПРАВИЛО: tk несёт КАЖДОЕ событие. Мест рождения событий ровно два, и оба его ставят:
     push            — все события записи, tk = curTake (выдаётся на ● в onRec);
     loadArrangement — каждый СЛОЙ подложки/джема — своё взятое (свой tk): ⤺ снимает подложку послойно,
                       сначала ритм, как и прежде.
   Событие БЕЗ tk в этой сессии возникнуть не может (сохранения песен нет); если когда-нибудь появится —
   читается как tk=0, то есть САМОЕ СТАРОЕ: ⤺ снимет его последним.
   ⛳ И ТОТ ЖЕ tk ОТВЕЧАЕТ «звучит живьём?»: переигровка и догонялка пропускают `recording && ev.tk===curTake`
   — ровно события этого взятого (для взятого в новую дорожку это весь слой, то есть прежнее поведение).
   takeSeq МОНОТОНЕН на всю сессию (как laneSeq): номер взятого не выдаётся дважды, поэтому ⤺ после
   любых удалений и очисток не может спутать два взятых. */
let takeSeq=0, curTake=0;
/* ═══ ЗАХВАТ СЫГРАННОГО: СНИМОК ЦЕПЕЙ + ДОРОЖКА АВТОМАТИЗАЦИИ (слайс O-2) ═══
   ⛳ ЗАЧЕМ ЭТО ВООБЩЕ ЕСТЬ. ЗАМОРОЗКА — это РЕЖИМ ВОСПРОИЗВЕДЕНИЯ, а не преобразование: дорожку можно
   разморозить, поправить и заморозить снова, сколько угодно раз. Это работает только если ПОВТОРНЫЙ
   рендер даёт ТОТ ЖЕ звук, а значит всё, что рендер читает, обязано лежать В ЗАПИСИ, а не на живой
   ручке. Крутанул ручку и не записал — восстановить уже нечем.
   ⚠️ СЕГОДНЯ НЕ ПОМНИТ НИКТО: аккорды, бас и ударные не помнили никогда, а у соло пер-нотные величины
   снял слайс O-1 (эффекты стали свойством звучащего тембра). Этот реестр — замена сразу для всех
   владельцев и для ВСЕХ параметров, включая те, что пер-нотными быть не могли в принципе: длина и
   окраска комнаты, время и повторы делея, глубина и скорость тремоло.
   ⛳ КЛЮЧ — НОМЕР ВЗЯТОГО, и это не вкус. ⛔ Не дорожка: в одной дорожке лежит несколько взятых,
   записанных в разное время и с разными настройками. ⛔ Не номер слоя: номера ПЕРЕИСПОЛЬЗУЮТСЯ и имеют
   дыры (см. закон у laneNew). tk уже стоит на КАЖДОМ событии — по нему всё и сходится.
   ФОРМА ЗАПИСИ:
     { kinds:{ключ:вид}, chains:{ключ:[{fxId,params:[v01,…]},…]}, lane:[{t,key,fx,p,v},…] }
     chains — СОСТАВ И ЗНАЧЕНИЯ на старте взятого, В ПОРЯДКЕ ЦЕПИ (цепь последовательна — порядок слышен);
     lane   — ТОЛЬКО ИЗМЕНЕНИЯ после старта, t в АБСОЛЮТНЫХ ПЕСЕННЫХ долях (как у событий);
     kinds  — вид владельца ключа (см. chainOwners): чтобы цепи ТЕМБРА потом слились, а не мигрировали.
   ⛔ ЭТО НЕ СОБЫТИЯ. Реестр живёт РЯДОМ с events и не входит в него: он не касается ни курсоров
   переигровки, ни отсортированного префикса, ни единственной точки сброса (правило #28). Тронет —
   станет источником событий и унаследует все их законы разом. */
const takeFx=new Map();
/* ⛳ ВЕРСИЯ ЗАХВАТА — ЕДИНСТВЕННАЯ ИМЕНОВАННАЯ ТОЧКА ЕГО ПРОТУХАНИЯ (слайс O-4).
   ⚠️ ЗАЧЕМ ОНА ПОНАДОБИЛАСЬ. Подпись ленты переигровки (fxPlaySignature) считала ДЛИНЫ: число событий,
   число взятых, число точек. Пока захват только РОС, этого хватало. Редактор же двигает точку — время и
   величина меняются, а длины все до одной остаются прежними: лента не пересобралась бы, и правка не
   зазвучала бы, причём МОЛЧА. Поэтому всякая правка захвата поднимает счётчик, а подпись его читает.
   ⛔ ЭТО НЕ schedInvalidate И РЯДОМ С НИМ НЕ СТОИТ: захват — не события (правило #28), у него своя
   лента, свой курсор и вот эта своя точка сброса. Смешаешь — захват станет источником событий. */
let takeFxVer=0;
const takeFxTouch=()=>{ takeFxVer++; };
/* Последнее ЗАПИСАННОЕ значение по адресу «ключ|эффект|параметр» — опора прореживания. Живёт ровно
   столько, сколько идёт взятое: на старте засевается снимком, поэтому дорожка держит только ДЕЛЬТЫ. */
let takeFxLast=null;
/* ⛳ И ОТДЕЛЬНО — СОСТАВ ЦЕПИ (порядок id через запятую) НА ВЛАДЕЛЬЦА. Значения параметров его не
   выражают: сними эффект посреди взятого — его параметры просто ПЕРЕСТАНУТ приходить в обход, а это
   неотличимо от «не менялись». Добавь — придут новые, и это видно; убери или ПЕРЕСТАВЬ — не видно ничего.
   ⚠️ ПЕРЕСТАНОВКА СТАЛА СЛЫШНОЙ В O-1 (цепь последовательна), поэтому её пропуск — не мелочь: рендер
   собрал бы дорожку в другом порядке, чем её играли. Сравниваем строку состава на каждом ударе сердца. */
let takeFxOrder=null;
const FX_CHAIN='#chain';   // ⚠️ ЗАРЕЗЕРВИРОВАННЫЙ id записи состава. Решётка не может встретиться в настоящем fxId (те — идентификаторы), поэтому столкнуться не с чем
let curChordDeg=-1, curChordOct=0;                   // ступень И РЕГИСТР аккорда, что играет петля сейчас (для подсветки, §Q5). Регистр нужен с многопериодной сеткой: одна ступень живёт в нескольких прямоугольниках, без него подсветка всегда падала бы в нижний
/* ⛳ ДЛИНА ПЕСНИ — ВЫВОДИМАЯ, а не заданная: это позиция последнего события. Раньше длину задавал
   человек (loop.bars, 1..8), потому что от неё зависел заворот; заворота нет, и задавать нечего —
   песня ровно такая, сколько в неё записали.
   ⚠️ КЭШИРУЕМ: насос спрашивает её каждый тик, а обход всех событий на тике — ровно та цена, которую
   снял слайс S3.2. Значение поддерживается в ДВУХ местах и только в них: push двигает максимум вверх
   по одному событию, а schedInvalidate (единственная точка сброса курсоров — её и так зовёт КАЖДЫЙ
   путь, меняющий состав событий) пересчитывает целиком. */
let songLen=0;
const songBeats=()=>songLen;
function songLenRecalc(){ let m=0; const ly=new Set();
  for(const e of events){ if(e.t>m) m=e.t; ly.add(e.layer); }
  for(const l of ly){ const L=laneLen.get(laneId.get(l)); if(L>m) m=L; }   // слой подложки длится ВСЕ свои такты (laneLen), а не до последнего события
  songLen=m; }
/* ⛔ Помощника «длина подложки в долях» здесь НЕТ намеренно: loadArrangement передаёт в
   buildArrangement именно ТАКТЫ (loop.bars), доли считает уже он сам, и второй счёт того же завёл бы
   два источника одной величины. */

/* ═══ ОБЛАСТЬ ПОВТОРА: МОНОТОННАЯ ДОЛЯ → ПЕСЕННАЯ (слайс S3.4) ═══
   ⛳ ЭТО ВОСКРЕШЕНИЕ, А НЕ ИЗОБРЕТЕНИЕ. У петли ровно эту работу делал `% loopBeats`, просто область
   была прибита к [0, длина петли). Здесь та же свёртка, переанкеренная на [from, to).
   rgnReps(m) — сколько ПОЛНЫХ проходов области уже сделано к монотонной доле m. Ноль, пока не дошли до
   её конца (значит и ДО начала области, и ВНУТРИ первого прохода счёт нулевой — воспроизведение туда
   просто въезжает линейно, см. отчёт по пункту 2). */
const rgnLen=()=>loop.rgn.to-loop.rgn.from;
const cycling=()=>loop.rgn.on && rgnLen()>1e-9;
const rgnReps=m=>{ const R=loop.rgn, L=R.to-R.from; return m<R.to ? 0 : Math.floor((m-R.from)/L); };
/* Монотонная доля → доля ПЕСНИ. Без области — тождество (и это гарантия, что при rgn.on=false всё
   идёт ровно как в S3.3: ни одного лишнего вычисления в пути). */
const songAt=m=>{ if(!cycling()) return m; return m-rgnReps(m)*rgnLen(); };
/* ═══ СКОБА ПОВТОРА (слайс S3.5b) — ОДИН орган на ДВЕ работы, как loop brace в DAW ═══
   ГРАНИЦЫ скобы — ЧТО повторяется (когда ⟳ включён); НАЧАЛО скобы — ОТКУДА начинается запись.
   ⛔ Отдельной «линейки точки записи» нет и не заводить: это решение, а не упрощение.
   Кнопка ⟳ теперь ТОЛЬКО включает/выключает повтор скобы и границ НЕ переопределяет (прежде она на
   каждом включении помечала всю песню заново).
   ⛳ ДВА СОСТОЯНИЯ (rgn.user):
     false — СКОБА СЛЕДУЕТ ЗА МАТЕРИАЛОМ: [0, конец материала вверх до такта]. Так её видит нетронутая
             песня, и так она растёт при записи.
     true  — человек её ПОСТАВИЛ: стоит, где поставили; запись за её конец её НЕ двигает. Трогает её лишь
             одно — песня стала КОРОЧЕ её конца (отмена, снятие подложки): поджимаем к концу материала,
             чтобы скоба не указывала в пустоту. ✕ (clearRec) возвращает в «следует».
   ⛳ КВАНТ — ТАКТ, И ЭТО НЕ НЕДОДЕЛКА. На полосе в ~300px такт пятиминутной песни — пара пикселей: любая
     точность мельче такта была бы ЛОЖЬЮ о том, куда попал палец. ⛔ Не «улучшать» до долей без зума
     таймлайна. Побочная выгода — несущая: длина скобы кратна размеру, поэтому монотонная доля и песенная
     различаются на ЦЕЛОЕ число тактов — акценты метронома при повторе не съезжают, а перепривязка
     опоры (rgnApply) точна без округлений.
   ⛳ МИНИМУМ — ОДИН ТАКТ. Нулевая скоба не повторяет ничего (cycling() и так не считал её повтором) и
     на экране неотличима от отсутствия; повтор ОДНОГО такта — законная музыка (такт барабанов, остинато).
     Поэтому ноль запрещён клампом, такт разрешён. */
const braceCapBars=()=>Math.max(1,Math.ceil(songLen/loop.metre-1e-9));   // тактов материала (не меньше одного); −1e-9 — чтобы 8.0000000001 долей не дали лишний пустой такт
function braceClamp(from,to){                // ЕДИНЫЙ кламп границ: [0, конец материала], длина ≥ такт
  const M=loop.metre, cap=braceCapBars()*M;
  to=Math.min(to,cap); from=Math.max(0,Math.min(from,to-M)); to=Math.max(to,from+M);
  return [from,to];
}
/* ⛳ ЕДИНСТВЕННЫЙ ПИСАТЕЛЬ ГРАНИЦ И ВКЛЮЧЕНИЯ rgn (как laneNew у дорожек). Одно исключение — рост
   «следующей» скобы в push (braceFollowGrow), и оно безопасно ровно потому, что там повтор выключен.
   ⚠️ ГЛАВНАЯ РАБОТА — ПЕРЕПРИВЯЗКА ОПОРЫ, если транспорт идёт. Песенная доля — это songAt(m) по
   ГРАНИЦАМ; смени границы при неподвижной t0 — и песенная доля ПРЫГНЕТ. Именно так было до этого
   слайса: выключи ⟳ после нескольких проходов — m уже далеко за концом песни, songAt стал тождеством,
   и транспорт тут же вставал «в конце». Теперь: берём песенную долю p по СТАРОЙ карте, пишем границы и
   сдвигаем опору (t0, sched, lead, clickBeat) на целое число тактов так, чтобы по НОВОЙ карте сейчас было
   ровно p. Звук не рвётся, уже запланированное не дублируется, щелчки не съезжают.
   ⚠️ ИСКЛЮЧЕНИЕ — БЕГУНОК ОКАЗАЛСЯ ЗА КОНЦОМ ВКЛЮЧЁННОЙ СКОБЫ (край подвинули левее него): прыгаем на её
   НАЧАЛО — ровно то, что сделал бы шов. Это перемотка, и цена у неё та же, что у seekTo: голоса дорожек
   гасим, а удары/щелчки, уже поставленные в окно SCHED_AHEAD (~300мс), доиграют.
   Бегунок ПЕРЕД началом скобы остаётся где был и въезжает в неё линейно — решение S3.4 (rgnReps=0 до
   первого достижения конца), здесь не пересматривается. */
function rgnApply(from,to,on){
  const R=loop.rgn;
  if(from===R.from && to===R.to && on===R.on) return;
  const live=!!AC && loop.on;
  const m=live ? (AC.currentTime-loop.t0)*loop.bpm/60 : 0;
  const p=live ? songAt(m) : 0;                              // песенная доля по СТАРОЙ карте
  R.from=from; R.to=to; R.on=on;
  if(!live || m<loop.lead) return;                           // стоим или идёт отсчёт — опору заново поставит запуск/сама не сдвинется
  const spb=60/loop.bpm, d=m-p, past=cycling() && p>=R.to-1e-9;
  if(past || Math.abs(d-Math.round(d))>1e-6){                // вторая ветка — страховка: при потактовых границах d всегда целое
    const tgt=past ? R.from : p;
    releaseLoopLayersAt();
    loop.t0=AC.currentTime+0.06-tgt*spb; loop.lead=tgt; loop.cnt=false;
    loop.pos=tgt-1e-9; loop.sched=tgt; loop.clickBeat=Math.floor(tgt);
    if(tgt>1e-9){ const T=loop.t0+tgt*spb; chasePlay(tgt,T,false); chasePlay(tgt,T,true); }   // S3.5c: прыжок — тоже вход не с начала (см. chaseFor). chaseAt здесь может быть от старых границ — ключ кэша ДОЛЯ, не границы, поэтому он верен
    return;
  }
  const k=Math.round(d);
  if(k){ loop.t0+=k*spb; loop.sched-=k; loop.lead-=k; loop.clickBeat-=k; }   // монотонные величины — на k долей назад; loop.pos (ПЕСЕННАЯ) не трогаем: она и есть то, что сохраняем
}
/* Привести границы к материалу: «следующая» — пересчитать, «поставленная» — только поджать. Зовётся из
   schedInvalidate — единственной точки, через которую проходит КАЖДОЕ изменение состава событий
   (отмена, подложка, очистка, остановка записи), поэтому второго списка мест не заводим. */
function rgnSync(){
  const R=loop.rgn;
  const [from,to]= R.user ? braceClamp(R.from,R.to) : braceClamp(0, braceCapBars()*loop.metre);
  rgnApply(from,to,R.on);
}
/* Рост «следующей» скобы по одному событию — O(1), из push. ⚠️ ПРЯМАЯ запись мимо rgnApply, и она
   безопасна ТОЛЬКО при выключенном повторе: тогда границы не входят во временнýю карту вовсе. При
   включённом повторе расти и нечему — push сворачивает время внутрь скобы. Полный пересчёт — rgnSync. */
function braceFollowGrow(){
  const R=loop.rgn; if(R.user || cycling()) return;
  const to=braceCapBars()*loop.metre; if(to>R.to) R.to=to;
}
const regionOn=()=>loop.rgn.on;
/* ⟳ — ТОЛЬКО включить/выключить повтор скобы. Границы не трогает.
   ⚠️ СОРТИРОВКА ВО ВРЕМЯ ЗАПИСИ — несущая: schedInvalidate объявляет ВЕСЬ массив отсортированным
   префиксом (cursN=length), а дописанный хвост записи не отсортирован. Прежний setRegion звал
   schedInvalidate при записи БЕЗ сортировки — курсоры бинарным поиском шли по несортированному, и
   события других дорожек могли пропускаться. Сортировка на тапе стоит O(n log n) один раз. */
function setRegionOn(on){
  if(recording) events.sort((x,y)=>x.t-y.t);
  rgnSync();
  rgnApply(loop.rgn.from, loop.rgn.to, !!on);
  schedInvalidate();
}
/* ⛳ ТАП ПО ПОЛОСЕ СКОБЫ: доля → БЛИЖАЙШАЯ ЛИНИЯ ТАКТА; туда едет БЛИЖНИЙ к ней край. Равное расстояние
   (скоба в два такта, тап по средней линии) решает сторона тапа от середины скобы — иначе скобу в два
   такта нельзя было бы сузить до одного ни одним тапом. Возвращает, какой край взят ('from'/'to'), —
   ui держит его при перетаскивании, чтобы край не «перескакивал» на соседний.
   ⛔ ВО ВРЕМЯ ЗАПИСИ ПРАВКА ЗАПРЕЩЕНА (как и перемотка): сдвиг времени под открытыми нотами. */
function braceTap(beat){
  if(!AC||recording) return null;
  rgnSync();
  const R=loop.rgn, M=loop.metre, line=Math.max(0,Math.round(beat/M))*M;
  const d1=Math.abs(line-R.from), d2=Math.abs(line-R.to);
  const edge= d1<d2 ? 'from' : d2<d1 ? 'to' : (beat<(R.from+R.to)/2 ? 'from' : 'to');
  braceMove(edge,beat);
  return edge;
}
/* Поставить край edge на ближайшую к beat линию такта. Первое касание переводит скобу в «поставлена». */
function braceMove(edge,beat){
  if(!AC||recording) return;
  const R=loop.rgn, M=loop.metre, line=Math.max(0,Math.round(beat/M))*M;
  let from=R.from, to=R.to;
  if(edge==='from') from=Math.min(line,to-M); else to=Math.max(line,from+M);
  [from,to]=braceClamp(from,to);
  if(R.user && from===R.from && to===R.to) return;         // перетаскивание внутри того же такта: ничего не трогаем (и не перепривязываем каждый кадр)
  R.user=true;
  rgnApply(from,to,R.on); schedInvalidate();
}
/* ГРУППИРОВКА (акценты) по размеру — СТАТИЧНАЯ, по умолчанию. Массив длин групп, сумма = размер.
   Нечётные размеры чувствуются НЕ ровно: балканская 7 = 3+2+2, 9 = 2+2+2+3, 5 = 2+3; индийский
   тинтал (16) — 4 вибхага по 4. Пользовательский выбор 3+2+2 vs 2+2+3 отложен (BACKLOG §3.23) —
   один разумный вариант на размер. Дефолт нечислового/неизвестного — одна группа (акцент только сам).
   khali — индексы ГРУПП, что ОСЛАБЛЕНЫ (не акцент, а «пустая» голова, структурная черта тала). */
const METRE_GROUPS={ 2:[2],3:[3],4:[4],5:[2,3],6:[3,3],7:[3,2,2],8:[4,4],9:[2,2,2,3],10:[2,3,2,3],12:[3,3,3,3],16:[4,4,4,4] };
const METRE_KHALI ={ 16:[2] };   // тинтал: 3-й вибхаг (индекс 2 = доля 8) — khali (открытый баян, без баса)
/* Уровень акцента доли b∈[0,metre): 2 сам (начало такта), 1 голова группы, -1 khali-голова, 0 обычная. */
function beatLevel(metre,b){
  const g=METRE_GROUPS[metre]||[metre], kh=METRE_KHALI[metre]||[];
  let acc=0;
  for(let i=0;i<g.length;i++){ if(acc===b) return b===0?2:(kh.includes(i)?-1:1); acc+=g[i]; }
  return 0;   // не голова группы
}
const loopChordDeg=()=>loop.on?curChordDeg:-1;       // draw: подсветить аккорд петли, когда рука его не держит
const loopChordOct=()=>loop.on?curChordOct:0;        // его регистр — тем же путём (подсветка ищет прямоугольник по ПАРЕ deg+oct)
const maxLayer=()=>events.reduce((m,e)=>Math.max(m,e.layer),0);

/* ═══ ДОРОЖКИ: ЗАГЛУШЕНИЕ И СОЛО (слайс S1 «Редактора дорожек») ═══
   ⚠️ НАСТРОЙКА КЛЮЧУЕТСЯ НА СГЕНЕРИРОВАННОМ id ДОРОЖКИ, А НЕ НА НОМЕРЕ СЛОЯ. Номер для этого НЕ
   ГОДИТСЯ, и это не предосторожность на будущее, а три уже существующих факта:
     (1) номера ПЕРЕИСПОЛЬЗУЮТСЯ — овердаб берёт maxLayer()+1, поэтому после ⤺ отмены следующая
         запись получает ТОТ ЖЕ номер; ключуйся мы на номере, новая дорожка молча родилась бы
         заглушённой (и человек искал бы пропавший звук);
     (2) в номерах бывают ДЫРЫ — clearJam вырезает события ПО МЕТКЕ ev.jam, а не по слою, поэтому
         «слои 0 и 2 без 1» — нормальное состояние, а не сбой;
     (3) onUndo НЕ ПЕРЕНУМЕРОВЫВАЕТ — и не должен: номер слоя зашит в КЛЮЧИ ВЛАДЕЛЬЦЕВ ГОЛОСОВ
         ('loop:N' / 'bassloop:N' / 'leadloop:N:v'), перенумерация оторвала бы звучащие голоса от
         их владельцев.
   Отсюда разделение: НОМЕР СЛОЯ — адрес ЗВУКА (ключи владельцев, события), id ДОРОЖКИ — адрес
   НАСТРОЙКИ, связывает их одна таблица laneId.
   ⛔ Не сливать их и ⛔ не писать id в событие: формат события слайс S1 НЕ трогает вовсе. */
let laneSeq=0;
/* ⛳ ВООРУЖЁННАЯ ДОРОЖКА (слайс S3.5c) — id ДОРОЖКИ или null, а НЕ номер слоя. Номер переиспользуется
   (отмена освобождает его, следующая запись берёт тот же), и вооружение по номеру молча перешло бы на
   РОДИВШУЮСЯ на его месте чужую дорожку. id монотонен и не выдаётся дважды, поэтому устаревший id может
   только «никуда не указывать» — и все места, где id умирает (laneNew поверх, lanePrune, laneReset),
   снимают вооружение явно. null — ● создаёт новую дорожку, как всегда. */
let armLane=null;
/* Ожидание ПОДТВЕРЖДЕНИЯ удаления дорожки (S3.5d): {id дорожки, until — performance.now()} или null.
   Ключ — id дорожки, как у вооружения, и по той же причине: номер слоя переиспользуется. */
let delPend=null;
const laneId=new Map();      // номер слоя → СТАБИЛЬНЫЙ id дорожки
const laneMute=new Set();    // id заглушённых дорожек
const laneSolo=new Set();    // id дорожек в соло
/* ⛳ ДЛИНА МАТЕРИАЛА СЛОЯ ПОДЛОЖКИ (починка «подложка сама крутится», при слайсе «дрон и центы»): id дорожки → доля КОНЦА её материала
   (такты подложки × размер). Длина песни — позиция последнего СОБЫТИЯ (songLenRecalc), а у событий подложки нет выключений: дрон и
   бас-педаль лежат одним событием на доле 0, аккорд — одним «вкл» на такт. Без этой карты песня из одной подложки «Дрон» имела длину 0
   и вставала на первом же тике, а у прогрессии последний такт обрезался на его первой доле. Ключ — id (правило #27), не номер слоя:
   номер переиспользуется, и чужая длина не должна достаться новой дорожке. В событие ничего не пишется. */
const laneLen=new Map();
const laneLenOf=layer=>laneLen.get(laneId.get(layer))||0;   // доля конца материала слоя подложки (0 — не подложка); читает render.renderTrack
/* ⛳ ЗАКОН ЭТОГО БЛОКА, И НА НЁМ ДЕРЖИТСЯ ВСЯ КОРРЕКТНОСТЬ ДОРОЖЕК:
   **laneNew — ЕДИНСТВЕННЫЙ ПИСАТЕЛЬ laneId, и он ВСЕГДА выдаёт СВЕЖИЙ id, ЗАТИРАЯ прежнюю запись
   этого номера.** Значит правильность обеспечивает РОЖДЕНИЕ слоя, а не уборка за умершим.
   ⚠️ ПОЧЕМУ НЕ НАОБОРОТ (держать правильность на уборке) — так было, и это была мина: номера
   ПЕРЕИСПОЛЬЗУЮТСЯ (овердаб берёт maxLayer()+1), поэтому ОДНА пропущенная уборка означала бы, что
   свежезаписанный слой унаследовал id покойника вместе с его заглушением. Наружу это выглядит как
   «моя новая дорожка молчит, и непонятно почему» — тихо, правдоподобно и ищется долго.
   Теперь такого состояния не существует: что бы ни осталось в laneMute/laneSolo, НИ ОДИН номер на
   эти id больше не отображается, поэтому они НИКОГДА НИ С ЧЕМ НЕ СОВПАДУТ.
   ⛔ Не заводить второго писателя laneId. Появится новое место, где рождается слой, — оно обязано
   звать laneNew; список мест — в отчёте слайса и в комментариях у самих мест. */
function laneNew(layer){
  const old=laneId.get(layer);
  if(old!=null){ laneMute.delete(old); laneSolo.delete(old); laneLen.delete(old); if(armLane===old) armLane=null; }   // ГИГИЕНА, А НЕ КОРРЕКТНОСТЬ: без этой строки старый id просто мёртвым грузом лежал бы в множестве и ни на что не влиял — но множества росли бы всю сессию. Вооружение (S3.5c) — снимаем: его дорожки больше нет
  laneId.set(layer,++laneSeq);
  return laneSeq;
}
/* ЧТЕНИЕ id — ЧИСТОЕ: вернёт либо ДЕЙСТВУЮЩИЙ id номера (тот, что выдало последнее рождение), либо
   undefined. ⛔ ЗАВОДИТЬ id ЗДЕСЬ НЕЛЬЗЯ, и это не стиль: «страховка», заводящая id по требованию,
   была бы ВТОРЫМ писателем, а значит вторым источником правды о том, какое поколение номера сейчас
   живёт. Отсутствие записи читается как «обычная слышимая дорожка» — что и верно: id, которого
   никогда не выдавали, не может лежать ни в laneMute, ни в laneSolo. */
const laneOf=layer=>laneId.get(layer);
/* Уборка за слоями, у которых больше НЕТ СОБЫТИЙ (⤺ отмена слоя, снятие подложки).
   ⚠️ ЭТО ГИГИЕНА, А НЕ КОРРЕКТНОСТЬ (см. закон выше): пропусти мы её где-нибудь — таблица и
   множества просто подрастут мусором, но ни одна дорожка не перепутается, потому что номер получит
   свежий id при следующем рождении. Держим ради того, чтобы состояние не копилось за долгую сессию.
   Пишущийся слой ЩАДИМ — он законно пуст, пока в него не сыграли (его строку уже показывает полоса). */
/* ═══ ЗАХВАТ: ТРИ ОПЕРАЦИИ (O-2) ═══ */
/* СТАРТ ВЗЯТОГО — снимок состава и значений ВСЕХ цепей. Зовётся из ДВУХ мест рождения взятого: ● (onRec)
   и каждый слой подложки (loadArrangement). Подложку захватываем тоже: её рендер обязан быть таким же
   воспроизводимым, как и сыгранного вручную.
   ⚠️ Снимок ЗАСЕВАЕТ опору прореживания — поэтому дорожка ниже держит только то, что РЕАЛЬНО сдвинулось. */
function takeCapStart(tk){
  if(!AC||!tk) return;
  const rec={ kinds:{}, chains:{}, lane:[] };
  /* ⛔ ОПОРУ ПРОРЕЖИВАНИЯ ЗАСЕВАЕМ ТОЛЬКО СВОЕМУ ВЗЯТОМУ. Подложку можно положить ПОСРЕДИ записи — и её
     слои тоже рождают взятые. Сбрось мы опору здесь безоговорочно, идущая запись продолжила бы мерить
     дельты от ЧУЖОГО отсчёта: расхождение вышло бы крохотным (оба снимка сняты с одной живой цепи) и
     оттого неотличимым от правды — худший вид ошибки. Условие точное: на ● curTake уже равен tk, у
     подложки — никогда. */
  const mine = tk===curTake;
  if(mine){ takeFxLast=new Map(); takeFxOrder=new Map(); }
  for(const {key,kind} of chainOwners()){
    rec.kinds[key]=kind;
    rec.chains[key]=fxCaptureChain(key);
    if(mine){
      fxCaptureWalk(key,(fxId,pKey,v)=>{ takeFxLast.set(key+'|'+fxId+'|'+pKey, fineNew(v,-Infinity)); });   // засев: то же множество адресов, что пишет дорожка. Тонкая запись: опора — величина снимка, «записана» — до начала взятого (−∞), поэтому первый уход ляжет с точкой удержания: полка снимка держится до мига, где рука ушла
      takeFxOrder.set(key,chainOrderOf(key));                                            // засев состава: снимок выше и есть его исходное значение
    }
  }
  takeFx.set(tk,rec);
}
const chainOrderOf=key=>fxChainOf(key).map(e=>e.fxId).join(',');
/* ═══ ТОНКАЯ ЗАПИСЬ — ОДИН АВТОМАТ НА ШИНУ И НА ВЕЛИЧИНЫ «В НОТЕ» (слайсы «запись отражает плавность руки» и «медленное — тоже движение») ═══
   ⛳ ЗАПИСЬ ХРАНИТ ДВИЖЕНИЕ РУКИ, А НЕ АРТЕФАКТЫ ВЫБОРКИ И НЕ ДРОЖАНИЕ КАМЕРЫ. Дрожание и медленное движение различаются не РАЗМЕРОМ, а
   ХАРАКТЕРОМ: дрожание случайно и в среднем — ноль, движение идёт в одну сторону и копится. Поэтому:
     СРЕДНЕЕ — по каждой величине держим память выборок (H) и СРЕДНЕЕ за окно REC_AVG_S (2 с). Дрожание от усреднения сжимается в
       √N раз, движение — нет: неподвижная рука среднее не сдвигает, а рука, идущая хоть единицу за пять секунд, сдвигает непрерывно.
       Единицы пишутся по СРЕДНЕМУ (каждая, как только среднее ушло на REC_FINE_EPS от записанного). Числа и довод — config.
     ВРЕМЯ ЕДИНИЦЫ — середина окна (среднее время выборок): у ровного движения среднее за окно — это ТОЧНО положение руки в середине
       окна, поэтому единица ложится в миг, когда рука её прошла, а не когда среднее в этом убедилось. Не раньше, чем хоть одна
       выборка руки туда дошла.
     РЫВОК — выборка дальше REC_JUMP_EPS от среднего окна: окно начинается ЗАНОВО с неё. Быстрое движение так не сглаживается и не
       опаздывает (окно само сужается до ~0.06/скорость), а неподвижная рука до рывка не дотягивается (там 5–10σ дрожания).
     ПАУЗА — по ФОРМЕ, а не по порогу: перед записью единицы после промежутка дольше REC_PAUSE_S сравниваем две модели выборок с мига
       прошлой записи — «ровная линия от записанного» и «стояла, потом пошла» (излом). Излом лучше настолько, что дрожанием этого не
       объяснить (F > REC_KNEE_F), — в его миг кладём ТОЧКУ УДЕРЖАНИЯ с прежней величиной: пауза ровная, подъём — ровно там, где рука
       двинулась. Нет излома — это медленное движение, и единицы идут сплошной прямой (без площадок прежнего «покоя»).
   ⚠️ ЗАПИСЬ ЧУТЬ ГЛАЖЕ ЖИВОГО ЗВУКА: живьём величина несла дрожание под единицу, запись — только движение руки. Дрожание — камеры, не
   руки; записывать руку и есть принцип.
   x — число (шина) или нагрузка ноты (величины «в ноте»: громкость, яркость, ключи карты; высоту не трогаем — её смена пишется сама).
   Отдаёт к записи [{t,x}] ПО ВРЕМЕНИ; состояние обновлено так, будто всё записано (запись с явной долей не отказывает). Время пошло
   НАЗАД (шов скобы) — память с нуля: выборки прошлого прохода к новому не относятся. */
const FINE_NUM={ sig:()=>'v', vec:x=>[x], make:(x,a)=>a[0] };
const fxKeysOf=x=>x.fx?Object.keys(x.fx).sort():[];
const FINE_PN={                                                    // нагрузка ноты ↔ вектор усредняемых величин (громкость, яркость, ключи карты)
  sig:x=>['vol', ...(x.bri!=null?['bri']:[]), ...fxKeysOf(x)].join('|'),
  vec:x=>{ const a=[x.vol||0]; if(x.bri!=null) a.push(x.bri); for(const k of fxKeysOf(x)) a.push(x.fx[k]); return a; },
  make:(x,a)=>{ const y={...x, vol:a[0]}; let i=1; if(x.bri!=null) y.bri=a[i++];
    if(x.fx){ const f={}; for(const k of fxKeysOf(x)) f[k]=a[i++]; y.fx=f; } return y; },
};
const fineSec=b=>b*60/loop.bpm, fineBeats=s=>s*loop.bpm/60;
/* Состояние: lastA — вектор последней ЗАПИСАННОЙ величины (с ним сравнивает среднее), lastX — она же в виде, который пишется (число
   или нагрузка ноты): его ЧИТАЮТ вызывающие (r.vol/r.fx соло и баса, vol/bri аккорда — их же впишет шов recFoldRoll).
   ⚠️ ПОЧИНКА: при переходе на среднее состояние получило lastA, а lastX пропал — вызывающие читали fine.lastX.vol, падали каждым
   кадром удержанной ноты соло и баса (у аккорда — на кадре, где писалась единица), и кадр обрывался до отрисовки сетки. */
function fineNew(x,t){ const C=typeof x==='number'?FINE_NUM:FINE_PN; return { C, sig:C.sig(x), lastA:C.vec(x), lastX:x, lastT:t, H:[], ws:0 }; }
function fineReset(st,x,t){ st.sig=st.C.sig(x); st.lastA=st.C.vec(x); st.lastX=x; st.lastT=t; st.H=[]; st.ws=0; }   // записали сами (смена высоты, новый состав полей) — опора и память с нуля
function fineMean(H,from){ const n=H.length-from, d=H[from].a.length, m=new Array(d).fill(0); let tc=0;
  for(let i=from;i<H.length;i++){ const a=H[i].a; tc+=H[i].t; for(let j=0;j<d;j++) m[j]+=a[j]; }
  for(let j=0;j<d;j++) m[j]/=n; return { m, tc:tc/n }; }
function fineStep(st,x,t){
  const C=st.C, out=[];
  if(C.sig(x)!==st.sig){ fineReset(st,x,t); out.push({t,x}); return out; }   // другой состав полей (эффект на пальце появился/ушёл) — пишем сразу, как прежде
  if(st.H.length && t<st.H[st.H.length-1].t-1e-9){ st.H=[]; st.ws=0; st.lastT=-Infinity; }   // шов: величина прежняя (она и звучит), «когда записана» в этом проходе неизвестно
  const H=st.H, a=C.vec(x), Wb=fineBeats(REC_AVG_S);
  while(st.ws<H.length && H[st.ws].t<t-Wb) st.ws++;
  if(st.ws<H.length){ const {m}=fineMean(H,st.ws); let dj=0; for(let j=0;j<a.length;j++) dj=Math.max(dj,Math.abs(a[j]-m[j]));
    if(dj>REC_JUMP_EPS) st.ws=H.length; }                         // РЫВОК: окно — с этой выборки
  H.push({t,a});
  const old=fineBeats(REC_HIST_S); if(H[0].t<t-old*1.25){ let k=0; while(k<H.length && H[k].t<t-old) k++; k=Math.min(k,st.ws); H.splice(0,k); st.ws-=k; }   // память — REC_HIST_S, чистим пачкой
  const {m,tc}=fineMean(H,st.ws);
  let d=0, c=0; for(let j=0;j<m.length;j++){ const dd=Math.abs(m[j]-st.lastA[j]); if(dd>d){ d=dd; c=j; } }
  if(d<=REC_FINE_EPS) return out;
  const sg=Math.sign(m[c]-st.lastA[c]);
  let p=Math.max(tc, st.lastT+1e-6);
  for(const h of H){ if(h.t<=st.lastT) continue; if((h.a[c]-st.lastA[c])*sg>=REC_FINE_EPS){ if(p<h.t) p=h.t; break; } }   // не раньше, чем рука туда хоть раз дошла
  const k=fineKnee(st,c,sg,p);
  if(k!=null) out.push({t:k, x:C.make(x,st.lastA)});              // УДЕРЖАНИЕ: прежняя величина ТОЧНО, в миг, где рука пошла
  const w=C.make(x,m);
  out.push({t:p, x:w});
  st.lastA=m; st.lastX=w; st.lastT=p;
  return out;
}
/* ПАУЗА ПО ФОРМЕ — излом «стояла, потом пошла» против ровной линии от записанного, на сырых выборках с мига прошлой записи (y — уход
   от записанной величины по ведущей составляющей, x — время). Ровная линия: y = s·x. Излом в τ: y = 0 до τ, y = s'·(x−τ) после.
   Перебор τ по выборкам — суффиксные суммы, O(n). Излом принимается, если он объясняет данные лучше линии в F > REC_KNEE_F раз
   дисперсии остатка (с запасом: соседние выборки дрожания не независимы — сглаживание руки и повтор кадра на тиках шины), если пауза
   не короче REC_PAUSE_S и если после неё величина и правда пошла в ту же сторону. Нет прошлой записи в этом проходе (начало взятого,
   шов) — удержание кладётся всегда: в миг излома или на самой ранней выборке памяти (раньше нам ничего не известно). */
function fineKnee(st,c,sg,p){
  const H=st.H, first=st.lastT===-Infinity;
  const T0= first ? (H.length?H[0].t:p) : st.lastT;
  const S=[]; for(const h of H) if(h.t>T0+1e-9) S.push({x:h.t-T0, y:(h.a[c]-st.lastA[c])*sg});
  const pauseB=fineBeats(REC_PAUSE_S);
  let knee=null;
  if(S.length>=6 && p-T0>pauseB){
    let XX=0, XY=0, YY=0; for(const s of S){ XX+=s.x*s.x; XY+=s.x*s.y; YY+=s.y*s.y; }
    const sseA= XX>0 ? YY-(XY>0?XY*XY/XX:0) : YY;
    let n=0, Sx=0, Sxx=0, Sy=0, Syy=0, Sxy=0, best=Infinity, bt=null;
    for(let i=S.length-1;i>=0;i--){ const s=S[i]; n++; Sx+=s.x; Sxx+=s.x*s.x; Sy+=s.y; Syy+=s.y*s.y; Sxy+=s.x*s.y;
      if(n<2 || s.x<pauseB || T0+s.x>=p-1e-6) continue;   // после излома хоть две выборки: у решительного рывка излом — ПОСЛЕДНЯЯ ровная выборка перед ним, а не на два тика раньше
      const tau=s.x, num=Sxy-tau*Sy, den=Sxx-2*tau*Sx+tau*tau*n;
      const sse=(YY-Syy) + Syy - (num>0&&den>0 ? num*num/den : 0);
      if(sse<best){ best=sse; bt=tau; } }
    if(bt!=null && S.length>2){ const s2=best/(S.length-2);
      if(sseA-best > REC_KNEE_F*Math.max(s2,1e-12)) knee=T0+bt; }   // пол у дисперсии: ровно постоянная пауза (рука ушла из кадра, величина стояла) даёт остаток 0 — излом тогда идеален, а не «неопределён»
  }
  if(knee==null && first && T0<p-1e-6) knee=T0;
  return knee;
}
const pnSnap=p=> !p ? p : p.fx ? {...p, fx:{...p.fx}} : {...p};   // в память и в опору — КОПИЯ (как fxCopy у r.fx): живой снимок руки не должен стать псевдонимом записанного
/* УДАР СЕРДЦА — обход живых величин и запись ИЗМЕНИВШИХСЯ. Зовётся из tick, ПОСЛЕ отсчёта и в ПЕСЕННОЙ
   доле (оба свойства даёт место вызова, см. tick).
   ⛳ ПОЧЕМУ ИЗ СЕРДЦА, А НЕ ИЗ ЖЕСТ-ЦИКЛА — в этом весь смысл формы. Сердце бьёт независимо от того,
   есть ли рука в кадре, зажат ли щипок и звучит ли нота. Пер-событийная карта (как у соло до O-1) могла
   записать величину ТОЛЬКО вместе с нотой, и потому «покрутил ручку, пока звучит ЗАЩЁЛКНУТЫЙ аккорд с
   разомкнутыми пальцами» не записывалось НИКАК: для этого аккорда в тот миг не выполнялось ни одной
   строки. Здесь этот случай ничем не особен.
   ⚠️ ПРОРЕЖИВАНИЕ — ТОЙ ЖЕ МЁРТВОЙ ЗОНОЙ, что у прочих величин записи (REC_FX_EPS, довод — в config):
   величины НОРМИРОВАНЫ, поэтому один порог перцептивно ровен для секунд, герц и подмеса разом.
   ⛔ БУХГАЛТЕРИЯ И НИЧЕГО БОЛЬШЕ (правило #15): ни одного голосового вызова, ни одной постановки в
   расписание. Окно опережения этот обход не трогает. */
function takeCapSample(p){
  if(!recording||!curTake) return;
  const rec=takeFx.get(curTake); if(!rec||!takeFxLast||!takeFxOrder) return;   // обе опоры ставятся и снимаются вместе (takeCapStart/takeReset) — проверяем обе, чтобы связь была видна, а не подразумевалась
  for(const {key} of chainOwners()){
    /* СОСТАВ — ПЕРВЫМ: добавили, убрали или переставили эффект посреди взятого. Запись состава несёт
       список id (поле ids) и стоит В ТОЙ ЖЕ дорожке, на своей доле, — поэтому рендер узнает не только
       ЧТО менялось, но и КОГДА. Величина v здесь не значит ничего и стоит нулём ради единой формы. */
    const ord=chainOrderOf(key);
    if(takeFxOrder.get(key)!==ord){
      takeFxOrder.set(key,ord);
      rec.lane.push({t:p, key, fx:FX_CHAIN, p:'order', v:0, ids:ord?ord.split(','):[]});
    }
    fxCaptureWalk(key,(fxId,pKey,v)=>{
      const a=key+'|'+fxId+'|'+pKey, st=takeFxLast.get(a);
      if(!st){ takeFxLast.set(a, fineNew(v,p)); rec.lane.push({t:p, key, fx:fxId, p:pKey, v}); return; }   // адрес, которого не было в снимке (эффект добавлен посреди взятого), — первая величина сразу, как прежде
      /* ТОНКАЯ ЗАПИСЬ (см. fineStep): в покое — ничего; уход — дописан с мига, где рука ушла (с точкой удержания); в движении — каждая
         единица. ⚠️ Дописанные точки лежат РАНЬШЕ уже лежащих в ленте точек ДРУГИХ адресов — лента взятого больше не упорядочена по
         времени добавления. Её читают только через сортировку (fxLaneMerge, autPointsCalc) и счёт (captureInfoOf), так что это безвредно. */
      for(const s of fineStep(st,v,p)) rec.lane.push({t:s.t, key, fx:fxId, p:pKey, v:s.x});
    });
  }
}
/* ═══ ПЕРЕИГРОВКА АВТОМАТИЗАЦИИ (слайс O-3) ═══
   ⛳ ЗАКОН, РАДИ КОТОРОГО ВСЯ ДУГА: ДОРОЖКА ЗВУЧИТ ТЕМ, С ЧЕМ ЕЁ СЫГРАЛИ. Крутить ручку после записи
   можно сколько угодно — на уже записанное это не влияет. У каждой величины ровно ОДИН хозяин: РУКА,
   пока транспорт стоит, и ЗАПИСЬ, пока он играет. Третьего («тронул — перехватил») нет намеренно:
   правка записанной автоматизации — дело РЕДАКТОРА (полоса под нотами), а не случайного касания.
   ⛳ ФОРМА — ТА ЖЕ, ЧТО У ДОГОНЯЛКИ (chaseFor/chasePlay), и это не совпадение, а переиспользование:
   «сверни отсортированный префикс ДО доли x в состояние, затем примени его». Догонялка так поднимает
   зажатые ноты при входе в песню не с начала; здесь тем же движением поднимаются величины эффектов.
   Второй механики входа не заводим.
   ⛔ НЕ ВО ВРЕМЯ ЗАПИСИ. Гони мы дорожку в параметры при работающем ●, захват тут же снял бы эти самые
   величины как «сыгранные рукой» — автоматизация писала бы сама себя по кругу. Пока идёт запись, хозяин
   один: рука.
   ⚠️ ЭТО БУХГАЛТЕРИЯ И ЗВУК ПАРАМЕТРОВ, НО НЕ СОБЫТИЯ (правило #28): своя сортировка, свой курсор, ни
   одного касания cursN/curSched/curNear/schedInvalidate. И не расписание (правило #15): ни одного
   голосового вызова, ни одной постановки в окно опережения. */
/* ПЛОСКАЯ ЛЕНТА ВСЕХ ВЗЯТЫХ, отсортированная по (доля, номер взятого). Снимок старта взятого входит в
   неё как точки на доле ПЕРВОГО СОБЫТИЯ этого взятого — только там он и вступает в силу.
   ⛳ ПОЧЕМУ ОДНА ЛЕНТА НА ВСЕХ, А НЕ «ГЛАВНОЕ ВЗЯТОЕ НА ВЛАДЕЛЬЦА»: у владельца ОДНА цепь и ОДНА сеть,
   а взятых на него может быть много (правило «цепь принадлежит владельцу, а не дорожке»). Две басовые
   дорожки с разным ревербом ОДНОВРЕМЕННО не звучат — это предел, который снимет только ЗАМОРОЗКА, когда
   у дорожки появятся свои экземпляры. До неё выбран самый нестранный из возможных законов: ПОБЕЖДАЕТ
   ПОСЛЕДНЯЯ ПО ВРЕМЕНИ ЗАПИСАННАЯ ТОЧКА — то есть та автоматизация, которая в этом месте песни была
   написана позже всех. Ничья по доле разрешается номером взятого: новее — сильнее.
   ⚠️ ОТБОР ПО ВЛАДЕЛЬЦУ: взятое правит цепью ТОЛЬКО тех ролей, которые в нём реально играли (evRole по
   его событиям). Иначе барабанное взятое, чей снимок тоже содержит цепь баса, перебивало бы басовую
   автоматизацию соседней дорожки — чужим значением, снятым мимоходом. */
let fxPlayList=null, fxPlayI=0, fxPlayAt=-1, fxPlaySig='';
const fxPlayVals=new Map(), fxPlayOrd=new Map();     // свёрнутое состояние: адрес → последняя победившая точка; ключ владельца → состав
/* ПОДПИСЬ ЛЕНТЫ: по ней решаем, не устарела ли она. Входит всё, что меняет ЛЕНТУ или ПОБЕДИТЕЛЯ в ней:
   состав событий (от них доли старта и роли взятых), состав захвата, длина дорожек и ЗАГЛУШЕНИЕ
   (заглушённая дорожка своей автоматикой не правит, значит смена mute/solo меняет исход свёртки).
   ⚠️ Множества mute/solo крошечные — склейка на тике дешевле отдельной точки инвалидации, а главное
   не требует помнить о ней в четырёх местах, где эти множества правятся. */
const fxPlaySignature=()=>{ let n=0; for(const r of takeFx.values()) n+=r.lane.length;
  return events.length+'|'+takeFx.size+'|'+n+'|'+takeFxVer+'|'+[...laneMute].join(',')+'/'+[...laneSolo].join(','); };   // takeFxVer — правки редактора: длины при них не меняются (см. его шапку)
/* ⛳ СЛИЯНИЕ ЛЕНТЫ — ЧИСТАЯ ФУНКЦИЯ (выделена в F3). Ничего не мутирует и ни на что не подписана:
   строит и ОТДАЁТ отсортированный список точек. ⛔ ВТОРОГО СЛИЯНИЯ БЫТЬ НЕ ДОЛЖНО — здесь и только
   здесь живёт закон «побеждает последняя по времени точка, при равенстве старшее взятое, и взятое
   правит ТОЛЬКО ролями, которые в нём играли». Разойдись рендер с этим законом — замороженная
   дорожка зазвучала бы иначе, чем её играет транспорт, а это единственное, чего не простят.
   Потребителей двое: живая переигровка (fxPlayBuild ниже) и офлайн-рендер (F3). */
function fxLaneMerge(){
  const list=[];
  /* Метаданные взятого выводим ОДНИМ проходом по событиям: доля первого события (когда снимок вступает
     в силу), слой (для слышимости) и ключи владельцев, которыми это взятое вправе править. */
  const meta=new Map(), lt=new Map();                              // lt (S1): слой → (взятое → его первая доля В ЭТОМ слое)
  for(const e of events){ const tk=e.tk||0; let m=meta.get(tk);
    if(!m) meta.set(tk, m={t0:e.t, layer:e.layer, keys:new Set()});
    if(e.t<m.t0) m.t0=e.t;
    const r=evRole(e.fn); if(r) m.keys.add(chainKeyOf(r));
    let tm=lt.get(e.layer); if(!tm) lt.set(e.layer, tm=new Map());
    const q=tm.get(tk); if(q==null||e.t<q) tm.set(tk,e.t);
  }
  /* СНИМОК ВЗЯТОГО В ЛЕНТУ: состав и величины на доле t. Одна функция на оба случая ниже (свой снимок взятого и заимствованный, S1). */
  const snapPush=(t,tk,layer,key,ch)=>{
    list.push({t, tk, layer, key, fx:FX_CHAIN, ids:ch.map(e=>e.fxId)});   // СОСТАВ на старте взятого
    for(const eff of ch){
      const names=fxParamKeysOf(eff.fxId);                      // снимок хранит величины массивом — имена берём у реестра эффектов
      eff.params.forEach((v,i)=>{ if(v!=null && names[i]!=null && !fxIsPerNote(eff.fxId,names[i]))   // V4b: параметр «в ноте» ведёт НОТА, не лента (см. ниже)
        list.push({t, tk, layer, key, fx:eff.fxId, p:names[i], v, snap:true}); });   // snap — точка СНИМКА, а не ленты: от неё плавный отрезок не начинается (см. fxLaneAt)
    }
  };
  for(const [tk,rec] of takeFx){
    const m=meta.get(tk); if(!m||!m.keys.size) continue;          // взятое без событий (пишется прямо сейчас) или без ролей с цепью — пропускаем
    for(const key of m.keys){
      const ch=rec.chains[key]; if(!ch) continue;
      snapPush(m.t0, tk, m.layer, key, ch);
    }
    /* ⛳ V4b: ТОЧКИ ПАРАМЕТРОВ «В НОТЕ» В ЛЕНТУ НЕ ИДУТ — НИ ПЕРЕИГРОВКЕ, НИ РЕНДЕРУ. Их величину записанная нота несёт САМА
       (карта a.fx или своё поле — fxIsPerNote), и её же читают переигровка и заморозка. Лента здесь была бы ВТОРЫМ источником:
       гнала бы живой экземпляр по снятым точкам, а те после правки в редакторе расходятся с нотами — рука, играющая поверх
       ▶, получала бы величину, которой ни одна записанная нота уже не несёт, и столбик помечался бы «ведёт запись», хотя запись
       ведёт свои ноты, а не экземпляр. Теперь у величины «в ноте» хозяева разведены чисто: у ЗАПИСАННОЙ ноты — её событие, у
       ЖИВОЙ — рука, и так всё время, а не «рука до ▶, запись после». ⛔ ЗАХВАТ ПРИ ЭТОМ НЕ МЕНЯЛСЯ: точки по-прежнему пишутся
       (правило #29 — объявлено, значит захвачено), их просто не читает никто из звука. Здесь — ЕДИНСТВЕННОЕ слияние, поэтому
       живое и рендер расходиться не могут. */
    for(const ent of rec.lane){
      if(!m.keys.has(ent.key)) continue;
      if(ent.fx!==FX_CHAIN && fxIsPerNote(ent.fx,ent.p)) continue;   // V4b: см. выше
      list.push({t:ent.t, tk, layer:m.layer, key:ent.key, fx:ent.fx, p:ent.p, v:ent.v, ids:ent.ids, sh:ent.sh});   // sh — ФОРМА отрезка, ВХОДЯЩЕГО в точку ('s' — плавно; нет — ступенькой, как всё записанное)
    }
  }
  /* ⛳ S1: ВЗЯТОЕ БЕЗ ЗАХВАТА ВНУТРИ ЗАХВАЧЕННОЙ ДОРОЖКИ ИГРАЕТ ЦЕПЬЮ ДОРОЖКИ. Такое взятое сегодня одно — ВСТАВКА В РЕДАКТОРЕ
     (editTake: editInsertHit/editInsertBass захвата не заводят), и своего захвата оно больше НЕ получает никогда, пока он есть у
     дорожки (autCaps, freezePinCaptures). Позже первого захваченного взятого дорожки ему ничего и не нужно: его ноты звучат под
     тем составом, что правит в их долю, — то есть цепью дорожки. Нужно ОДНО: вставка РАНЬШЕ всех захваченных взятых дорожки —
     туда цепь дорожки ещё не вступила, и ноты шли бы живой цепью (переигровка) или пустой (рендер). Поэтому такое взятое
     ЗАИМСТВУЕТ снимок САМОГО РАННЕГО захваченного взятого своей дорожки и кладёт его со СВОЕЙ первой доли: цепь дорожки
     начинается с её первой ноты. ⛔ Позже — не заимствует: снимок посреди чужого взятого сбросил бы его автоматику на стартовые
     величины. ⚠️ Как и любой снимок, он правит РОЛЬЮ с этой доли (одна сеть на владельца — Known limits №1–2), ровно как
     старт любого взятого. Записанное и подложки захват имеют всегда — сюда они не попадают, их лента прежняя дословно. */
  for(const [tk,m] of meta){
    if(takeFx.has(tk)||!m.keys.size) continue;
    for(const [ly,tm] of lt){
      const t0=tm.get(tk); if(t0==null) continue;
      let C=null;
      for(const [tk2,t2] of tm){ if(tk2===tk||!takeFx.has(tk2)) continue;
        if(!C||t2<C.t0||(t2===C.t0&&tk2<C.tk)) C={tk:tk2, t0:t2}; }
      if(!C||!(t0<C.t0-1e-9)) continue;
      const rec=takeFx.get(C.tk), mc=meta.get(C.tk);
      for(const key of m.keys){ if(!mc||!mc.keys.has(key)) continue;
        const ch=rec.chains[key]; if(ch) snapPush(t0, tk, ly, key, ch); }
    }
  }
  list.sort((a,b)=> a.t-b.t || a.tk-b.tk);
  /* ⛳ СОСЕД СПРАВА ТОГО ЖЕ АДРЕСА (nx) — по уже отсортированному списку, то есть по ТОМУ ЖЕ закону победителя: следующая
     точка адреса в ленте — это ровно та, что сменит величину следующей. Плавный отрезок едет к ней. Объекты списка —
     свежие, построенные здесь же, поэтому функция остаётся чистой. */
  const lastOf=new Map();
  for(const e of list){ if(e.fx===FX_CHAIN) continue; const a=e.key+'|'+e.fx+'|'+e.p, L=lastOf.get(a); if(L) L.nx=e; lastOf.set(a,e); }
  return list;
}
/* ═══ ГЛАДКАЯ АВТОМАТИЗАЦИЯ ШИННЫХ ПАРАМЕТРОВ — ОДИН ЗАКОН ИНТЕРПОЛЯЦИИ ═══
   ⛳ ФОРМА ЖИВЁТ НА ТОЧКЕ И ОПИСЫВАЕТ ОТРЕЗОК, КОТОРЫЙ В НЕЁ ВХОДИТ (поле sh точки ленты). ТРИ значения:
     's' — ПЛАВНО (поставил человек), по прямой в НОРМИРОВАННОЙ шкале 0..1 — той самой, в которой полоса рисует (у лог-параметров
           это ровный ход на слух, как и у ручки);
     'h' — СТУПЕНЬКОЙ (поставил человек: точка после полки, кнопка ⌐, правленая точка, застывшая в ступеньке);
     нет поля — ЗАПИСАННАЯ точка: отрезок в неё ПЛАВНЫЙ (autSmoothOf ниже). Пауза записанного — не форма отрезка, а ДАННЫЕ: тонкая
           запись (fineStep) находит её по излому и кладёт ТОЧКУ УДЕРЖАНИЯ с прежней величиной в миг, где рука пошла, — поэтому ровная
           пауза и подъём ровно с места движения получаются сами, а медленное движение — сплошной прямой, хоть единица за пять секунд.
   ⛳ ПОЧЕМУ БОЛЬШЕ НЕ ВЫВОДИМ ПО ПРОМЕЖУТКУ И СКАЧКУ (как было в слайсе «плавная внутри движения»). Тот закон отличал движение от паузы
   по ДВУМ точкам: длинный промежуток с решительным скачком — ступенька. Медленное движение (единица в секунду и медленнее) даёт ровно
   такие промежутки — и закон рисовал бы его ступенями. Различить медленное движение и паузу по двум точкам нельзя; по ВСЕМ выборкам
   между ними — можно, и это делает запись, у которой они есть (fineKnee). Отрезку остаётся одно правило: записанное — плавно.
   Её зовут ВСЕ: переигровка (fxPlayDrive на тике), рендер заморозки и ухо-проба (fxLaneExpand) и рисунок полосы (autPointsCalc кладёт
   ответ в вид, draw его только читает). Разойтись рисунку и звуку нечем.
   ⛳ ОТ ТОЧКИ СНИМКА (snap) ПЛАВНЫЙ ОТРЕЗОК НЕ НАЧИНАЕТСЯ: снимок — состояние цепи на старте взятого, а не точка с ручкой; полоса
   рисует его полкой, и прямая от начала взятого к первой точке была бы подъёмом, которого там никто не ставил.
   ⛳ ПЕРЕКЛЮЧАТЕЛЬ ДЛЯ УХА (autRecSmoothOn): выключен — записанные точки снова ступеньки, как до слайса, везде сразу (▶, полоса,
   рендер, R.live). Ставит его только ухо-проба (render.recSteps / aud({recSteps})); в интерфейсе его нет.
   Живая переигровка зовёт это на каждом тике (fxPlayDrive), рендер и ухо-проба — через fxLaneExpand. Второй формулы нет. */
let autRecSmoothOn=true;
const setAutRecSmooth=on=>{ autRecSmoothOn=!!on; takeFxTouch(); };   // takeFxTouch — переигровка пересоберёт ленту, полоса — вид (мемо autPoints)
/* ФОРМА ОТРЕЗКА prev→pt: форма человека главнее; нет её — записанная точка, отрезок в неё плавный (если переключатель уха не снят).
   prev — точка, не снимок (от снимка не едут — см. fxLaneSmooth). Пустой промежуток — не отрезок. */
function autSmoothOf(prev,pt){
  if(!prev||!pt) return false;
  if(pt.sh==='s') return true;
  if(pt.sh) return false;                                         // 'h' — ступенька, поставленная человеком
  return autRecSmoothOn && pt.t>prev.t+1e-9;
}
const fxLaneSmooth=e=>{ const n=e&&e.nx; return !!(n && !e.snap && n.t>e.t+1e-9 && autSmoothOf(e,n)); };
function fxLaneAt(e,x){
  if(!fxLaneSmooth(e)) return e.v;
  const n=e.nx, u=(x-e.t)/(n.t-e.t);
  return u<=0 ? e.v : u>=1 ? n.v : e.v+(n.v-e.v)*u;
}
/* РАЗВЁРТКА ПЛАВНЫХ ОТРЕЗКОВ В ТОЧКИ — для тех, кто ставит величины ЗАРАНЕЕ по списку (офлайн-рендер, ухо-проба R.live).
   ⛳ ШАГ — ТОТ ЖЕ, ЧТО У ЖИВОГО ТИКА (SCHED_TICK_MS), переведённый в доли по темпу вызывающего: живой тик ставит величину раз в
   25 мс, сеттер сглаживает ступеньку своей τ; рендер обязан делать ровно то же, иначе заморозка звучала бы глаже или грубее ▶.
   Сэмпл несёт tk и слой своей точки, поэтому победитель при равной доле решается тем же законом (сортировка по (t, tk)).
   ⚠️ Нативную рампу AudioParam (linearRamp/exponentialRamp) здесь НЕ берём, и это не лень: величина обязана пройти СЕТТЕР
   эффекта (единственная дверь, правило #29), а сеттеры нелинейны — длина реверба пересчитывается в усиления четырёх линий
   (10^(−3d/RT60)), глубина тремоло пишет два узла. Рампа в одном AudioParam повела бы не ту величину, которую рисует полоса. */
function fxLaneExpand(list,stepBeats){
  if(!(stepBeats>0)) return list;
  const out=[];
  for(const e of list){ out.push(e);
    if(e.fx===FX_CHAIN || !fxLaneSmooth(e)) continue;
    for(let t=e.t+stepBeats; t<e.nx.t-1e-9; t+=stepBeats) out.push({ t, tk:e.tk, layer:e.layer, key:e.key, fx:e.fx, p:e.p, v:fxLaneAt(e,t) });
  }
  out.sort((a,b)=> a.t-b.t || a.tk-b.tk);   // устойчивая сортировка: при равной доле и взятом точка ленты остаётся перед сэмплом, как и была
  return out;
}
function fxPlayBuild(){
  fxPlayList=fxLaneMerge(); fxPlayReset();
  fxPlaySig=fxPlaySignature();
}
function fxPlayReset(){ fxPlayI=0; fxPlayAt=-1; fxPlayVals.clear(); fxPlayOrd.clear(); }
/* Свернуть ленту ДО доли x и применить. ВПЕРЁД — курсором, сворачивая только НОВЫЕ точки (цена тика не
   зависит от длины песни, тот же довод, что у курсоров планировщика в S3.2). НАЗАД (перемотка, заворот
   скобы) — свёртка с нуля: ровно так и входит в песню догонялка, второй механики не заводим. */
function fxPlayDrive(x){
  if(fxPlaySig!==fxPlaySignature()) fxPlayBuild();
  if(!fxPlayList||!fxPlayList.length) return;
  if(x<fxPlayAt) fxPlayReset();                                  // время пошло назад — префикс сворачиваем заново
  fxPlayAt=x;
  const gated=laneGated();
  while(fxPlayI<fxPlayList.length && fxPlayList[fxPlayI].t<=x+1e-9){
    const e=fxPlayList[fxPlayI++];
    if(gated && !laneAudible(e.layer)) continue;                 // заглушённая дорожка своей автоматикой не правит
    if(e.fx===FX_CHAIN) fxPlayOrd.set(e.key, e.ids);             // ПОСЛЕДНЯЯ точка по адресу и побеждает — просто перезаписываем
    else fxPlayVals.set(e.key+'|'+e.fx+'|'+e.p, e);
  }
  for(const [key,ids] of fxPlayOrd) fxPlayPath(key, ids);        // СОСТАВ — ПЕРВЫМ: величины поедут уже в верную цепь. fxPlayPath молча выходит, если состав тот же
  /* ГЛАДКАЯ АВТОМАТИЗАЦИЯ: у плавного отрезка величина на ЭТОМ тике — точка прямой (fxLaneAt). Сеттер ставит её своей τ, и
     25-мс ступеньки тика сливаются в рампу; ступенчатый отрезок отдаёт e.v, как было. Сосед справа из заглушённой дорожки не
     правит (как и в свёртке выше) — к нему не едем, держим. */
  for(const e of fxPlayVals.values()){
    const v = fxLaneSmooth(e) && !(gated && !laneAudible(e.nx.layer)) ? fxLaneAt(e,x) : e.v;
    fxPlaySet(e.key, e.fx, e.p, v);   // fxPlaySet молча выходит, если величина уже там
  }
}
/* ⛳ ПРАВИТ ЛИ ЭТИМ АДРЕСОМ СЕЙЧАС ЗАПИСЬ — для показа (столбики). Ответ ПО ПАРАМЕТРУ, а не по эффекту и
   не по роли: в цепи, где запись вела подмес и не трогала длину, помечен обязан быть ровно один столбик.
   ⚠️ Правда одна и та же для звука и для показа: ключи fxPlayVals — это РОВНО те адреса, которые тик
   сейчас ведёт (их же он и применяет строкой ниже в fxPlayDrive). Второго списка «что помечено» нет.
   Транспорт стоит → свёрнутое состояние очищено (fxPlayReset) → не правит никто, и пометок нет. */
const fxIsDriven=(key,fxId,pKey)=> loop.on && !recording && fxPlayVals.has(key+'|'+fxId+'|'+pKey);
/* ⚠️ `!recording` ОБЯЗАТЕЛЕН, и это не перестраховка. Свёрнутое состояние живёт между тиками, а во время
   записи fxPlayDrive не зовётся вовсе (правило O-3: пока пишем — хозяин рука). Нажми человек ● посреди
   воспроизведения — состояние осталось бы от последнего кадра, и столбики продолжали бы помечать чужим
   то, чем в этот миг распоряжается ТОЛЬКО его рука. Пометка обязана исчезнуть ровно тогда, когда
   исчезает власть записи. */
/* Транспорт встал — вернуть живую цепь. ⛳ ВЕЛИЧИНЫ ОСТАВЛЯЕМ ТАМ, ГДЕ ИХ ОСТАВИЛА ЗАПИСЬ, и это выбор:
   ручки — это ручки, они стоят там, где стоят, их видно (столбики и меню читают те же p.cur) и их можно
   двигать. Возврат «как было до ▶» потребовал бы второй копии всех величин и ещё одного провала на
   остановке, а главное — ничего бы не защитил: записанное всё равно неприкосновенно.
   ⚠️ СОСТАВ — НАОБОРОТ, ВОЗВРАЩАЕМ ВСЕГДА: это не величина, а ЧУЖАЯ раскладка, и оставить человека с
   составом чужой записи значило бы отобрать у него его собственную цепь. */
function fxPlayStop(){
  fxPlayReset();
  for(const {key} of chainOwners()){ fxPlayPath(key,null); fxRestoreAim(key); }   // состав — человеку обратно; звук — к ПРИЦЕЛУ руки, чтобы столбик и звук сошлись в тот же миг (см. fxRestoreAim)
}
/* УБОРКА — тем же законом, что у дорожек: запись взятого, чьих событий больше НЕТ, снимается.
   ⚠️ ЭТО ГИГИЕНА, А НЕ КОРРЕКТНОСТЬ (как и у lanePrune): осиротевшая запись никому не мешает, но копилась
   бы всю сессию. Зовётся ИЗ lanePrune — одной строкой, чтобы наследовать ВСЕХ её вызывающих сразу (⤺
   отмена взятого, удаление дорожки, снятие подложки) и не заводить третий список мест, где можно забыть.
   Пишущееся взятое ЩАДИМ — оно законно пусто, пока в него не сыграли. */
function takePrune(){
  const live=new Set(); for(const e of events) live.add(e.tk||0);
  for(const tk of [...takeFx.keys()]) if(!live.has(tk) && !(recording&&tk===curTake)) takeFx.delete(tk);
}
function takeReset(){ takeFx.clear(); takeFxLast=null; takeFxOrder=null; }   // ✕ — песни нет, значит нет и захвата
/* РОЛЬ СОБЫТИЯ. chaseRole отвечает только про владельцев ГОЛОСОВ (аккорд/бас/соло) и на ударе молчит —
   ему так и надо, он про догонялку. Здесь вопрос другой: «чья это цепь эффектов», и у ударных она есть.
   Дрон остаётся без роли НАМЕРЕННО: он фон, в конструкторе не выбирается и цепи не имеет (см. довод
   у регистрации ролей в initAudio). */
const evRole=fn=> fn==='drum' ? 'dr' : chaseRole(fn);
/* ⛳ РОЛЬ ДОРОЖКИ (T4). С T2 в дорожке РОВНО ОДНА роль (маршрут по источнику), поэтому роль первого же её
   события с ролью — это роль всей дорожки; вторую искать незачем, её там нет по построению.
   null — у дорожки нет ни одной ноты: опустела правками или это слой дрона (дрон — уровень, а не нота, и
   роли не даёт — см. evRole). ⛔ Роль НЕ выдумывается: вызывающий обязан показать «нот нет», а не ось
   чужой роли. O(событий) — зовут её на открытии редактора и в правках цепи, не на кадр. */
function laneRoleOf(layer){
  if(layer==null) return null;
  for(const e of events) if(e.layer===layer){ const r=evRole(e.fn); if(r) return r; }
  return null;
}
/* ОДНА ЦЕПЬ ДОРОЖКИ — ключ владельца её роли. Выбора «в чью цепь» больше нет (его держали вкладки
   редактора, пока дорожка могла нести несколько ролей): у дорожки ровно одна роль, значит одна цепь. */
const laneChainKey=layer=>{ const r=laneRoleOf(layer); return r ? chainKeyOf(r) : null; };
/* ЧТО ЗАХВАЧЕНО У ДОРОЖКИ — для показа в редакторе (единственный сегодняшний читатель). Отдаёт СВОДКУ,
   а не сам реестр: наружу не должно утекать то, что пока никто не исполняет.
   ⛳ ОТБОР ПО ЦЕПИ САМОЙ ДОРОЖКИ — ГЛАВНОЕ ЗДЕСЬ, и это правка ошибки, а не украшение. Реестр взятого
   хранит цепи ВСЕХ владельцев (сплит пишет две роли в одно взятое, и они ложатся в РАЗНЫЕ дорожки);
   без отбора басовая дорожка показывала бы делей СОЛО и яркость АККОРДОВ. С T4 отбор — по ОДНОЙ цепи:
   роль у дорожки одна (laneRoleOf).
   ⚠️ ИМЕНА ЭФФЕКТОВ СОБИРАЕМ И ИЗ СНИМКА, И ИЗ ДОРОЖКИ. Снимок — это состав НА СТАРТЕ взятого; эффект,
   добавленный ПОСРЕДИ него, живёт только в дорожке (записью состава и своими величинами). Без второго
   источника «добавил реверб во время записи» читалось бы как «ничего не захвачено» — при непустом счёте
   точек, то есть противоречиво.
   ⚠️ null, А НЕ ПУСТАЯ СВОДКА, когда дорожки нет или у неё нет роли (опустевшая дорожка, слой дрона):
   показывать «захвачено: ничего» там, где вопрос неприменим, — шум. */
function captureInfoOf(layer){
  const role=laneRoleOf(layer); if(!role) return null;
  const key=chainKeyOf(role), tks=new Set();
  for(const e of events) if(e.layer===layer) tks.add(e.tk||0);
  const ids=new Set(); let pts=0;
  for(const tk of tks){ const r=takeFx.get(tk); if(!r) continue;
    const ch=r.chains[key]; if(ch) for(const e of ch) if(!fxPerm(e.fxId)) ids.add(e.fxId);   // VOL-0: громкость в сводке не называем (она у дорожки есть всегда и в этом слайсе невидима)
    for(const ent of r.lane){ if(ent.key!==key||fxPerm(ent.fx)) continue; pts++; if(ent.fx!==FX_CHAIN) ids.add(ent.fx); }   // FX_CHAIN — служебная запись состава, у неё нет имени и показывать её нечем. VOL-0/VOL-2: точки громкости (они бывают, когда громкость на пальце руки-эффектов — тогда захват пишет её общий p.cur; на горизонтали её p.cur не движется) в счёт не идут — громкость «в ноте», переигровка их не читает, и сводка их не называет
  }
  return { takes:tks.size, role, fx:[...ids], pts };
}
function lanePrune(){
  takePrune();   // O-2: захват взятого уходит вместе с его событиями — одной строкой, чтобы унаследовать всех вызывающих
  const live=new Set(); for(const e of events) live.add(e.layer);
  for(const [ly,id] of laneId) if(!live.has(ly) && !isRecLayer(ly)){   // T1: пишущиеся слои взятого щадим (прежде — один loop.layer)
    laneId.delete(ly); laneMute.delete(id); laneSolo.delete(id); laneLen.delete(id); laneEditVer.delete(id); if(armLane===id) armLane=null; if(delPend&&delPend.id===id) delPend=null;
    freezeDrop(id); }   // S3.5c: снятая дорожка (⤺, снятие подложки) снимает и вооружение — ● дальше создаст новую, а не пишет в пустоту   // F4: и БУФЕР уходит вместе с ней — иначе он остался бы звучать за дорожку, которой больше нет
}
/* ⚠️ laneSeq НАМЕРЕННО НЕ ОБНУЛЯЕТСЯ: счётчик монотонен на всю сессию. Обнуление вернуло бы в оборот
   уже выданные номера id — а это ровно тот вид совпадения, от которого id и заводился. Стоит он
   ничего (целое число), а класс ошибок закрывает целиком. */
function laneReset(){ for(const id of [...frozen.keys()]) freezeDrop(id);   // F4: ✕ — песни нет, значит нет и её заморозок
  laneId.clear(); laneMute.clear(); laneSolo.clear(); laneLen.clear(); laneEditVer.clear(); armLane=null; delPend=null; takeReset(); }   // A2: версии правок — гигиена (id не переиспользуются, мёртвая запись ни на что не влияла бы)   // O-2: захват сбрасывается вместе с дорожками (✕ и старт записи на пустой песне)
/* Слой вооружённой дорожки или null. ЧИСТОЕ чтение (его зовёт draw каждый кадр): обход таблицы дорожек —
   O(дорожек), не событий. id, не найденный в таблице, читается как «не вооружено». */
function laneLayerOf(id){ if(id==null) return null; for(const [ly,i] of laneId) if(i===id) return ly; return null; }
const armedLayer=()=>laneLayerOf(armLane);
/* Тап по строке дорожки вне гнёзд M/S: вооружить её / снять вооружение повторным тапом.
   ⛔ ВО ВРЕМЯ ЗАПИСИ НЕ МЕНЯЕТСЯ: пишущаяся дорожка уже выбрана, и метка «вооружена» на ДРУГОЙ строке в
   это время врала бы, куда идёт запись. `?? laneNew` — та же самопочинка, что у toggleLaneMute. */
function toggleArm(layer){
  if(recording) return;
  const id=laneOf(layer) ?? laneNew(layer);
  armLane = armLane===id ? null : id;
}
/* ═══ УДАЛЕНИЕ ЛЮБОЙ ДОРОЖКИ С ЕЁ СТРОКИ (слайс S3.5d) ═══
   ⛔ УДАЛЕНИЕ НЕ ОТМЕНЯЕТСЯ. ⤺ снимает взятые, а удалённая дорожка не взятое: её события ушли из массива, и
   вернуть их неоткуда. Поэтому ВЕСЬ вес несёт ПОДТВЕРЖДЕНИЕ: первый тап по ✕ только ВЗВОДИТ (кнопка
   заливается красным, строка краснеет, заголовок пишет «ещё раз ✕ — удалить Ln»), второй тап по ТОМУ ЖЕ ✕
   в течение DEL_CONFIRM_MS удаляет. Любой другой тап по полосе или истёкшее окно — снимают взвод.
   Почему не модальный диалог: он отнимает руку у камеры, вытаскивает DOM поверх холста и требует
   нажать в ДРУГОМ месте экрана; второй тап в то же место с видимой сменой состояния — честный минимум.
   ⛔ Удаление НЕ ПРИВЯЗАНО К ВООРУЖЕНИЮ: красная рамка значит «куда запишу», и если бы она же значила
   «что удалю», однажды человек удалил бы дорожку, думая о записи. Два смысла — две цели. */
const DEL_CONFIRM_MS=3000;
function laneDelTap(layer){
  if(!AC || isRecLayer(layer)){ delPend=null; return false; }   // T1: любой слой взятого (прежде — loop.layer)   // в пишущуюся дорожку push продолжает писать — удалить её посреди взятого значило бы тут же воскресить
  const id=laneOf(layer) ?? laneNew(layer), now=performance.now();
  if(delPend && delPend.id===id && now<delPend.until){ delPend=null; return deleteLane(layer); }
  delPend={id, until:now+DEL_CONFIRM_MS};
  return false;
}
function laneDelCancel(){ delPend=null; }
/* Слой, чьё удаление взведено, или null (окно истекло / дорожки больше нет). ЧИСТОЕ чтение — его зовёт draw. */
function laneDelPendingLayer(){ if(!delPend || performance.now()>=delPend.until) return null; return laneLayerOf(delPend.id); }
/* Снять дорожку целиком. ⚠️ ЗВУЧАЩЕЕ ГАСИМ ТЕМ ЖЕ ПУТЁМ, ЧТО ЗАГЛУШЕНИЕ (releaseLoopLayersAt со слоем): ровно её
   владельцы — 'loop:N', 'loop:N:k' влитых взятых, 'bassloop:N…', 'leadloop:N:v' — и больше ничьи, поэтому
   хвосты остальных дорожек не обрываются (в отличие от ⤺, который зовёт softAllOff). Удары, уже поставленные
   в окно SCHED_AHEAD, доиграют — та же принятая цена, что у заглушения.
   СИРОТ НЕ ОСТАЁТСЯ: события ушли (с ними a.v соло и a.k влитых взятых — эти номера выводятся из лежащего в
   слое на каждом ●, отдельного состояния у них нет); курсоры, кэш догонялки и длину песни сбрасывает
   schedInvalidate; строку, mute/solo, вооружение и взвод — lanePrune; дрон — laneHush (уровень по слышимости
   ОСТАВШИХСЯ дорожек: ушёл последний слой-дрон — дрон гаснет). */
function deleteLane(layer){
  if(!AC || isRecLayer(layer)) return false;   // T1: любой слой взятого (прежде — loop.layer)
  releaseLoopLayersAt(undefined,layer);
  if(recording) events.sort((x,y)=>x.t-y.t);   // хвост взятого — в отсортированный префикс ДО schedInvalidate (см. setRegionOn)
  if(!compactEvents(e=>e.layer===layer)) return false;
  schedInvalidate(); lanePrune();
  curChordDeg=-1;                               // подсветка аккорда петли могла принадлежать снятой дорожке; следующий chOn выставит заново
  laneHush();
  if(!events.length) clearRec(); else hooks.loop && hooks.loop(loop.on);
  return true;
}
/* ⛳ ПРЕДИКАТ СЛЫШИМОСТИ — ОДИН НА ОБА ПУТИ ПЕРЕИГРОВКИ (scheduleLayers и fireNear).
   СОЛО ПЕРЕБИВАЕТ ЗАГЛУШЕНИЕ: как только соло включено хоть где-то, слышны РОВНО соло-дорожки, а
   остальные молчат независимо от своих галочек mute (и возвращаются как были, когда соло снимут). */
/* Зовётся из планировщика (40 раз в секунду на каждое событие) и из draw — поэтому важно, что laneOf
   ЧИСТЫЙ: ни одной записи в таблицу на горячем пути. Нет id → дорожка обычная, слышимая. */
const laneAudible=layer=>{ const id=laneOf(layer);
  return laneSolo.size ? (id!=null&&laneSolo.has(id)) : !(id!=null&&laneMute.has(id)); };
/* ⛳ ГЕЙТ ЦЕЛИКОМ ВЫКЛЮЧЕН, ПОКА НИЧЕГО НЕ ЗАГЛУШЕНО И НИЧЕГО НЕ В СОЛО — и это НЕ микро-оптимизация,
   а УСЛОВИЕ ПРИЁМКИ слайса: пока человек не тронул переключатели, пер-событийная проверка не
   выполняется ВООБЩЕ (в цикле остаётся один уже вычисленный булев), и переигровка идёт байт-в-байт
   как раньше. Считается ОДИН РАЗ НА ВЫЗОВ планировщика, а не на событие. */
const laneGated=()=> laneMute.size>0 || laneSolo.size>0;
/* Дрон — не нота, а УРОВЕНЬ (выделенные узлы, softAllOff его не трогает), поэтому «заглушить слой
   с дроном» нельзя сделать пропуском события: droneOn уже отработал. Спрашиваем отдельно, слышен ли
   дрон хоть на одной дорожке, и ведём общий уровень. */
/* ⚠️ «Слышим ЖИВЫМ ГОЛОСОМ» (A2): свежая замороженная дорожка свой дрон играет из БУФЕРА — посчитай мы её
   здесь, дрон звучал бы дважды на каждом пуске (дефект F4, найден при сверке A2). Устаревшая — снова в
   счёте: она играет события. */
const droneAudible=()=>events.some(e=>e.fn==='drone'&&laneAudible(e.layer)&&!frzLayer(e.layer));
/* Привести ЖИВОЙ дрон в соответствие со слышимостью — одна строка на всех: приглушение, заморозка,
   разморозка, устаревание. when — время шва (по умолчанию «сейчас»). */
const droneSync=(when,tc)=>{ if(droneActive()){ if(loop.on&&droneAudible()) droneOn(undefined,when,tc); else droneOff(when,tc); } };   // tc (A2b) — короткий только на шве заморозки; иначе прежние постоянные
const FRZ_DRONE_TC=0.02;   // A2b: дрон на шве — подмена в миг шва (буфер уходит рампой FRZ_FADE), без секундного провала
/* Переключатели. Наружу дорожка адресуется НОМЕРОМ СЛОЯ — тем же, чем подписана её строка на полосе
   лупера; id остаётся внутренним делом (ui не может подержать протухший id).
   ⚠️ `?? laneNew(layer)` — НЕ «мягкое заведение id», а ЕДИНСТВЕННЫЙ БЕЗОПАСНЫЙ способ его получить,
   когда записи нет. Он безопасен ровно потому, что ОТСУТСТВИЕ записи не может нести устаревший id:
   вернуть что-то протухшее laneOf физически неспособен (он либо отдаёт действующий id, либо ничего).
   Сюда мы попадаем, только если слой родился мимо всех известных мест рождения, — то есть это ещё и
   САМОПОЧИНКА: дорожка получит id и переключатель сработает, вместо того чтобы молча ничего не делать. */
function toggleLaneMute(layer){ const id=laneOf(layer) ?? laneNew(layer);
  if(laneMute.has(id)) laneMute.delete(id); else laneMute.add(id);
  laneHush(); }
function toggleLaneSolo(layer){ const id=laneOf(layer) ?? laneNew(layer);
  if(laneSolo.has(id)) laneSolo.delete(id); else laneSolo.add(id);
  laneHush(); }
/* ЧИТАТЕЛИ ДЛЯ ПОКАЗА — через тот же чистый laneOf (их зовёт draw на каждый кадр; правило #5 с
   обратной стороны: рисование не смеет менять состояние). */
const laneMuted =layer=>{ const id=laneOf(layer); return id!=null&&laneMute.has(id); };
const laneSoloed=layer=>{ const id=laneOf(layer); return id!=null&&laneSolo.has(id); };
const laneSoloOn=()=> laneSolo.size>0;
/* ⚠️ ЗАГЛУШАТЬ НАДО НЕМЕДЛЕННО, А НЕ «СО СЛЕДУЮЩЕГО СОБЫТИЯ»: удержанный аккорд слоя звучал бы до
   заворота (chOff у него ещё впереди). Ключи владельцев дают ТОЧНЫЙ адрес слоя, поэтому гасим ровно
   ставшие неслышимыми слои — ТЕМ ЖЕ обходом, что и граница повтора (releaseLoopLayersAt со слоем),
   второго обхода не заводим.
   Зовём после КАЖДОГО переключения и проходим ВСЕ слои, а не только тронутый: включение соло делает
   неслышимыми чужие дорожки, а снятие одного из двух соло — ту, что осталась без него.
   Уже молчащие слои проходят вхолостую (chordOff/bassOff/leadOff выходят сразу, если владельца нет).
   ⚠️ УДАРНЫЕ ОТМЕНИТЬ НЕЛЬЗЯ: drumHit — одноразовые осцилляторы, поэтому удары, уже запланированные
   в окно SCHED_AHEAD (~300мс), прозвучат ПОСЛЕ заглушения. Та же принятая и ограниченная цена, что у
   стопа петли и у отмены слоя; чинить её здесь нечем. */
function laneHush(){
  if(!AC) return;
  const seen=new Set();
  for(const e of events){ if(seen.has(e.layer)) continue; seen.add(e.layer);
    if(!laneAudible(e.layer)) releaseLoopLayersAt(undefined,e.layer); }
  frzGainAll();                                                                  // F4: у замороженной нет голосов, которые можно отпустить, — её приглушает ГЕЙН ШИНЫ; бьём отсюда же, откуда бьёт живое приглушение
  droneSync();   // уровень дрона — по слышимости ЕГО дорожки (уровень, а не нота: пропуском события его не заглушить)
}

/* ═══════════ ⛳ ЗАМОРОЖЕННЫЕ ДОРОЖКИ — РЕЖИМ ВОСПРОИЗВЕДЕНИЯ (слайс F4) ═══════════
   ⛳ ЗАМОРОЗКА — ЭТО НЕ ПРЕОБРАЗОВАНИЕ. События НИКОГДА не выбрасываются: пока дорожка заморожена,
   транспорт играет ЕЁ БУФЕР ВМЕСТО её событий, и только. Разморозка — снять буфер, и дорожка снова
   играет события. Мгновенно и без потерь. Ради этого и существует редактор.

   ⛔ КЛЮЧ РЕЕСТРА — ID ДОРОЖКИ, А НЕ НОМЕР СЛОЯ (правило #27). Номера ПЕРЕИСПОЛЬЗУЮТСЯ (новая дорожка
   берёт maxLayer()+1, после отмены — освобождённый) и бывают с дырами. Ключуйся мы номером, новая
   дорожка молча унаследовала бы чужой буфер — правдоподобно, тихо и не найти. `laneNew` всегда выдаёт
   СВЕЖИЙ id, поэтому мёртвый id просто больше никогда не совпадёт.
   ⛔ И НИ В КОЕМ СЛУЧАЕ НЕ В СОБЫТИЕ: буфер — не часть записи, он живёт здесь, в recorder, рядом с
   дорожками. Правило #28 цело: реестр не в массиве событий, курсоров и schedInvalidate не трогает.

   ⚠️ ИСТОЧНИК БУФЕРА ОДНОРАЗОВ. AudioBufferSourceNode нельзя перезапустить — ни после stop, ни после
   естественного конца. Значит НОВЫЙ узел нужен на КАЖДЫЙ пуск транспорта, КАЖДУЮ перемотку и КАЖДЫЙ
   проход повтора. Это ТО ЖЕ САНКЦИОНИРОВАННОЕ ИСКЛЮЧЕНИЕ правила #3, что у ударов и метронома
   («per-hit drums/metronome — the exception»), только «на пуск», а не «на удар»: узел создают, он
   отыгрывает и уходит. Правило же запрещает ГЛУШИТЬ голоса пулов, а их здесь нет вовсе.

   ⛳ ПЕРЕМОТКА — ДАРОМ, И ЭТО САМОЕ ИЗЯЩНОЕ ЗДЕСЬ. У источника есть СМЕЩЕНИЕ, поэтому дорожка, в
   которую вошли посреди ноты, просто играет с середины сэмпла. Догонялка (chasePlay), которой живая
   дорожка поднимает зажатые голоса на входе, замороженной НЕ НУЖНА ВООБЩЕ. */
const frozen=new Map();     // id дорожки → { layer, buf, startSec, endSec, tailSec, pinned, bus, nodes[], armedRep }
/* «Есть ли хоть одна СВЕЖАЯ заморозка» — дешёвый гейт горячих путей. ⚠️ Устаревшие здесь не в счёт:
   их события обязаны играть, значит пропускать их нельзя. */
const frozenOn=()=>frozen.size>0;
/* Заморожен ли СЛОЙ (события этого слоя играть не надо). ⚠️ Спрашивают горячие пути, поэтому сначала
   дешёвая проверка «есть ли вообще хоть одна заморозка». */
function frzOf(layer){
  if(!frozen.size) return null;
  const id=laneOf(layer);
  return id==null?null:(frozen.get(id)||null);
}
/* ⛳ ИГРАЕТ ЛИ ЗА ЭТУ ДОРОЖКУ БУФЕР. ⛔ ИМЕННО «ЗАМОРОЖЕНА И СВЕЖА»: на этом предикате висят ОБА пути
   переигровки и догонялка, поэтому устаревшая дорожка автоматически возвращается к своим событиям —
   без единой отдельной ветки «а если устарела». */
const frzLayer=layer=> freezeState(layer)==='fresh';
/* А ЭТО — «есть ли буфер вообще», для показа и для уборки: устаревший буфер никуда не делся, его
   просто не слушают. Не путать с предыдущим. */
const frzHas=layer=>{ const f=frzOf(layer); return !!f&&!f.drop; };   // A2b: уходящая на шве — уже не заморожена
/* Буфер СЕЙЧАС владеет дорожкой (взведён) — даже если дорожка уже устарела и ждёт шва выхода. A2c: догонялка
   такую пропускает — передачу сделает frzLeave. В самом frzLeave armedRep сброшен ДО его догонялки. */
const frzBufOwns=layer=>{ const f=frzOf(layer); return !!(f&&f.armedRep!=null); };

/* ЗАВЕСТИ/СНЯТЬ. ⛳ Зовёт их render.js — с F5 из кнопки ❄ редактора (ui.onFreeze), а также из консоли. */
/* ⛳ ПОДПИСЬ СВЕЖЕСТИ (F5) — «изменилось ли хоть что-то, из чего рендер собирал буфер».
   ⛳ ФОРМА ВЗЯТА У fxPlaySignature, А НЕ ПРИДУМАНА ЗАНОВО: та же дешёвая строка, которую можно сверять
   на каждом кадре, и тот же приём «считаем длины и версии, а не содержимое».
   ЧТО ВХОДИТ — РОВНО ТО, ЧТО РЕНДЕР ПОТРЕБЛЯЕТ:
     • СОБЫТИЯ ДОРОЖКИ: сколько их, первая и последняя доля, и сумма долей. ⚠️ Сумма — не «хеш ради
       хеша»: она ловит СДВИГ ноты внутри дорожки, при котором и число событий, и края не меняются
       (ровно случай «подвинул ноту в редакторе»);
     • ВЕРСИЯ ПРАВОК ЭТОЙ ДОРОЖКИ (laneEditVer, с A2; прежде — общий takeFxVer): правки полосы
       автоматизации и правки нот поднимают её, а длины при этом не меняются (сдвиг ноты по высоте сумму
       долей не трогает) — поэтому длины одни не годятся. ⛔ Своя у дорожки, а не общая: общий счётчик
       старил ВСЕ замороженные от правки одной — см. шапку laneEditVer;
     • ПРИКОЛОЧЕННОЕ рендером: тоника, эталон A4 и темп — всегда (смени тонику — буфер звучит в прежней,
       а события зазвучали бы в новой); лад, септаккорд и три запасных тембра — ТОЛЬКО если у дорожки
       есть событие, которое их читает (см. тело).
   ⛔ ЧТО НАМЕРЕННО НЕ ВХОДИТ: ПРИГЛУШЕНИЕ И СОЛО. Они не меняют ЗВУК дорожки, они меняют, слышно ли
   её, — и у замороженной это делает гейн шины. Включи мы их в подпись, любое нажатие M пометило бы
   дорожку устаревшей на ровном месте. (У fxPlaySignature они входят по другой причине: там от них
   зависит ПОБЕДИТЕЛЬ в свёртке автоматизации.)
   ⚠️ И НЕ ВХОДЯТ события ЧУЖИХ дорожек — хотя чужое взятое той же роли правит той же цепью (предел
   №1–2). Это осознанный компромисс: иначе запись на соседней дорожке помечала бы устаревшими все
   заморожённые сразу, а разница почти всегда неслышна. Названо, а не пропущено. */
/* ⚠️ МЕМО ОБЯЗАТЕЛЬНО, И ЭТО НЕ ОПТИМИЗАЦИЯ «НА ВСЯКИЙ». freezeState зовёт ОТРИСОВКА — по строке на
   кадр, — а подпись обходит ВСЕ события. На песне в несколько минут с двумя десятками дорожек это
   O(дорожек × событий) НА КАДР, ровно та беда, которую полоса лупера уже однажды пережила (см. метки
   событий в draw). Ключ мемо — ДЕШЁВЫЕ величины, которые меняются всегда, когда мог измениться ответ:
   число событий (запись/отмена/удаление) + takeFxVer (ЛЮБАЯ правка редактора поднимает его в
   editCommit) + приколоченное. Совпал ключ — отдаём готовую подпись, обход не делаем.
   ⚠️ Сумму долей всё равно СЧИТАЕМ (она ловит сдвиг ноты): ключ отвечает «могло ли измениться»,
   подпись — «изменилось ли». Полагаться на один takeFxVer было бы ставкой на то, что будущий путь
   правки не забудет его поднять.
   ⛳ A1 (дуга «АВТОЗАМОРОЗКА»): МЕМО СТАЛО ПО СЛОЮ. Прежде место было ОДНО, а ключ начинался со слоя —
   поэтому при двух замороженных дорожках полоса спрашивала L1, L2, L1, L2… и каждый вызов вытеснял
   предыдущий: мемо не попадало НИКОГДА, и довод абзацем выше был правдой только для одной дорожки.
   Теперь это Map «слой → подпись», и она очищается ЦЕЛИКОМ, как только сменилась НЕСЛОЕВАЯ часть
   ключа (frzGlobalKey): всё, что в неё входит, общее для всех дорожек, значит и устаревают они вместе.
   ⛔ ЧТО ВОЗВРАЩАЕТ freezeSig — НЕ ИЗМЕНИЛОСЬ НИ ДЛЯ ОДНОГО ВХОДА: та же строка, собранная тем же
   обходом. Поменялось только то, КАК ЧАСТО обход делается. Мемо никуда не выгружается: слоёв столько,
   сколько дорожек, и вся Map гибнет при следующей же смене ключа. */
/* ⛳ ГЛОБАЛЬНЫЙ КЛЮЧ ГРЯЗИ — дешёвая строка, которая меняется ВСЕГДА, когда могла смениться подпись
   хотя бы одной дорожки: число событий + поколение состава (evGen, см. у schedInvalidate) + версия
   захвата + приколоченное. Экспортирован для A3/A4: наблюдатель сверяет ЕЁ раз в полсекунды и только
   при смене пересчитывает подписи по дорожкам. ⛔ Он лишь ЧИТАЕТ и schedInvalidate не зовёт (#28). */
/* P3 «строй от»: tunedFrom — в приколоченном, как scaleIdx: он входит в CUR() — запасной лад события без sc (сегодня таких нет).
   ⛳ В ПОДПИСЬ ДОРОЖКИ он попадает ТОЛЬКО через эту запасную ветку (noSc в freezeSig): у события есть sc — вариант лада со своим
   якорем, и смена выбора его звук не меняет; значит замороженная дорожка от передвижения выбора НЕ стареет (мемо подписи лишь
   пересчитается к той же строке). ⛳ T2: пара scaleIdx + tunedFrom — ровно КЛЮЧ ВИДА (строй, лад, якорь), который отдаёт CUR(). */
const frzPinned=()=>[tonic,aRef,scaleIdx,tunedFrom,seventh?1:0,loop.bpm,leadIdx,bassIdx,chIdx,droneNonOct()].join(',');   // droneNonOct — выбор второй струны дрона Болена–Пирса (R.droneBP): меняет звук дрона
const frzGlobalKey=()=>events.length+'|'+evGen+'|'+takeFxVer+'|'+frzPinned();
const frzSigMemo=new Map(); let frzSigG=null;
/* ⛳ ВЕРСИЯ ПРАВОК ДОРОЖКИ (A2) — по ID, не по номеру (правило #27). Поднимается там же, где takeFxTouch
   (editCommit и autCommit), но ТОЛЬКО у открытой в редакторе дорожки: все правки идут через editGuard, а
   он пускает лишь её.
   ⛔ ЗАЧЕМ ОНА, А НЕ takeFxVer. Тот — ОДИН НА ВСЁ ПРИЛОЖЕНИЕ, и стоял в подписи КАЖДОЙ дорожки: любая
   правка в редакторе (а разморозить дорожку затем и нужно, чтобы править) делала УСТАРЕВШИМИ все
   замороженные разом — они откатывались к событиям и выглядели размороженными. Это и была ошибка
   «разморозил одну — разморозились все»: реестр при этом никто не трогал.
   ⚠️ Правка ЧУЖОЙ дорожки той же роли правит ту же цепь (предел №1–2) — и подпись этого НЕ ловит. Тот же
   осознанный компромисс, что уже записан про чужие СОБЫТИЯ (см. шапку подписи выше). */
const laneEditVer=new Map();                 // id дорожки → число правок
const laneEditTouch=()=>{ if(editLane!=null) laneEditVer.set(editLane,(laneEditVer.get(editLane)||0)+1); };
function freezeSig(layer){
  const P=frzPinned();
  const g=events.length+'|'+evGen+'|'+takeFxVer+'|'+P;          // = frzGlobalKey(), но P уже посчитан. takeFxVer здесь ОСТАЁТСЯ: это ключ МЕМО («могла ли смениться хоть одна подпись»), а не сама подпись
  if(frzSigG!==g){ frzSigMemo.clear(); frzSigG=g; }
  const hit=frzSigMemo.get(layer); if(hit!==undefined) return hit;
  /* ⛳ ЗАПАСНЫЕ ЗНАЧЕНИЯ — ТОЛЬКО ЕСЛИ ДОРОЖКА ИХ ЧИТАЕТ. Лад и септаккорд нужны событию без `sc`, живые
     тембры — «вкл» без `a.inst` (правила чтения — у самих записей ENG и в bassOn: `ins ?? bassIdx`).
     Сегодня таких событий почти не бывает, и безусловное включение делало одно: смена живого тембра в
     панели старила ВСЕ замороженные дорожки — та же болезнь, что у takeFxVer. Тоника, A4 и темп
     входят ВСЕГДА: они меняют звук любой дорожки. */
  /* ⛳ T0: ТЕМБРЫ САМОЙ ДОРОЖКИ — в подписи. Тембр живёт в «вкл» ноты (соло/аккорд/бас — `a.inst`), в каждом
     ударе (`a.kit`) и — только у СОЛО — ещё в ведении (смена тембра посреди ноты, см. noInst); свёртка по
     порядку событий ловит и смену тембра, и перестановку «какая нота каким».
     Прежде тембра в подписи не было вовсе: будущая замена тембра у замороженной дорожки оставила бы её
     играть СТАРЫЙ звук свежим буфером — если бы путь замены забыл поднять версию правок.
     ⚠️ УРОК A2 СОБЛЮДЁН: в свёртку идут только данные СОБЫТИЙ дорожки, живые индексы — никогда (они входят
     лишь запасными значениями, и лишь когда событие без тембра их читает, см. выше). Переключатель тембра
     в панели замороженную дорожку не старит.
     ⚠️ Мемо подписи сбрасывается по глобальному ключу (число событий, поколение, takeFxVer, приколоченное):
     замена тембра обязана пройти через editCommit — он поднимает takeFxVer, как и любая правка редактора. */
  const tmix=(h,tag,x)=>(Math.imul(h,31)+tag*64+((x==null?-1:x)|0)+1)|0;   // индексы < 63 (тембров соло 23, наборов 5). ⚠️ ВЕРНО ТОЛЬКО ДЛЯ ВСТРОЕННЫХ ИНДЕКСОВ: id упакован малым целым (|0), и строковый id (стабильные id тембров, BACKLOG §7.4) свернётся в 0 — два разных тембра подпишутся одинаково. ПЕРЕПИСАТЬ вместе со стабильными id
  let n=0, first=null, last=null, sum=0, noSc=false, ld=false, ch=false, bs=false, tim=0;
  for(const e of events) if(e.layer===layer){
    n++; sum+=e.t; if(first===null||e.t<first) first=e.t; if(last===null||e.t>last) last=e.t;
    if(!e.sc) noSc=true;
    if(e.fn==='drone') noSc=true;   // слайс «дрон и центы»: дрон читает ЖИВОЙ лад (вторая струна — ступень лада, scales.droneDegree), а не sc события — значит смена лада/«строй от» меняет его звук, и замороженная дорожка с дроном обязана устареть
    const a=e.a; if(a){ if(e.fn==='leadOn'){ tim=tmix(tim,1,a.inst); if(a.inst===undefined) ld=true; }
                        else if(e.fn==='leadSet'&&a.inst!=null) tim=tmix(tim,5,a.inst);   // T0-fix: ведение соло несёт тембр (нота переливается), и рендер его играет — значит и подпись его видит
                        else if(e.fn==='chOn'){ tim=tmix(tim,2,a.inst); if(a.inst===undefined) ch=true; }
                        else if(e.fn==='bassOn'){ tim=tmix(tim,3,a.inst); if(a.inst==null) bs=true; }
                        else if(e.fn==='drum') tim=tmix(tim,4,a.kit); } }
  const id=laneOf(layer), ver=id==null?0:(laneEditVer.get(id)||0);
  const v=n+'|'+first+'|'+last+'|'+sum.toFixed(6)+'|e'+ver+'|'+tonic+','+aRef+','+loop.bpm
         +'|'+(noSc?scaleIdx+','+tunedFrom+','+(seventh?1:0)+','+droneNonOct():'-')+'|'+(ld?leadIdx:'-')+','+(ch?chIdx:'-')+','+(bs?bassIdx:'-')+'|i'+tim;
  frzSigMemo.set(layer, v);
  return v;
}
/* ⛳ СОСТОЯНИЕ ДОРОЖКИ ДЛЯ ПОКАЗА И ДЛЯ ЗВУКА: 'none' | 'fresh' | 'stale'.
   ⛔ ЗВУК ГАТИТСЯ НА «ЗАМОРОЖЕНА И СВЕЖА», А НЕ НА «ЗАМОРОЖЕНА» — устаревшая дорожка обязана
   ВЕРНУТЬСЯ К СВОИМ СОБЫТИЯМ, а не замолчать и не играть старое как ни в чём не бывало. */
function freezeState(layer){
  const f=frzOf(layer); if(!f||f.drop) return 'none';   // drop (A2b): разморожена НА ХОДУ — для показа и для событий её уже нет; запись живёт лишь до шва, пока буфер доигрывает (см. frzLeave)
  return f.sig===freezeSig(layer) ? 'fresh' : 'stale';
}
/* ⛳ ЕСТЬ ЛИ У ДОРОЖКИ ВЗЯТОЕ БЕЗ ЗАХВАТА (F5) — и прикалываем его, раз уж морозим.
   ⚠️ ЭТО РЕАЛЬНАЯ СМЕНА ПОВЕДЕНИЯ, КОТОРАЯ ДО СИХ ПОР ПРОИСХОДИЛА МОЛЧА, В ДВУХ МЕСТАХ: дорожка без
   захвата шла ЗА ЖИВОЙ ЦЕПЬЮ, и первый же снимок (добавление эффекта в редакторе — autCaps, S1; а теперь
   и заморозка) ПРИКАЛАЧИВАЕТ её к цепи в том виде, в каком та стоит В ЭТОТ МИГ. Звучать она
   продолжает ровно так же, как секунду назад, — но живые ручки до неё больше не дотянутся.
   ⛳ Единственный сегодняшний источник таких взятых — ВСТАВКА В РЕДАКТОРЕ (editInsertHit/editInsertBass
   заводят свой editTake и takeCapStart не зовут).
   ⛳ S1 — ПРИКАЛЫВАЕМ, ТОЛЬКО ЕСЛИ У ДОРОЖКИ НЕТ ЗАХВАТА ВОВСЕ, и тогда ОДНОМУ, самому раннему взятому. ⚠️ ИСПРАВЛЕНО: прежде
   снимок живой цепи получало КАЖДОЕ взятое без захвата — и вставка в редакторе посреди записанной дорожки после ❄ переводила с
   доли вставленной ноты ВСЮ РОЛЬ (на каждой её дорожке — цепи принадлежат роли) на то, как стоят живые ручки: снимок взятого
   вступает с его первой доли (fxLaneMerge). Взятое без захвата внутри захваченной дорожки играет цепью дорожки и захвата не
   получает (см. fxLaneMerge: раньше всех захваченных — заимствует снимок самого раннего из них). ⛔ Живая цепь здесь читается
   лишь для дорожки, у которой своей цепи нет ни в одном взятом, — она и шла за живой цепью.
   Возвращаем true, если что-то приколотили, — вызывающий скажет об этом ОДИН раз. */
function freezePinCaptures(layer){
  const Ts=autTakesOf(layer); if(!Ts.length) return false;
  if(Ts.some(T=>takeFx.has(T.tk))) return false;             // у дорожки есть своя цепь — прикалывать нечего
  const E=autEarliest(Ts); takeCapStart(E.tk);
  return takeFx.has(E.tk);
}
/* ⛳ БИЛЕТ ЗАМОРОЗКИ (A2) — что именно рендер берётся заморозить, снятое ДО рендера: слой, ID дорожки и
   подпись. Рендер идёт секунды; за это время в дорожку могут влить дубль, отменить взятое (и номер слоя
   уйдёт ДРУГОЙ дорожке — правило #27 с новой стороны), сменить тонику. Прежде подпись снималась ПОСЛЕ
   рендера, и старый материал вставал бы как свежий — неверная музыка, найти которую нельзя.
   `?? laneNew` — та же самопочинка, что у переключателей дорожки (довод — у toggleLaneMute). */
function freezeTicket(layer){
  if(layer==null) return null;
  const id=laneOf(layer) ?? laneNew(layer);
  return { layer, id, sig:freezeSig(layer) };
}
/* Поставить отрендеренный буфер. Возвращает true, либо СЛОВО-причину отказа ('lane' — номер слоя теперь
   у другой дорожки или её нет; 'sig' — дорожка изменилась за время рендера; 'engine' — нет движка).
   ⛔ «Раз уж посчитали — поставим» НЕЛЬЗЯ НИКОГДА: это неверная музыка, помеченная свежей. */
function freezeSet(ticket, rendered){
  if(!AC||!ticket||!rendered||!rendered.buf) return 'engine';
  const {layer, id}=ticket;
  if(laneOf(layer)!==id) return 'lane';
  if(freezeSig(layer)!==ticket.sig) return 'sig';
  freezeDrop(id);                                   // перезаморозка: старый буфер и его узлы уходят целиком
  const bus=makeFrozenBus(); if(!bus) return 'engine';
  /* evRun — «в этом прогоне дорожку сейчас играют СОБЫТИЯ». Играем — да: планировщик на ближайшем
     отрезке сделает шов ВХОДА (frzEnter). Стоим — нет: пуск взведёт буфер как обычно. */
  const f={ id, layer, buf:rendered.buf, startSec:rendered.startSec, endSec:rendered.endSec,
            tailSec:rendered.tailSec, pinned:rendered.pinned, sig:ticket.sig, bus, nodes:[], armedRep:null,
            evRun:loop.on, mark:null, drop:false };
  frozen.set(id, f);
  frzGain(id);                                      // приглушение/соло действуют сразу
  return true;
}
/* ═══ ⛳ ДВА ШВА — ВХОД В БУФЕР И ВЫХОД ИЗ НЕГО (A2 и A2b). ОБА ЗОВЁТ ТОЛЬКО ПЛАНИРОВЩИК. ═══
   ⛳ ОДНО ПРАВИЛО НА ОБА НАПРАВЛЕНИЯ: ШОВ СТОИТ НА ГОРИЗОНТЕ ЗАПЛАНИРОВАННОГО — в начале отрезка `lo`
   планировщика, в миг T = t0 + (lo+сдвиг прохода)·spb. Всё, что до шва, УЖЕ поставлено тем, кто владел
   дорожкой до него; всё, что после, — поставит новый владелец. Поэтому ничего не надо ни отменять, ни
   переписывать заново, а курсоры не трогаются вовсе (правило #28 цело: сброса нет, потому что нечего
   сбрасывать — планировщик и так идёт вперёд с `lo`).
   ⛳ ПОЧЕМУ ИМЕННО ПЛАНИРОВЩИК, А НЕ МЕСТО СОБЫТИЯ. Дорожка покидает буфер тремя путями — устаревает от
   правки (запись в неё, отмена взятого), устаревает от тоники/A4/темпа, её размораживают — и входит в
   него двумя (заморозили на ходу, снова стала свежей). Ловить каждое в месте, где оно случилось, значило
   бы пять копий шва. Планировщик же на КАЖДОМ отрезке спрашивает одно: «кто сейчас должен звучать за эту
   дорожку — буфер или события?» — и если ответ сменился, шьёт. Один путь на все выходы и один на все входы. */
/* ВХОД (A2): до шва дорожку играли события — их голоса гасим ПО ВРЕМЕНИ ШВА. Релиз делает
   cancelScheduledValues(T), значит атаки аккордов/баса, уже поставленные в окно ПОСЛЕ шва, тоже снимаются.
   Удары, поставленные в окно, лежат ДО шва, а буфер играет только ПОСЛЕ — не двоится ничто. Соло и дрон
   идут «почти сейчас» через fireNear, им шов — отметка f.mark (проход и песенная доля шва): события слоя
   раньше неё ещё играют, позже — нет, а tick, дойдя до неё, гасит соло-голоса слоя (frzNearDone). ⛔ Правило #20: только
   голоса ДОРОЖКИ ('loop:N'/'bassloop:N'/'leadloop:N'), живой 'latch' не трогаем. */
function frzEnter(f, lo, T, rep){
  releaseLoopLayersAt(T, f.layer, 'pool');
  f.mark={ kind:'enter', rep, beat:lo, at:T }; f.evRun=false;
  droneSync(T, FRZ_DRONE_TC);
}
/* ⛳ ВЫХОД (A2b) — ЗЕРКАЛО ВХОДА. Буфер доигрывает ДО шва и уходит рампой FRZ_FADE (та же, что у любого
   обрыва: stop() насухо щёлкает); события берут дорожку С шва.
   ⛳ ДОГОНЯЛКА — ТА САМАЯ, ЧТО У ВХОДА В ПЕСНЮ НЕ С НАЧАЛА (chasePlay/chaseFor), второй не заводим: шов —
   это и есть вход в середину песни для одной дорожки. Она поднимает удержанные аккорды, бас и соло к доле
   `lo` по времени T, каждый со своим замороженным ладом и картой эффектов (правило #7), — в НОВОЙ тонике,
   если выход случился из-за неё: частоту выводит ENG из живой тоники. `only` ограничивает её этой дорожкой.
   ⛳ УДАРЫ В ОКНЕ ОПЕРЕЖЕНИЯ НЕ ТЕРЯЮТСЯ И НИЧЕГО НЕ ПЕРЕКЛАДЫВАЕТСЯ: окно до шва расписано буфером (события
   дорожки туда не ставились — она была заморожена), и буфер его ДОИГРЫВАЕТ; с шва события ставит обычный
   проход планировщика, который как раз начинается с `lo`. Прежде буфер глушили «сейчас», а события шли с
   горизонта — отсюда и дыра до ~300 мс.
   ⚠️ УЗЕЛ-ХВОСТ НЕ ОБРЫВАЕМ: если к шву буфер уже за концом музыки (endSec), в нём звучит только хвост цепи —
   пусть доиграет, как хвост живых голосов (тот же довод, что у шва скобы в frzArm).
   ⚠️ ЦЕНА, названная: хвосты реверба/делея от нот ДО шва жили в буфере — живая цепь этих нот не слышала,
   поэтому на шве «комната» дорожки начинается заново. Для сухой дорожки — ничего. */
function frzLeave(f, lo, T, rep){
  for(const n of f.nodes.slice()){
    const pos = n.off + (T - n.at);                 // где в буфере узел окажется на шве
    if(pos < f.endSec - 1e-6) frzKill(n, T);        // ещё музыка — уходим рампой в миг шва; иначе хвост доигрывает сам
  }
  f.armedRep=null; f.mark={ kind:'leave', rep, beat:lo, at:T }; f.evRun=true;
  chasePlay(lo, T, false, f.layer);                 // аккорды и бас — ДО событий этого отрезка (их поставит цикл сразу после)
  chasePlay(lo, T, true,  f.layer);                 // соло — по явному времени шва, как при пуске (startTransport)
  droneSync(T, FRZ_DRONE_TC);
}
/* ⛳ ОТМЕТКА ШВА ДЛЯ fireNear — f.mark = {kind:'enter'|'leave', rep, beat, at}. Соло и дрон идут «почти
   сейчас», а не по планировщику, поэтому им шов нужен явной отметкой.
   ⛳ СРАВНИВАЕМ ПАРУ (проход, песенная доля) СОБЫТИЯ с парой шва, а не часы с часами. По часам: тик идёт раз
   в ~25 мс, и тик, пересекающий шов, потерял бы (вход) или удвоил бы (выход) ноту, начатую в последние
   миллисекунды перед ним. По одной доле: шов стоит на ГОРИЗОНТЕ, и под крутящейся скобой он бывает уже в
   СЛЕДУЮЩЕМ проходе, пока играет ещё этот, — голая доля шва тогда меньше доли событий хвоста прохода, и
   порядок читался бы наоборот. Номер прохода (rgnReps, как у планировщика) снимает это целиком.
   ⚠️ `at` — часы шва: страховка, а не правило (см. frzNearDone).
   Возвращает true — событие слоя играть НЕ надо (его играет буфер). */
function frzSkipNear(ev, rep){
  const f=frzOf(ev.layer); if(!f) return false;
  const mk=f.mark;
  if(mk){ const before = rep<mk.rep || (rep===mk.rep && ev.t<mk.beat-1e-9);
          return mk.kind==='leave' ? before : !before; }       // выход: до шва — буфер; вход: с шва — буфер
  return freezeState(ev.layer)==='fresh';                      // без шва: свежая — буфер, устаревшая/уходящая — события
}
/* Тик дошёл до (прохода rep, доли p): снять отметки, чей шов пройден. Вход — погасить соло-голоса слоя
   (дальше их играет буфер); выход — если это была разморозка, отпустить запись реестра.
   ⚠️ СТРАХОВКА ПО ЧАСАМ: смена скобы в те ≤300 мс, что шов ждёт, переназначает номера проходов — и отметка
   могла бы не дождаться своей пары никогда (выход тогда вечно глушил бы соло дорожки). Поэтому шов, чьё
   время прошло с запасом, снимается в любом случае. */
const FRZ_MARK_GRACE=0.25;
function frzNearDone(rep, p){
  const now=AC.currentTime;
  for(const f of frozen.values()){ const mk=f.mark; if(!mk) continue;
    if(!(rep>mk.rep || (rep===mk.rep && p>=mk.beat-1e-9) || now>=mk.at+FRZ_MARK_GRACE)) continue;
    f.mark=null;
    if(mk.kind==='enter') releaseLoopLayersAt(undefined, f.layer, 'lead');
    else if(f.drop) frzRetire(f);
  }
}
/* Снять запись реестра. ⛳ ШИНУ ОТКЛЮЧАЕМ С ОТСРОЧКОЙ: мгновенный disconnect обрывал рампу FRZ_FADE,
   которую frzKill только что поставила, — то есть щёлкал ровно так, как рампа и должна была не дать.
   Отсрочка по стенным часам здесь законна: это уборка, а не музыкальное время. */
function frzRetire(f){
  if(frozen.get(f.id)!==f) return;
  frozen.delete(f.id);
  const b=f.bus; setTimeout(()=>{ try{ b.disconnect(); }catch(e){} }, 80);
}
function freezeDrop(id){
  const f=frozen.get(id); if(!f) return false;
  frzStopOne(f, 0);                                 // 0 — «сейчас»: рампа FRZ_FADE, затем отсроченное отключение шины
  frzRetire(f);
  return true;
}
/* ⛳ РАЗМОРОЗКА ТРОГАЕТ РОВНО ОДНУ ДОРОЖКУ (ошибка «разморозил одну — разморозились все» жила в подписи —
   см. laneEditVer). Стоим, или буфер сейчас не владеет дорожкой (устарела) — снимаем сразу, шить нечего.
   Играем и буфер звучит — только ПОМЕЧАЕМ: запись сразу перестаёт считаться заморозкой (freezeState →
   'none': индикатор, кнопка и события видят разморозку немедленно), а шов ВЫХОДА делает планировщик на
   ближайшем отрезке — тем же frzLeave, что и устаревание. Запись реестра живёт до шва и уходит в
   frzNearDone (или на любой остановке — frzStopOne). */
const unfreezeLayer=layer=>{
  const id=laneOf(layer); const f=id==null?null:frozen.get(id); if(!f||f.drop) return false;
  if(loop.on && f.armedRep!=null){ f.drop=true; return true; }
  freezeDrop(id); droneSync(); return true;
};
const frozenLayers=()=>[...frozen.values()].filter(f=>!f.drop).map(f=>f.layer);   // A2b: уходящая на шве — уже не в списке
const frozenInfo=layer=>{ const f=frzOf(layer); return f?{ layer:f.layer, state:freezeState(layer), seconds:+f.buf.duration.toFixed(3),
  startSec:f.startSec, endSec:+f.endSec.toFixed(3), tailSec:+f.tailSec.toFixed(2), pinned:f.pinned, nodes:f.nodes.length }:null; };

/* ПРИГЛУШЕНИЕ/СОЛО — ОДНО ПРИСВАИВАНИЕ. ⚠️ У буфера нет голосов, которые можно отпустить, поэтому
   обычный путь (releaseLoopLayersAt) до него не дотягивается: слышимость проверяется ПОСОБЫТИЙНО
   внутри планировщика, а событий у замороженной дорожки там нет. Отсюда своя проверка — и звать её
   надо оттуда же, откуда бьёт живое приглушение (laneHush). */
function frzGain(id){
  const f=frozen.get(id); if(!f) return;
  const on=laneAudible(f.layer);
  f.bus.gain.setTargetAtTime(on?1:0, AC.currentTime, 0.01);   // не рубильник: щелчок на приглушении читался бы поломкой
}
const frzGainAll=()=>{ for(const id of frozen.keys()) frzGain(id); };

/* ═══ УЗЛЫ: ЖИЗНЕННЫЙ ЦИКЛ ═══
   ⛳ СКОЛЬКО ИХ ЖИВЁТ: на дорожку — не больше ДВУХ одновременно, и только на шве повтора. Обычно один.
   Рождение: пуск транспорта, снятие паузы, перемотка и КАЖДЫЙ проход скобы.
   Смерть: пауза, паника, конец песни, перемотка, разморозка, удаление дорожки — и естественный конец
   буфера, когда его не обрывали.
   ⚠️ ЗАТУХАНИЕ ПРИ ОБРЫВЕ: stop() режет насухо, то есть ЩЁЛКАЕТ. Поэтому у каждого узла свой гейн, и
   обрыв — это короткая рампа FRZ_FADE, а уже потом stop. Естественный конец рампы не требует. */
const FRZ_FADE=0.006;
function frzStart(f, songBeat, atSec){
  /* СМЕЩЕНИЕ В БУФЕРЕ: сколько секунд от начала МУЗЫКИ уже прошло, плюс «разгон», который рендер
     положил перед первой нотой. Вот и вся догонялка. */
  const spb=60/loop.bpm;
  let off=f.startSec + (songBeat - frzT0(f))*spb;
  /* ⚠️ ОПОЗДАВШИЙ ТИК (заблокированный поток) — двигаем НЕ ТОЛЬКО время старта, НО И СМЕЩЕНИЕ. Сдвинь
     мы одно время, дорожка поехала бы назад ровно на величину опоздания и разошлась бы с живыми. */
  let at=atSec; const nowT=AC.currentTime;
  if(at<nowT){ off+=nowT-at; at=nowT; }
  /* ⛔ ВХОД ДО ПЕРВОЙ НОТЫ ДОРОЖКИ (найдено при A2): смещение выходит ОТРИЦАТЕЛЬНЫМ, и прежний
     start(at, max(0,off)) пускал буфер С НАЧАЛА И СРАЗУ — дорожка, записанная с 3-го такта, играла с 1-го.
     Отрицательное смещение значит «ещё рано»: старт откладываем на столько же, смещение — ноль. */
  if(off<0){ at-=off; off=0; }
  if(off>=f.buf.duration) return null;                    // вошли за конец буфера — играть нечего
  const src=AC.createBufferSource(); src.buffer=f.buf;
  const g=AC.createGain(); g.gain.value=1;
  src.connect(g); g.connect(f.bus);
  src.start(at, Math.max(0,off));
  const n={src,g,killAt:null,at,off};              // at/off (A2b): где узел будет в буфере в любой миг — frzLeave отличает по ним музыку от хвоста
  src.onended=()=>{ const i=f.nodes.indexOf(n); if(i>=0) f.nodes.splice(i,1); try{ g.disconnect(); }catch(e){} };
  f.nodes.push(n);
  return n;
}
/* ПЕРВАЯ ДОЛЯ ДОРОЖКИ — та же, от которой рендер считал раскладку. ⚠️ Берём из СОБЫТИЙ, а не храним:
   события живы и неизменны, а лишняя копия числа однажды разъехалась бы с ними. */
function frzT0(f){
  let t0=null;
  for(const e of events) if(e.layer===f.layer && (t0===null||e.t<t0)) t0=e.t;
  return t0===null?0:t0;
}
function frzKill(n, atSec){
  if(!n||n.killAt!=null) return;
  const t=Math.max(atSec==null?AC.currentTime:atSec, AC.currentTime);
  n.killAt=t;
  try{
    n.g.gain.cancelScheduledValues(t);
    n.g.gain.setValueAtTime(n.g.gain.value,t);
    n.g.gain.linearRampToValueAtTime(0,t+FRZ_FADE);     // де-щелчок: рубильник слышен как поломка
    n.src.stop(t+FRZ_FADE);
  }catch(e){}
}
/* Отметки швов (A2/A2b) — сбрасываем: любой останов/перезапуск перевзводит дорожку целиком, недошитый шов
   теряет смысл (голоса гасят сами остановки). Уходящая на шве (разморожена на ходу) — уходит совсем. */
function frzStopOne(f, atSec){ for(const n of f.nodes.slice()) frzKill(n, atSec); f.armedRep=null; f.mark=null;
  if(f.drop) frzRetire(f); }
/* ⛳ ЕДИНАЯ ДВЕРЬ ОСТАНОВКИ — её и зовут пауза, паника, конец песни, перемотка и очистка. */
function frzStopAll(atSec){ for(const f of frozen.values()) frzStopOne(f, atSec); }

/* ⛳ ВЗВЕСТИ ИСТОЧНИКИ НА ТЕКУЩЕМ ПРОХОДЕ — зовётся ИЗ ПЛАНИРОВЩИКА, тем же временем и тем же
   сдвигом прохода, каким он ставит события слоёв (правило #15: второго пути таймирования нет).
   `rep` — номер прохода: сменился, значит начался новый круг и нужен НОВЫЙ узел (старый одноразов).
   ⛳ ШОВ: старый узел НЕ ОБРЫВАЕМ — он доигрывает СВОЙ ХВОСТ поверх начала следующего прохода. Ровно
   это живая дорожка делает релизами голосов, которые звучат через шов. ⛔ Складывать хвост нельзя,
   только перекрывать.
   ⚠️ ЧЕСТНО О ГРАНИЦАХ ПЕРЕКРЫТИЯ. В буфере после конца музыки (endSec) лежит ХВОСТ, и только он.
   Если шов приходится на конец материала (а так стоит скоба по умолчанию — она следует за материалом),
   то всё, что осталось в буфере, и есть хвост: отпускаем узел доигрывать до конца, обрывать нечего.
   Если же скоба — КУСОК середины, то за швом в буфере лежит СЛЕДУЮЩАЯ МУЗЫКА, а не хвост; играть её
   поверх нового прохода было бы неправдой, поэтому такой узел глушим с короткой рампой. Хвоста в этом
   случае не будет — он не существует в линейном аудио нигде, кроме конца дорожки. Названо, а не скрыто. */
function frzArm(f, songBeat, atSec, rep){
  const prev=f.nodes[f.nodes.length-1];
  if(prev){
    const spb=60/loop.bpm;
    const posAtSeam=f.startSec + (songBeat - frzT0(f))*spb;   // где в буфере окажется шов
    const musicEnd=f.endSec;                                   // конец МУЗЫКИ в координатах буфера
    if(posAtSeam < musicEnd - 1e-6) frzKill(prev, atSec);       // за швом ещё музыка — перекрывать ею нельзя
    /* иначе: за швом только хвост — пусть доигрывает сам, узел умрёт по onended */
  }
  f.armedRep=rep;
  frzStart(f, songBeat, atSec);
}
/* ⛔ frzArmAll УДАЛЁН (A2). Его единственный вызов — заморозка на ходу — перезапускал ВСЕ замороженные
   дорожки (обрыв с рампой и новый узел через 20 мс) ради одной новой. Пуск, снятие паузы и перемотка
   его не звали никогда: там взводит планировщик (armedRep=null). Заморозка на ходу — шов ВХОДА frzEnter
   из планировщика, одна дорожка. */

/* ═══ РЕДАКТОР ДОРОЖКИ: ОДИН ФЛАГ — ВСЕ ОТКАЗЫ (слайс S5.0) ═══
   ⛳ ФЛАГ ЖИВЁТ ЗДЕСЬ, А НЕ В ui, И ЭТО НЕСУЩЕЕ. «Редактор открыт» — условие, при котором ЗАПИСЬ
   невозможна, а запись держит recorder. Спрячь флаг в ui — и каждый новый вход (кнопка ●, рука-лупер,
   будущая педаль, урок) обязан был бы ВСПОМНИТЬ про отказ. Здесь про него не помнит никто: onRec
   спрашивает один раз, и этого хватает всем настоящим и будущим путям.
   ⛔ АДРЕС ДОРОЖКИ — id, А НЕ НОМЕР СЛОЯ (правило #27): номера переиспользуются (⤺ освобождает, следующая
   запись берёт тот же), и редактор, открытый «на слое 2», после отмены смотрел бы на ЧУЖУЮ дорожку с тем
   же номером. id не выдаётся дважды, поэтому протухший id может только «никуда не указывать» — тогда
   editLayer() отдаёт null, и редактор честно говорит «дорожки больше нет».
   `laneOf(layer) ?? laneNew(layer)` — та же самопочинка, что у toggleLaneMute/toggleArm, и безопасна по
   той же причине: ОТСУТСТВИЕ записи не может нести устаревший id, затирать нечего.
   ⚠️ ОТКРЫТИЕ ГЛУШИТ ЗВУК, И ДВУМЯ РАЗНЫМИ ПУТЯМИ — оба уже существуют, новых не заводим:
     транспорт ИДЁТ → onLoop() — обычная ПАУЗА: она закрывает открытые ноты в записи (recAllOff) и гасит;
     транспорт СТОИТ → softAllOff() — иначе ЗАЩЁЛКНУТЫЙ аккорд звенел бы дальше: пальцы разомкнуты,
       watchdog жестов его не снимает (endPinch в защёлке аккорд не гасит — см. gestures).
   ⛔ Запись и запись клипа — отказ. Открывать редактор поверх них значит редактировать то, что прямо
   сейчас меняется под руками (запись) или снимать в файл служебный экран (клип). */
let editLane=null;                                   // id ДОРОЖКИ, открытой в редакторе (не номер слоя!), или null
const editIsOpen=()=>editLane!=null;
const editLayer=()=>laneLayerOf(editLane);           // НОМЕР СЛОЯ открытой дорожки или null, если её больше нет
function editOpen(layer){
  if(!AC||recording||activeKind()||layer==null) return false;
  const id=laneOf(layer) ?? laneNew(layer);
  if(loop.on) onLoop(); else softAllOff();
  editLane=id; editHist=[]; editFuture=[]; editTake=0;   // S5.1/S5.3: сессия правки начинается с чистыми историей И будущим
  return true;
}
function editClose(){ editLane=null; editHist=[]; editFuture=[]; editTake=0; }
/* Сменить открытую дорожку, не закрывая редактор (чип дорожки в панели). Звук уже заглушён открытием. */
function editSetLayer(layer){
  if(editLane==null||layer==null) return false;
  const id=laneOf(layer); if(id==null) return false;
  editLane=id; editHist=[]; editFuture=[]; editTake=0;   // S5.1/S5.3: история И будущее — про ТУ дорожку, что на экране; отмена/возврат «вслепую» на другой были бы враньём
  return true;
}
/* ═══ ПРАВКА УДАРОВ И ОТМЕНА ПРАВОК (слайс S5.1) ═══
   ⛳ ТРЕТЬЕ МЕСТО РОЖДЕНИЯ СОБЫТИЙ (после push и loadArrangement) — и обязано соблюдать ровно то же:
   абсолютное время, tk на КАЖДОМ событии, ОДИН schedInvalidate на правку с сортировкой ПЕРЕД ним
   (правило #28), удаление — только через compactEvents (массив events — стабильная ссылка, её читает draw).
   ⛔ push СЮДА НЕ ГОДИТСЯ, и это не лень: он берёт время у часов AudioContext, квантует живой сеткой и
   пишет только при recording. У правки время приходит от ПАЛЬЦА, а не от часов.
   ⛳ ПОЧЕМУ ПЕРЕНОС УДАРА НЕ МОЖЕТ НАРУШИТЬ ПОРЯДОК, который стережёт S4.3: тот порядок обязателен ВНУТРИ
   КЛЮЧА ВЛАДЕЛЬЦА — там, где «вкл» и «выкл» обязаны идти по очереди. У удара владельца нет вовсе
   (chaseRole('drum') → null), пары нет, ENG.drum сам себе начало и конец — «раньше своего вкл» лечь
   физически нечему. Остаётся ОДНО требование — отсортированность массива, и её держит editCommit.
   ⚠️ СОБЫТИЕ ПРАВИМ, НЕ ПЕРЕСОЗДАВАЯ. Объект события — РУЧКА: за него держатся выделение, история отмены и
   спаривание нот (songNotes.head). Поэтому t меняем на месте, а нагрузку кладём НОВЫМ объектом — прежний
   уходит в историю ЦЕЛИКОМ. Так обратный ход не может растерять поля: sc/sev/tk/jam едут вместе с объектом,
   а не переписываются по одному (у удара sc/sev мертвы — ENG.drum контекста не читает, — но формат события
   один на все роли, и ломать его здесь нечем).
   ⛳ ОТМЕНА ПРАВОК — СВОЯ, И ЭТО НЕ ВТОРОЕ ⤺. ⤺ снимает ВЗЯТОЕ (целый дубль записи), ↶ — ОДНУ правку.
   Спутать их нажатием нельзя: пока редактор открыт, ⤺ с экрана убран (S5.0), а ↶ живёт только в редакторе.
   ⛳ ИСТОРИЯ ЖИВЁТ РОВНО СЕССИЮ ПРАВКИ (чистят открытие, закрытие и смена дорожки). Причина не в экономии
   памяти: ВНЕ редактора песню меняют запись, ⤺, ✕ и подложка, и обратный ход, сохранённый «на потом»,
   однажды указал бы на событие, которого в песне уже нет. Закрыл редактор — история закрыта вместе с ним. */
/* Громкость вставленной в редакторе ноты, когда в дорожке спросить не у кого: прежние 0.8, пересчитанные в новую шкалу
   (VOL-2b, config.volFromOld) — чтобы вставка звучала так же громко, как до стандартизации (удар и бас: √0.86 ≈ 0.927). */
const editDefVol=role=>volFromOld(role,0.8);
/* ⛳ ИСТОРИЯ ДВУНАПРАВЛЕННАЯ (S5.3). ⚠️ РЕДО — НЕ ЗЕРКАЛО ОТМЕНЫ, и запись не симметрична: отмене хватало
   ОБРАТНОГО хода, а возврату нужен ПРЯМОЙ. Поэтому запись переноса несёт ОБА состояния (from/to), а
   удаление и вставка симметричны сами по себе — там хватает ССЫЛКИ НА СОБЫТИЕ, и в обе стороны едет ОДИН
   И ТОТ ЖЕ объект (это несущее: и спаривание нот, и выделение держатся за сам объект, а не за копию).
   ⛔ ОБРЫВ БУДУЩЕГО. Отменил три правки, сделал НОВУЮ — отменённое больше недостижимо: оно описывает песню,
   которой уже нет. Не выбрось мы его здесь, ↷ применил бы старый ход к изменившемуся материалу, и это НЕ
   упало бы с ошибкой — просто удар появился бы там, куда его никто не ставил. Поэтому ЕДИНСТВЕННЫЙ писатель
   истории — editPush, и он же чистит будущее: забыть про обрыв невозможно, потому что мимо него не пройти.
   Будущее живёт ровно столько же, сколько история (открытие/закрытие/смена дорожки) — по той же причине:
   ссылка на событие, пережившая сессию, однажды указала бы в пустоту. */
let editHist=[], editFuture=[], editTake=0;   // сделанное · отменённое (ждёт ↷) · номер взятого для ВСТАВОК сессии
const editCanUndo=()=>editHist.length>0;
const editCanRedo=()=>editFuture.length>0;
const editPush=u=>{ editHist.push(u); editFuture.length=0; };   // НОВАЯ правка обрывает ветку отменённого
/* ⛳ СОСТАВНАЯ ПРАВКА (E1) — ОДНА запись истории из НЕСКОЛЬКИХ ходов уже существующих видов ('move', 'ins',
   'del', 'timbre', ходы полосы автоматизации). Вперёд — по порядку, назад — в ОБРАТНОМ (editApply, 'batch'),
   сортировка и сброс курсоров — ОДИН раз на всю правку (editCommit, правило #28).
   ⛳ ЗАЧЕМ ИМЕННО ТАК: у человека одна ↶, и она обязана снимать ОДНО действие, из скольких бы событий оно ни
   состояло — перенос ноты целиком (E1), отделение сегмента глиссандо (E2: «выкл» слева + ноты под свежим
   ключом + «вкл» справа), затем правка соло и аккордов. Нового вида хода для каждой из них не заводим:
   они собираются из тех, что уже умеют ходить в обе стороны.
   ⚠️ list строит ВЫЗЫВАЮЩИЙ, и ходы в нём ещё НЕ ПРИМЕНЕНЫ (у 'move' — оба состояния, from и to): применяет их
   editBatch тем же editApply, которым потом ходят ↶/↷, — вперёд и назад по одному пути, а не по двум.
   Вызывающий уже прошёл editGuard. */
function editBatch(list){
  if(!list||!list.length) return false;
  for(const u of list) editApply(u,false);
  editPush(list.length===1 ? list[0] : { kind:'batch', list });   // один ход — сам ход, без обёртки: в истории та же запись, что дала бы прежняя одиночная правка
  editCommit(); return true;
}
/* Дорожка ПОДЛОЖКИ (🎵): её события помечены ev.jam, и clearJam снимает их ЦЕЛИКОМ. Правка внутри такой
   дорожки пережила бы снятие подложки осиротевшим обрывком — поэтому подложка в S5.1 ТОЛЬКО ЧИТАЕТСЯ.
   ⚠️ Аранжировка из ⚙-панели метки НЕ несёт (известное расхождение, см. отчёт) и потому правится как
   обычная запись — это честно: clearJam её и не тронет. */
const laneIsBacking=layer=> layer!=null && events.some(e=>e.layer===layer&&e.jam);
const editBackingOpen=()=>laneIsBacking(editLayer());
/* ЕДИНЫЙ ВХОД ВСЕХ ПРАВОК: редактор открыт, дорожка жива и не подложка, транспорт ОСТАНОВЛЕН.
   ⚠️ ПАУЗУ СТАВИМ ЗДЕСЬ, А НЕ В ui: правка при идущем транспорте легла бы под уже запланированные в окно
   опережения события и под звучащие голоса. onLoop — обычная пауза, а следующий ▶ поднимет состояние
   обычной догонялкой (chasePlay в startTransport) — уже с учётом правки. */
/* ⛳ T5: backingOk — ЕДИНСТВЕННОЕ послабление: ЗАМЕНА ТЕМБРА подложке разрешена (решение пользователя №2).
   Она переписывает тембр у всех событий дорожки и не рождает обрывков — clearJam снимает их все, ev.jam
   цел. Ноты подложки по-прежнему только читаются: все прочие правки зовут editGuard() без флага. */
function editGuard(backingOk){
  if(!AC||!editIsOpen()||editLayer()==null) return false;
  if(!backingOk && editBackingOpen()) return false;
  if(loop.on) onLoop();
  return true;
}
function editCommit(){ events.sort((x,y)=>x.t-y.t); schedInvalidate(); takeFxTouch(); laneEditTouch(); }   // A2: laneEditTouch — устаревает ТОЛЬКО правленая дорожка, а не все замороженные   // ОДИН раз на правку: сортировка ДО сброса — он объявляет массив отсортированным (правило #28). O-4: takeFxTouch — от времён СОБЫТИЙ зависит доля старта взятого, то есть база полосы автоматизации и лента переигровки; двигать ноту, не освежив их, значило бы показывать и играть прежнюю базу
/* Кит и громкость вставленного удара — у БЛИЖАЙШЕГО удара ЭТОЙ дорожки («как здесь принято»), иначе живой
   кит и средняя громкость. Обход O(n) — один на вставку, не на кадр. */
function editDrumDefaults(layer,t){
  let best=null,bd=Infinity;
  for(const e of events) if(e.layer===layer&&e.fn==='drum'){ const d=Math.abs(e.t-t); if(d<bd){ bd=d; best=e; } }
  return { kit: best&&best.a.kit!=null ? best.a.kit : drumKitIdx,
           vol: best&&best.a.vol!=null ? best.a.vol : editDefVol('dr') };
}
function editMoveHit(ev,t,row){
  if(!editGuard()||!ev||ev.fn!=='drum'||ev.layer!==editLayer()) return false;
  const from={t:ev.t, a:ev.a}, to={t:Math.max(0,t), a:{...ev.a, row}};   // ОБА состояния: from для ↶, to для ↷
  editPush({ kind:'move', ev, from, to });
  ev.t=to.t; ev.a=to.a;
  editCommit(); return true;
}
function editDeleteHit(ev){
  if(!editGuard()||!ev||ev.fn!=='drum'||ev.layer!==editLayer()) return false;
  if(!compactEvents(e=>e===ev)) return false;
  editPush({ kind:'del', evs:[ev] });                      // держим САМИ объекты — и ↶, и ↷ возвращают/убирают ровно их
  editCommit(); return true;
}
/* ═══ БАС: ПРАВКА ПО СЕГМЕНТАМ (слайс S5.5; НЕЗАВИСИМЫЕ НОТЫ — E1/E2) ═══
   ⛳ ПОЧЕМУ НЕ «НОТА». У бас-ноты ОДИН владелец голоса (в ведущем режиме — один на дорожку; в полифоническом у каждой
   одновременной ноты свой, по a.v), и смена высоты — это ВЕДЕНИЕ (bassSet),
   а не новая нота: бас-линия, сыгранная одним непрерывным движением, — это ОДНА нота songNotes на
   много высот. Редактировать её как одну — значит показать многоминутную полосу на одной высоте.
   Единица правки здесь — СЕГМЕНТ: событие, которое ЗАДАЁТ высоту («вкл» или ведение со сменой ступени),
   и промежуток до следующей такой смены. Вывод сегментов — songSegs, рядом с songNotes.
   ⛔ ПОРЯДОК ВНУТРИ КЛЮЧА ВЛАДЕЛЬЦА — вот чем бас опаснее удара (у того ключа нет вовсе). Все события
   одной бас-ноты И все ноты того же k делят ключ 'bassloop:N[:k]', а движок требует, чтобы время внутри
   ключа не шло назад: переставь ведение за соседа — и на переигровке ноты поменяются местами, а «выкл»
   закроет чужую.
   ⛳ S0 (правка соло и аккордов): функции ниже больше не басовые — роль берут из таблицы EDIT_ROLE (чуть ниже), и та же
   машинерия отделения служит соло и аккордам. С S2 правимы и аккорды (state.ROLL_EDITABLE); соло — слайсом S4, до него сюда приходят
   бас и аккорды. Слово «бас» в доводах ниже — это история того, для кого их писали; закон тот же у всех трёх ролей.
   ⛳ E2: ЗАКОН НЕЗАВИСИМОСТИ. Прежде порядок стерегли ЗАЖИМОМ — событие нельзя было увести за соседа по ключу, —
   и именно зажим делал ноты ЗАВИСИМЫМИ: перенос сегмента глиссандо двигал общую с соседом границу, длина
   середины отнималась у следующего, удаление середины давало прежней высоте тянуться дальше. Пользователь это
   отверг: в редакторе ноты обязаны быть независимы. Теперь правка, которая задела бы соседа, сперва ОТДЕЛЯЕТ
   сегмент в собственную ноту под СВЕЖИМ k (тот же ход, что у вставки editInsertBass), и столкнуться ему больше
   не с кем — зажим не нужен вовсе. Перекрытие двух бас-нот переигровка уже умеет: ключ различает голоса. */
const EDIT_GAP=1e-4;                                        // зазор у границы: «вплотную» с равным t порядок решила бы сортировка, а не мы
const EDIT_MIN_LEN=1/32;                                    // минимальная длина ноты в долях: короче — это уже не нота, а щелчок
/* ═══ ТАБЛИЦА РОЛЕЙ ПРАВКИ (слайс S0 правки соло и аккордов) ═══
   ⛳ ОДНА МОДЕЛЬ ПРАВКИ НА ТРИ ЛАДОВЫЕ РОЛИ. Отделение сегмента, перенос ноты целиком, длина и удаление (E1/E2) строились для
   баса, но в них нет ничего басового, кроме ТРЁХ вещей, — их и держит эта таблица, а функции ниже читают её вместо литералов:
     on / off — какие события начинают и кончают ноту роли;
     fresh(слой) — СВЕЖАЯ идентичность ноты (часть ключа владельца, которой в слое ещё нет): у баса и аккордов — суффикс взятого k
       ('bassloop:N:k[:v]', 'loop:N:k'; layerTakeTop — выше всех k слоя), у соло — номер ноты v ('leadloop:N:v'; layerSlotTop —
       выше всех номеров слоя). ⚠️ У ключа соло суффикса k НЕТ ВОВСЕ — свежий k соло ничего бы не развёл (и layerTakeTop на
       дорожке соло всегда 0);
     keep(a) — поля ключа, которые нота ОСТАВЛЯЕТ себе при свежей идентичности: у баса это номер ноты v (P2: ключ 'bassloop:N:k:v'
       различает одновременные бас-ноты и при новом k); у аккорда и соло — ничего (у соло v и есть свежая идентичность);
     oldOff(a) — что несёт «выкл», закрывающий ноту под ПРЕЖНИМ ключом (по нагрузке определяющего события): бас — k и v, только
       ненулевые (байт-в-байт прежний E2); аккорд — k, только ненулевой; соло — v ВСЕГДА, как пишет запись (recLeadOff).
   ⛔ ВСТАВКА СЮДА НЕ ВХОДИТ: у каждой роли свои поля новой ноты (тембр, карта, тип) — это слайсы S2/S4.
   ⚠️ S0 был НЕВИДИМ (список правимых ролей не тронут); S2 открыл аккорды, соло — S4: таблица его знает, но редактор к нему не
   пускает; у баса каждая функция ниже даёт ТЕ ЖЕ события, что и прежде (сверено построчно — см. отчёт слайса). */
const EDIT_ROLE={
  bs:{ on:'bassOn', off:'bassOff', fresh:ly=>({k:layerTakeTop(ly)}),
       keep:a=>{ const v=(a&&a.v)||0; return v?{v}:null; },
       oldOff:a=>{ const k=(a&&a.k)||0, v=(a&&a.v)||0; return {...(k?{k}:null), ...(v?{v}:null)}; } },
  ch:{ on:'chOn', off:'chOff', fresh:ly=>({k:layerTakeTop(ly)}),
       keep:()=>null,
       oldOff:a=>{ const k=(a&&a.k)||0; return k?{k}:{}; } },
  ld:{ on:'leadOn', off:'leadOff', fresh:ly=>({v:layerSlotTop(ly)}),
       keep:()=>null,
       oldOff:a=>({v:(a&&a.v)||0}) },
};
const editRoleOf=fn=>EDIT_ROLE[chaseRole(fn)]||null;       // null — удар, дрон, сирота без роли: правкам сегмента не подлежит
/* События ОДНОГО сегмента, по времени: определяющее («вкл» или смена высоты) и ведения громкости внутри.
   Берём тем же обратным указателем byEv, которым songSegs их и собрал: «выкл» туда не входит (он кончает
   сегмент, а не принадлежит ему), определяющее событие следующего сегмента — тоже. */
function segEvs(seg){ const SV=songSegs(); return seg.note.evs.filter(e=>SV.byEv.get(e)===seg); }
/* Есть ли на отрезке [a,b] (с зазором) событие ДРУГОЙ ноты того же ключа владельца. O(n) на правку, не на кадр.
   S0: роль — у самой ноты (n.role), ключ — тем же chaseKey, что у движка и songNotes; у баса проверка дословно прежняя. */
function keyClash(n,a,b){
  const own=new Set(n.evs);
  for(const e of events){
    if(own.has(e)||e.layer!==n.layer||chaseRole(e.fn)!==n.role||chaseKey(n.role,e)!==n.key) continue;
    if(e.t>=a-EDIT_GAP && e.t<=b+EDIT_GAP) return true;
  }
  return false;
}
/* ⛳ E1: НОТА ИЗ ОДНОГО СЕГМЕНТА ПЕРЕНОСИТСЯ ЦЕЛИКОМ. Прежде перенос двигал ТОЛЬКО определяющее событие — «вкл», —
   зажатое перед соседом по ключу, а соседом у одиночной ноты оказывался её же «выкл». Призрак при этом рисовал
   блок ПРЕЖНЕЙ длины на новом месте (ui держит rollDrag.len), а в песню ложилось другое: нота, утащенная вправо,
   укорачивалась и не могла перейти свой старый конец, влево — удлинялась. Обещание и результат расходились
   (правило #9 — о том же, со стороны правки).
   Одиночная нота = сегмент-НАЧАЛО (first), кончающийся СВОИМ «выкл» (endEv — «выкл»): смены высоты в ней нет.
   Ведения ГРОМКОСТИ границами сегмента не являются (songSegs режет только по смене высоты), поэтому записанная
   нота с дрожью руки внутри — по-прежнему ОДИН сегмент, и сюда она попадает.
   Такую ноту переносим ЦЕЛИКОМ — «вкл», её ведения громкости и «выкл» на одну и ту же дельту, одной составной
   правкой. Высота — всем событиям, которые её несут («выкл» высоты не несёт).
   ⛳ ЧУЖАЯ НОТА ТОГО ЖЕ КЛЮЧА на новом месте — нота берёт СВЕЖИЙ k (см. шапку): зажим снова разошёлся бы с призраком. */
function editMoveNote(n,t,deg,oct,ty){
  const R=EDIT_ROLE[n.role]; if(!R) return false;
  const pt = ty ? {deg,oct,ty} : {deg,oct};                  // U4: ty — однонотный аккорд в КАНОНИЧЕСКОЙ форме ряда (chordUnit); без него — прежние {deg,oct}
  const d=Math.max(0,t)-n.start;
  const fr= keyClash(n, n.start+d, n.end+d) ? R.fresh(n.layer) : null;   // S0: свежая идентичность ПО РОЛИ (бас/аккорд — {k} ≥1: в слое есть хотя бы эта нота; соло — {v} выше всех номеров слоя)
  const list=n.evs.map(e=>{
    const pitch = chaseKind(e.fn)!=='f';                     // S0: «выкл» высоты не несёт — у любой роли (у баса прежнее e.fn!=='bassOff')
    const a = (pitch||fr) ? {...e.a, ...(pitch?pt:null), ...fr} : e.a;   // нагрузка — НОВЫМ объектом (как у переноса); sc/sev/tk едут с самим событием (правило #7). Порядок полей прежний: {…, deg, oct, k}
    return { kind:'move', ev:e, from:{t:e.t, a:e.a}, to:{t:e.t+d, a} };
  });
  return editBatch(list) ? n.head : false;
}
/* ═══ E2: ОТДЕЛЕНИЕ СЕГМЕНТА ГЛИССАНДО ═══
   Сегмент s ноты под ключом K становится ОТДЕЛЬНОЙ нотой — строится ПЛАН, ещё ничего не тронуто:
     • s — не начало ноты → в его начале под K ложится «выкл»: левая часть ноты кончается там;
     • события s (определяющее и ведения громкости внутри) переходят под СВЕЖИЙ k. Определяющее, если оно было
       сменой высоты, становится «вкл» — с тембром НАЧАЛА ноты (ведения баса тембра не несут, T0);
     • конец s: свой «выкл» ноты (s — последний) переходит под новый k вместе с ним; иначе в конце s ложится
       новый «выкл» под новый k;
     • s кончался СЛЕДУЮЩЕЙ СМЕНОЙ ВЫСОТЫ → та смена становится «вкл» под K: правая часть — новая атака и дальше
       идёт под K как шла. Время внутри K монотонно: левая часть < «выкл» в начале s < «вкл» в конце s.
   Затем правка применяется к ОТДЕЛЁННОЙ ноте (items), и всё вместе — ОДНА составная запись истории (editBatch):
   один ↶ возвращает глиссандо в точности (те же объекты событий, те же нагрузки).
   ⚠️ ЦЕНА ПЛАТИТСЯ ЗДЕСЬ, И ОНА НАЗВАНА: скольжение В отделённую ноту и ИЗ неё пропадает — где было непрерывное
   глиссандо, теперь «выкл» и новая атака (левая часть отпускается с хвостом релиза, отделённая и правая
   атакуют заново). Нетронутые части звучат ровно как прежде. ⛔ Отделяется ТОЛЬКО то, что правят, и только
   правкой, которая иначе задела бы соседа (перенос во времени, длина на границе глиссандо, удаление); смена
   одной высоты глиссандо сохраняет (решение пользователя).
   ⛔ Новые события — в ТОМ ЖЕ взятом (tk), в том же слое (правило #27) и в СВОЁМ замороженном ладу (sc/sev
   копируются с события, чьё место они занимают, — правило #7): ⤺ снаружи снимет их вместе с дублем.
   null — отделять нечего или некуда (открытый сегмент без конца — так лежит подложка, а её не правят).
   ⛳ S0: РОЛЬ — ИЗ ТАБЛИЦЫ EDIT_ROLE (вид событий, свежая идентичность, «выкл» под прежним ключом). «Под свежим k» выше — это у
   баса и аккордов; у соло свежая идентичность — номер ноты v (см. таблицу). У баса нагрузки и порядок их полей — прежние. */
function detachPlan(seg){
  const n=seg.note, E=seg.ev, X=seg.endEv, R=EDIT_ROLE[n.role];
  if(seg.end==null||!R) return null;
  const fr=R.fresh(n.layer);                                  // свежая идентичность отделённой ноты: бас/аккорд {k}, соло {v}
  /* P2: НОМЕР НОТЫ v — часть ключа владельца баса (bassOwnerKey). Все события одной ноты несут один v, поэтому новый «выкл»
     левой части и «выкл» отделённой ноты обязаны нести его тоже: иначе «выкл» ушёл бы под ДРУГОЙ ключ и не закрыл свою
     ноту. При v=0 (ведущий режим, один владелец) поля нет — нагрузки те же, что до P2; у полифонического баса v бывает ≠0.
     S0: это и есть R.keep (бас) и R.oldOff (у баса — {k?, v?}); у соло «выкл» прежнего ключа несёт свой v всегда (как запись). */
  const keep=R.keep(E.a);
  const inst=((n.head&&n.head.a)||{}).inst, withInst=inst!==undefined?{inst}:null;   // тембр НАЧАЛА ноты: ведения баса и аккорда тембра не несут (T0); у соло ведение несёт тот же тембр, что «вкл» (с T3 открытая нота тембр не меняет)
  const ops=[], items=[];
  if(!seg.first) ops.push({ kind:'ins', evs:[{ t:seg.start, layer:n.layer, fn:R.off, a:R.oldOff(E.a), sc:E.sc, sev:E.sev, tk:E.tk }] });
  for(const e of segEvs(seg)){
    const on = e===E;
    items.push({ orig:e, fn: on?R.on:e.fn, t:e.t, a:{...e.a, ...(on&&e.fn!==R.on?withInst:null), ...fr} });
  }
  if(X && chaseKind(X.fn)==='f') items.push({ orig:X, fn:R.off, t:X.t, a:{...X.a, ...fr} });
  else {
    items.push({ orig:null, proto:E, fn:R.off, t:seg.end, a:{...fr, ...keep} });
    if(X) ops.push({ kind:'del', evs:[X] },
                   { kind:'ins', evs:[{ t:X.t, layer:X.layer, fn:R.on, a:{...X.a, ...withInst}, sc:X.sc, sev:X.sev, tk:X.tk }] });
  }
  return { ops, items };
}
/* ПЛАН → ОДНА СОСТАВНАЯ ПРАВКА. items уже несут КОНЕЧНОЕ состояние отделённой ноты (с правкой). Событие, чей
   вид не меняется, едет ходом 'move' (оба состояния); сменившее вид (ведение → «вкл») и новое — 'del'+'ins'
   новым объектом (вид события в ходе 'move' не хранится); keep=false или it.drop — событие уходит.
   → «вкл» отделённой ноты (его выделит редактор; это НОВЫЙ объект, если «вкл» родилось из смены высоты),
   true для удаления, false при отказе. */
/* U3: у РАСПАДА «вкл» в плане несколько (по одному на ноту), и выделить редактору надо не последний, а ту ноту, которую правили, —
   её «вкл» помечен it.sel; без пометки (отделение E2, удаление U2) — прежнее правило: последнее «вкл» плана. */
function commitDetach(P,keep){
  const list=P.ops.slice(), del=[], ins=[]; let head=null, pick=null;
  for(const it of P.items){
    if(!keep||it.drop){ if(it.orig) del.push(it.orig); continue; }
    if(it.orig && it.orig.fn===it.fn){
      list.push({ kind:'move', ev:it.orig, from:{t:it.orig.t, a:it.orig.a}, to:{t:it.t, a:it.a} });
      if(chaseKind(it.fn)==='n'){ head=it.orig; if(it.sel) pick=it.orig; }   // S0: «вкл» отделённой ноты — у любой роли (у баса прежнее it.fn==='bassOn': в плане бывают только события своей роли)
    }else{
      if(it.orig) del.push(it.orig);
      const p=it.orig||it.proto, ev={ t:it.t, layer:p.layer, fn:it.fn, a:it.a, sc:p.sc, sev:p.sev, tk:p.tk };
      ins.push(ev); if(chaseKind(it.fn)==='n'){ head=ev; if(it.sel) pick=ev; }
    }
  }
  if(del.length) list.push({ kind:'del', evs:del });
  if(ins.length) list.push({ kind:'ins', evs:ins });
  if(!editBatch(list)) return false;
  return keep ? (pick||head) : true;
}
/* Перенос СЕГМЕНТА: во времени и/или по высоте. Высота — НОВАЯ нагрузка (deg/oct), всё прочее едет с
   объектом: ⛔ ev.sc НЕ ТРОГАЕМ НИКОГДА — событие остаётся в СВОЁМ ладу (правило #7), иначе правка в
   хроматике молча переписала бы партчевскую ноту на полутона.
   Три пути, по тому, ЧТО меняется:
     ТОЛЬКО ВЫСОТА (время на месте) — глиссандо СОХРАНЯЕТСЯ (решение пользователя): новая ступень ложится на
       КАЖДОЕ событие сегмента, несущее высоту, — определяющее И ведения громкости внутри. ⚠️ Это починка E1:
       прежде ступень получало одно определяющее событие, а ведения внутри несли старую, и нота РАСПАДАЛАСЬ —
       с первого же ведения снова звучала прежняя высота (songSegs видел смену и резал сегмент).
     ОДИНОЧНАЯ НОТА во времени — целиком (E1, editMoveNote).
     СЕГМЕНТ ГЛИССАНДО во времени — ОТДЕЛЯЕТСЯ и едет один (E2): все его события на одну дельту, соседи на месте.
   → событие, которое редактор выделит после правки (у отделённой — её новое «вкл»), или false. */
/* U4: ty (необязателен) — тип, который ложится вместе со ступенью и регистром на каждое событие, несущее высоту: так однонотный аккорд
   переносится на ряд в КАНОНИЧЕСКОЙ форме (chordUnit) и звучит ровно высоту ряда. Без ty — прежний перенос, тип не трогается. */
function editMoveSeg(ev,t,deg,oct,ty){
  if(!editGuard()||!ev||ev.layer!==editLayer()) return false;
  const pt = ty ? {deg,oct,ty} : {deg,oct};
  if(!editRoleOf(ev.fn)) return false;                       // S0: ладовая роль из таблицы (бас/аккорды/соло); с S2 редактор пускает сюда бас и аккорды, соло — с S4 (ROLL_EDITABLE)
  const seg=songSegs().byEv.get(ev); if(!seg||seg.ev!==ev) return false;   // правится только ОПРЕДЕЛЯЮЩЕЕ событие сегмента — его и отдаёт попадание (h.ev)
  const nt=Math.max(0,t);
  if(Math.abs(nt-ev.t)<=1e-9){
    const list=segEvs(seg).map(e=>({ kind:'move', ev:e, from:{t:e.t, a:e.a}, to:{t:e.t, a:{...e.a, ...pt}} }));
    return editBatch(list) ? ev : false;
  }
  if(seg.first && seg.endEv && chaseKind(seg.endEv.fn)==='f') return editMoveNote(seg.note,nt,deg,oct,ty);
  const P=detachPlan(seg); if(!P) return false;
  const d=nt-P.items[0].t;                                   // items[0] — определяющее событие (события сегмента идут по времени)
  for(const it of P.items){ it.t+=d; if(chaseKind(it.fn)!=='f') it.a={...it.a, ...pt}; }   // S0: «выкл» высоты не несёт — у любой роли
  return commitDetach(P,true);
}
/* Удаление сегмента.
     ОДИНОЧНАЯ нота (и нота без собственного конца) — уходит ЦЕЛИКОМ, как прежде: все её события.
     СЕГМЕНТ ГЛИССАНДО — E2: отделяется и уходит ОДИН. На его месте — ТИШИНА: левая часть кончается в его начале,
       правая начинается в его конце новой атакой. Прежде уходило одно событие, и предыдущая высота ТЯНУЛАСЬ через
       место удалённой, а удаление НАЧАЛА глиссандо уносило ВСЮ ноту — обе вещи задевали соседей. */
function editDeleteSeg(ev){
  if(!editGuard()||!ev||ev.layer!==editLayer()) return false;
  if(!editRoleOf(ev.fn)) return false;                       // S0: см. editMoveSeg
  const seg=songSegs().byEv.get(ev);
  const whole = !seg || (seg.first && !(seg.endEv && chaseKind(seg.endEv.fn)!=='f'));   // нет сегмента (сирота) / одиночная / начало ноты без смены высоты за ним
  if(!whole){ const P=detachPlan(seg); if(P) return commitDetach(P,false); }
  const evs = (seg&&seg.first&&seg.note) ? seg.note.evs.slice() : [ev];
  const drop=new Set(evs);
  if(!compactEvents(e=>drop.has(e))) return false;
  editPush({ kind:'del', evs });
  editCommit(); return true;
}
/* ═══ U2: РАСПАД АККОРДА — ПРАВКА ОДНОЙ ЕГО НОТЫ ═══
   ⛳ ЗАКОН (решение пользователя, план «АККОРД КАК НОТЫ»): правка ОДНОЙ ноты аккорда РАСПУСКАЕТ его на ОДНОНОТНЫЕ аккорды, и
   правка применяется к одной из них. U2 — УДАЛЕНИЕ ноты, U3 — её перенос во времени и длина, U4 — по высоте (chordNoteEdit ниже).
   ⛳ ЧТО ПИШЕТСЯ. Сперва — ТО ЖЕ ОТДЕЛЕНИЕ, что у переноса и удаления сегмента (detachPlan, E2): сегмент посреди ведения
   (аккорды, сменённые одной защёлкой) становится отдельной нотой; одиночный аккорд (сегмент-начало со своим «выкл») берётся как
   есть — отделять его не от чего. Затем отделённая нота РАЗМНОЖАЕТСЯ: на каждую оставшуюся ноту аккорда — своя копия ВСЕХ её
   событий («вкл», ведения громкости и яркости внутри, «выкл»), каждая
     • с ТЕМ ЖЕ корнем и регистром (a.deg/a.oct) и ТЕМ ЖЕ замороженным ладом (sc/sev едут с событием — правило #7);
     • с ОДНОЭЛЕМЕНТНЫМ ТИПОМ a.ty = [интервал этой ноты] — интервал ровно тот, что вернула scales.chordNotes (iv — в мере ветки
       цены: целые полутоны у сетки и ступенчатых наборов, отношение у чистых); ⚠️ это НОВЫЙ массив, а не ссылка в наборе
       семейств (правило #7 — тип в событии теперь бывает и данными вне палитры; сравнение — tyEq, по значению);
     • со СВОИМ свежим суффиксом взятого k (k0, k0+1, … — выше всех k слоя, layerTakeTop), то есть со своим владельцем
       'loop:N:k': у каждой ноты свой голос, ничья с ничьей не путается;
     • громкость, яркость, тембр («вкл»), отметки автоматизации (sh/gen) — КОПИИ полей исходных событий, ничего не выдумано.
   Удаляемая нота просто не получает копии. Первая оставшаяся нота едет на ИСХОДНЫХ объектах событий (ход 'move'), прочие —
   новыми объектами в том же взятом (tk) и слое (правило #27). Всё — ОДНА составная правка (commitDetach → editBatch): один ↶
   возвращает аккорд в точности (те же объекты, те же нагрузки), одна запись истории.
   ⛳ ПОЧЕМУ ЗВУК ОСТАВШИХСЯ НОТ НЕ МЕНЯЕТСЯ (доказательство — по движку, audio.chordOn/chordGlide/chordOff):
     • ВЫСОТА: chordFreqs(deg,oct,sc,sev,[iv_i]) — та же ветка chordNotes с тем же корнем (корень не зависит от типа ни в одной из
       четырёх ветвей), нота = корень·iv_i (или ступень корень+iv_i сетки / шаг r0+iv_i) — ровно частота ноты i исходного аккорда;
     • УРОВЕНЬ: голос аккорда получает ins.lvl·volAmp(vol)·(1−rnd·0.05) — от ЧИСЛА нот уровень не зависит (нормировки на число
       голосов в chordOn нет), значит одна нота звучит так же, как в составе;
     • ФИЛЬТРЫ: f (атака) ставится из тембра и громкости, fb (яркость) — из a.bri; оба — пер-голосовые и от состава не зависят
       (правило #19 не тронуто);
     • ВЕДЕНИЕ: chordGlide сопоставляет голос i частоте i; у однонотного аккорда голос 0 — частоте 0, то есть той же ноте;
     • ШИНА: все владельцы 'loop:N:*' слоя идут в одну chordBus → одна цепь эффектов дорожки;
     • ГОЛОСОВ не больше, чем было (N−1 из N): живой пул 24 крадёт не раньше прежнего.
     Различается лишь гуманизация (−0..5% уровня, ±10% атаки, центы) — она СВЕЖАЯ на каждой атаке и не записывается (правило
     #11), то есть различалась и между двумя переигровками одного аккорда.
   ⚠️ ЦЕНА ПЛАТИТСЯ ЗДЕСЬ (та же, что у E2, и только у сегмента ВНУТРИ ведения): там, где аккорд плавно сменялся из соседнего и
   плавно перетекал в следующий, теперь «выкл» и новая атака — края сегмента РЕ-АРТИКУЛИРУЮТСЯ (detachPlan). Одиночный аккорд
   распадается без цены: ноты атакуют и отпускаются ровно там, где и прежде.
   null — распускать нечего или некуда (открытый сегмент — так лежит подложка, её не правят). */
function dissolvePlan(seg,N,drop){
  const n=seg.note, X=seg.endEv;
  const alone = seg.first && X && chaseKind(X.fn)==='f';      // одиночный аккорд: отделять не от чего — берём все его события как есть
  const P = alone ? { ops:[], items:n.evs.map(e=>({ orig:e, fn:e.fn, t:e.t, a:e.a })) } : detachPlan(seg);
  if(!P) return null;
  const k0=layerTakeTop(n.layer), items=[];
  N.map((x,i)=>i).filter(i=>i!==drop).forEach((i,j)=>{
    const ty=[N[i].iv], k=k0+j;                               // свой тип из одной ноты и свой владелец 'loop:N:k'
    for(const it of P.items){
      const a={...it.a, ...(chaseKind(it.fn)!=='f'?{ty}:null), k};   // «выкл» типа не несёт — у него только ключ
      items.push({ ...(j===0 ? {...it, a} : { orig:null, proto:it.orig||it.proto, fn:it.fn, t:it.t, a }), note:i });   // U3: note — номер ноты в chordNotes, чья это копия (по нему перенос и длина находят СВОЮ однонотную)
    }
  });
  return { ops:P.ops, items };
}
/* Удалить ОДНУ ноту аккорда (idx — её номер в scales.chordNotes сегмента, тот же, что у блока на экране): аккорд распадается
   на однонотные, удаляемая уходит (см. dissolvePlan). Аккорд из одной ноты — это удаление сегмента целиком, как прежде.
   → true или false. */
function editDeleteChordNote(ev,idx){
  if(!editGuard()||!ev||ev.layer!==editLayer()||chaseRole(ev.fn)!=='ch') return false;
  const seg=songSegs().byEv.get(ev); if(!seg||seg.ev!==ev) return false;
  const N=chordNotes(seg.deg,seg.oct,seg.sc,seg.sev,seg.ty);
  if(!(idx>=0&&idx<N.length)) return false;
  if(N.length<2) return editDeleteSeg(ev);
  const P=dissolvePlan(seg,N,idx); if(!P) return false;
  return !!commitDetach(P,true);
}
/* ═══ U3: ПЕРЕНОС ВО ВРЕМЕНИ И ДЛИНА ОДНОЙ НОТЫ АККОРДА ═══
   ⛳ ТОТ ЖЕ РАСПАД, ЧТО У УДАЛЕНИЯ (U2), — без второй модели: dissolvePlan(seg, N, -1) распускает сегмент на однонотные аккорды, НИ
   ОДНОЙ не снимая (каждая звучит ровно как в составе — доказательство в шапке распада), а затем правка трогает ТОЛЬКО копию выбранной
   ноты (it.note === idx): перенос сдвигает ВСЕ её события («вкл», ведения громкости/яркости внутри, «выкл») на одну дельту; длина
   двигает её «выкл» и снимает её же ведения за новым концом (как editResizeSeg). Прочие копии стоят где стояли.
   ⛳ СТОЛКНУТЬСЯ НЕ С ЧЕМ: у каждой копии свой свежий k выше всех k слоя (dissolvePlan), значит ни перенос, ни удлинение не заходят на
   чужой ключ — зажим и «свежий k по столкновению» (E1) здесь не нужны. Перекрытие с соседним аккордом — два голоса, как у E2.
   ⚠️ ЦЕНА — та же, что у распада: сегмент внутри ведения сперва ОТДЕЛЯЕТСЯ (detachPlan), и его края ре-артикулируются.
   Всё — ОДНА составная правка (commitDetach → editBatch): один ↶ возвращает аккорд в точности.
   Высота одной ноты — U4 (editMoveChordNote с deg/oct, ниже). Аккорд из одной ноты — обычный сегмент: editMoveSeg / editResizeSeg.
   → «вкл» правленой однонотной (её выделит редактор) или false. */
function chordNoteEdit(ev,idx,fn){
  if(!editGuard()||!ev||ev.layer!==editLayer()||chaseRole(ev.fn)!=='ch') return false;
  const seg=songSegs().byEv.get(ev); if(!seg||seg.ev!==ev) return false;
  const N=chordNotes(seg.deg,seg.oct,seg.sc,seg.sev,seg.ty);
  if(!(idx>=0&&idx<N.length)) return false;
  if(N.length<2) return fn(seg,null);
  const P=dissolvePlan(seg,N,-1); if(!P) return false;
  const mine=P.items.filter(it=>it.note===idx);               // копия выбранной ноты: «вкл» первым, свой «выкл» последним (события сегмента идут по времени)
  if(!mine.length||fn(seg,mine)===false) return false;
  for(const it of mine) if(chaseKind(it.fn)==='n') it.sel=true;
  return commitDetach(P,true);
}
/* ⛳ U4: ПЕРЕНОС ОДНОЙ НОТЫ ПО ВЫСОТЕ — тот же распад, затем копия выбранной ноты получает КАНОНИЧЕСКУЮ ФОРМУ РЯДА: ступень и регистр
   ряда (deg/oct — ui расшифровывает ряд rollRowPitch по ладу оси) и однонотный тип scales.chordUnit(лад сегмента) — единицу корня, то
   есть аккорд из одного корня. Нота звучит ровно высоту ряда — ступени лада, то есть высоты СТРОЯ (HANDOFF, «УНИВЕРСАЛЬНАЯ МОДЕЛЬ СТРОЯ»:
   ноты строятся из высот строя, лад — подсветка; ряд вне лада — приглушённый, правка на нём — T5, а пока ui прилипает к ярким): нота
   вне ряда (чистое отношение между высотами строя), перенесённая
   на ряд, ПРИЛИПАЕТ к нему. Лад события не трогаем (правило #7): форма считается в его же sc.
   deg==null — высота не меняется (только время, U3). Время и высота вместе — ОДНА правка. Высота на все события копии, несущие
   высоту («вкл» и ведения внутри); «выкл» её не несёт.
   Аккорд из одной ноты (сам — нота): обычный перенос сегмента, но с той же канонической формой (editMoveSeg с ty) — иначе его
   прежний однонотный тип [iv] от прежнего корня увёл бы ноту мимо ряда, к которому её тянули (у нетипизированного лада корень
   идёт по ступеням, а интервал — в шагах). */
function editMoveChordNote(ev,idx,t,deg,oct){
  const pitch = deg!=null && oct!=null;
  return chordNoteEdit(ev,idx,(seg,mine)=>{
    if(!mine) return pitch ? editMoveSeg(seg.ev,t,deg,oct,chordUnit(seg.sc)) : editMoveSeg(seg.ev,t,seg.deg,seg.oct);
    const d=Math.max(0,t)-mine[0].t;
    if(Math.abs(d)<=1e-9 && !pitch) return false;
    const ty=pitch ? chordUnit(seg.sc) : null;
    for(const it of mine){ it.t+=d; if(pitch && chaseKind(it.fn)!=='f') it.a={...it.a, deg, oct, ty}; }
  });
}
function editResizeChordNote(ev,idx,t){
  return chordNoteEdit(ev,idx,(seg,mine)=>{
    if(!mine) return editResizeSeg(seg.ev,t);
    const on=mine[0], off=mine[mine.length-1];
    if(chaseKind(off.fn)!=='f') return false;
    const T=Math.max(t, on.t+EDIT_MIN_LEN);
    if(Math.abs(T-off.t)<=1e-9) return false;
    off.t=T;
    for(const it of mine) if(it!==on && it!==off && it.t>=T-EDIT_GAP) it.drop=true;   // ведения этой ноты за новым концом — после «выкл» они сироты
  });
}
/* ═══ ДЛИНА СЕГМЕНТА (S5.6; E2) ═══
   ⛳ ЧТО ДВИГАЕТ ИЗМЕНЕНИЕ ДЛИНЫ — по тому, ЧЕМ сегмент кончается:
     СВОИМ «выкл» (одиночная нота или последний сегмент глиссандо) → двигаем этот «выкл»: это и есть длина ноты,
       соседей она не задевает. Ведения громкости этого сегмента, оказавшиеся за новым концом, уходят (после «выкл»
       они сироты — их не слышно); прежде их время ЗАЖИМАЛО укорочение, и записанную ноту с дрожью руки внутри
       нельзя было укоротить. Удлинение поверх чужой ноты того же ключа → нота берёт свежий k (как перенос, E1),
       а не упирается в соседку.
     СЛЕДУЮЩЕЙ СМЕНОЙ ВЫСОТЫ (граница глиссандо) → E2: сегмент ОТДЕЛЯЕТСЯ, и двигается ЕГО СОБСТВЕННЫЙ новый «выкл».
       Прежде двигалась общая граница: этот сегмент рос, следующий на столько же укорачивался.
     «ВКЛ» СОСЕДНЕЙ НОТЫ того же ключа (endEv нет) / открытый сегмент — тянуть нечего, отказ (как было).
   ⚠️ НУЛЕВОЙ И ОТРИЦАТЕЛЬНОЙ ДЛИНЫ НЕ БЫВАЕТ: конец не ближе EDIT_MIN_LEN к началу.
   → определяющее событие сегмента (его выделит редактор; у отделённого — его новое «вкл») или false. */
function editResizeSeg(ev,t){
  if(!editGuard()||!ev||ev.layer!==editLayer()) return false;
  const R=editRoleOf(ev.fn); if(!R) return false;            // S0: см. editMoveSeg
  const seg=songSegs().byEv.get(ev); if(!seg||!seg.endEv||seg.end==null) return false;
  const X=seg.endEv;
  if(chaseKind(X.fn)==='f'){
    const n=seg.note, T=Math.max(t, seg.start+EDIT_MIN_LEN);
    if(Math.abs(T-X.t)<=1e-9) return false;
    const drop=segEvs(seg).filter(e=>e!==seg.ev && e.t>=T-EDIT_GAP);
    const fr= (T>X.t && keyClash(n, X.t, T)) ? R.fresh(n.layer) : null;   // S0: свежая идентичность по роли (у баса — прежний {k})
    const list=[];
    for(const e of n.evs){
      if(drop.includes(e)) continue;
      if(e!==X && !fr) continue;
      list.push({ kind:'move', ev:e, from:{t:e.t, a:e.a}, to:{t: e===X?T:e.t, a: fr?{...e.a, ...fr}:e.a} });
    }
    if(drop.length) list.push({ kind:'del', evs:drop });
    return editBatch(list) ? seg.ev : false;
  }
  const P=detachPlan(seg); if(!P) return false;
  const on=P.items[0], off=P.items[P.items.length-1];         // отделённая нота: «вкл» первым, свой «выкл» последним
  const T=Math.max(t, on.t+EDIT_MIN_LEN);
  off.t=T;
  for(const it of P.items) if(it!==on && it!==off && it.t>=T-EDIT_GAP) it.drop=true;   // ведения громкости за новым концом
  return commitDetach(P,true);
}
/* Вставка бас-ноты: пара «вкл»+«выкл» со СВЕЖИМ k (свой владелец — см. довод о порядке выше).
   ⛳ ОТКУДА ПОЛЯ: тембр — ТОЛЬКО с «вкл» соседней ноты (у ведения он записан, но звук его не читает —
   тембр печётся на атаке; брать его с ведения значит списывать у того, кто им не распоряжается);
   громкость — с ближайшего бас-события; ЛАД И СЕПТАККОРД — с ПОКАЗАННОЙ ГРУППЫ (их передаёт редактор),
   ⛔ а не CUR(): нота обязана родиться в том ладу, в котором нарисована ось. Пустая дорожка группы не
   имеет — тогда вызывающий честно передаёт живой лад. */
function editInsertBass(t,deg,oct,sc,sev,len){
  if(!editGuard()) return false;
  const layer=editLayer();
  let on=null, near=null, bd=Infinity;
  for(const e of events){
    if(e.layer!==layer||chaseRole(e.fn)!=='bs') continue;
    const d=Math.abs(e.t-t);
    if(d<bd){ bd=d; near=e; }
    if(e.fn==='bassOn' && (!on||Math.abs(e.t-t)<Math.abs(on.t-t))) on=e;
  }
  const inst = on&&on.a.inst!=null ? on.a.inst : bassIdx;
  const vol  = near&&near.a.vol!=null ? near.a.vol : editDefVol('bs');
  const k=layerTakeTop(layer);                               // свой ключ владельца: пересечься с существующим басом нечем
  if(!editTake) editTake=++takeSeq;
  const t0=Math.max(0,t), t1=t0+Math.max(EDIT_GAP*2,len||1);
  const mk=(fn,a,tt)=>({ t:tt, layer, fn, a:(k?{...a,k}:a), sc, sev, tk:editTake });
  const evOn =mk('bassOn', {deg,oct,vol,inst}, t0);
  const evOff=mk('bassOff',{}, t1);
  events.push(evOn,evOff);
  editPush({ kind:'ins', evs:[evOn,evOff] });
  editCommit(); return evOn;
}
/* ═══ ВСТАВКА АККОРДА (слайс S2 правки соло и аккордов) — пара «вкл»+«выкл» со СВЕЖИМ k, как у баса ═══
   ⛳ ТИП (решение пользователя): тип ВЫДЕЛЕННОГО аккорда (sel — событие, которое было выделено в редакторе), иначе БЛИЖАЙШЕГО аккорда
   дорожки в ТОЙ ЖЕ группе лада (тип — ССЫЛКА в наборе семейств лада, a.ty; из чужого лада он не годится), иначе — null у
   нетипизированного лада (качество выводит ступень и септаккорд) или ПЕРВЫЙ тип палитры у типизированного.
   ТЕМБР — с «вкл» ближайшего аккорда (тембр печётся на атаке; ведение аккорда тембра не несёт), иначе живой chIdx. ГРОМКОСТЬ — с
   ближайшего события аккорда, иначе editDefVol('ch') (правило #30: у ноты громкость есть всегда). ЯРКОСТИ НЕТ: отсутствие a.bri —
   «не задана», фильтр открывается на атаке (правило аккордов). ЛАД И СЕПТАККОРД — показанной группы (их передаёт редактор; правило #7).
   ⛔ Живая защёлка ('latch') не трогается ничем: это события дорожки, её владелец — 'loop:N:k' (правило #20). */
function editChordTypeFor(layer,t,sc,sel){
  if(sel && sel.layer===layer && chaseRole(sel.fn)==='ch' && sel.sc===sc && sel.a && 'ty' in sel.a) return sel.a.ty??null;
  let best=null, bd=Infinity;
  for(const e of events){
    if(e.layer!==layer||e.sc!==sc||(e.fn!=='chOn'&&e.fn!=='chSet')||!e.a) continue;
    const d=Math.abs(e.t-t); if(d<bd){ bd=d; best=e; }
  }
  if(best) return best.a.ty??null;
  if(!typedChords(sc)) return null;
  const F=chordFams(sc), f0=F&&F[0], ty0=f0&&f0.types&&f0.types[0];
  return ty0 ? ty0.iv : null;
}
function editInsertChord(t,deg,oct,sc,sev,len,sel){
  if(!editGuard()) return false;
  const layer=editLayer();
  let on=null, near=null, bd=Infinity;
  for(const e of events){
    if(e.layer!==layer||chaseRole(e.fn)!=='ch'||e.fn==='chOff') continue;
    const d=Math.abs(e.t-t);
    if(d<bd){ bd=d; near=e; }
    if(e.fn==='chOn' && (!on||Math.abs(e.t-t)<Math.abs(on.t-t))) on=e;
  }
  const inst = on&&on.a.inst!=null ? on.a.inst : chIdx;
  const vol  = near&&near.a.vol!=null ? near.a.vol : editDefVol('ch');
  const ty   = editChordTypeFor(layer,t,sc,sel);
  const k=layerTakeTop(layer);                               // свой ключ владельца 'loop:N:k': пересечься с аккордами дорожки нечем
  if(!editTake) editTake=++takeSeq;
  const t0=Math.max(0,t), t1=t0+Math.max(EDIT_GAP*2,len||1);
  const mk=(fn,a,tt)=>({ t:tt, layer, fn, a:(k?{...a,k}:a), sc, sev, tk:editTake });
  const evOn =mk('chOn', {deg,oct,vol,inst,ty}, t0);
  const evOff=mk('chOff',{}, t1);
  events.push(evOn,evOff);
  editPush({ kind:'ins', evs:[evOn,evOff] });
  editCommit(); return evOn;
}
function editInsertHit(t,row){
  if(!editGuard()) return false;
  const layer=editLayer(), d=editDrumDefaults(layer,t);
  /* ⛳ ОДНО ВЗЯТОЕ НА СЕССИЮ ПРАВКИ, а не на удар: ⤺ снаружи снимает «последнее взятое», и сессия правки —
     ближайший аналог дубля записи. Иначе десять вставок требовали бы десяти ⤺. */
  if(!editTake) editTake=++takeSeq;
  const ev={ t:Math.max(0,t), layer, fn:'drum', a:{row, vol:d.vol, kit:d.kit}, sc:CUR(), sev:seventh, tk:editTake };
  events.push(ev);
  editPush({ kind:'ins', evs:[ev] });
  editCommit(); return ev;
}
/* ═══ ЗАМЕНА ТЕМБРА ДОРОЖКИ (слайс T5) ═══
   ⛳ ПОСЛЕ ЗАПИСИ ЭТО ЕДИНСТВЕННЫЙ ПУТЬ сменить тембр дорожки (вооружение живой тембр не переключает — T3).
   Замена — ВНУТРИ РОЛИ: роли хранят разные виды нот (ряд / ступень+тип / одна нота), поэтому поле одно
   на роль — у ударных набор (`a.kit`), у прочих тембр (`a.inst`). Роль дорожки от замены не меняется, а
   значит не меняется и её ЦЕПЬ (ключ — по роли, T4): эффекты и записанная автоматика остаются дорожке —
   записанная автоматика И ЕСТЬ исполнение (решение пользователя №1).
   ЧТО ПЕРЕПИСЫВАЕТСЯ — ровно то, что тембр НЕСЁТ: каждое начало ноты («вкл», удар) и ведение соло, если в
   нём тембр есть (смена посреди ноты из материала до T3 — переигровка его играет, T0-fix). Ведения аккорда
   и баса тембра не несут никогда. Дрон — ни то, ни другое: у слоя дрона роли нет, выбора ему не дают.
   ⚠️ НАГРУЗКА — НОВЫМ ОБЪЕКТОМ, как у переноса: прежний уходит в историю целиком, и обратный ход не может
   растерять поля (tie, v, k, fx, bend, bri…). Время и замороженный лад (sc/sev, правило #7) не трогаются.
   ⛳ ОДНА ЗАПИСЬ ИСТОРИИ на всю замену: один тап — один ↶ — один ↷ (kind:'timbre', список {ev,from,to}).
   ⛳ ОБЫЧНЫЙ editCommit: версия правок дорожки растёт, а свёртка тембров в подписи свежести (T0) меняется
   сама — замороженная дорожка УСТАРЕВАЕТ и играет событиями уже в новом тембре. Курсоры — как у любой
   правки (#28), сортировка ничего не переставит: времена те же. */
function laneTimbreOf(layer){
  if(layer==null) return null;
  for(const e of events) if(e.layer===layer&&isNoteStart(e.fn)&&e.a){ const x= e.fn==='drum' ? e.a.kit : e.a.inst; if(x!=null) return x; }
  return null;
}
function editSetTimbre(id){
  if(id==null||!editGuard(true)) return false;             // true — подложке тоже можно (см. editGuard)
  const layer=editLayer(), role=laneRoleOf(layer); if(!role) return false;
  const f= role==='dr' ? 'kit' : 'inst', ch=[];
  for(const e of events){
    if(e.layer!==layer||!e.a) continue;
    if(!(isNoteStart(e.fn) || (e.fn==='leadSet'&&e.a.inst!=null))) continue;
    if(e.a[f]===id) continue;
    const from=e.a, to={...e.a, [f]:id};
    ch.push({ev:e, from, to}); e.a=to;
  }
  if(!ch.length) return false;                              // уже этот тембр — не правка (иначе ↶ «ничего не делает»)
  editPush({ kind:'timbre', ch });
  editCommit(); return true;
}
/* ═══ ПОЛОСА АВТОМАТИЗАЦИИ: ЧТЕНИЕ И ПРАВКА (слайс O-4) ═══
   ⛳ ЧТО ЗДЕСЬ ЗА ЕДИНИЦА. Полоса показывает ОДИН АДРЕС — (владелец цепи, эффект, параметр) — на ВСЕЙ
   дорожке, как его видит переигровка: точки всех взятых дорожки, слитые по времени. Это не «вид на одно
   взятое»: звучит-то именно слитая лента (fxPlayBuild), и показывать другое значило бы рисовать не то,
   что слышно.
   ⛳ КАКОМУ ВЗЯТОМУ ПРИНАДЛЕЖИТ ПРАВКА (ответ на «а если взятых два»):
     ПЕРЕТАСКИВАНИЕ правит ТУ САМУЮ точку, за которую взялись, — она лежит в СВОЁМ взятом и там остаётся.
     НОВАЯ точка ложится в ПОСЛЕДНЕЕ взятое дорожки (высший tk). Это не произвол: переигровка разрешает
     спор «последняя по времени, при равенстве — старшая по номеру взятого», поэтому точка в последнем
     взятом ПОБЕЖДАЕТ в любой момент, который она покрывает. То есть «добавил точку — она и слышна».
   ⚠️ СНИМОК СТАРТА — НЕ ТОЧКА. Уровень до первой точки задаёт снимок цепи взятого; он рисуется полкой, но
   ручки у него нет: двигать «состояние на старте» как точку значило бы править не автоматизацию, а сам
   снимок. Нужна точка раньше всех — её добавляют обычным способом, тапом в режиме вставки. */
const AUT_EPS=1e-9;
/* Взятые ДОРОЖКИ, от старшего к младшему, и их доли старта — одним проходом по событиям.
   ⛳ T4: ролей по взятым больше НЕ собираем. Прежде каждое взятое несло набор ключей своих ролей в этой
   дорожке, потому что дорожка могла держать несколько; теперь роль у дорожки одна, и каждое её взятое
   играло именно её — цепь одна на всю дорожку (laneChainKey). ⚠️ Одно ВЗЯТОЕ по-прежнему может нести
   несколько ролей (сплит) — но они лежат в РАЗНЫХ дорожках, и чужую цепь отсекает ключ точки (ent.key). */
function autTakesOf(layer){
  const m=new Map();
  for(const e of events) if(e.layer===layer){
    const tk=e.tk||0; let x=m.get(tk);
    if(!x) m.set(tk, x={tk, t0:e.t});
    if(e.t<x.t0) x.t0=e.t;
  }
  return [...m.values()].sort((a,b)=>b.tk-a.tk);      // старший первым: «последнее взятое» — это [0]
}
/* ВСЕ АДРЕСА, которые полоса может показать у этой дорожки: параметры эффектов её ОДНОЙ цепи.
   Порядок — порядок ЦЕПИ (он слышен с O-1): снимки ВСЕХ захваченных взятых, при расхождении порядок — у более старшего.
   S1: правки цепи (autChainAdd/Remove/Move) идут во все эти снимки сразу — список и правка смотрят в одно и то же. */
function autAddrs(layer){
  const out=[], key=laneChainKey(layer); if(!key) return out;
  /* ⛳ VOL-3: ГРОМКОСТЬ — ПЕРВОЙ, У КАЖДОЙ ДОРОЖКИ С РОЛЬЮ, и не из снимка захвата. Громкость есть у КАЖДОЙ ноты (поле a.vol),
     значит её полоса есть у каждой дорожки — в том числе у той, что захвата не имеет (вставленные в редакторе ноты). Вид и
     правка — из самих нот (autPoints → pnView), как у любого параметра «в ноте». Ниже, в обходе снимков, запись громкости
     пропускается (fxPerm), чтобы адрес не встал второй раз. */
  for(const meta of fxParamMetaOf(FX_VOL)) out.push({key, fx:FX_VOL, p:meta.key, labelKey:meta.labelKey, short:meta.short});
  for(const T of autTakesOf(layer).slice().reverse()){
    const rec=takeFx.get(T.tk); if(!rec) continue;
    const ch=rec.chains[key]; if(!ch) continue;
    for(const eff of ch) if(!fxPerm(eff.fxId)) for(const meta of fxParamMetaOf(eff.fxId)){   // громкость уже стоит первой (выше); прочие — в порядке цепи
      const i=out.findIndex(o=>o.fx===eff.fxId&&o.p===meta.key);
      if(i>=0) out.splice(i,1);                       // тот же адрес у более старшего взятого — порядок берём у него
      out.push({key, fx:eff.fxId, p:meta.key, labelKey:meta.labelKey, short:meta.short});
    }
  }
  /* ⛳ И ЭФФЕКТЫ, ДОБАВЛЕННЫЕ ПОСРЕДИ ВЗЯТОГО. Снимок цепи — это состав НА СТАРТЕ; эффект, добавленный по ходу, живёт в ленте
     записью состава (FX_CHAIN, поле ids) и своими величинами с той доли. Переигровка и заморозка его слышат, а полоса его не
     перечисляла — пока его не добавляли дорожке руками. Теперь его адреса стоят В КОНЦЕ списка, в порядке появления; их
     точки полоса берёт из ленты как обычно (autPointsCalc), а до первой точки полки нет — эффекта тогда и не было. */
  for(const T of autTakesOf(layer).slice().reverse()){
    const rec=takeFx.get(T.tk); if(!rec) continue;
    for(const ent of rec.lane){ if(ent.key!==key||ent.fx!==FX_CHAIN||!ent.ids) continue;
      for(const id of ent.ids){ if(fxPerm(id)||out.some(o=>o.fx===id)) continue;   // VOL-0: громкость есть в каждом составе — «добавленной посреди взятого» она не бывает
        for(const meta of fxParamMetaOf(id)) out.push({key, fx:id, p:meta.key, labelKey:meta.labelKey, short:meta.short}); } }
  }
  return out;
}
/* ТОЧКИ ОДНОГО АДРЕСА ПО ВСЕЙ ДОРОЖКЕ + УРОВЕНЬ ДО ПЕРВОЙ ТОЧКИ.
   base — величина из снимка САМОГО РАННЕГО взятого, которое этим адресом правит; ею рисуется полка слева.
   pts — записи дорожки (их и правит редактор) по времени; при равном времени старше тот, у кого больше
   tk, — тот же закон, что у переигровки. */
/* ⚠️ МЕМО НА ОДНУ ЗАПИСЬ, И ОНО ОБЯЗАТЕЛЬНО: autPoints зовёт ОТРИСОВКА, то есть 60 раз в секунду, а
   внутри — полный обход событий (autTakesOf) и всех дорожек захвата. На пятиминутной песне это десятки
   тысяч шагов НА КАДР. Ключ мемо — адрес плюс takeFxVer: версия поднимается КАЖДОЙ правкой захвата И
   каждой правкой нот (editCommit), то есть ровно тогда, когда ответ мог измениться. Одной записи хватает:
   полоса показывает РОВНО ОДИН адрес зараз (см. rollAut). */
/* ═══ V4b: ПАРАМЕТР «В НОТЕ» НА ПОЛОСЕ — ВИД И ПРАВКА ИЗ САМИХ НОТ ═══
   ⛳ ОДИН ИСТОЧНИК ПРАВДЫ. Величину параметра «в ноте» (fxIsPerNote: прицепочный модуля — Скольжение, яркость аккордов — и
   старые скаляры соло vib/drv/trm) переигровка и заморозка читают из СОБЫТИЯ НОТЫ. Значит и полоса обязана показывать и
   править ИМЕННО ЕГО: прежде она рисовала точки захвата, их правка не меняла ни одной ноты — видно одно, звучит другое.
   Точки захвата для этих адресов больше никто не читает (fxLaneMerge их пропускает); захват при этом не тронут.
   ⛳ ЧТО ТАКОЕ «ТОЧКА». Несут величину «вкл» и ведения ноты (pnCarrier) — каждое своё значение, по времени. Подряд идущие
   события с ОДНОЙ величиной — один ОТРЕЗОК; точка — его первое событие. Ступенька между точками — ровно то, что звучит:
   каждая нота берёт величину своего события, и до следующего события величина та же.
   ⛳ ГЛАДКАЯ АВТОМАТИЗАЦИЯ — ФОРМА И РАМПА ЖИВУТ В САМИХ СОБЫТИЯХ, в двух картах нагрузки по ключу адреса 'fxId:pKey':
     a.sh[адрес] = 's' — событие-ТОЧКА, в которую отрезок ВХОДИТ плавно (прямая от предыдущей точки);
                   'r' — событие ВНУТРИ плавного отрезка: его величина — точка прямой, ТОЧКОЙ оно не считается (pnPoints его пропускает);
     a.gen[адрес] = 1 — событие ПОРОЖДЕНО редактором ради этого адреса: ЯКОРЬ (точка посреди зажатой ноты — ведение на её доле) или
                   ШАГ РАМПЫ (ведение внутри зажатой ноты, чтобы голос ехал по прямой). Перестраивая адрес, редактор такие снимает и
                   кладёт заново; событие, нужное и другому адресу, остаётся (снимается только метка).
   Нет карт — ступенька, как было: всё записанное и всё, что пишет рука, звучит байт-в-байт по-прежнему. Звуку карты не нужны
   вовсе: движок читает только величины, а величины в событиях уже стоят на прямой.
   ⛳ ПРАВКА — ПЕРЕСТРОЙКА АДРЕСА ИЗ СПИСКА ТОЧЕК (pnPlan, ОДНА функция на все правки): точки полосы → где каждая вступает
   (на событии этой доли; посреди зажатой ноты — якорем; между нотами — на первом событии после неё, как и прежде) → каждому
   событию дорожки величина и метка по закону «ступенька или прямая» → шаги рампы внутри зажатых нот. Полоса после правки
   перестраивается из нот — точка встаёт туда, где величина действительно вступила, а не туда, куда ткнули.
   ⛳ ПРЕДЕЛ «ТОЧКА ПОСРЕДИ ЗАЖАТОЙ НОТЫ НЕ РОЖДАЕТ СОБЫТИЯ» СНЯТ этим же слайсом: её держит якорь, иначе нарастание внутри ОДНОЙ
   долгой ноты поставить было бы некуда.
   ⛳ ПРАВКА — ОДНА ЗАПИСЬ ИСТОРИИ И ОДИН СБРОС: ходы 'del' (прежние порождённые), 'move' (нагрузка — НОВЫМ объектом, время и
   замороженный лад нетронуты — правило #7) и 'ins' (новые порождённые) собирает editBatch (правило #28); editCommit поднимает
   версию правки дорожки — замороженная устаревает.
   ⛳ «НЕ ЗАДАНО» — ОТСУТСТВИЕ величины в событии: нота играет СЕГОДНЯШНЕЕ умолчание роли (у Скольжения — 20/12 мс, у яркости —
   открытый фильтр, у скаляров — ноль). Рисуется на уровне умолчания (fxDefaultsOf — та же шкала, что у меню); ведущий
   отрезок «не задано» — полка без ручки, как снимок старта у ленты. */
const pnCarrier=fn=> fn==='leadOn'||fn==='leadSet'||fn==='bassOn'||fn==='bassSet'||fn==='chOn'||fn==='chSet'||fn==='drum';   // удар несёт свою карту (яркость ударных), как «вкл» ноты
const pnSame=(x,y)=> (x==null&&y==null) || (x!=null&&y!=null&&Math.abs(x-y)<1e-6);
/* Величина в событии (0..1) либо null — «не задано». Где лежит — по объявлению (fxNoteField) И РОЛИ события: своё поле или
   карта a.fx (яркость — поле a.bri у аккордов, карта у соло/баса/ударных). */
function pnGet(ev,fxId,pKey){
  const a=ev.a, nf=fxNoteField(fxId,pKey,evRole(ev.fn));
  if(nf){ const x=a&&a[nf.key]; return x==null ? null : (nf.inv?1-x:x); }
  const m=a&&a.fx, x=m?m[fxId+':'+pKey]:undefined; return x==null ? null : x;
}
/* НОВАЯ нагрузка с этой величиной (v=null — снять). Карта — тоже новым объектом: записанная карта неизменяема (см. push).
   ⚠️ БАС: опустевшая карта снимается ЦЕЛИКОМ — отсутствие карты у баса и есть «не задано», событие снова байт-в-байт как без
   Скольжения. СОЛО: карта остаётся всегда — у соло её ОТСУТСТВИЕ значит «звучи живой цепью» (правило R2 в applyFx). */
function pnWith(ev,fxId,pKey,v){
  const a=ev.a||{}, nf=fxNoteField(fxId,pKey,evRole(ev.fn)), b={...a};
  if(nf){ if(v==null){ if(!nf.required) delete b[nf.key]; } else b[nf.key]= nf.inv?1-v:v; return b; }   // VOL-3: ОБЯЗАТЕЛЬНОЕ поле (громкость) не снимается никогда — второй рубеж после pnPlan
  const k=fxId+':'+pKey, m={...(a.fx||{})};
  if(v==null) delete m[k]; else m[k]=v;
  if(Object.keys(m).length || ev.fn[0]==='l') b.fx=m; else delete b.fx;
  return b;
}
/* Умолчание адреса в 0..1 — уровень «не задано» на полосе. Та же шкала, что у меню и захвата (fxDefaultsOf, с defBy владельца). */
const pnDef=(key,fxId,pKey)=>{ const i=fxParamKeysOf(fxId).indexOf(pKey), d=fxDefaultsOf(fxId,key); return i>=0&&d[i]!=null ? d[i] : 0; };
/* Метки гладкой автоматизации (см. шапку): форма ('s'/'r') и «порождено ради адреса». Ключ адреса — 'fxId:pKey', как в карте a.fx. */
const pnMk=(fxId,pKey)=>fxId+':'+pKey;
const pnShOf=(e,mk)=>{ const s=e.a&&e.a.sh; return s?s[mk]:undefined; };
const pnGenOf=(e,mk)=>{ const g=e.a&&e.a.gen; return !!(g&&g[mk]); };
/* НОВАЯ нагрузка с меткой формы sh (undefined — снять) и флагом «порождено» для адреса mk. Пустые карты снимаются целиком —
   событие без меток байт-в-байт как до гладкой автоматизации. */
function pnMarks(a,mk,sh,gen){
  const b={...a}, s={...(a.sh||{})}, g={...(a.gen||{})};
  if(sh) s[mk]=sh; else delete s[mk];
  if(gen) g[mk]=1; else delete g[mk];
  if(Object.keys(s).length) b.sh=s; else delete b.sh;
  if(Object.keys(g).length) b.gen=g; else delete b.gen;
  return b;
}
/* ТОЧКИ АДРЕСА: события дорожки, несущие величину, по времени (массив отсортирован — редактор открыт только вне записи).
   Точка — событие, с которого величина МЕНЯЕТСЯ; события внутри плавного отрезка ('r') точками не бывают. Метка 's' делает точкой
   и событие с прежней величиной — это плоский кусок перед подъёмом (pnPlan ставит её ровно для этого случая).
   leadUnset — перед первой точкой есть события БЕЗ величины (ведущее «не задано»): туда можно поставить точку (pnAdd). */
/* ⛳ g0 (слайс «запись отражает плавность руки») — доля ПОСЛЕДНЕГО события предыдущего отрезка с той же величиной (события «внутри
   плавного» 'r' не в счёт). Это миг, до которого величина ТОЧНО стояла: у записанного движения после паузы там лежит ведение
   УДЕРЖАНИЯ (fineStep), и плавный вход в точку начинается ОТТУДА, а не от начала отрезка — иначе прямая ползла бы через всю паузу.
   Рисунок ведёт прямую ОТ g0 (до него — ровно: записанная пауза). У поставленного рукой 's' внутри отрезка события перестроены по прямой ('r'), так
   что g0 там совпадает с долей предыдущей точки — и форма человека едет от точки, как и прежде.
   sh: 's' / 'h' — форма человека; нет — записанная точка (отрезок в неё плавный; паузу записанного несёт ведение удержания). */
function pnPoints(layer,fxId,pKey){
  const mk=pnMk(fxId,pKey), pts=[]; let cur=null, end=null;
  pts.leadUnset=false;
  for(const e of events){ if(e.layer!==layer||!pnCarrier(e.fn)) continue;
    const v=pnGet(e,fxId,pKey), s=pnShOf(e,mk);
    if(!cur){ cur={t:e.t, v, sh:undefined, ev:e}; end=e.t; if(v!=null) pts.push(cur); else pts.leadUnset=true; continue; }
    if(s==='r') continue;
    if(pnSame(v,cur.v) && !(s==='s' && e.t>cur.t+AUT_EPS)){ end=e.t; continue; }
    cur={t:e.t, v, sh: (s==='s'||s==='h')?s:undefined, ev:e, g0:end}; pts.push(cur); end=e.t;
  }
  return pts;
}
/* ФОРМА ОТРЕЗКА, ВХОДЯЩЕГО В ТОЧКУ i, — тем же законом, что у шины (autSmoothOf), промежуток — от g0. 's'/'h' — форма человека. */
function pnEffSh(P,i){
  const p=P[i]; if(!p) return undefined;
  if(p.sh) return p.sh;
  if(i<=0||p.v==null||P[i-1].v==null) return 'h';
  return autSmoothOf({t:(p.g0??P[i-1].t), v:P[i-1].v}, p) ? 's' : 'h';
}
/* ВИД ДЛЯ ПОЛОСЫ — в той же форме, что у ленты ({base, baseT, pts}), плюс per (адрес «в ноте») и spans — где у дорожки ЗВУЧАТ
   ноты: вне их величина не звучит ни на чём, и draw рисует там линию приглушённой (ноты берём из songNotes — единственного
   спаривания «вкл»/«выкл», правило редактора). */
function pnView(layer,key,fxId,pKey){
  const pts=[], P=pnPoints(layer,fxId,pKey);
  /* VOL-3: у ОБЯЗАТЕЛЬНОГО поля (громкость) «не задано» нет — полка слева до первой точки стоит на величине ПЕРВОЙ ноты, а не на
     уровне умолчания: ей там просто не на чем звучать (линия приглушена — там нет нот), и уровень умолчания ничего бы не значил. */
  const d = pnReq(fxId,pKey,laneRoleOf(layer)) && P.length && P[0].v!=null ? P[0].v : pnDef(key,fxId,pKey);
  /* ⛳ smooth — ТОТ ЖЕ закон, что у шины и у переигровки (pnEffSh → autSmoothOf): draw ведёт прямую, ui показывает ╱/⌐. g0 — откуда
     прямая начинается у ЗАПИСАННОЙ точки (после паузы — от ведения удержания, см. pnPoints); у формы человека — от предыдущей точки.
     ⛳ ЗВУК ТУТ ЖЕ: величина «в ноте» звучит из событий, и записанное движение лежит в них КАЖДОЙ единицей (тонкая запись, fineStep) —
     ровно та плотность, с какой редактор кладёт ведения рампы поставленному рукой плавному отрезку (AUT_RAMP_EPS = 0.01). Голос
     ведёт каждую ступень своей τ 40–50 мс — плавный отрезок записанного звучит так же, как нарисованный рукой, без добавленных
     событий. */
  P.forEach((r,i)=>{   // ведущее «не задано» точкой не бывает (pnPoints) — это полка (base), ручки нет
    const sh=pnEffSh(P,i), smooth= sh==='s' && i>0 && r.v!=null && P[i-1].v!=null;   // от «не задано» ехать не от чего — как и прежде
    pts.push({ per:true, smooth, g0: smooth && !r.sh && r.g0!=null ? r.g0 : null,
               pt:{ t:r.t, v:r.v==null?d:r.v, unset:r.v==null, sh:r.sh, pn:{layer,key,fx:fxId,p:pKey} } });   // sh — форма человека ('s'/'h') или нет (записанная)
  });
  /* У УДАРНЫХ «пауз» в этом смысле нет: удар — миг, его величина звучит в миг удара, и приглушать линию между ударами значило
     бы приглушить её всю. Поэтому для дорожки ударных spans не отдаём — линия рисуется целиком. */
  if(laneRoleOf(layer)==='dr') return { base:d, baseT:0, pts, per:true, spans:null };
  const sp=[];
  for(const n of songNotes().notes) if(n.layer===layer&&n.role!=='dr') sp.push([n.start, n.end==null?Infinity:n.end]);
  sp.sort((a,b)=>a[0]-b[0]);
  const spans=[]; for(const s of sp){ const L=spans[spans.length-1]; if(L&&s[0]<=L[1]) L[1]=Math.max(L[1],s[1]); else spans.push([s[0],s[1]]); }
  return { base:d, baseT:0, pts, per:true, spans };
}
/* ═══ ⛔ ИНВАРИАНТ VOL-3: ГРОМКОСТЬ У НОТЫ НЕ СНИМАЕТСЯ НИКОГДА ═══
   Параметр с ОБЯЗАТЕЛЬНЫМ полем в событии (объявление note.required — сегодня только громкость, поле a.vol) не бывает «не задан»:
   нота без громкости дала бы движку undefined, то есть NaN в гейне, а в лучшем случае — тишину по случайности. Держится ТРЕМЯ
   рубежами, все здесь, где живут пер-нотные правки полосы:
     1. pnPlan (ниже) — ЕДИНСТВЕННЫЙ производитель пер-нотных ходов — у обязательного поля берёт ведущую величину из первой
        точки (а не «не задано») и без единой точки отказывает;
     2. pnWith не удаляет обязательное поле, даже если его попросят (второй рубеж);
     3. операции полосы подставляют НАСТОЯЩУЮ величину вместо «не задано»: удаление ПЕРВОЙ точки отдаёт её отрезку величину
        СЛЕДУЮЩЕГО (а не «не задано»); единственный отрезок удалить нельзя; сдвиг первой точки ПОЗЖЕ отказывает (левее неё
        нет величины, которую отдать). Снять громкость с дорожки (autChainRemove) и переставить её (autChainMove) нельзя —
        она постоянная (fxPerm).
   ⚠️ Это НЕ запрет на тишину: громкость 0 — законная величина, её можно поставить точкой. Запрет — на ОТСУТСТВИЕ величины. */
const pnReq=(fxId,pKey,role)=>{ const nf=fxNoteField(fxId,pKey,role); return !!(nf&&nf.required); };
/* ═══ ПЕРЕСТРОЙКА АДРЕСА ИЗ СПИСКА ТОЧЕК (гладкая автоматизация) — ОДНА функция на все правки полосы «в ноте» ═══
   want — желаемые точки по времени: {t, v (null — «не задано»), sh ('s' — въезжать плавно), me (это та точка, которую правят)}.
   Отдаёт {list — ходы для editBatch, P — точки, как они ВСТУПЯТ}, либо null (обязательному полю не осталось ни одной точки).
   ⛳ ПОЧЕМУ ВЕДЕНИЯ, А НЕ РАМПА В ГОЛОСЕ. Величину «в ноте» голос берёт из СОБЫТИЙ, и её же читают переигровка, догонялка, шов
   заморозки и рендер. Рампа в голосе потребовала бы нового поля события («ехать к v до доли t»), перевода долей в секунды в
   каждом из этих путей (темп, шов скобы, вход посреди рампы) и своей кривой у каждого параметра (громкость — v², яркость — лог
   герц, скаляры — свои глубины), то есть пяти новых дорог звука. Ведения не требуют НИ ОДНОЙ: это обычные события, их уже
   умеет каждый путь, и заморозка повторяет их по построению. Цена названа: события — не больше ста на ноту за весь ход (порог
   AUT_RAMP_EPS), и правка ноты (перенос, длина) рампу не перестраивает — перестроит следующая правка этой полосы.
   ⚠️ Скольжение (fxNoteFollows=false) ведений не получает: голос читает его лишь на смене высоты, и там оно уже стоит на прямой. */
function pnPlan(layer,fxId,pKey,want){
  const mk=pnMk(fxId,pKey), req=pnReq(fxId,pKey,laneRoleOf(layer)), follow=fxNoteFollows(fxId,pKey);
  const xOnly=e=>{ const g=e.a&&e.a.gen; return !!(g&&g[mk]) && Object.keys(g).length===1; };   // порождено ТОЛЬКО ради этого адреса — снимается и кладётся заново
  const car=events.filter(e=>e.layer===layer&&pnCarrier(e.fn));
  const drop=car.filter(xOnly), keep=car.filter(e=>!xOnly(e));
  const notes=songNotes().notes.filter(n=>n.layer===layer&&n.role!=='dr');   // удар — миг: посреди него точке не встать, рампе ехать не в чем
  const heldAt=t=>notes.filter(n=>n.start<t-AUT_EPS && (n.end==null||n.end>t+AUT_EPS));
  /* 1) ГДЕ ТОЧКА ВСТУПАЕТ: на событии этой доли; посреди зажатой ноты — ЯКОРЕМ на своей доле; между нотами — на первом событии
        после неё (там величина и вступит; прежнее правило). Две точки на одной доле — побеждает поздняя по списку, а правленая
        (me) — всегда. */
  let P=[];
  for(const w of want){
    const at=keep.find(e=>Math.abs(e.t-w.t)<AUT_EPS);
    let te=null, anchor=false;
    if(at) te=at.t;
    else if(follow && heldAt(w.t).length){ te=w.t; anchor=true; }  // якорь. ⚠️ Скольжению — нет: его читают лишь на смене высоты, и точка вступает там (ниже)
    else { const nx=keep.find(e=>e.t>w.t); if(nx) te=nx.t; }
    if(te==null) continue;                                          // после последней ноты точке звучать не на чем
    const q={t:te, v:w.v, sh:w.sh, me:w.me, anchor};
    if(P.length && Math.abs(P[P.length-1].t-te)<AUT_EPS){ if(!P[P.length-1].me || q.me) P[P.length-1]=q; }   // правленая точка (me) не уступает соседу, на чьё событие она съехала
    else P.push(q);
  }
  /* 2) ЧИСТКА. Точка с прежней величиной не нужна — кроме плоского куска перед плавным подъёмом: там она держит начало прямой и
        становится 's' (плоская прямая звучит как ступенька, а меткой её видно pnPoints). Плавно въезжать можно лишь из точки с
        величиной в точку с величиной — иначе форма снимается (от «не задано» ехать не от чего). */
  const Q=[];
  for(let i=0;i<P.length;i++){ const p=P[i], pr=Q[Q.length-1], nx=P[i+1];
    if(!pr && !req && p.v==null) continue;                          // «не задано» первой точкой — то же, что ведущее «не задано»
    if(pr && pnSame(p.v,pr.v)){ if(nx && nx.sh==='s' && p.v!=null && nx.v!=null) p.sh='s'; else { if(p.me&&Q.length) Q[Q.length-1].me=true; continue; } }
    if(p.sh==='s' && !(pr && pr.v!=null && p.v!=null)) p.sh='h';   // ехать не от чего — СТУПЕНЬКА ЧЕЛОВЕКА, а не «нет формы» (иначе её начал бы выводить закон движения записанного)
    Q.push(p);
  }
  P=Q;
  if(req && !P.length) return null;
  const lead= req ? P[0].v : null;                                  // VOL-3: у обязательного поля левее первой точки — ЕЁ величина, не «не задано»
  const idxAt=t=>{ let i=-1; for(let k=0;k<P.length&&P[k].t<=t+AUT_EPS;k++) i=k; return i; };
  const valAt=t=>{ const i=idxAt(t); if(i<0) return lead;
    const p=P[i], q=P[i+1];
    if(q && q.sh==='s' && t>p.t+AUT_EPS) return p.v+(q.v-p.v)*(t-p.t)/(q.t-p.t);   // ПРЯМАЯ в шкале 0..1 — той, в которой рисует полоса
    return p.v; };
  const markAt=t=>{ const i=idxAt(t); if(i<0) return undefined;
    if(Math.abs(P[i].t-t)<AUT_EPS) return P[i].sh;                 // событие точки — форма входящего отрезка
    const q=P[i+1]; return q&&q.sh==='s' ? 'r' : undefined; };      // внутри плавного — метка «часть прямой»
  /* 3) ХОДЫ: прежние порождённые — снять; каждому событию — величина и метка; новые порождённые — положить. */
  const list=[];
  if(drop.length) list.push({ kind:'del', evs:drop });
  const atPt=t=>P.some(p=>Math.abs(p.t-t)<AUT_EPS);
  for(const e of keep){
    const v=valAt(e.t), m=markAt(e.t);
    /* ПОРОЖДЁННОЕ ДРУГИМ АДРЕСОМ, но служащее и этому (точка или шаг рампы на той же доле) — помечаем и этим адресом: иначе
       перестройка того адреса сняла бы событие, и здесь на его доле осталась бы дыра. */
    const gx = !!(e.a&&e.a.gen) && (m==='r' || atPt(e.t));
    if(pnSame(pnGet(e,fxId,pKey),v) && pnShOf(e,mk)===m && pnGenOf(e,mk)===gx) continue;   // уже так — не ход (↶ не должен «ничего не делать»)
    list.push({ kind:'move', ev:e, from:{t:e.t, a:e.a}, to:{t:e.t, a:pnMarks(pnWith(e,fxId,pKey,v),mk,m,gx)} });
  }
  /* ПОРОЖДЁННОЕ ВЕДЕНИЕ ноты n на доле T: копия её последнего события не позже T — ступень, регистр, ключ владельца (a.v/a.k),
     замороженный лад (правило #7), номер взятого (⤺ снимет его вместе с нотой). Без связки T3 и без бенда (они — атаки).
     ⚠️ СОЛО: hold:true ТОЛЬКО у ноты терменвокса — такое ведение частоты не несёт и бенд не сбивает. У обычной ноты hold был бы
     ложью: догонялка прочла бы ведение как терменвоксное и подняла ноту на ступени АТАКИ, а не на той, где она звучит.
     ⚠️ ЧУЖИЕ АДРЕСА, чья прямая идёт через T, получают точку СВОЕЙ прямой (между соседними событиями ноты — это она и есть),
     а не прошлую величину: иначе ведение громкости откатывало бы идущую рампу яркости на шаг назад. */
  const setFn={ld:'leadSet', bs:'bassSet', ch:'chSet'};
  const mkEv=(n,T,m,v)=>{
    let src=null, nxt=null;
    for(const x of n.evs){ if(!pnCarrier(x.fn)||xOnly(x)) continue; if(x.t<=T+AUT_EPS) src=x; else { nxt=x; break; } }
    if(!src) return null;
    const fn=setFn[n.role];
    let a={...src.a}; delete a.tie; delete a.bend; delete a.sh; delete a.gen;
    if(n.role==='ld'){ const th=src.a.hold || ldTherm(n); if(th) a.hold=true; else delete a.hold; }   // S0: тот же тест терменвокса, что у songSegs (ldTherm) — истинность прежняя
    else delete a.inst;                                              // ведения баса и аккорда тембра не несут (T0)
    const ss=src.a.sh||{}, ns=(nxt&&nxt.a.sh)||{}, sh={};
    for(const k of new Set([...Object.keys(ss),...Object.keys(ns)])){ if(k===mk) continue;
      const inR = ns[k]==='r'||ns[k]==='s';
      if(!(ss[k]==='r'||inR)) continue;
      sh[k]='r';
      if(inR && nxt.t>src.t){ const c=k.indexOf(':'), f=k.slice(0,c), p=k.slice(c+1), v0=pnGet(src,f,p), v1=pnGet(nxt,f,p);
        if(v0!=null&&v1!=null) a=pnWith({fn,a},f,p, v0+(v1-v0)*(T-src.t)/(nxt.t-src.t)); }
    }
    if(Object.keys(sh).length) a.sh=sh;
    const e={ t:T, layer:src.layer, fn, a:pnMarks(pnWith({fn,a},fxId,pKey,v),mk,m,true), sc:src.sc, sev:src.sev, tk:src.tk };
    if(src.jam) e.jam=true;
    return e;
  };
  const ins=[];
  /* ЯКОРЬ — только у точки, под которой нет ни одного события дорожки, и тогда в КАЖДУЮ ноту, зажатую на её доле: полоса одна на
     дорожку, и поставленная посреди звука величина вступает у всего, что звучит.
     ⚠️ Точке, стоящей НА событии, якорей в чужих зажатых нотах НЕ кладём, и это защита, а не экономия: перестройка обходит ВСЕ
     точки адреса, а у записанного полифонично (две руки, свои громкости) точки чередуются по рукам — якоря у каждой переписали бы
     каждой ноте величину соседней руки по всей дорожке от первой же правки. Там величина вступает, как и прежде, на следующем
     событии ноты. */
  for(const p of P) if(p.anchor) for(const n of heldAt(p.t)){ const e=mkEv(n,p.t,p.sh,p.v); if(e) ins.push(e); }
  if(follow) for(let i=1;i<P.length;i++){ const p=P[i-1], q=P[i]; if(q.sh!=='s') continue;
    for(const n of notes){
      const lo=Math.max(p.t,n.start), hi=Math.min(q.t, n.end==null?Infinity:n.end);
      if(!(hi>lo+AUT_EPS)) continue;
      const own=n.evs.filter(x=>pnCarrier(x.fn)&&!xOnly(x));
      let last=valAt(lo);
      /* Сетка шагов — от начала ОТРЕЗКА (а не ноты и не такта): перестройка того же отрезка кладёт шаги на те же доли. */
      for(let k=Math.floor((lo-p.t)/AUT_RAMP_BEAT)+1; ; k++){ const T=p.t+k*AUT_RAMP_BEAT;
        if(T>=hi-AUT_EPS) break;
        if(T<=lo+AUT_EPS) continue;
        const v=valAt(T); if(Math.abs(v-last)<AUT_RAMP_EPS) continue;
        last=v;
        if(own.some(x=>Math.abs(x.t-T)<AUT_EPS)) continue;          // своё событие на этой доле уже есть — величину ему дал проход выше
        const e=mkEv(n,T,'r',v); if(e) ins.push(e);
      }
    }
  }
  if(ins.length) list.push({ kind:'ins', evs:ins });
  return { list, P };
}
/* Точка списка — по её доле и величине (объекты точек пересобираются после каждой правки, держаться за них нельзя). */
function pnLocate(P,pt){
  return P.findIndex(r=> Math.abs(r.t-pt.t)<AUT_EPS && pnSame(r.v, pt.unset?null:pt.v));
}
const pnWant=P=>P.map(p=>({t:p.t, v:p.v, sh:p.sh}));
/* Доля, на которой ВСТУПИЛА правленая точка (me), — туда и ставим выделение. */
const pnAt=(R,t)=>{ const p=R.P.find(q=>q.me); return p?p.t:t; };
/* Точка вида, которую выделить после правки: первая на доле ≥ t (там величина и вступила). Объект — ИЗ мемо autPoints, поэтому
   ui находит его в D.pts простым сравнением. */
function pnPick(P,t){ const D=autPoints(P.layer,P.key,P.fx,P.p); return D.pts.find(r=>r.pt.t>=t-AUT_EPS) || null; }
/* ПЕРЕНОС ТОЧКИ. Величина — у точки (её отрезок до следующей); время — зажато между соседями: дотянул до соседа — перенесённая
   его ЗАМЕНЯЕТ (прежде перенос «перетирал» всех, через кого проехал; с формами отрезков это давало бы непредсказуемые прямые).
   Форма точки едет вместе с ней. */
/* ⛳ ПРАВЛЕНАЯ ТОЧКА ДЕРЖИТ ТУ ФОРМУ, ЧТО БЫЛА ВИДНА (тот же закон, что у шины, autFreeze): записанная точка без своей формы получает
   выведенную ('s'/'h') — у правленой и у соседа справа. flat — только для САМОЙ правленой точки: если её выведенный плавный вход
   начинался ПОСЛЕ удержания (g0 позже предыдущей точки), форма человека поехала бы от предыдущей ТОЧКИ — через всю паузу; поэтому
   перед ней кладётся плоская точка на g0 с прежней величиной (pnPlan такую держит: «плоский кусок перед плавным подъёмом»). Соседу
   справа плоской точки не даём — её величина была бы величиной правленой точки, а та сейчас меняется; там форма остаётся выводимой. */
function pnFreeze(want,P,j,flat){
  const p=P[j]; if(!p||p.sh||!want[j]) return;
  const sh=pnEffSh(P,j), late= sh==='s' && p.g0!=null && j>0 && p.g0>P[j-1].t+AUT_EPS;
  if(late && !flat) return;
  want[j].sh=sh;
  if(late) want.splice(j,0,{ t:p.g0, v:P[j-1].v });
}
function pnMove(pt,t,v){
  if(!editGuard()) return false;
  const A=pt.pn, P=pnPoints(A.layer,A.fx,A.p), i=pnLocate(P,pt); if(i<0) return false;
  const want=pnWant(P); want[i].me=true;
  pnFreeze(want,P,i+1,false); pnFreeze(want,P,i,true);             // сосед справа ПЕРВЫМ: его заморозка индексов не сдвигает, а плоская точка правленой — сдвигает
  const k=want.findIndex(w=>w.me);
  if(Math.abs(t-pt.t)>AUT_EPS){                                    // ВРЕМЯ — соседи по списку ЖЕЛАНИЙ (с плоской точкой, если она легла)
    const lo= k>0 ? want[k-1].t : 0, hi= k+1<want.length ? want[k+1].t : Infinity;
    const b=Math.max(lo,Math.min(hi,Math.max(0,t)));
    if(k===0 && b>want[0].t && pnReq(A.fx,A.p,laneRoleOf(A.layer))) return false;   // VOL-3: первая точка громкости ПОЗЖЕ — левее неё величина та же (ведущая = первая), правка ничего бы не сдвинула, кроме лишнего якоря
    want[k].t=b;
    if(k>0 && Math.abs(b-lo)<AUT_EPS) want.splice(k-1,1);
    else if(k+1<want.length && Math.abs(b-hi)<AUT_EPS) want.splice(k+1,1);
  }else want[k].v=Math.max(0,Math.min(1,v));                       // ВЕЛИЧИНА
  const R=pnPlan(A.layer,A.fx,A.p,want);
  if(!R||!editBatch(R.list)) return false;                         // пусто — не правка (↶ не должен «ничего не делать»)
  return pnPick(A,pnAt(R,pt.t)) || true;
}
/* УДАЛЕНИЕ. Отрезок уходит к предыдущей величине. VOL-3: у ОБЯЗАТЕЛЬНОГО поля ведущая величина — первой точки, поэтому при
   удалении первой её место занимает следующая; единственную удалить нечем заменить — отказ (pnPlan вернёт null). */
function pnDelete(pt){
  if(!editGuard()) return false;
  const A=pt.pn, P=pnPoints(A.layer,A.fx,A.p), i=pnLocate(P,pt); if(i<0) return false;
  const want=pnWant(P);
  pnFreeze(want,P,i+1,false);                                      // сосед справа теперь въезжает от предыдущей — его видимая форма застывает (без плоской точки, см. pnFreeze)
  want.splice(i,1);
  const R=pnPlan(A.layer,A.fx,A.p,want);
  return !!R && editBatch(R.list);
}
/* НОВАЯ ТОЧКА — ПЛАВНАЯ, если перед ней есть точка с величиной (решение: поставленное рукой въезжает плавно). Ставится и ПОСРЕДИ
   зажатой ноты (якорь). До первой точки — только в ведущее «не задано» (как прежде): иначе новая первая точка тихо переписала
   бы все ноты левее неё. На доле существующей точки — это правка её величины. */
function pnAdd(layer,key,fxId,pKey,t,v){
  if(!editGuard()) return null;
  const P=pnPoints(layer,fxId,pKey); let j=-1;
  for(let i=0;i<P.length;i++){ if(P[i].t<=t+AUT_EPS) j=i; else break; }
  if(j<0 && !P.leadUnset) return null;                             // до первой ТОЧКИ нот без величины нет — покрывать нечего
  const want=pnWant(P), x=Math.max(0,Math.min(1,v));
  pnFreeze(want,P,j+1,false);                                      // сосед справа теперь въезжает от новой точки — его видимая форма застывает (индексов не сдвигает)
  if(j>=0 && Math.abs(P[j].t-t)<AUT_EPS){ want[j].me=true; pnFreeze(want,P,j,true); want[want.findIndex(w=>w.me)].v=x; }   // на доле точки — правка её величины, как перенос по величине
  else want.splice(j+1,0,{ t, v:x, sh: j>=0&&P[j].v!=null ? 's' : 'h', me:true });   // форма поставленной точки — ВСЕГДА человеческая: без неё её форму начал бы выводить закон движения
  const R=pnPlan(layer,fxId,pKey,want);
  if(!R||!editBatch(R.list)) return null;                          // между t и следующей нотой нет — точке негде звучать
  const r=pnPick({layer,key,fx:fxId,p:pKey},pnAt(R,t)); return r?r.pt:null;
}
/* ФОРМА ОТРЕЗКА, ВХОДЯЩЕГО В ТОЧКУ: плавно ↔ ступенькой. Отказ у первой точки и у «не задано» — ехать не от чего. */
function pnShape(pt){
  if(!editGuard()) return false;
  const A=pt.pn, P=pnPoints(A.layer,A.fx,A.p), i=pnLocate(P,pt); if(i<=0) return false;
  if(P[i].v==null || P[i-1].v==null) return false;
  const want=pnWant(P); want[i].sh= pnEffSh(P,i)==='s' ? 'h' : 's'; want[i].me=true;   // переключаем ВИДИМУЮ форму (у записанной — выведенную) и делаем её формой человека
  const R=pnPlan(A.layer,A.fx,A.p,want);
  if(!R||!editBatch(R.list)) return false;
  return pnPick(A,pnAt(R,pt.t)) || true;
}
/* Снять величину адреса со ВСЕХ нот дорожки (для снятия голосового эффекта с дорожки, autChainRemove) — той же перестройкой без
   единой точки: величины уходят, метки снимаются, порождённые ради адреса ведения удаляются.
   ⚠️ Планы параметров одного эффекта строятся по ОДНОМУ исходному состоянию; у сегодняшних голосовых модулей параметр «в ноте»
   один (громкость, яркость, скольжение, скаляры), так что ходы двух планов по одному событию не встречаются. Появится модуль с
   двумя — строить второй план после применения первого. */
function pnStripMoves(layer,fxId){
  const list=[];
  for(const pk of fxParamKeysOf(fxId)) if(fxIsPerNote(fxId,pk)){ const R=pnPlan(layer,fxId,pk,[]); if(R) list.push(...R.list); }
  return list;
}
let autMemoK='', autMemoV=null;
function autPoints(layer,key,fxId,pKey){
  const mk=layer+'|'+key+'|'+fxId+'|'+pKey+'|'+takeFxVer+'|'+evGen+'|'+loop.bpm;   // + loop.bpm: форма записанной точки выводится по промежутку в СЕКУНДАХ (autSmoothOf). Переключатель уха поднимает takeFxVer сам. V4b: + evGen (поднимает КАЖДЫЙ schedInvalidate): вид «в ноте» строится из СОБЫТИЙ, а takeFxVer поднимают только правки редактора — новое взятое в ту же дорожку оставило бы мемо прежним
  if(autMemoK===mk && autMemoV) return autMemoV;
  const r=autPointsCalc(layer,key,fxId,pKey);
  autMemoK=mk; autMemoV=r; return r;
}
function autPointsCalc(layer,key,fxId,pKey){
  let base=null, baseT=Infinity;
  const pts=[];
  /* ⚠️ Адрес ЧУЖОЙ цепи — пусто. Адреса приходят из autAddrs и несут ключ цепи дорожки, так что это страж,
     а не развилка: без него адрес не той цепи вытащил бы точки соседней дорожки из общего взятого сплита. */
  if(key!==laneChainKey(layer)) return { base, baseT:0, pts };
  if(fxIsPerNote(fxId,pKey)) return pnView(layer,key,fxId,pKey);   // V4b: параметр «в ноте» — вид из самих нот, не из точек захвата
  for(const T of autTakesOf(layer)){
    const rec=takeFx.get(T.tk); if(!rec) continue;
    const ch=rec.chains[key];
    if(ch && T.t0<=baseT){ const eff=ch.find(e=>e.fxId===fxId);
      if(eff){ const names=fxParamKeysOf(fxId), i=names.indexOf(pKey);
        if(i>=0 && eff.params[i]!=null){ base=eff.params[i]; baseT=T.t0; } } }
    for(const ent of rec.lane) if(ent.key===key&&ent.fx===fxId&&ent.p===pKey)
      pts.push({pt:ent, tk:T.tk, lane:rec.lane});
  }
  pts.sort((a,b)=> a.pt.t-b.pt.t || a.tk-b.tk);
  /* ФОРМА КАЖДОГО ОТРЕЗКА — ТЕМ ЖЕ законом, что у переигровки (autSmoothOf): draw рисует прямую, где smooth, и ступеньку, где нет;
     кнопка ╱/⌐ показывает то же. Первая точка входит с полки снимка — плавно оттуда не едут ни звук, ни рисунок.
     ⚠️ Предшественник здесь — точка ЭТОЙ дорожки; у переигровки — точка того же адреса во всей песне (одна цепь на роль). Если
     другая дорожка той же роли пишет тот же адрес вперемешку, звук и рисунок могут разойтись — тот же давний предел, что у полки. */
  for(let i=0;i<pts.length;i++) pts[i].smooth = i>0 && autSmoothOf(pts[i-1].pt, pts[i].pt);
  return { base, baseT: baseT===Infinity?0:baseT, pts };
}
/* ⛳ ОБЩИЙ ХВОСТ ВСЕХ ПРАВОК ПОЛОСЫ. editCommit сортирует СОБЫТИЯ и сбрасывает курсоры — здесь этого не
   нужно и НЕЛЬЗЯ: захват не события (правило #28). Нужно ровно одно — поднять версию захвата, чтобы
   лента переигровки пересобралась и правка зазвучала на следующем ▶. */
const autCommit=()=>{ takeFxTouch(); laneEditTouch(); };   // A2: см. laneEditVer
/* ═══ S1: ОДНА ЦЕПЬ ДОРОЖКИ В РЕДАКТОРЕ ═══
   ⛳ ЦЕПЬ ДОРОЖКИ — ЭТО СНИМКИ ВСЕХ ЕЁ ЗАХВАЧЕННЫХ ВЗЯТЫХ. Каждый снимок вступает с первой доли своего взятого (fxLaneMerge),
   поэтому правка цепи, легшая в ОДНО взятое, звучала бы лишь с его старта. Отсюда закон: добавить, снять, переставить —
   ВО ВСЕХ захваченных взятых дорожки, ОДНОЙ записью истории.
   ⚠️ ИСПРАВЛЕННЫЙ ДЕФЕКТ (бас и ударные — уже до S1). Прежде правки брали СТАРШЕЕ взятое дорожки (autEnsure) и, если у него
   не было захвата, заводили ему снимок ЖИВОЙ цепи. Старшим после вставки в редакторе становится РЕДАКТОРСКОЕ взятое (editTake,
   захвата у него нет) — и первая же правка цепи или шинная точка переводила с доли вставленной ноты ВСЮ РОЛЬ, на каждой её
   дорожке (цепи принадлежат роли), на то, как стоят живые ручки. А эффект, добавленный в редакторе, звучал лишь с начала
   последнего взятого.
   ⛳ ВЗЯТОЕ БЕЗ ЗАХВАТА ВНУТРИ ЗАХВАЧЕННОЙ ДОРОЖКИ СВОЕГО НЕ ПОЛУЧАЕТ НИКОГДА — оно играет цепью дорожки (fxLaneMerge: вставка
   раньше всех захваченных заимствует снимок самого раннего из них). ⛔ ЖИВАЯ ЦЕПЬ читается ровно в одном случае: у дорожки
   захвата нет НИ В ОДНОМ взятом — она и шла за живой цепью, а снимок оставляет её звучать ровно как в этот миг (и с этого
   мига ПРИКАЛЫВАЕТ: ручки её больше не достают). Тогда захват получает ОДНО взятое — самое раннее, чтобы цепь начиналась с
   первой ноты дорожки. Снимок делает ТА ЖЕ takeCapStart, что и на ● (опору прореживания она засевает только своему взятому,
   tk===curTake, — здесь это не так, идущая запись цела), а ход 'autcap' кладётся ПЕРВЫМ в ту же запись истории: ↶ снимет и
   его, и дорожка снова пойдёт за живой цепью, как до правки. */
/* Захваченные взятые дорожки — старший номер первым (порядок autTakesOf). */
const autCapTakes=layer=>autTakesOf(layer).filter(T=>takeFx.has(T.tk));
/* Самое раннее взятое по первой доле в дорожке; при равенстве — младший номер. */
const autEarliest=Ts=>Ts.reduce((a,b)=> !a||b.t0<a.t0||(b.t0===a.t0&&b.tk<a.tk) ? b : a, null);
/* Захваты дорожки для правки цепи: [{tk, rec}] (старший первым) и ходы, которые уже сделаны и обязаны войти в запись истории
   ПЕРВЫМИ (сегодня — только заведённый захват, 'autcap'). make=false — не заводить никогда (снять и переставить нечего, пока
   захвата нет: список цепи тогда пуст). */
function autCaps(layer,make){
  const caps=autCapTakes(layer).map(T=>({tk:T.tk, rec:takeFx.get(T.tk)}));
  if(caps.length||!make) return { caps, ops:[] };
  const E=autEarliest(autTakesOf(layer)); if(!E) return { caps, ops:[] };
  takeCapStart(E.tk);
  const rec=takeFx.get(E.tk); if(!rec) return { caps, ops:[] };
  return { caps:[{tk:E.tk, rec}], ops:[{ kind:'autcap', tk:E.tk, rec }] };
}
/* ПРАВКА ЗАХВАТА ОДНОЙ ЗАПИСЬЮ ИСТОРИИ. Ходы ещё НЕ применены: применяет их тот же editApply, которым ходят ↶/↷ (как editBatch).
   Хвост — autCommit, а не editCommit: события не менялись (правило #28 — про события). Один ход — сам ход, без обёртки. */
function autBatch(list){
  if(!list||!list.length) return false;
  for(const u of list) editApply(u,false);
  editPush(list.length===1 ? list[0] : { kind:'batch', list });
  autCommit(); return true;
}
/* ⛳ ПРАВЛЕНАЯ ТОЧКА ДЕРЖИТ ТУ ФОРМУ, ЧТО БЫЛА ВИДНА (слайс «плавная внутри движения»). Форма записанной точки ВЫВОДИТСЯ из
   промежутка и скачка до соседки (autSmoothOf) — сдвинь одну точку, и выведенная форма её отрезка и отрезка СЛЕДУЮЩЕЙ точки могла
   бы молча перевернуться (тронул точку — а ступенька через одну стала прямой). Поэтому правка точки (перенос, удаление, вставка
   перед ней) сперва ЗАМОРАЖИВАЕТ выведенную форму у двух отрезков, которых она касается, — входящего в правленую точку и
   входящего в следующую, — делая их обычными формами человека ('s' или 'h'). Остальные записанные отрезки по-прежнему выводятся.
   Ход 'autshape' — в той же записи истории: ↶ вернёт и точку, и «форма выводится». */
function autFreeze(D,j){
  const r=D&&D.pts[j]; if(!r||r.per||r.pt.sh) return null;       // у «в ноте» и у точки с формой человека — нечего замораживать
  return { kind:'autshape', pt:r.pt, from:undefined, to: r.smooth?'s':'h' };
}
/* Перенос точки: время и величина. Обе зажаты — время не отрицательное, величина в 0..1. */
function autMovePoint(pt,t,v){
  if(pt&&pt.pn) return pnMove(pt,t,v);   // V4b: точка «в ноте» — переписываем НОТЫ; отдаём точку, которую выделить (объекты вида пересобраны)
  if(!editGuard()||!pt) return false;
  const to={t:Math.max(0,t), v:Math.max(0,Math.min(1,v))};
  if(Math.abs(to.t-pt.t)<AUT_EPS && Math.abs(to.v-pt.v)<1e-6) return false;   // не сдвинулось — не правка (иначе ↶ «ничего не делает»)
  const D=autPoints(editLayer(), pt.key, pt.fx, pt.p), i=D.pts.findIndex(r=>r.pt===pt);
  const list=i<0 ? [] : [autFreeze(D,i), autFreeze(D,i+1)].filter(Boolean);
  list.push({ kind:'autmove', pt, from:{t:pt.t,v:pt.v}, to });
  return autBatch(list);
}
function autDeletePoint(rec){
  if(rec&&rec.pt&&rec.pt.pn) return pnDelete(rec.pt);   // V4b: см. pnDelete
  if(!editGuard()||!rec||!rec.lane) return false;
  if(rec.lane.indexOf(rec.pt)<0) return false;
  const pt=rec.pt, D=autPoints(editLayer(), pt.key, pt.fx, pt.p), i=D.pts.findIndex(r=>r.pt===pt);
  const fz=i<0 ? null : autFreeze(D,i+1);                         // следующая точка теперь въезжает от предыдущей — её видимая форма застывает
  return autBatch([...(fz?[fz]:[]), { kind:'autdel', pt, lane:rec.lane }]);
}
/* Новая точка — в СТАРШЕЕ ЗАХВАЧЕННОЕ взятое дорожки (см. шапку O-4: при равной доле побеждает старший номер), в ЦЕПЬ ДОРОЖКИ
   (T4: ключ не передаётся — у дорожки одна цепь, выбирать её вызывающему нечем). ⚠️ S1: именно ЗАХВАЧЕННОЕ — редакторское
   взятое своего захвата не получает (см. autCaps); у дорожки без захвата вовсе он заводится самому раннему взятому. */
function autAddPoint(layer,fxId,pKey,t,v){
  if(!editGuard()) return null;
  const key=laneChainKey(layer); if(!key) return null;
  if(fxIsPerNote(fxId,pKey)) return pnAdd(layer,key,fxId,pKey,Math.max(0,t),v);   // V4b: захват не нужен — правится нота
  /* ⛳ ПОСТАВЛЕННАЯ РУКОЙ ТОЧКА — ПЛАВНАЯ (гладкая автоматизация), если перед ней есть ТОЧКА, от которой плавно ехать. Полка
     снимка точкой не считается (см. fxLaneSmooth): первая точка на полке встаёт ступенькой — иначе одна точка на такте 8 тянула
     бы подъём от самого начала взятого. Смотрим до autCaps: снимок, заведённый им, точек не прибавляет. */
  const D=autPoints(layer,key,fxId,pKey);
  const before=D.pts.some(r=>r.pt.t<=t+AUT_EPS);
  const fz=autFreeze(D, D.pts.findIndex(r=>r.pt.t>t+AUT_EPS));     // следующая точка теперь въезжает от новой — её видимая форма застывает (до autCaps: вид тот, что на экране)
  const {caps,ops}=autCaps(layer,true); if(!caps.length) return null;
  const rec=caps[0].rec;                                          // старшее захваченное
  /* Форма поставленной точки — ВСЕГДА человеческая: 's' от точки, 'h' после полки. Без поля она стала бы «записанной» (плавной по
     умолчанию), и ступенька человека пропала бы. */
  const pt={ t:Math.max(0,t), key, fx:fxId, p:pKey, v:Math.max(0,Math.min(1,v)), sh: before?'s':'h' };
  return autBatch([...ops, ...(fz?[fz]:[]), { kind:'autins', pt, lane:rec.lane }]) ? pt : null;   // точку кладёт editApply (как ↷) — сюда же, первым, ход заведённого захвата
}
/* ⛳ ФОРМА ОТРЕЗКА, ВХОДЯЩЕГО В ВЫБРАННУЮ ТОЧКУ: плавно ↔ ступенькой (гладкая автоматизация). Одна запись истории.
   Отказ, когда перед точкой нет точки (полка снимка / «не задано» / первая) — плавно ехать там не от чего; ui говорит это словами.
   Отдаёт: false — отказ; для точки ленты — true; для точки «в ноте» — точку, которую выделить (вид пересобран из нот). */
function autShapePoint(rec){
  const pt=rec&&rec.pt; if(!pt) return false;
  if(pt.pn) return pnShape(pt);
  if(!editGuard()) return false;
  const D=autPoints(editLayer(), pt.key, pt.fx, pt.p);           // полоса показывает ОТКРЫТУЮ дорожку — её вид и спрашиваем
  const i=D.pts.findIndex(r=>r.pt===pt);
  if(i<=0) return false;                                          // первая точка адреса — слева только полка снимка
  const from=pt.sh, to= D.pts[i].smooth ? 'h' : 's';               // переключаем ВИДИМУЮ форму (у записанной — выведенную) и делаем её формой человека
  return autBatch([{ kind:'autshape', pt, from, to }]);
}
const autShapeSet=(pt,sh)=>{ if(sh) pt.sh=sh; else delete pt.sh; };   // ПОЛЯ НЕТ — записанная точка (отрезок плавный); 's'/'h' — форма человека
/* ═══ ЧАСТЬ 2: ЦЕПЬ САМОЙ ДОРОЖКИ ═══
   ⛳ ГДЕ ЖИВЁТ ЭФФЕКТ, ДОБАВЛЕННЫЙ В РЕДАКТОРЕ: в СНИМКЕ ЦЕПИ ВЗЯТОГО (rec.chains[key]) — то есть в
   ЗАХВАТЕ ДОРОЖКИ, и больше нигде. ⛔ Живая цепь (state.fxChains) не трогается ни на символ: она —
   инструмент рук, и переписать её значило бы отнять у человека раскладку по пальцам (тот же закон, по
   которому переигровка подменяет ПУТЬ, а не цепь, — см. fxPlayPath).
   Переигровка подхватит это сама: fxPlayBuild кладёт снимок в ленту записью состава (FX_CHAIN), а
   fxPlayDrive превращает её в путь. Ни одной новой строки в звуковом пути не понадобилось.
   ⛳ T4: ЦЕПЬ — ОДНА, ЦЕПЬ ДОРОЖКИ. Ключ владельца функции берут сами (laneChainKey), а не у вызывающего:
   прежде ui выбирал «в чью цепь» по вкладке роли, и на дорожке двух ролей полоса могла показывать одну
   цепь, а ▲ двигать другую. Роль у дорожки одна — и выбора, который можно сделать неверно, больше нет. */
/* ⛳ S1: СПИСОК ЦЕПИ ДОРОЖКИ — ОБЪЕДИНЕНИЕ снимков ВСЕХ её захваченных взятых, ТЕМ ЖЕ законом, что у списка адресов полосы
   (autAddrs): от младшего взятого к старшему, эффект, встреченный снова, переезжает на место из более старшего. Разойдись эти
   два порядка — меню показало бы одного соседа, а ▲▼ двигали бы к другому. Прежде список брал одно старшее взятое, и эффект из
   раннего взятого полоса показывала, а ▲▼⊘ его не видели. Эффекты, добавленные ПОСРЕДИ взятого (запись состава в ленте, а не
   в снимке), сюда по-прежнему не входят — их ▲▼⊘ не трогают (названный предел). */
function autChainOf(layer){
  const key=laneChainKey(layer); if(!key) return [];
  const out=[];
  for(const T of autCapTakes(layer).slice().reverse()){
    const ch=takeFx.get(T.tk).chains[key]; if(!ch) continue;
    /* VOL-0: БЕЗ постоянной записи (громкость). Этот список читает ТОЛЬКО ui редактора — и ради индексов ▲▼: громкость стоит в
       снимке первой, и без фильтра у первого показанного эффекта ожила бы стрелка ▲ (двигать его «выше громкости»). */
    for(const e of ch){ if(fxPerm(e.fxId)) continue;
      const i=out.indexOf(e.fxId); if(i>=0) out.splice(i,1);
      out.push(e.fxId); }
  }
  return out;
}
/* ДОБАВИТЬ — в КАЖДОЕ захваченное взятое, где эффекта нет (у каждого своя запись с умолчаниями владельца — не общий объект:
   снимки взятых независимы). Эффект звучит по всей дорожке, с её первой ноты. У дорожки без захвата вовсе захват заводится
   (autCaps) — если в живой цепи эффект уже стоял, правкой остаётся сам заведённый захват: дорожка теперь с ним приколочена. */
function autChainAdd(layer,fxId){
  if(!editGuard()||!fxId) return false;
  const key=laneChainKey(layer); if(!key) return false;
  const {caps,ops}=autCaps(layer,true); if(!caps.length) return false;
  const list=ops.slice();
  for(const c of caps){ const ch=c.rec.chains[key];
    if(!ch || ch.some(e=>e.fxId===fxId)) continue;                   // тот же инвариант, что у живой цепи: одна запись на эффект
    list.push({ kind:'autfxins', ent:{ fxId, params:fxDefaultsOf(fxId,key) }, ch });   // V4: умолчание — ДЛЯ ЭТОГО владельца (defBy)
  }
  return autBatch(list);
}
/* СНЯТЬ — из КАЖДОГО захваченного взятого, где эффект есть, одной записью истории (ходы 'autfxdel' помнят место: ↶ вернёт в
   обратном порядке каждый на своё). Захвата не заводит: у дорожки без него снимать нечего. */
function autChainRemove(layer,fxId){
  if(!editGuard()||fxPerm(fxId)) return false;                      // VOL-0: постоянную запись не снимают (громкость есть у ноты всегда)
  const key=laneChainKey(layer); if(!key) return false;
  const list=[];
  for(const c of autCaps(layer,false).caps){ const ch=c.rec.chains[key]; if(!ch) continue;
    const i=ch.findIndex(e=>e.fxId===fxId); if(i>=0) list.push({ kind:'autfxdel', ent:ch[i], ch, at:i }); }
  if(!list.length) return false;
  /* ⛳ V4b: ГОЛОСОВОЙ ЭФФЕКТ ЖИВЁТ В НОТАХ, и снять его с дорожки — значит снять его величины с нот: иначе полоса пропала бы, а
     ноты звучали бы по-прежнему со Скольжением («убрал — а слышно»). Снятие из цепи и очистка нот — ОДНА запись истории,
     один сброс (editBatch, правило #28): ↶ вернёт и эффект, и величины. Шинный — как было. */
  const strip=pnStripMoves(layer,fxId);
  return strip.length ? editBatch([...list, ...strip]) : autBatch(list);
}
/* Перестановка — тем же переносом splice, что и у живой цепи (fxChainMove): порядок слышен, значит его
   надо уметь менять; вторая модель порядка не заводится. dir: −1 раньше, +1 позже.
   ⛳ S1: СОСЕД — ПО ПОКАЗАННОМУ СПИСКУ (autChainOf, объединение взятых), и в КАЖДОМ захваченном взятом, где есть оба, эффект
   встаёт ВПЛОТНУЮ перед соседом (−1) или сразу за ним (+1). Где снимки взятых совпадают по порядку (обычный случай), это ровно
   прежний шаг на одно место. Где разошлись — эффект подтягивается к соседу через стоящих между ними. */
function autChainMove(layer,fxId,dir){
  if(!editGuard()) return false;
  const key=laneChainKey(layer); if(!key) return false;
  const U=autChainOf(layer), i=U.indexOf(fxId), j=i+(dir<0?-1:1);
  if(i<0||j<0||j>=U.length) return false;
  const nb=U[j];
  if(fxPerm(fxId)||fxPerm(nb)) return false;   // VOL-0: постоянная запись не переставляется и соседом для переноса не служит (её место в снимке — первое; в U её и так нет)
  const list=[];
  for(const c of autCaps(layer,false).caps){ const ch=c.rec.chains[key]; if(!ch) continue;
    const a=ch.findIndex(e=>e.fxId===fxId), b=ch.findIndex(e=>e.fxId===nb); if(a<0||b<0) continue;
    const b2=b-(a<b?1:0), to= dir<0 ? b2 : b2+1;                    // индексы ПОСЛЕ изъятия — так их читает editApply ('autfxmove': splice(from,1), splice(to,0))
    if(to!==a) list.push({ kind:'autfxmove', ch, from:a, to });
  }
  return autBatch(list);
}
/* ОДИН ход истории в ЛЮБУЮ сторону. undo=true — назад, false — вперёд. Перенос переставляет время и
   нагрузку на нужное состояние; удаление и вставка — зеркальны друг другу и возят ТОТ ЖЕ объект события
   (никаких копий: за объект держатся выделение и спаривание нот). */
function editApply(u,undo){
  if(u.kind==='move'){ const s= undo?u.from:u.to; u.ev.t=s.t; u.ev.a=s.a; return; }
  if(u.kind==='timbre'){ for(const c of u.ch) c.ev.a = undo?c.from:c.to; return; }   // T5: вся замена — одним ходом, нагрузки те же объекты
  if(u.kind==='batch'){ const L=u.list;                                            // E1: составная правка — вперёд по порядку, назад в обратном (см. editBatch)
    if(undo) for(let i=L.length-1;i>=0;i--) editApply(L[i],true); else for(const s of L) editApply(s,false);
    return; }
  /* ⛳ ПРАВКИ ПОЛОСЫ АВТОМАТИЗАЦИИ (O-4) — В ТОЙ ЖЕ ИСТОРИИ, что и ноты, и по той же форме: ход возит
     ТОТ ЖЕ объект (точку или запись цепи), а не копию. Разной у них только цель: там массив событий,
     здесь массив дорожки автоматизации или снимок цепи взятого.
     ⛔ ВТОРОЙ ИСТОРИИ НЕ ЗАВОДИМ: ↶ у человека одна, и она обязана снимать последнее сделанное, чем бы
     оно ни было. Отсюда же и общий хвост — takeFxTouch, чтобы снятая правка перестала звучать. */
  if(u.kind==='autmove'){ const s= undo?u.from:u.to; u.pt.t=s.t; u.pt.v=s.v; takeFxTouch(); return; }
  if(u.kind==='autshape'){ autShapeSet(u.pt, undo?u.from:u.to); takeFxTouch(); return; }   // гладкая автоматизация: форма отрезка точки ленты — оба состояния в записи, как у переноса
  if(u.kind==='autins'||u.kind==='autdel'){
    const add=(u.kind==='autdel')===undo;
    if(add){ if(u.lane.indexOf(u.pt)<0) u.lane.push(u.pt); }
    else { const i=u.lane.indexOf(u.pt); if(i>=0) u.lane.splice(i,1); }
    takeFxTouch(); return;
  }
  if(u.kind==='autfxins'||u.kind==='autfxdel'){
    const add=(u.kind==='autfxdel')===undo;
    if(add){ if(u.ch.indexOf(u.ent)<0) u.ch.splice(u.at==null?u.ch.length:Math.min(u.at,u.ch.length),0,u.ent); }
    else { const i=u.ch.indexOf(u.ent); if(i>=0) u.ch.splice(i,1); }
    takeFxTouch(); return;
  }
  if(u.kind==='autfxmove'){ const from=undo?u.to:u.from, to=undo?u.from:u.to;
    if(from>=0&&from<u.ch.length){ const [e]=u.ch.splice(from,1); u.ch.splice(to,0,e); }
    takeFxTouch(); return; }
  /* S1: ЗАХВАТ, ЗАВЕДЁННЫЙ ПРАВКОЙ ЦЕПИ дорожке, у которой его не было вовсе (autCaps). Вперёд — поставить (при первом ходе он уже
     стоит: его завела takeCapStart), назад — снять, и дорожка снова идёт за живой цепью, как до правки. Снимаем, только если на
     месте ТОТ ЖЕ объект: чужой захват того же взятого не наш. */
  if(u.kind==='autcap'){
    if(undo){ if(takeFx.get(u.tk)===u.rec) takeFx.delete(u.tk); } else takeFx.set(u.tk,u.rec);
    takeFxTouch(); return; }
  /* S5.5: удаление/вставка возят НАБОР событий (бас-нота — это «вкл»+«выкл», а то и её ведения), но
     механизм тот же и объекты ТЕ ЖЕ. Набор из одного — прежний случай удара, байт-в-байт. */
  const back=new Set(u.evs);
  if((u.kind==='del')===undo) events.push(...u.evs);
  else compactEvents(e=>back.has(e));
}
/* ↶ — снять последнюю правку (и положить её в будущее, чтобы ↷ мог вернуть). */
/* T5: ход ЗАМЕНЫ ТЕМБРА снимается и на подложке — ровно тем же послаблением, каким был сделан. Прочих ходов
   на подложке не бывает (их правки отказывают), так что отмена ей не открывает ничего сверх замены. */
function editUndo(){
  const u=editHist[editHist.length-1];
  if(!u||!editGuard(u.kind==='timbre')) return false;
  editHist.pop(); editApply(u,true); editFuture.push(u);
  editCommit(); return u.kind;
}
/* ↷ — вернуть отменённое. ⛔ Мимо editPush — И ЭТО ВЕРНО: возврат не создаёт новой ветки, он идёт ПО ТОЙ
   ЖЕ, и чистить будущее здесь было бы ошибкой (стёрло бы остаток очереди ↷). Ветку рвёт только НОВАЯ правка. */
function editRedo(){
  const u=editFuture[editFuture.length-1];
  if(!u||!editGuard(u.kind==='timbre')) return false;
  editFuture.pop(); editApply(u,false); editHist.push(u);
  editCommit(); return u.kind;
}

/* Позиция для визуализации: фаза отсчёта / игры, ПЕСЕННАЯ доля, длина песни в долях.
   ⛳ ДВЕ ПОЗИЦИИ, И У КАЖДОГО ПОТРЕБИТЕЛЯ СВОЯ (слайс S3.5b — именно здесь их и перепутали):
     МОНОТОННАЯ m = (now−t0)·bpm/60 — это ЧАСЫ. Ею считают ТОЛЬКО арифметику времени: опору t0 (смена
       темпа, перепривязка области), окно опережения планировщика (loop.sched, горизонт), счёт проходов
       области (rgnReps), отсчёт перед записью (m<0), индекс щелчка метронома (clickBeat).
     ПЕСЕННАЯ p = songAt(m) — это МЕСТО В МАТЕРИАЛЕ. Ею пользуется ВСЁ, что указывает на события или на
       длину песни: запись (push/curBeat), переигровка лида (fireNear, loop.pos), точка возобновления,
       конец песни — и ВСЁ, ЧТО ВИДИТ ЧЕЛОВЕК: бегунок полосы и её ширина.
   ⚠️ БАГ, КОТОРЫЙ ЭТО ЧИНИТ: здесь отдавалась МОНОТОННАЯ доля. Без области они совпадают (songAt —
   тождество), поэтому S3.3 был прав; S3.4 развёл их — звук пошёл по песенной и зациклился, а полоса
   осталась на часах: бегунок уезжал за конец, а ширина (max(песня, pos, подложка)) росла вслед за ним
   и дорисовывала новые такты без конца. Правило простое: ПОКАЗЫВАЕМ МАТЕРИАЛ — значит ПЕСЕННАЯ. */
function loopPos(){
  if(!loop.on||!AC)return null;
  const e=(AC.currentTime-loop.t0)*loop.bpm/60;
  /* Отсчёт кончается на ДОЛЕ ЗАПУСКА loop.lead, а не на нуле (S3.5b, тот же довод, что в tick/push): запись
     со скобы с такта 3 отсчитывает доли 4..8 — они ≥0, и по старому `e<0` полоса показывала бы бегущий
     бегунок во втором такте вместо «ОТСЧЁТ». При старте с 0 (lead=0) — прежнее `e<0` дословно. Разгон
     без отсчёта (60мс после ▶) показывает бегунок на точке запуска, а не мигает «ОТСЧЁТ 1». */
  if(e<loop.lead && loop.cnt) return {phase:'count', countLeft:Math.ceil(loop.lead-e), pos:0, total:songLen};
  return {phase:'play', pos:songAt(Math.max(e,loop.lead)), total:songLen};   // songAt: при выключенной области тождество → байт-в-байт прежнее
}

/* ENG — единая точка исполнения (живьём через W* и на переигровке). deg→частота
   выводится ЗДЕСЬ. Ладовый КОНТЕКСТ: живьём (ctx нет) — текущий лад/септаккорд;
   на переигровке ctx=событие с ЗАМОРОЖЕННЫМ ладом (ev.sc) и септаккордом (ev.sev),
   §3.4. baseF() всегда живой → тоника глобальна, лад заморожен. leadFreq/bassFreq
   сами страхуют ступень вне лада (модуло+октава), так что частота не улетает в NaN.
   Владелец голосов ПО СЛОЮ (ctx=событие переигровки): аккорд — 'loop:'+layer / живой
   'latch'; бас — 'bassloop:'+layer / живой 'bass'. Так слой не крадёт голос у живого. */
/* ⛳ СУФФИКС ВЗЯТОГО (a.k, слайс S3.5c). У аккорда и баса ОДИН владелец на слой — «последний побеждает»
   было их задуманным поведением, пока каждое взятое рождало НОВЫЙ слой. Запись В СУЩЕСТВУЮЩУЮ дорожку
   это ломает: аккорды нового взятого и старые аккорды той же дорожки легли бы на ОДИН владелец, и на
   переигровке chOn нового гасил бы старый, а chOff старого — новый. «Слияние» на деле стало бы заменой.
   Поэтому взятое, влитое в дорожку, где уже есть аккорды/бас, получает свой k ≥ 1, и его владелец —
   'loop:N:k'.
   ⛳ И ТОТ ЖЕ k ПОДНИМАЕТСЯ НА КАЖДОМ ШВЕ ПОВТОРА (S3.5e, recFoldRoll): проходы одного взятого — это тоже
   наложение на одно и то же время, и без подъёма «выкл» последнего прохода обрывал бы аккорд каждого.
   Событие без k — это k=0, ключ БЕЗ суффикса: так звучат старые записи и ПЕРВЫЙ проход взятого в новую
   дорожку; следующие проходы того же взятого при крутящейся скобе уже идут с k ≥ 1. Обходы по префиксу
   (releaseLoopLayersAt: хвост 'N' или 'N:…') суффикс понимают — так устроены ключи соло 'leadloop:N:v'. */
const chOwnerKey  =ctx=> ctx?'loop:'+ctx.layer+(ctx.a&&ctx.a.k?':'+ctx.a.k:''):'latch';
/* P2: БАС — ЕЩЁ И НОМЕР НОТЫ v (одновременные бас-ноты одного взятого, зеркало 'leadloop:N:v'). Хвост ':k:v' — только при
   v≠0, и тогда k пишется всегда (даже 0), чтобы 'N:k' и 'N:k:v' не путались. ⛔ При v=0 ключ БАЙТ-В-БАЙТ прежний — так
   звучит весь бас, записанный до P2, и весь бас одного владельца. Префиксное сравнение дорожки (releaseLoopLayersAt:
   хвост 'N' или 'N:…') с обеими формами работает. */
const bassOwnerKey=ctx=>{ if(!ctx) return 'bass';
  const k=(ctx.a&&ctx.a.k)||0, v=(ctx.a&&ctx.a.v)||0;
  return 'bassloop:'+ctx.layer+(v ? ':'+k+':'+v : (k ? ':'+k : '')); };
/* Ключ владельца СОЛО-голоса на ПЕРЕИГРОВКЕ: слой + номер одновременной ноты (a.v). Живой ключ
   ('lead:L'/'lead:R') строит gestures и передаёт явным аргументом — в событие он НЕ попадает (это
   состояние руки, а не намерение). a.v||0 — вот та самая совместимость: событие без v = нота №0. */
const ldKey=(ctx,a)=> ctx ? 'leadloop:'+ctx.layer+':'+(a.v||0) : 'lead:?';
/* ⛳ ЕДИНАЯ ФОРМА ВЫЗОВА: КАЖДАЯ запись ENG — это (a, ctx, opt), где opt — ОДИН И ТОТ ЖЕ ИМЕНОВАННЫЙ
   набор `{when, live, own}`. Слайс S2 завёл эту форму, и это НЕ косметика, а снятие ловушки.
   ⚠️ ЧТО БЫЛО: у записей была РАЗНАЯ позиционная форма — `leadOn:(a,ctx,live,own)` против
   `chOn:(a,ctx,when)` и `bassOn:(a,ctx,when,live)`, — а диспетчер планировщика зовёт их ОДИНАКОВО:
   `ENG[ev.fn](ev.a, ev, when)`. Пока лид шёл мимо планировщика (fireNear), это сходило с рук. Но стоило
   бы завести лид в планировщик — и ВРЕМЯ В СЕКУНДАХ легло бы в слот ЖИВЫХ ГЕРЦ терменвокса: нота
   зазвучала бы на абсурдной высоте или не зазвучала вовсе. Тихо, правдоподобно, ищется долго.
   ⚠️ ПОЧЕМУ НЕ ХВАТИЛО БЫ «поставить when последним у всех». У лида кроме when есть ещё live и own,
   поэтому третий позиционный слот У РАЗНЫХ записей всё равно значил бы разное — в каком порядке ни
   расставляй. Ловушка позиционная ПО ПРИРОДЕ, и лечится она только снятием позиционности: у
   дополнительных аргументов больше НЕТ номеров, есть ИМЕНА. Время может попасть в `live` теперь лишь
   у того, кто СОБСТВЕННОРУЧНО напишет слово `live`, — то есть ошибка стала невыразимой, а не
   несовершённой.
   ⚠️ live (живые Гц терменвокса) остаётся ОТДЕЛЬНЫМ полем и ЖИВЫМ-ТОЛЬКО (правило #11): переигровка
   его не передаёт никогда, частота там выводится из ступени по замороженному ладу.
   ⛔ Добавляешь запись в ENG — держи ту же форму. Второй формы здесь быть не должно. */
/* ⛳ ТАБЛИЦА ДИСПЕТЧЕРИЗАЦИИ — ТЕПЕРЬ ФАБРИКА (слайс F3), А НЕ ЛИТЕРАЛ.
   Причина одна: офлайн-рендер обязан звать ТЕ ЖЕ отображения «событие → вызов движка», но у ДРУГОЙ
   копии движка (своей, против своего контекста). Второй такой таблицы писать нельзя — она бы
   разошлась с этой, и замороженная дорожка зазвучала бы иначе, чем её играет транспорт. Поэтому
   таблица параметризована модулем звука: живая — makeENG(AUD), рендерная — makeENG(своя копия).
   ⚠️ ТЕЛА ЗАПИСЕЙ НЕ ТРОНУТЫ — добавлен только префикс A. у функций звука. Ключи владельцев
   (ldKey/chOwnerKey/bassOwnerKey), замороженный лад и loop.bpm остаются здешними: они про ЗАПИСЬ,
   а не про движок, и у обеих копий обязаны быть одни и те же. */
const makeENG=A=>({
  /* ⚠️ setLeadInstr(a.inst) ОТСЮДА УБРАН, и это ПОЧИНКА, а не потеря: переигранный слой уводил ЖИВОЙ
     инструмент (и кнопку в панели) — слой на Ситаре молча перекрашивал руку, играющую Органом. Теперь
     тембр печётся В ГОЛОСЕ на атаке (leadOn получает inst), как это давно делают аккорды и бас. */
  leadOn:(a,ctx,{when,live,own}={})=>{ const o=own||ldKey(ctx,a);
              /* live — ЖИВОЙ override частоты (терменвокс): непрерывные Гц вместо ступенной leadFreq.
                 Только на ЖИВОМ пути (WleadOn); переигровка зовёт ENG без live → частота из leadFreq по
                 замороженному ладу (полимодальность цела). */
              if(ctx)A.leadCancel(o,when);           // атака переигранной ноты: снять рампы прошлого бенда (не перетечёт) — ТОЛЬКО в своём голосе и В ТО ЖЕ ВРЕМЯ, что и атака
              const base=leadFreq(a.deg,a.oct,ctx?ctx.sc:CUR());
              const gl=A.applyFx(a.fx);   // КАРТА ЭФФЕКТОВ ЭТОГО СОБЫТИЯ (3.7.2). Нет карты (события аранжировки) → applyFx возьмёт ТЕКУЩУЮ цепь роли, а не нейтраль. V4: заодно отдаёт СКОЛЬЖЕНИЕ ноты (или undefined — не задано)
              /* ⛔ V4, КОНТРАКТ V1: живой кадр ТЕРМЕНВОКСА (live!=null) скольжения НЕ получает — его 20 мс это сглаживание слежения, а не
                 портаменто; руке с долгим Скольжением высота отставала бы от руки. Свежую атаку отсекает сам движок (fresh → умолчание). */
              A.leadOn(o,(live!=null?live:base),a.vol,a.inst===undefined?leadIdx:a.inst,a.deg,a.oct,live!=null?undefined:gl,a.tie,when);   // время — в слоте when   // deg/oct — не для звука (частота уже посчитана), а для ПОДСВЕТКИ: leadHold знает, что звучит
              if(a.bend&&a.bend.length)A.scheduleBend(o,a.bend,base,60/loop.bpm,when); },   // переигровка: кривая бенда поверх ступени замороженного лада, в СВОЙ голос, с якорем в момент атаки
  leadSet:(a,ctx,{when,own}={})=>{ const o=own||ldKey(ctx,a);
              const gl=A.applyFx(a.fx);   // V4: скольжение ведения — из ЕГО карты (карта ведения несёт величину на миг ведения: сдвинул палец посреди ноты — следующий переезд уже с новой)
              A.leadSet(o,(a.hold?null:leadFreq(a.deg,a.oct,ctx?ctx.sc:CUR())),a.vol,a.deg,a.oct,a.inst,gl,when); },   // ведение терменвокса (hold) частоты не несёт — скольжению там применяться не к чему   // T0-fix: a.inst — смена тембра ПОСРЕДИ НОТЫ, как она прозвучала живьём (кроссфейд банков голоса; см. audio.leadSet)   // live здесь не читался никогда: ведение терменвокса идёт через hold:true (частоту не сбиваем), а не через override
  leadOff:(a,ctx,{when,own}={})=>A.leadOff(own||ldKey(ctx,a),a&&a.tie,when),   // V2: tie ПЕРЕД when (правило #15)   // a.tie (T3) — нота продолжена в другой дорожке после смены тембра: быстрый релиз
  /* when — ЯВНОЕ время (опережение лупера, §планировщик). Живой путь (W*) зовёт без when → undefined
     → аудио-функции берут AC.currentTime (сейчас), байт-в-байт. Переигровка слоёв передаёт точное время. */
  chOn:(a,ctx,{when}={})=>A.chordOn(chOwnerKey(ctx),chordFreqs(a.deg,a.oct,ctx?ctx.sc:CUR(),ctx?ctx.sev:seventh,a.ty),a.vol,a.inst,a.bri,when),   // a.bri — пер-событийная яркость (0=нейтраль); when остаётся ПОСЛЕДНИМ (планировщик)
  chSet:(a,ctx,{when}={})=>A.chordGlide(chOwnerKey(ctx),chordFreqs(a.deg,a.oct,ctx?ctx.sc:CUR(),ctx?ctx.sev:seventh,a.ty),a.vol,a.bri,when),
  chOff:(a,ctx,{when}={})=>A.chordOff(chOwnerKey(ctx),when),
  /* ⛳ V4: СКОЛЬЖЕНИЕ БАСА — ИЗ КАРТЫ СОБЫТИЯ, И ОТСУТСТВИЕ КАРТЫ ЗНАЧИТ «НЕ ЗАДАНО» (умолчание движка BASS_GLIDE_TC), а НЕ
     «возьми живую цепь». Карту бас несёт ТОЛЬКО при прицепочном параметре в цепи баса (gestures), поэтому ей нет у всего
     записанного без Скольжения, у подложки (arrange строит нагрузку сам) и у нот, вставленных в редакторе. Правило соло
     «нет карты → текущая цепь» здесь заставило бы басовую линию подложки скользить так, как сейчас стоит рука, — ровно
     довод яркости аккордов (fxChordBri). Кадр терменвокса (live) скольжения не получает — контракт V1. */
  bassOn:(a,ctx,{when,live,own}={})=>A.bassOn(own||bassOwnerKey(ctx),(live!=null?live:bassFreq(a.deg,a.oct,ctx?ctx.sc:CUR())),a.vol,a.inst,a.deg,a.oct,live!=null?undefined:A.fxGlideOf(a.fx),A.fxBriOf(a.fx),when),   // ЯРКОСТЬ — из карты; нет карты — «не задана» (правило баса), звук как сегодня   // P1: deg/oct — для подсветки из реестра движка (как у leadOn); when ПОСЛЕДНИМ (правило #15)   // live — живой override Гц (терменвокс-бас), как у leadOn; переигровка без него → bassFreq (полимодальность цела)
  bassSet:(a,ctx,{when}={})=>A.bassSet(bassOwnerKey(ctx),bassFreq(a.deg,a.oct,ctx?ctx.sc:CUR()),a.vol,a.deg,a.oct,A.fxGlideOf(a.fx),A.fxBriOf(a.fx),when),   // ЯРКОСТЬ ведения — своя величина события. V4: скольжение — из карты ведения; нет карты — BASS_GLIDE_TC, та же, что у живого баса без Скольжения
  bassOff:(a,ctx,{when,own}={})=>A.bassOff(own||bassOwnerKey(ctx),when),   // P2: own — живой владелец (WbassOff), как у leadOff; переигровка его не передаёт — ключ из события
  drum:(a,ctx,{when}={})=>A.drumHit(a.row,a.vol,a.kit,A.fxBriOf(a.fx),when),   // ЯРКОСТЬ удара — из его карты (карта есть, только когда в цепи ударных есть прицепочный параметр); нет — удар как сегодня
  drone:(a,ctx,{when}={})=>A.droneOn(a.lvl,when),        // дрон: выделенные узлы, гасится по жизненному циклу (не в softAllOff)
});
const ENG=makeENG(AUD);   // ЖИВАЯ таблица — против живой копии движка. Поведение прежнее дословно
const inPB=()=>loop.on;                               // для строки статуса (draw)

/* Сетка квантизации в долях: аккорды — доля, бас — восьмая, соло — не квантуется.
   УДАРНЫЕ — 1/loop.sub доли: при sub=4 шестнадцатая (как было), при sub=3 ТРИОЛЬ. Дробление —
   ЯВНАЯ настройка (панель лупера), а НЕ вывод из последнего загруженного паттерна: неявная смена
   поведения квантизации (снял джем — сетка молча переехала) хуже лишнего контрола. */
const gridFor=fn=> fn[0]==='c'?1 : fn.slice(0,4)==='bass'?0.5 : fn==='drum'?1/(loop.sub||4) : 0;
/* Запись события на ТЕКУЩУЮ АБСОЛЮТНУЮ долю песни; при квантизации время снапится к сетке.
   ⛳ ЗДЕСЬ БЫЛ СГИБ В ПЕТЛЮ — `t = e % lb` (S3.3 его снял). Ровно эта строка и делала запись
   петлёй: она уничтожала абсолютное время В МОМЕНТ ЗАПИСИ, ещё до того как событие возникало.
   ⛔ И ВМЕСТЕ С НИМ УМЕРЛА ЕГО СПУТНИЦА — «складка заворота». Она существовала затем, что при
   триольной сетке (g=1/3) удар у самого конца круга округлялся к lb−1e-16, а `%` такое значение НЕ
   сворачивал, и событие садилось на волосок ДО конца петли вместо доли 0 — на слух пропадал сильный
   удар. Без модуло округлять некуда: t=Math.round(t/g)*g и есть окончательное время.
   ⚠️ НЕ ВОССТАНАВЛИВАТЬ ни то, ни другое: обе строки осмысленны ТОЛЬКО при сворачивании в петлю, и
   вернуть их — значит вернуть петлю. Зацикливание придёт ОБЛАСТЬЮ на таймлайне, а не модулем здесь. */
/* at — ЯВНАЯ песенная доля (S3.5a-fix), и зовёт так РОВНО ОДНО место: шов прохода (recFoldRoll), где «сейчас»
   уже свернулось в начало области, а выключения принадлежат КОНЦУ прошлого прохода (соло, бас, аккорд), а
   новое «вкл» защёлкнутого аккорда — НАЧАЛУ следующего (S3.5e). С at не квантуем и не сворачиваем.
   fz — {sc,sev}: ЗАМОРОЖЕННЫЙ ладовый контекст вместо текущего (S3.5e, то же место). Вписанное на шве «вкл»
   обязано нести лад САМОГО аккорда — тот, с которым легло его последнее событие, — а не тот, что сейчас
   выбран в панели. Без at и fz — байт-в-байт как было. */
function push(fn,a,at,fz,q,ly){   // ly (T1/T2) — слой события: ведение и «выкл» передают слой СВОЕЙ ноты (r.layer / recCh.layer / recBass.layer); «вкл» и удар передают undefined — тогда слой выбирает МАРШРУТ ПО РОЛИ (takeRoute), и только ПОСЛЕ отказа отсчёта. Куда легло — pushLy. // → true, если событие ЛЕГЛО в массив (S4.1: открывающие пути записи ставят состояние только по true). q — ЗАМОРОЖЕННОЕ на ноте решение квантизации (S4.3); не задано — текущее loop.quant
  if(!AC)return false;
  /* ⛳ ЗАПИСЬ ИДЁТ В ПЕСЕННОЙ ДОЛЕ, то есть СВЁРНУТОЙ в область (S3.4). Отсюда и ответ на вопрос «что
     делает ● при включённом повторе»: НАКОПЛЕНИЕ В ОБЛАСТЬ — каждый следующий проход дописывает
     поверх, как и ждут от лупера и как приложение вело себя до S3.3. Ветки для этого не понадобилось
     ни одной: songAt — та же свёртка, что делал прежний `e % lb`, только переанкеренная. */
  const m=(AC.currentTime-loop.t0)*loop.bpm/60;
  /* ⚠️ ОТСЧЁТ КОНЧАЕТСЯ НА ДОЛЕ ЗАПУСКА (loop.lead), А НЕ НА НУЛЕ (S3.5b). Прежнее `e<0` было верно
     только при старте с доли 0; с доли 8 отсчёт шёл по долям 4..8 — они ≥0, и сыгранное во время
     отсчёта ложилось в запись ДО точки записи. При старте с 0 lead=0 — то же самое, что было. */
  /* ⛳ S4.3: ОТКАЗ — ТОЛЬКО В НАСТОЯЩЕМ ОТСЧЁТЕ (loop.cnt — тот же предикат, что у loopPos). Иное m<lead при записи бывает
     лишь в ~60мс разгона после ПРЫЖКА скобы (rgnApply ставит cnt=false): там отказ ронял «выкл», и нота оставалась открытой.
     Теперь время прижимается к доле запуска — туда, где транспорт реально продолжит, — ровно как бегунок в loopPos. */
  if(at==null && m<loop.lead && loop.cnt) return false;
  const e= at!=null ? at : songAt(Math.max(m,loop.lead));
  if(e<0)return false;                                // ещё идёт отсчёт
  let t=e;
  const g=((q??loop.quant)&&at==null)?gridFor(fn):0;   // S4.3: правило НОТЫ, а не кнопки в этот миг (см. recChOn/recBassEv)
  if(g>0){
    t=Math.round(t/g)*g;
    /* ⚠️ ОКРУГЛЕНИЕ МОГЛО ВЫНЕСТИ СОБЫТИЕ ЗА КОНЕЦ ОБЛАСТИ — сыграно внутри, а село бы снаружи, где
       повтор его уже не услышит. Удар сворачиваем на НАЧАЛО области (музыкально то же место следующего
       прохода), всё прочее держим на её КОНЦЕ — см. S4.2 ниже. Гейт `e<to` — чтобы трогать ровно то, что и правда сыграно внутри.
       ⛔ ЭТО НЕ ВОССТАНОВЛЕННАЯ «складка заворота» из S3.3: та была безусловной и жила при модуло,
       эта работает ТОЛЬКО при включённой области и только на её границе. */
    /* ⛳ S4.2: СВОРАЧИВАЕТСЯ ТОЛЬКО УДАР. ВСЁ, ЧТО ПРИНАДЛЕЖИТ НОТЕ (аккорд/бас: «вкл», ведение, «выкл»), ДЕРЖИМ НА КОНЦЕ ПРОХОДА.
       Соло сюда не доходит вовсе: оно не квантуется (gridFor=0), поэтому ни свёртки, ни удержания у него нет.
       ⚠️ БЫЛО: сворачивалось ВСЁ. Для «выкл» это ломало данные: ОНО ЛОЖИЛОСЬ НА НАЧАЛО ПРОХОДА, РАНЬШЕ СВОЕГО «ВКЛ» — нота
       оставалась без конца (при повторе её гасил шов, при линейной игре она звенела до конца песни), а спаривание видело сироту.
       Ведение аккорда (смена) сворачивалось туда же и либо перекрашивало аккорд С НАЧАЛА прохода (если его «вкл» лежит на
       rgn.from — прогрессия «аккорд на проход» теряла свой аккорд целиком), либо ложилось раньше «вкл» и терялось.
       ⚠️ И «ВКЛ» АККОРДА/БАСА СВОРАЧИВАТЬ ТОЖЕ НЕВЕРНО — вопреки прежнему «для начала ноты свёртка верна». Нота, взятая в
       последней доле прохода, звучит «на раз» СЛЕДУЮЩЕГО прохода, и тот её уже получает сам: удержанный аккорд вписывает шов
       (recFoldRoll: «вкл» на rgn.from с НОВЫМ takeK), удержанный бас переатакует рука (новая нота, квантуется к rgn.from).
       Свёрнутое «вкл» лишь ДУБЛИРОВАЛО её — в ключ ПРОШЛОГО прохода и на его начало: при повторе аккорд звучал дважды весь
       проход, при линейной игре — на проход раньше; а в ключе, где на rgn.from уже лежит своя нота, «вкл» затирало её
       (ON поверх ON) и оставляло сироту её «выкл». Отпущенная же до шва — нулевой длины что там, что тут: округлённые к
       одной линии «вкл» и «выкл» длины не имеют (как и короткий аккорд внутри прохода).
       ⛳ КУДА ДЕРЖИМ — РОВНО НА rgn.to, как шов пишет свои «выкл» (recFoldRoll, at=rgn.to). Не «на волосок раньше»: окно
       планировщика при повторе полуоткрыто [lo,hi) и кончается на границе, так что событие на rgn.to в круге НЕ ИГРАЕТ НИКОГДА —
       звучащий конец там даёт шов (releaseLoopLayersAt в тот же миг), а при линейной игре оно играет ровно на своей доле.
       «На волосок раньше» заставило бы удержанную смену/«вкл» реально прозвучать щелчком перед каждым швом.
       Всё, что удерживается, записано РАНЬШЕ «выкл» шва на ту же долю, и стабильная сортировка оставляет их перед ним.
       УДАР — единственное, что сворачивается по-прежнему: у него нет пары, и «на раз» следующего прохода его никто не впишет.
       Гейт тот же, что был у свёртки: только при крутящейся скобе и только для сыгранного ВНУТРИ неё. До скобы округлиться
       за её конец нельзя (скоба ≥ такта ≥ 2 долей, сетки ≤ доли); при выключенной скобе или квантизации ветка не достигается. */
    const R=loop.rgn;
    if(cycling() && e<R.to && t>=R.to-1e-9) t= fn==='drum' ? R.from : R.to;
  }
  /* ⛳ S4.3: СТРАЖ ПОРЯДКА ЖИВОГО КЛЮЧА — событие аккорда/баса не ложится РАНЬШЕ предыдущего события того же ключа.
     Зачем, если правило квантизации заморожено на ноте: заморозка держит порядок ВНУТРИ ноты, но ключ владельца один на все
     аккорды (и все басы) взятого-прохода. Нота 1 без квантизации кончилась на 5.15, кнопку включили, нота 2 взята на 5.2 →
     округлилась к 5.0 — её «вкл» легло бы раньше «выкл» соседки, и спаривание отдало бы тот «выкл» новой ноте, а её
     собственный — сироте. Здесь такое «вкл» встаёт вплотную за соседкой (легато), а не раньше неё.
     ⛔ ПРИ НЕИЗМЕННОЙ КВАНТИЗАЦИИ НЕ СРАБАТЫВАЕТ НИКОГДА: одна сетка на роль, округление монотонно, удержание S4.2 — потолок
     rgn.to, шов пишет «выкл» на rgn.to (≥ всего прохода) и рождает новый ключ (сброс в recFoldRoll). Соло и удары не касается:
     соло не квантуется (время ключа монотонно само), у удара нет пары. */
  const cb= fn[0]==='c' ? 1 : fn[0]==='b' ? 2 : 0;
  /* ⛳ T2: МАРШРУТ — ЗДЕСЬ, А НЕ У ВЫЗЫВАЮЩЕГО: отказ отсчёта (выше) уже случился, событие точно ляжет, значит
     рождение дорожки не останется пустым. Ниже этой строки отказов нет. */
  if(ly===undefined) ly=takeRoute(noteSource(fn,a));   // ключ — ИСТОЧНИК ноты (сегодня роль; см. noteSource)
  const S=ts(ly);                                     // T1: страж ключа и суффикс — ЭТОГО слоя (ключ владельца несёт номер слоя, значит и они по слою)
  const bv= cb===2 ? ((a&&a.v)||0) : 0;               // P2: очередь баса — ПО НОМЕРУ НОТЫ v (ключ владельца = слой+k+v); у одного владельца v=0 — ровно прежний страж
  if(cb===1 && t<S.chLastT) t=S.chLastT; else if(cb===2){ const lt=S.bsLast.get(bv); if(lt!=null && t<lt) t=lt; }
  /* ⛔ КОПИЯ КАРТЫ ЭФФЕКТОВ — R1, САМЫЙ ОПАСНЫЙ БАГ ЭТОГО ПЛАСТА, ЗАКРЫТ ЗДЕСЬ И ТОЛЬКО ЗДЕСЬ.
     До 3.7.2 ВСЯ полезная нагрузка была примитивами, кроме двух намеренных ссылок: ty (никогда не
     мутируется) и bend (дописывается осознанно). Карта a.fx — первый МУТИРУЕМЫЙ объект в нагрузке, а
     push кладёт `a` ПО ССЫЛКЕ, и вызывающие копируют МЕЛКО ({...p}) — значит без этой строки один и
     тот же объект оказался бы и в записанном событии, и в живом состоянии сравнения. Следующее
     движение руки тихо переписало бы УЖЕ ЗАПИСАННОЕ прошлое: слой начал бы звучать не так, как его
     сыграли. Снаружи это читается как «петля сама меняется» — и искать причину пришлось бы долго.
     ЗАПИСАННАЯ КАРТА С ЭТОГО МОМЕНТА НЕИЗМЕНЯЕМА: её больше никто не трогает, только читает. */
  const ev={t,layer:ly,fn,a,sc:fz?fz.sc:CUR(),sev:fz?fz.sev:seventh,tk:curTake};   // §3.4: замораживаем ладовый контекст события (fz — уже замороженный, S3.5e); tk — номер взятого (S3.5d)
  if(a && a.fx) ev.a={...a, fx:{...a.fx}};
  if(S.k && (fn[0]==='c'||fn[0]==='b')) ev.a={...ev.a, k:S.k};   // S3.5c: аккорд/бас взятого, влитого в дорожку со своими аккордами/басом, — свой владелец (см. chOwnerKey). Копия, а не запись в `a`: `a` — живое состояние сравнения
  events.push(ev);
  if(cb===1) S.chLastT=t; else if(cb===2) S.bsLast.set(bv,t);   // S4.3: страж ключа (T1: по слою; P2: у баса — по номеру ноты)
  if(t>recHiT) recHiT=t;                               // S4.3: высшая записанная доля участка (отличает шов от прыжка)
  if(t>songLen){ songLen=t; braceFollowGrow(); }      // длина песни растёт по одному событию (полный пересчёт — только в schedInvalidate); «следующая» скоба — вместе с ней, O(1)
  pushLy=ly;                                           // T2: куда легло — «вкл» узнаёт так свою дорожку
  return true;
}
/* АБСОЛЮТНАЯ доля СЕЙЧАС (тот же счёт, что и push) — для dt точек бенда.
   ⛳ Модуль снят вместе с петлёй. Побочно это ПОЧИНКА: у ноты, тянувшейся через бывший заворот, dt
   уходил в минус и зажимался нулём (см. pushBend) — кривая бенда там врала. Теперь dt монотонен. */
const curBeat=()=>songAt(Math.max((AC.currentTime-loop.t0)*loop.bpm/60, loop.lead));   // ПЕСЕННАЯ доля — тот же счёт, что у push (иначе dt бенда разошёлся бы с временем самой ноты). S4.3: прижата к доле запуска, как в push — иначе ~60мс разгона после страховочной перепривязки rgnApply (tgt=p) читались бы шовом («время назад»)
/* Точка бенда: центы ЖИВОЙ высоты (live) относительно ступени АТАКИ (r.deg/oct по
   замороженному-в-будущем ладу CUR()). Само-прореживание порогом BEND_EPS_CENTS.
   ⛳ Кламп dt≥0 ОСТАВЛЕН, но повод у него сменился: прежде dt уходил в минус у ноты, тянувшейся ЧЕРЕЗ
   ЗАВОРОТ (curBeat сворачивался по модулю и падал ниже опоры r.t0). Заворота нет, время монотонно —
   теперь это просто страховка от отрицательного dt при перемотке/смене темпа.
   Опора и порог — В ЗАПИСИ ВЛАДЕЛЬЦА (r), поэтому две гнущие руки не путают друг другу отсчёт. */
function pushBend(r,live){
  if(!r||!r.bend||live==null)return;
  const c=1200*Math.log2(live/leadFreq(r.deg,r.oct,CUR()));
  if(r.lastC!=null&&Math.abs(c-r.lastC)<=BEND_EPS_CENTS)return;
  r.bend.push({dt:Math.max(0,curBeat()-r.t0),c});
  r.lastC=c;
}
/* СВОБОДНЫЙ НОМЕР одновременной ноты v внутри пишущегося слоя: 0,1,2… Нужен только чтобы переигровка
   спарила leadOn с его leadOff (в слое может быть открыто несколько соло-нот). Первая всегда получает 0
   — поэтому обычная одноголосная запись даёт события с v:0, а старые (без v) читаются как v=0. */
/* ⛳ S3.5a: СЧЁТ НАЧИНАЕТСЯ С vBase, А НЕ С НУЛЯ. freeSlot видит только ОТКРЫТЫЕ сейчас ноты (vSlots) и
   ничего не знает о том, что уже ЛЕЖИТ в слое. Пока каждое взятое рождает НОВЫЙ слой, лежать там нечему
   и vBase=0 — события байт-в-байт прежние. Но стоит писать В СУЩЕСТВУЮЩУЮ дорожку — и новая нота взяла
   бы v:0 у лежащей ноты с тем же v: владелец 'leadloop:N:0' один на двоих, на переигровке поздняя
   крадёт голос ранней, а leadOff ранней гасит позднюю. Две перекрытые по времени ноты глушат друг друга.
   ⚠️ ВНУТРИ взятого номера по-прежнему ПЕРЕИСПОЛЬЗУЮТСЯ (свободный от открытых) — это держит их малыми;
   монотонный счётчик «номер на ноту» тоже был бы верен (leadAlloc ищет голос по ключу лишь пока нота
   зажата), но плодил бы тысячи ключей без нужды. */
/* T1: номера — ПО СЛОЮ. Заняты только номера открытых нот ТОГО ЖЕ слоя (владелец 'leadloop:N:v' несёт номер
   слоя, так что у разных слоёв v не сталкиваются), база — vBase этого слоя. Пока слой во взятом один, у
   каждой открытой ноты он и есть — множество занятых то же, что было, номера те же. */
/* P2: правило «наименьший свободный номер от базы» — ОДНО на соло и бас (bassSlot); прежде жило только здесь, строкой ниже. */
function lowestFree(used,base){ let v=base; while(used.has(v))v++; return v; }
function freeSlot(layer){ const used=new Set(); for(const [o,v] of vSlots){ const r=recLead.get(o); if(!r||r.layer===layer) used.add(v); }
  return lowestFree(used, ts(layer).vBase); }
/* Первый номер v ВЫШЕ всех соло-нот, уже лежащих в слое layer (0 — соло-нот нет). Событие без v — это
   нота №0 (совместимость ldKey), поэтому считаем его как 0, и слой со старой записью даст 1.
   ⛳ ОБХОД O(n) — ОДИН РАЗ НА ВЗЯТОЕ, на нажатии ●, а НЕ на ноту и НЕ в push: слайс S3.2 затем и был,
   чтобы на горячем пути не ходить по всей песне. На том же нажатии и так идёт maxLayer() — такой же
   полный обход, то есть цена нажатия ● по порядку не меняется. Кэша по слою НЕ заводим сознательно:
   его пришлось бы держать в строю через onUndo/clearJam/compactEvents — ещё одна точка рассинхрона.
   Отсортированность массива не нужна (максимум), поэтому хвост записи ему не помеха. */
function layerSlotTop(layer){
  let top=0;
  for(const e of events) if(e.layer===layer && e.fn.slice(0,4)==='lead'){ const v=(e.a&&e.a.v)||0; if(v+1>top) top=v+1; }
  return top;
}
/* S3.5c: суффикс взятого для аккорда/баса — выше всех k, уже лежащих в слое у аккордов/баса; 0, если их там
   нет вовсе (тогда и сталкиваться не с чем, и ключи остаются прежними). Тот же довод о цене, что выше:
   один обход на нажатие ●. */
function layerTakeTop(layer){
  let top=-1;
  for(const e of events) if(e.layer===layer && (e.fn[0]==='c'||e.fn[0]==='b')){ const k=(e.a&&e.a.k)||0; if(k>top) top=k; }
  return top+1;
}
/* live!=null ⟺ соло-рука назначена на ТЕРМЕНВОКС (функция руки 'therm' — gestures шлёт S.hz только
   оттуда). Тогда высоту несёт БЕНД: deg/oct ЗАМОРОЖЕНЫ на атаке (не сравниваем и не обновляем — у c
   стабильная опора), а leadSet пишем лишь на смену громкости/реверба/тембра с меткой hold (переигровка
   не сбивает бенд частотой).
   live==null (рука на любой ДРУГОЙ функции — ноты/удержание/эффекты) — логика БАЙТ-В-БАЙТ как раньше,
   только состояние взято по владельцу own. */
/* ⛳ ОБОБЩЁННОЕ ДЕЛЬТА-СЖАТИЕ ПО КАРТЕ ЭФФЕКТОВ (Пласт 3.7.2) — вместо явного списка полей.
   Прежде сравнивались ЧЕТЫРЕ ИМЕНОВАННЫХ поля (deg/oct/inst/vol/rev), а vib/drv/trm/dly, хотя и лежали
   в нагрузке, В СРАВНЕНИЕ НЕ ВХОДИЛИ ВОВСЕ — поэтому «покрутил ручку при зажатой ноте» не писалось
   НИЧЕГО, и эффекты в слой фактически не записывались. Теперь набор параметров ПРОИЗВОЛЕН, значит и
   сравнение — по МНОЖЕСТВУ: другой состав ключей ИЛИ любой ключ ушёл дальше мёртвой зоны.
   ⚠️ Порог REC_FX_EPS — в НОРМИРОВАННЫХ единицах, один на все параметры (довод — в config). */
/* ⚠️ С тонкой записи («запись отражает плавность руки») НЕ ЗОВЁТСЯ: сравнение величин «в ноте» живёт в pnDist внутри общего автомата
   fineStep (тот же закон «состав ключей или любой ключ»), а порог ухода из покоя — тот же REC_FX_EPS. Оставлена ради ссылок в доводах. */
function fxChanged(a,b){
  const A=a||{}, B=b||{}, ka=Object.keys(A), kb=Object.keys(B);
  if(ka.length!==kb.length) return true;
  for(const k of ka){ if(!(k in B) || Math.abs(A[k]-B[k])>REC_FX_EPS) return true; }
  return false;
}
const fxCopy=m=> m?{...m}:m;   // в состояние сравнения кладём КОПИЮ: иначе r.fx стал бы псевдонимом живого снимка и «изменилось?» всегда было бы «нет»
/* ⛳ СОСТОЯНИЕ ЗАПИСИ СЛЕДУЕТ ЗА ТЕМ, ЧТО ЛЕГЛО В МАССИВ (слайс S4.1) — для соло, аккорда и баса одинаково.
   push отказывает во время отсчёта (m<loop.lead). Прежде открывающие пути ставили состояние ВСЁ РАВНО: «вкл» в песню не
   ложилось, а ведения и «выкл», сыгранные уже после старта записи, ложились — ссылаясь на ноту, которой в песне нет
   (сироты: их не слышит движок, но их увидит редактор). Документы называли такую ноту «просто пропавшей» — это было неверно.
   ТЕПЕРЬ: «вкл» и ведение меняют состояние ТОЛЬКО если push вернул true. Не легло «вкл» — нет состояния, а значит не будет
   ни ведений, ни «выкл». Не легло ведение — состояние прежнее, следующий кадр попробует снова.
   Закрывающие пути (rec*Off) состояние снимают ВСЕГДА: рука отпущена, и призрак, оставленный «до лучших времён», закрылся
   бы потом не там.
   ⛳ НОТА, ВЗЯТАЯ В ОТСЧЁТЕ И ЗАЖАТАЯ ЧЕРЕЗ СТАРТ, ОТКРЫВАЕТСЯ НА СТАРТЕ ЗАПИСИ — выбор, а не случайность: руки зовут W*
   КАЖДЫЙ кадр, поэтому первый кадр после loop.lead пишет обычное «вкл» (аккорд и бас квантуются к доле старта — она на
   линии такта; соло — не позже одного кадра). Сыграно после старта — записано; до старта — нет. Защёлка, ОТПУЩЕННАЯ в
   отсчёте, в запись не попадает, пока её не тронут, — ровно как защёлка, взятая до ●.
   Вне отсчёта push не отказывает (m≥lead ⇒ песенная доля ≥0) — события байт-в-байт прежние. S4.3: ~60мс разгона после
   прыжка скобы (rgnApply) — БОЛЬШЕ НЕ ОТКАЗ: там время прижимается к доле запуска (см. push), и «выкл» не теряется. */
function recLeadEv(own,p,live){
  if(!recording)return;
  recFoldRoll();                                   // S3.5a-fix: СНАЧАЛА шов (если время свернулось) — иначе ниже нашлась бы запись ноты ПРОШЛОГО прохода или выдался бы номер от старой базы
  let r=recLead.get(own);
  if(!r){ recLeadOpen(own,p,live,false); return; }
  /* ⛳ T3: СМЕНА ТЕМБРА ПОСРЕДИ НОТЫ СОЛО — ЗАКРЫТЬ В СТАРОЙ ДОРОЖКЕ, ПРОДОЛЖИТЬ В НОВОЙ. Соло переливается ЖИВЬЁМ
     (кроссфейд банков голоса, 20 мс), а в дорожке ОДИН тембр — значит слышанное пишется как та же форма, что у
     смены роли и шва повтора: «выкл» в дорожке прежнего тембра, «вкл» — в дорожке нового, в тот же миг.
     Обе ноты помечены tie: переигровка делает из них не «отпустил и ударил заново», а тот же 20-мс переход —
     прежний голос уходит быстрым релизом, новый входит без атаки и без удара (audio.leadOn/leadOff).
     ⛳ ВЕДЕНИЕ С НОВЫМ ТЕМБРОМ (T0-fix) ЭТИМ ЗАМЕНЕНО: открытая нота больше никогда не расходится с тембром
     своего «вкл», поэтому ведение тембр не меняет, и дважды смена не пишется.
     ⛳ ТЕРМЕНВОКС: продолжение — новая нота со СВЕЖЕЙ кривой бенда от ближайшей ступени в миг смены. Прежний предел
     («смена посреди бенда не переигрывается: кривая расписана в банк атаки») снят: смены посреди ноты больше нет.
     Надёжность: p.inst — живой тембр КАЖДОГО кадра зажатой руки, r.inst — тембр «вкл» ноты; расхождение и есть смена. */
  if(p.inst!==r.inst){
    push('leadOff',{v:r.v,tie:true},null,null,undefined,r.layer);
    recLead.delete(own); vSlots.delete(own);
    recLeadOpen(own,p,live,true);
    return;
  }
  if(live!=null){                                  // терменвокс: пишем бенд + громкость/ЭФФЕКТЫ (hold), НЕ deg/oct
    pushBend(r,live);
    /* ⚠️ БЕНД НЕ ТРОГАЕМ (R3): точка бенда дописывается в a.bend ПОСЛЕ push, по ссылке из r.bend, и
       опора (r.deg/r.oct/r.t0/r.lastC) живёт своей жизнью. Карта эффектов добавлена РЯДОМ, ни ссылка,
       ни пороги бенда не задеты — hold:true по-прежнему говорит переигровке «частоту не сбивать». */
    /* ⛳ ТОНКАЯ ЗАПИСЬ (fineStep): громкость и карта — каждая единица, пока рука движется; уход из покоя — с мига, где рука ушла.
       Каждое ведение — с ЯВНОЙ долей своей выборки (уход дописывается из памяти); с явной долей push не отказывает. T0-fix: тембр
       В ведении соло — нота переливается живьём (см. noInst). deg/oct остаются на атаке. */
    for(const s of fineStep(r.fine, pnSnap(p), curBeat())) push('leadSet',{...s.x,hold:true,v:r.v},s.t,null,undefined,r.layer);
    r.vol=r.fine.lastX.vol; r.fx=fxCopy(r.fine.lastX.fx);
    return;
  }
  /* СМЕНА ВЫСОТЫ — сразу, как прежде (T0-fix: смена живого тембра посреди ноты — ЗАПИСЫВАЕТСЯ, соло её слышно); тонкая запись
     начинает опору заново от неё. Громкость и карта — тонкой записью (см. ветку терменвокса выше). */
  if(p.deg!==r.deg||p.oct!==r.oct){
    if(!push('leadSet',{...p,v:r.v},null,null,undefined,r.layer)) return;   // S4.1: не легло — состояние прежнее
    r.deg=p.deg; r.oct=p.oct; r.vol=p.vol; r.fx=fxCopy(p.fx); fineReset(r.fine,pnSnap(p),curBeat());
    return;
  }
  for(const s of fineStep(r.fine, pnSnap(p), curBeat())) push('leadSet',{...s.x,v:r.v},s.t,null,undefined,r.layer);
  r.vol=r.fine.lastX.vol; r.fx=fxCopy(r.fine.lastX.fx);
}
/* Открыть ноту соло в записи — её «вкл» маршрутом по источнику (T2/T3). tie — продолжение после смены тембра. */
function recLeadOpen(own,p,live,tie){
    /* T2: номер v нужен ДО push (он в нагрузке), а слой выбирает push. Смотрим, куда ляжет (takePeek, без
       действия): туда же push и положит — между двумя строками ничего не меняется. Родится новая дорожка —
       там пусто, номер 0 (ровно то, что дал бы freeSlot свежего слоя). */
    const pk=takePeek(noteSource('leadOn',p));    // тот же ключ, что спросит push: push получит {...p, v, bend} — поля ИСТОЧНИКА (роль, в T3 — тембр p.inst) те же
    const v= pk==null ? 0 : freeSlot(pk);
    const a={...p,v};                              // v — номер одновременной ноты в слое (пара для leadOff)
    if(tie) a.tie=true;                            // T3: продолжение ноты после смены тембра — связка, а не новая атака (см. recLeadEv)
    const t0= live!=null ? curBeat() : 0;          // опора бенда — ДО push, как и прежде (то же мгновение, что у самой ноты)
    if(live!=null) a.bend=[];
    if(!push('leadOn',a,null,null,undefined,undefined)) return;   // T2: слой — по роли (push). S4.1: отсчёт — нота не открыта: ни номера, ни состояния (иначе её ведения и «выкл» легли бы сиротами)
    const ly=pushLy;                               // T2: дорожка, в которую нота легла; её ведения и «выкл» пойдут туда же
    vSlots.set(own,v);
    const S=ts(ly); if(v+1>S.vTop) S.vTop=v+1;      // высшая выданная за взятое В ЭТОТ СЛОЙ — до неё поднимется база на шве
    const r={deg:p.deg,oct:p.oct,vol:p.vol,fx:fxCopy(p.fx),inst:p.inst,bend:live!=null?a.bend:null,t0,lastC:null,v,layer:ly,fine:fineNew(pnSnap(p),curBeat())};   // layer (T1) — слой ноты: туда же её ведения и «выкл»   // r.bend — ТОТ ЖЕ массив, что в событии (push копирует a мелко)   // fine — тонкая запись величин «в ноте» (fineStep)
    recLead.set(own,r);
    if(live!=null)pushBend(r,live);                // стартовая точка (r уже есть — опора известна)
}
/* ⛳ ТЕМБР В ВЕДЕНИИ — ПО РОЛИ, И ЗАПИСЬ ИДЁТ ЗА ЗВУКОМ (T0, исправленный). Что делает ЖИВАЯ нота при смене
   тембра, пока она звучит, — проверено по коду, а не предположено:
     СОЛО — ПЕРЕЛИВАЕТСЯ. Живой путь зовёт leadOn каждый кадр, и leadVoiceBank делает кроссфейд банков голоса
            за 20 мс. Значит смена ЗАПИСЫВАЕТСЯ ведением с новым a.inst, переигровка делает тот же кроссфейд
            (audio.leadSet), догонялка берёт тембр последнего ведения — так звучало в этом месте.
     БАС    — НЕ переливается: bassOn печёт тембр в голосе только на атаке (`if(!v.on)`). Ведение баса тембр
            НЕ несёт, и смена живого тембра при зажатой ноте — не повод для ведения: звучит прежний. До T0
            bassSet нёс новый тембр, и догонялка поднимала ноту тембром, которого никто не слышал.
     АККОРД — не переливается: chordGlide тембра не знает, chSet его не нёс никогда.
   ⚠️ Прежняя редакция T0 считала «тембр печётся на атаке» у ВСЕХ и сняла тембр и с ведений соло — неверно:
   записанное перестало совпадать со слышанным. ⛔ Поле у баса УБИРАЕТСЯ, ни одно не добавляется (#11). */
const noInst=p=>{ if(!p||!('inst' in p)) return p; const {inst, ...rest}=p; return rest; };
function recLeadOff(own){ recFoldRoll();          // S3.5a-fix: шов ПЕРВЫМ — нота прошлого прохода закрывается на его КОНЦЕ, а не свёрнутым «сейчас» (иначе leadOff лёг бы раньше своего leadOn и нота повисла бы)
  const r=recLead.get(own);
  if(recording&&r) push('leadOff',{v:r.v},null,null,undefined,r.layer);
  recLead.delete(own); vSlots.delete(own); }
function recLeadReset(){ recLead.clear(); vSlots.clear(); }   // паника/очистка: открытых нот больше нет (шов прохода во время записи идёт через recFoldRoll)
/* ═══ ШОВ ПРОХОДА ОБЛАСТИ ВО ВРЕМЯ ЗАПИСИ (слайс S3.5a-fix) ═══
   ⚠️ БАГ, КОТОРЫЙ ЭТО ЗАКРЫВАЕТ: при включённом ⟳ одно взятое пишет НЕСКОЛЬКО ПРОХОДОВ В ОДИН СЛОЙ (push
   сворачивает время в область). Раньше на шве состояние записи просто сбрасывалось, и счёт номеров
   начинался заново с vBase — нота второго прохода получала v ноты первого, которая звучит под ней. На
   переигровке поздняя крала голос ранней, а leadOff ранней обрывал позднюю.
   ⛳ ЛЕЧЕНИЕ: на шве (1) каждая открытая нота получает НАСТОЯЩИЙ leadOff на КОНЦЕ прохода (rgn.to) — она
   больше не сирота и её номер закрыт ровно один раз; (2) база поднимается выше ВСЕХ выданных за взятое
   (vBase=vTop), поэтому номер прошлого прохода больше не выдаётся никогда. ВНУТРИ прохода номера
   по-прежнему переиспользуются (freeSlot), как в линейной записи.
   ⚠️ ПОЧЕМУ ШОВ ОПРЕДЕЛЯЕМ ПО «ВРЕМЯ ЗАПИСИ ПОШЛО НАЗАД», А НЕ ТОЛЬКО ИЗ tick. Граничная функция
   liveWrapRelease достигается на КАЖДОМ шве, но ПОЗДНО: tick ходит раз в SCHED_TICK_MS (плюс любой
   затор потока), а кадр жестов между пересечением шва и тиком уже пишет СВЁРНУТОЕ время. Нота, взятая
   в этой щели, получила бы номер от старой базы, а потом тиковый сброс оставил бы её без выключения.
   Поэтому проверку зовут ОБА пути — tick (через liveWrapRelease) и сама запись (recLeadEv/recLeadOff), —
   а функция ИДЕМПОТЕНТНА: второй вызов на том же шве видит время уже не назад и ничего не делает.
   «Назад» — ровно определение бага: время вернулось на уже записанный материал. Отсюда и свойство:
   номера делятся только внутри МОНОТОННОГО участка времени, а там логика открытых нот верна.
   ⛔ ПРИ ВЫКЛЮЧЕННОЙ ОБЛАСТИ песенная доля монотонна (перемотка во время записи запрещена, темп держит
   долю) — условие не наступает НИКОГДА, база не растёт, события байт-в-байт прежние. */
function recFoldRoll(){
  if(!recording||!AC) return;
  const now=curBeat();
  if(now<recLastT-1e-6){
    /* ⛳ S4.3: ШОВ ИЛИ ПРЫЖОК — ВЫВОДИМ ИЗ САМИХ ДОЛЕЙ, без флага от вызывающих.
       НАСТОЯЩИЙ ШОВ: проход дошёл до rgn.to, и всё записанное за участок лежит ≤ rgn.to — это теорема, а не надежда: несвёрнутая
       доля < rgn.to, округление к сетке (линии тактов кратны сетке) не выносит за rgn.to, удержание S4.2 — ровно rgn.to, удар
       сворачивается к rgn.from, страж ключа не поднимает выше уже записанного. Значит end ≤ rgn.to → «выкл» на rgn.to, как и было.
       ПРЫЖОК (⟳ включён или скоба поджата, а бегунок был ЗА её концом): до rgn.to никто не доигрывал — участок ушёл дальше, и
       end > rgn.to. Закрыть на rgn.to значило бы положить «выкл» РАНЬШЕ «вкл» (сироты). Закрываем на end — последней доле,
       которую запись реально видела или записала: она ≥ каждого события открытых нот (recHiT ловит и округление вперёд). */
    const end=Math.max(recLastT,recHiT);
    const at = cycling() && end<=loop.rgn.to+1e-9 ? loop.rgn.to : end;
    for(const r of recLead.values()) push('leadOff',{v:r.v},at,null,undefined,r.layer);   // T1: «выкл» — в слой своей ноты
    recLead.clear(); vSlots.clear();
    for(const S of takeSt.values()) S.vBase=Math.max(S.vBase,S.vTop);   // T1: база поднимается В КАЖДОМ слое взятого (слой один — ровно прежнее)
    /* S3.5d-fix: БАС — ТОТ ЖЕ ДЕФЕКТ, ТА ЖЕ ПОЧИНКА. Прежде на шве liveWrapRelease просто обнулял recBass: бас-нота,
       удержанная через шов, оставалась в слое с bassOn без bassOff — висла на переигровке и воскресала
       догонялкой на каждом следующем входе. Теперь — настоящий bassOff на конце прохода; зажатая рука
       переатакует со следующего кадра (живой голос liveWrapRelease уже погасил) и откроет новую ноту.
       Проходы баса разводит суффикс владельца k, который поднимается ниже; номера нот v (P2) внутри прохода
       разводят одновременные ноты — со следующего прохода они снова считаются с нуля (ключ уже другой, k+1). */
    for(const r of recBass.values()) push('bassOff',bassA(null,r.v),at,null,undefined,r.layer);   // P2: КАЖДАЯ открытая бас-нота — в слой своей ноты, со своим номером (при одном владельце — ровно прежний «выкл»)
    recBass.clear();
    /* ⛳ S3.5e: ЗАЩЁЛКНУТЫЙ (или удерживаемый) АККОРД — последний случай незакрытой ноты. Состояние записи аккорда
       шов переживало: его ведения и итоговое «выкл» ложились СВЁРНУТЫМ временем РАНЬШЕ его «вкл», и с выключенным
       повтором он звенел до конца песни, а догонялка поднимала его на каждом следующем входе.
       ЛЕЧЕНИЕ — то же, что у соло и баса: «выкл» на КОНЦЕ прохода и свежее «вкл» в НАЧАЛЕ следующего, с ТЕКУЩИМ
       состоянием аккорда. Отличие одно и техническое: голос соло/баса переатакует сам (рука зажата, живой голос
       погашен), а живой голос аккорда на шве НЕ гасится (правило #20) и лишь ведётся — поэтому «вкл» приходится
       ВПИСАТЬ, а не поймать. Это честная запись ЗВУКА: защёлка действительно звучит на каждом проходе.
       ⛔ ПРАВИЛО #20 НЕ ЗАТРОНУТО: здесь ни одного звукового вызова — только события в массив. liveWrapRelease по-прежнему
       не трогает 'latch', живой аккорд звучит сквозь шов без разрыва.
       ⛳ ПОРЯДОК НЕСУЩИЙ: «выкл» баса и аккорда пишутся СТАРЫМ takeK (их владелец — проход, который кончился), затем
       takeK поднимается, затем «вкл» пишется НОВЫМ. Без подъёма проходы одного взятого делили бы ОДНОГО владельца
       ('loop:N[:k]'), и на переигровке «выкл» последнего прохода обрывал бы аккорд КАЖДОГО прохода — ровно та кража
       голоса, от которой соло разводит vBase. takeK стартует выше всех k, лежавших в слое (layerTakeTop), и дальше
       только растёт, поэтому номер не повторится. */
    const ch=recCh;
    if(ch) push('chOff',{},at,null,undefined,ch.layer);
    recHiT=-Infinity;                                          // S4.3: «выкл» старого ключа записаны — дальше новый участок и новые ключи (k ниже)
    for(const S of takeSt.values()){ S.chLastT=-Infinity; S.bsLast.clear(); S.k=S.k+1; }   // T1: стражи и суффикс — в КАЖДОМ слое взятого; порядок прежний: «выкл» уже записаны СТАРЫМ k
    if(ch) ch.q=loop.quant;                                    // S4.3: вписанное «вкл» — новая нота в данных, она берёт ТЕКУЩЕЕ правило (как бас, что переатакует после шва). Безопасно для порядка: rgn.from — линия такта, лежит на любой сетке
    if(ch) push('chOn',{deg:ch.deg,oct:ch.oct,vol:ch.vol,inst:ch.inst,ty:ch.ty,bri:ch.bri},
                cycling() ? loop.rgn.from : now, {sc:ch.sc, sev:ch.sev}, undefined, ch.layer);   // T1: вписанное «вкл» — в слой того же аккорда, НОВЫМ k   // та же нагрузка, что у настоящего chOn (WchOn): deg/oct/vol/inst/ty/bri; лад и септаккорд — замороженные самого аккорда
  }
  recLastT=now;
}
/* ty входит в сравнение: у типизированных аккордов громкость ФИКСИРОВАНА, а сектор
   меняется без смены ступени/октавы — без этой проверки смена типа не попала бы в
   запись вовсе, и петля играла бы не тот аккорд. Сравнение по ссылке корректно:
   ty — это всегда один и тот же массив из таблицы CHORD_FAMS. */
/* a.bri (яркость) входит в запись КАК a.rev у соло: ложится в полезную нагрузку a (рядом с ty/inst),
   слой запоминает свою яркость и переигрывается с ней. Смена ТОЛЬКО яркости (рука двинулась в глубину,
   ступень/тип/громкость те же) должна попасть в запись → добавляем |Δbri|>REC_REV_EPS в тест chSet
   (та же мёртвая зона, что у реверба соло). События аккордов КВАНТУЮТСЯ к доле (gridFor='chOn'/'chSet'→1),
   поэтому при вкл. квантизации кривая яркости привязывается к долям (грубее соло, но согласно с тем, что
   аккорды и так поbeat-квантованы); при выкл. — полное разрешение жеста. */
/* S3.5e: состояние записи аккорда теперь помнит ещё inst и ЗАМОРОЖЕННЫЙ лад (sc/sev) последнего записанного события —
   ровно то, что нужно шву, чтобы вписать полноценное «вкл» (recFoldRoll). sc/sev берутся в том же синхронном вызове,
   что и push, поэтому совпадают с тем, что push положил в событие.
   ⚠️ inst — ПОПУТНАЯ ПОЧИНКА, И ОНА НЕСУЩАЯ: WchSet несёт {deg,oct,vol,ty,bri} БЕЗ тембра, а recChSet, когда аккорд ещё
   не открыт в записи (защёлка звучала ДО ●, рука зажата), писал этот объект как chOn. На переигровке chordOn брал
   CHORD_INSTR[undefined] и падал на ins.t1 — насос звука бросал исключение. Теперь такой chOn несёт chIdx — тот же
   индекс тембра, что gestures отдаёт в WchOn. Когда inst есть (путь WchOn), нагрузка байт-в-байт прежняя.
   Шов проверяем ПЕРВЫМ во всех трёх — как у соло и баса: кадр жестов между пересечением шва и тиком иначе записал бы
   ведение/«выкл» свёрнутым временем ещё в СТАРОЕ состояние. */
/* ⛳ S4.3: ПРАВИЛО КВАНТИЗАЦИИ ЗАМОРАЖИВАЕТСЯ НА НОТЕ (q в recCh/recBass). Нота — один музыкальный предмет: половина её, снятая
   на сетку, и половина мимо — несвязно при любом порядке событий. Нота доигрывает по правилу, по которому началась; кнопка
   действует со СЛЕДУЮЩЕЙ ноты. Звука это не касается вовсе: квантизация живёт только в push, то есть во времени ЗАПИСИ.
   АККОРД: правило держится от «вкл из тишины» до «выкл» или до шва. «Вкл» поверх звучащего аккорда (смена числа нот в защёлке)
   правило НЕ пересчитывает: это СМЕНА того же звучащего аккорда — то же, что ведение, только с переатакой по технической
   причине. Прогрессия в защёлке остаётся на своём правиле до отпускания; при повторе — до ближайшего шва (там вписанное «вкл»
   берёт текущее, см. recFoldRoll), ровно когда бас, переатакуя, тоже его берёт. */
function recChOn(a){ if(!recording)return; recFoldRoll();
  const q=recCh?recCh.q:loop.quant;                                  // S4.3: смена звучащего — правило прежнее; из тишины — текущее
  const inst=a.inst??chIdx; if(!push('chOn',{...a,inst},null,null,q,undefined)) return;   // S4.1: не легло (отсчёт) — состояния не ставим, см. шапку у recLeadEv. T2: слой — по роли
  const ly=pushLy;
  /* ⛳ T2: ОТКРЫТЫЙ ПРЕЖНИЙ АККОРД В ДРУГОЙ ДОРОЖКЕ — ЗАКРЫТЬ ЯВНО. В одной дорожке его закрывает само это «вкл»:
     у них общий ключ владельца (слой тот же) — так звучит и так спаривает songNotes. Легло «вкл» в ДРУГОЙ слой —
     ключ другой, и прежний аккорд остался бы открытым в своей дорожке навсегда (на переигровке звенел бы до конца
     песни). «Выкл» — в ЕГО слой, по ЕГО правилу квантизации; ложится в тот же миг, после нового «вкл».
     ⚠️ В T2 такого почти не бывает: роль аккордов во взятом одна, и её дорожка одна. Пути сюда откроет T3
     (маршрут по тембру); закрываем уже сейчас, чтобы T3 это не забыл. */
  if(recCh && recCh.layer!==ly) push('chOff',{},null,null,recCh.q,recCh.layer);
  recCh={deg:a.deg,oct:a.oct,vol:a.vol,ty:a.ty,bri:a.bri,inst,q,sc:CUR(),sev:seventh,layer:ly,fine:fineNew(chA(a),curBeat())}; }   // fine — тонкая запись громкости и яркости (fineStep)
/* Нагрузка ВЕДЕНИЯ аккорда из состояния записи — ровно поля chSet (WchSet): тембра нет, служебного (q, sc, слой) — тоже. Нужна тонкой
   записи как опора: её точка удержания пишется этой нагрузкой. */
const chA=r=>({deg:r.deg,oct:r.oct,vol:r.vol,ty:r.ty,bri:r.bri});
function recChSet(a){
  if(!recording)return;
  recFoldRoll();
  if(!recCh){                                                       // S4.1: зажатая через старт защёлка/удержание откроется первым кадром после отсчёта — этой же веткой
    const inst=chIdx, q=loop.quant; if(!push('chOn',{...a,inst},null,null,q,undefined)) return;   // T2: слой — по роли
    recCh={deg:a.deg,oct:a.oct,vol:a.vol,ty:a.ty,bri:a.bri,inst,q,sc:CUR(),sev:seventh,layer:pushLy,fine:fineNew(chA(a),curBeat())};   // layer (T1) — слой аккорда: туда же его ведения, «выкл» и вписанное на шве «вкл»
    return;
  }
  /* СМЕНА АККОРДА (ступень, регистр, тип) — сразу и по правилу квантизации ноты, как прежде; тонкая запись начинает опору заново. */
  const fine=recCh.fine||(recCh.fine=fineNew(chA(recCh),curBeat()));   // опора есть не у всех путей открытия (защёлка, открытая на старте записи, — recLatchOpen)
  if(a.deg!==recCh.deg||a.oct!==recCh.oct||a.ty!==recCh.ty){
    if(!push('chSet',{...a},null,null,recCh.q,recCh.layer)) return;
    fineReset(fine,chA(a),curBeat());
    recCh={deg:a.deg,oct:a.oct,vol:a.vol,ty:a.ty,bri:a.bri,inst:recCh.inst,q:recCh.q,sc:CUR(),sev:seventh,layer:recCh.layer,fine};
    return;
  }
  /* ⛳ ГРОМКОСТЬ И ЯРКОСТЬ — ТОНКОЙ ЗАПИСЬЮ (fineStep), с явной долей каждой выборки, то есть БЕЗ квантизации. ⚠️ Меняет прежнее: при
     включённой квантизации ведение одной громкости/яркости ложилось на долю — плавный свелл аккорда записывался ступенями по доле
     (довод — у recBassEv). Смена аккорда по-прежнему квантуется; порядок внутри ключа держит страж push (chLastT). */
  const out=fineStep(fine, chA(a), curBeat()); if(!out.length) return;
  for(const s of out) push('chSet',{...s.x},s.t,null,recCh.q,recCh.layer);
  recCh={...recCh, vol:fine.lastX.vol, bri:fine.lastX.bri, sc:CUR(), sev:seventh};   // состояние — по последней ЗАПИСАННОЙ величине (её и впишет шов: recFoldRoll)
}
function recChOff(){ recFoldRoll(); if(recording&&recCh){ push('chOff',{},null,null,recCh.q,recCh.layer); recCh=null; } }   // шов первым: «выкл» открытого в новом проходе аккорда ложится в новый проход, а не свёрнутым временем в старый
/* ⛳ P2: НОМЕР ОДНОВРЕМЕННОЙ БАС-НОТЫ В СЛОЕ — тем же правилом, что у соло (lowestFree): наименьший, не занятый ОТКРЫТОЙ
   бас-нотой того же слоя. База — 0, а не vBase соло: у баса взятые и проходы уже разводит суффикс k (layerTakeTop, +1 на
   шве), так что с лежащими в слое нотами новый номер не столкнётся никогда. Один владелец → всегда 0. */
function bassSlot(layer){ const used=new Set(); for(const r of recBass.values()) if(r.layer===layer) used.add(r.v); return lowestFree(used,0); }
/* Нагрузка бас-события с номером ноты — ТОЛЬКО когда он не ноль. ⛔ Это несущее: при одном владельце v=0, и событие
   обязано остаться байт-в-байт прежним (у записанного до P2 баса поля v нет вовсе; ключ владельца без него тот же). */
const bassA=(p,v)=> v ? {...(p||{}), v} : (p?{...p}:{});
function recBassEv(own,p){                              // бас прореживается как соло
  if(!recording)return;
  recFoldRoll();                                          // S3.5d-fix: шов прохода ПЕРВЫМ, как у соло — открытая бас-нота прошлого прохода закрывается на ЕГО конце, и ниже откроется новая
  const r=recBass.get(own);
  if(!r){
    /* Открыть — «вкл» маршрутом по источнику (T2/T3). Номер v нужен ДО push (он в нагрузке), слой выбирает push: смотрим,
       куда ляжет (takePeek — тот же ключ, что спросит push), как это делает соло (recLeadOpen). */
    const q=loop.quant;                                   // S4.3: правило квантизации — от «вкл» ноты (см. шапку у recChOn)
    const pk=takePeek(noteSource('bassOn',p)), v= pk==null ? 0 : bassSlot(pk);
    if(!push('bassOn',bassA(p,v),null,null,q,undefined)) return;   // S4.1: не легло (отсчёт) — состояния не ставим, см. шапку у recLeadEv
    recBass.set(own,{deg:p.deg,oct:p.oct,vol:p.vol,inst:p.inst,q,layer:pushLy,v,fx:fxCopy(p.fx),fine:fineNew(pnSnap(p),curBeat())});   // T0: тембр ноты — тембр её атаки. T1: layer — слой ноты. V4: карта эффектов — КОПИЕЙ, как у соло (fxCopy: иначе сравнение шло бы с живым снимком). fine — тонкая запись (fineStep)
    return;
  }
  /* V4: и СМЕНА КАРТЫ ЭФФЕКТОВ — тем же сравнением, что у соло (fxChanged: состав ключей или любой ключ дальше REC_FX_EPS).
     Карты нет ни у живой ноты, ни у записи (в цепи баса нет прицепочного параметра — так по умолчанию) → fxChanged({},{})
     = ложь, и события байт-в-байт прежние. Есть — палец, ведущий Скольжение посреди ноты, пишет ведение, и следующий
     переезд на переигровке идёт уже с новой величиной. */
  /* СМЕНА ВЫСОТЫ — сразу и по правилу квантизации ноты (r.q), как прежде. T0: тембр — только в «вкл» (см. noInst); смена живого
     тембра посреди ноты — не повод для ведения (бас держит тембр атаки до отпускания). */
  if(p.deg!==r.deg||p.oct!==r.oct){
    if(!push('bassSet',bassA(noInst(p),r.v),null,null,r.q,r.layer)) return;
    r.deg=p.deg; r.oct=p.oct; r.vol=p.vol; r.fx=fxCopy(p.fx); fineReset(r.fine,pnSnap(p),curBeat());   // тембр, правило и слой — от «вкл», не трогаем
    return;
  }
  /* ⛳ ГРОМКОСТЬ И КАРТА — ТОНКОЙ ЗАПИСЬЮ (fineStep), каждое ведение с ЯВНОЙ долей своей выборки, то есть БЕЗ квантизации. ⚠️ Это
     меняет прежнее: ведение одной громкости шло по правилу ноты и при включённой квантизации ложилось на сетку ½ доли — плавный
     свелл баса записывался ступенями сетки. Квантизация — про то, КОГДА БЕРУТ НОТУ, а не про то, как движется рука; смена высоты
     по-прежнему квантуется. Порядок внутри ключа держит страж push (bsLast): ведение не ляжет раньше «вкл» своей ноты. */
  for(const s of fineStep(r.fine, pnSnap(p), curBeat())) push('bassSet',bassA(noInst(s.x),r.v),s.t,null,r.q,r.layer);
  r.vol=r.fine.lastX.vol; r.fx=fxCopy(r.fine.lastX.fx);
}
function recBassOff(own){ recFoldRoll();                // S3.5d-fix: как recLeadOff — иначе bassOff лёг бы свёрнутым «сейчас», раньше своего bassOn
  const r=recBass.get(own);
  if(recording&&r) push('bassOff',bassA(null,r.v),null,null,r.q,r.layer);
  recBass.delete(own); }
function recDrum(a){ if(recording)push('drum',{...a},null,null,undefined,undefined); }   // T2: слой — по роли (push)   // удар — одиночное событие
/* ⛳ ЗАКРЫТЬ В ЗАПИСИ ВСЁ, ЧТО ОСТАЛОСЬ ОТКРЫТЫМ (слайс S3.1). Зовётся при ОСТАНОВКЕ ОВЕРДАБА, когда
   человек жмёт «●», не отпустив пальцы: каждая звучащая нота обязана получить в слой своё «выключение»,
   иначе слой записан незавершённым.
   ⚠️ ДВЕ ДЫРЫ, КОТОРЫЕ ЭТО ЗАКРЫВАЕТ, И ОБЕ БЫЛИ НАСТОЯЩИМИ:
     (1) СОЛО. На остановке стоял голый `recLeadOff()` — БЕЗ АРГУМЕНТА. А состояние записи соло с
         полифонии ПО ВЛАДЕЛЬЦУ (Map recLead), поэтому `recLead.get(undefined)` не находил НИЧЕГО:
         ни одного leadOff не писалось, а запись владельца и его номер v ТЕКЛИ в recLead/vSlots до
         ближайшего recLeadReset. Обход по ВСЕМ владельцам — единственно верная форма: рук две, а
         пальцев на руке до четырёх, открытых нот может быть восемь.
     (2) БАС. Его не закрывали ВООБЩЕ: recBassOff существовал, но достижим был только из WbassOff
         (живое размыкание пальцев). Удержанный на остановке бас оставался в слое без bassOff.
   ⚠️ ПОЧЕМУ ЭТО НЕ БЫЛО СЛЫШНО: на завороте петли releaseLoopLayersAt гасит зависшие голоса слоёв, а
   liveWrapRelease — живые. Сеть безопасности прятала обе дыры. ЛИНЕЙНЫЙ ТРАНСПОРТ заворот убирает, и
   тогда такая нота звенела бы вечно — потому чиним СЕЙЧАС, пока поведение можно проверить в изоляции.
   ⛔ ЗВАТЬ ТОЛЬКО ДО setRecording(false): все три rec*Off пишут событие лишь при `recording`. Переставь
   вызовы местами — и починка тихо перестанет работать, выглядя при этом целой.
   ⚠️ КЛЮЧИ КОПИРУЕМ: recLeadOff удаляет владельца из Map прямо в цикле. */
function recAllOff(){
  for(const own of [...recLead.keys()]) recLeadOff(own);   // соло — ПО КАЖДОМУ владельцу ('lead:L'/'lead:R' и их пальцевые ключи)
  recChOff();                                              // аккорд, в т.ч. ЗАЩЁЛКНУТЫЙ: он звучит и с разомкнутыми пальцами, recCh при этом не сброшен
  for(const own of [...recBass.keys()]) recBassOff(own);   // P2: бас — тоже ПО КАЖДОМУ владельцу (пока он один — 'bass'); ключи копируем: recBassOff удаляет в цикле
}
/* ВЫБРОСИТЬ состояние записи БЕЗ «выкл» (S4.1). Нужен ровно там, где закрывать НЕЧЕГО: «вкл» открытых нот уже нет в песне
   (⤺ снял само текущее взятое). Закрыть их там — значит написать сирот. Везде, где «вкл» в песне есть, — recAllOff. */
function recDrop(){ recLeadReset(); recCh=null; recBass.clear(); }

/* Обёртки W*: живой звук СРАЗУ + запись (если вооружено). Переигровка (насос)
   зовёт ENG напрямую, мимо W* → сама себя не пишет; живой гейт больше не нужен. */
/* own — КЛЮЧ ВЛАДЕЛЬЦА живого голоса ('lead:L'/'lead:R', строит gestures). В событие он НЕ пишется:
   в петле нота принадлежит СЛОЮ, а не руке — там ключ соберёт ldKey из ctx.layer и a.v. */
const WleadOn =(own,p,live)=>{ ENG.leadOn(p,null,{live,own}); recLeadEv(own,p,live); };   // live: в звук (стадия a) И в запись бенда (стадия b); ENG.leadOn получает p БЕЗ bend — живая нота не трогается. ⚠️ when НЕ передаём: живой путь звучит «сейчас», как всегда
const WleadOff=own=>{ ENG.leadOff(null,null,{own}); recLeadOff(own); };
/* ty — интервалы типизированного аккорда. Живёт в ПОЛЕЗНОЙ НАГРУЗКЕ a (как a.inst —
   тембр), а не рядом с sc/sev: тип — свойство самого аккорда, а не ладового контекста.
   Так он замораживается в событии сам собой и переигрывается как сыгран. */
/* ⛳ ЖИВОЙ АККОРД РУКИ, КАК ЕГО ВИДИТ ЗАПИСЬ (liveCh) — последняя нагрузка WchOn/WchSet: ступень, регистр,
   тип, громкость, яркость и ТЕМБР АТАКИ (он печётся в голосе на «вкл»: смена тембра в панели звучащую защёлку
   не перекрашивает, поэтому тембр берём от WchOn, а не живой chIdx). Нужен ровно одному: открыть в записи
   защёлку, которая уже звучит, когда запись начинается (recLatchOpen). Снимается вместе с живым аккордом —
   WchOff и softAllOff. ⛔ Правило #20 не задето: это чтение, живой голос никто не трогает. */
let liveCh=null;
const WchOn =(_o,deg,oct,vol,ins,ty,bri)=>{ const a={deg,oct,vol,inst:ins,ty,bri}; ENG.chOn(a); recChOn(a); liveCh={...a}; };   // bri — живая яркость руки: в звук (ENG) И в запись (rec), как a.rev у соло
const WchSet=(_o,deg,oct,vol,ty,bri)    =>{ const a={deg,oct,vol,ty,bri};          ENG.chSet(a); recChSet(a); if(liveCh) liveCh={...liveCh,...a}; };   // тембр остаётся от атаки (в a его нет)
const WchOff=_o                 =>{ ENG.chOff(); recChOff(); liveCh=null; };
/* ⛳ ЗАЩЁЛКА, УЖЕ ЗВУЧАЩАЯ В НАЧАЛЕ ЗАПИСИ, ОБЯЗАНА ЛЕЧЬ В ДУБЛЬ — запись идёт за звуком. Прежде она пропадала:
   в отсчёте push отказывает (S4.1), а покоящаяся защёлка с разомкнутыми пальцами не шлёт НИ ОДНОГО вызова записи
   (вызовы аккорда живут только внутри щипка) — человек слышал аккорд весь дубль, а на переигровке его не было,
   и в сплите дорожку получала лишь другая половина.
   КОГДА: один раз за взятое, на первом тике ПОСЛЕ отсчёта (там, где push перестаёт отказывать), — с доли начала
   записи latchOpenAt (её ставит onRec: доля запуска при старте с места, доля нажатия ● при идущем транспорте).
   ЧТО: «вкл» с ЯВНЫМ временем этой доли — как если бы аккорд взяли ровно тогда: нагрузка из liveCh (ступень,
   регистр, тип, тембр атаки, громкость, яркость), лад и септаккорд — текущие (смена лада/тоники/септаккорда
   гасит живую защёлку через softAllOff, значит звучащая защёлка всегда в текущем ладу).
   КУДА: обычным маршрутом по источнику (слой не передан) — в дорожку аккордов этого взятого; в сплите это
   вторая дорожка, рождённая на старте (takeMint, правило #27 — на легшем событии); вооружённая дорожка
   аккордов — туда же, слиянием.
   ДАЛЬШЕ: recCh ставится как у любого аккорда — ведения, «выкл», шов повтора, остановка/пауза/паника закрывают
   его обычными путями.
   ⚠️ ДВА СЛУЧАЯ ОТСЧЁТА разделяет ОДНО условие — звучит ли защёлка на первой доле (живой голос chordHold['latch']
   и liveCh): взятая в отсчёте и держащаяся — звучит → открываем; взятая и снятая в отсчёте — WchOff её уже
   погасил → открывать нечего. ⚠️ И если аккорд успела открыть сама рука (зажатый щипок шлёт ведение каждый кадр
   — recChSet открывает «вкл» первым кадром после отсчёта), recCh уже есть — второй раз не открываем. */
let latchOpenAt=null;   // песенная доля начала записи — там открыть звучащую защёлку; null — уже проверено (или не пишем)
function recLatchOpen(){
  const at=latchOpenAt; latchOpenAt=null;
  if(!recording||recCh||!liveCh||!chordHold['latch']) return;
  const a={deg:liveCh.deg,oct:liveCh.oct,vol:liveCh.vol,inst:liveCh.inst??chIdx,ty:liveCh.ty,bri:liveCh.bri};
  if(!push('chOn',a,at,null,loop.quant,undefined)) return;   // слой — маршрутом по источнику; явное время — без квантизации и без отказа отсчёта (мы уже после него)
  recCh={deg:a.deg,oct:a.oct,vol:a.vol,ty:a.ty,bri:a.bri,inst:a.inst,q:loop.quant,sc:CUR(),sev:seventh,layer:pushLy};
}
/* P2: own — КЛЮЧ ВЛАДЕЛЬЦА живой бас-ноты, как у WleadOn/WleadOff. ПОСЛЕДНИМ и с умолчанием 'bass'. С V2 gestures передают его
   всегда (wOn/wOff): 'bass' в ведущем режиме, 'bass:L[:f]' в полифоническом. В событие ключ не пишется. */
const WbassOn =(p,live,own='bass')=>{ ENG.bassOn(p,null,{live,own}); recBassEv(own,p); };   // live в звук, НЕ в запись (recBassEv пишет ступень) — инвариант «живые Гц не записываются», как у соло (правило #11). ⚠️ Прежде здесь стояло (p,null,undefined,live) — дырка под when позиционно; с именованным набором её не существует
const WbassOff=(own='bass')=>{ ENG.bassOff(null,null,{own}); recBassOff(own); };
const WdrumHit=(row,vol,fx)=>{ const a={row,vol,kit:drumKitIdx}; if(fx&&Object.keys(fx).length) a.fx=fx; ENG.drum(a); recDrum(a); };   // fx — карта эффектов удара: ТОЛЬКО когда цепь ударных её даёт (как у баса); иначе поля нет, удар байт-в-байт прежний

/* ⛳ softAllOff — ЕДИНСТВЕННАЯ ТОЧКА «ЗАГЛУШИТЬ ВСЁ», И ТЕПЕРЬ ОНА ЖЕ ЗАКРЫВАЕТ ЗАПИСЬ (слайс S4.1).
   БЫЛО: последняя строка обнуляла состояние записи БЕЗ «выкл». Звук гас здесь же, а нота в дорожке оставалась открытой и
   на переигровке звенела до конца песни (со скобой — до шва, и догонялка поднимала её на каждом входе). Зовут эту функцию
   ~17 мест в ui — лад, тоника, A4, раскладка, пальцев в руке, трезвучие/септаккорд, функция руки, действия пальцев, роль,
   сплит и его роли, поворот в портрет, сбросы уроков. Это была НЕ семнадцать дыр, а одна строка.
   ТЕПЕРЬ: при записи СНАЧАЛА recAllOff — тот же обход, что у ●, паузы, паники, ⤺ и снятия подложки. «Выкл» ложится на
   долю ЭТОГО мига — ровно там, где звук и правда кончился (строками ниже). Новый вызывающий получит это даром.
   ⛔ Не чинить по местам вызова: смысл в том, что восемнадцатый вызов не может забыть.
   ⚠️ ИДЕМПОТЕНТНО: каждый rec*Off снимает то, что закрыл, поэтому второй проход (пауза, clearJam, ⤺ закрывают ДО нас) не
   находит открытого и не пишет ничего; recFoldRoll второй раз не видит «времени назад».
   ⚠️ ДОЛЯ «ВЫКЛ» ОСМЫСЛЕННА ВСЕГДА: запись идёт только при бегущем транспорте (● поднимает его, а все остановки снимают
   запись раньше или в том же вызове). В отсчёте push отказывает — но там по S4.1 и открытого нет.
   ⛔ БЕЗ ЗАПИСИ — БАЙТ-В-БАЙТ ПРЕЖНЯЯ (гейт recording). Паника (recStop) и ✕ (setRecording(false)) снимают запись ДО вызова.
   ⛔ СБРОС В КОНЦЕ ОСТАЁТСЯ: вне записи rec*Off состояние не чистят, а обещание функции — «после неё не открыто ничего».
   Где закрывать нельзя (⤺ снял текущее взятое — его «вкл» больше нет), вызывающий обязан ДО неё звать recDrop. */
/* ⛳ БУФЕРЫ ЗАМОРОЖЕННЫХ ГАСИМ ТОЛЬКО НА СТОЯЩЕМ ТРАНСПОРТЕ (A2b-fix). Все остановки (пауза, паника, редактор)
   снимают loop.on ДО этого вызова — им буферы гасятся как прежде. А на ИДУЩЕМ транспорте softAllOff зовут
   ~17 мест ui (тоника, лад, A4, роль, сплит…), и буфер для них — не «живая нота», а записанное
   воспроизведение. ⛔ ИМЕННО ЗДЕСЬ ЖИЛА ОШИБКА «СМЕНИЛ ТОНИКУ — ДОРОЖКА ЗАМОЛЧАЛА ДО КОНЦА»: frzStopAll
   гасил буфер «сейчас» и сбрасывал armedRep, поэтому шов выхода (frzLeave в планировщике) не находил, что
   передавать, догонялка не звала, а удержанный бас/аккорд — одно «вкл» и цепочка ведений — молчал до
   следующего «вкл». Теперь устаревшую дорожку передаёт событиям планировщик (догонялка на шве), а свежая
   просто играет дальше (прежде она ещё и перезапускалась с горизонта — дыра до ~300 мс на каждое
   переключение роли). */
/* ⛳ НА ИДУЩЕМ ТРАНСПОРТЕ ГОЛОСА ДОРОЖЕК НЕ ГАСНУТ, А ПЕРЕДАЮТСЯ (A2c). Прежде softAllOff гасил ВСЕХ владельцев, и
   удержанный бас или защёлкнутый аккорд ДОРОЖКИ (одно «вкл» и цепочка ведений) молчал до своего следующего «вкл» —
   на каждой смене тоники, лада, A4. Так было всегда у незамороженных дорожек; после шва выхода (A2b) — и у
   устаревших замороженных, отчего пачка изменений A4 (числовое поле шлёт change на КАЖДЫЙ шаг стрелки) гасила
   дорожку, которую первый шаг только что передал событиям. Теперь: ЖИВЫЕ владельцы — как всегда, сейчас;
   владельцы дорожек — trackResplice (шов на горизонте, та же догонялка). Стоим — всё дословно по-старому. */
function softAllOff(){ if(!AC)return;
  if(!loop.on) frzStopAll();                        // F4: аварийная остановка НИЧЕГО не знала о буферах — теперь знает. A2b-fix: только на СТОЯЩЕМ транспорте (довод выше)
  if(recording) recAllOff();                        // S4.1: закрыть в записи то, что сейчас заглушим
  if(loop.on){
    /* ЖИВЫЕ — сейчас, как всегда: руки соло ('lead:*'), живой аккорд ('latch' — правило #20 о шве повтора, а
       softAllOff гасил его всегда и гасит дальше), живой бас ('bass' и 'bass:…' — всё, что не isTrackOwner). Дорожки —
       передаёт trackResplice. */
    for(const k of Object.keys(leadHold))  if(!isTrackOwner(k)) leadOff(k);
    for(const k of Object.keys(chordHold)) if(!isTrackOwner(k)) chordOff(k);
    for(const k of Object.keys(bassHold))  if(!isTrackOwner(k)) bassOff(k);
    trackResplice();
  }else{
    leadAllOff();                                   // все владельцы соло: 'lead:L/R' + 'leadloop:N:v' (раньше был один noteOff — соло было моно)
    Object.keys(chordHold).forEach(k=>chordOff(k)); // все владельцы аккордов: 'latch' + 'loop:N'
    Object.keys(bassHold).forEach(k=>bassOff(k));   // все владельцы баса: 'bass' + 'bassloop:N'
  }
  setLatchDeg(-1); setLatchTy(null); liveCh=null;   // живой аккорд погашен — и его запись-зеркало тоже. тип гасим вместе со ступенью: иначе после паники/очистки
  recDrop(); }                                    // следующий щипок той же ступени прочёлся бы как «тот же аккорд»; состояние записи — в ноль (при записи оно уже закрыто выше)
/* Владелец голоса ДОРОЖКИ — по префиксу ключа (те же, что у chOwnerKey/bassOwnerKey/ldKey и releaseLoopLayersAt). */
const isTrackOwner=k=> k.slice(0,5)==='loop:' || k.slice(0,9)==='bassloop:' || k.slice(0,9)==='leadloop:';
const trackOwnerLayer=k=> parseInt(k.slice(k.indexOf(':')+1),10);   // 'loop:3:2' → 3, 'leadloop:12:0' → 12
/* ⛳ ПЕРЕДАТЬ ДОРОЖКИ НА ГОРИЗОНТЕ — ТОТ ЖЕ ШОВ, ЧТО frzLeave, ТОЛЬКО ДЛЯ ВСЕХ ДОРОЖЕК, ИГРАЮЩИХ СОБЫТИЯМИ.
   Шов T — горизонт уже запланированного (loop.sched): всё до него поставлено, после — поставит обычный проход.
   Голоса дорожек гасим ПО ВРЕМЕНИ T (релиз отменяет и атаки, уже поставленные в окно после T), а догонялка
   (chasePlay — та же, что у входа в песню и у шва заморозки) поднимает удержанное к доле шва — в НОВОЙ высоте:
   частоту выводит ENG из живой тоники/A4, лад — свой замороженный (правило #7).
   ⚠️ СНЯТАЯ ДОРОЖКА (⤺/подложка на ходу: её событий больше нет) гасится СЕЙЧАС, а не на шве — догонять её
   нечем, а уже поставленные в окно атаки иначе прозвучали бы у удалённой ноты.
   ⚠️ Замороженные: свежую догонялка пропускает (играет буфер), ещё взведённую устаревшую — тоже (её передаст
   frzLeave, см. frzBufOwns в chasePlay); устаревшую и уже переданную — передаёт как любую.
   ⚠️ Во время записи: recAllOff (выше) уже закрыл открытое в дубле, а события пишущегося взятого chaseFor
   пропускает — дубль этим не задет. */
function trackResplice(){
  const spb=60/loop.bpm, m=loop.sched, T=loop.t0+m*spb, lo=songAt(m);
  const alive=new Set(); for(const e of events) alive.add(e.layer);
  const at=k=> alive.has(trackOwnerLayer(k)) ? T : undefined;          // живая дорожка — на шве; снятая — сейчас
  for(const k of Object.keys(chordHold)) if(k.slice(0,5)==='loop:')     chordOff(k, at(k));
  for(const k of Object.keys(bassHold))  if(k.slice(0,9)==='bassloop:') bassOff(k, at(k));
  for(const k of Object.keys(leadHold))  if(k.slice(0,9)==='leadloop:') leadOff(k, undefined, at(k));   // V2: слот tie пуст — время в слоте when
  chasePlay(lo, T, false);                          // аккорды и бас — по времени шва, до событий следующего отрезка
  chasePlay(lo, T, true);                           // соло — по явному времени шва, как при пуске
}
function setRecording(v){ recording=v; hooks.rec && hooks.rec(v); }

/* --- Транспорт петли --- */
function clearPump(){ if(pumpTimer){ clearInterval(pumpTimer); pumpTimer=null; } }
/* СЛОИ (аккорд/бас/удар) идут ВПЕРЁД по явному времени; ЛИД/дрон — «почти сейчас».
   ⚠️ ПРИЧИНА У ЛИДА БОЛЬШЕ НЕ ТА, что здесь стояла. Было: «моно-соло делит один голос с живой игрой,
   пред-планировать далеко вперёд опасно». Соло больше НЕ моно — слой и рука сидят в РАЗНЫХ голосах
   пула, драться им нечем.
   ⚠️ И ПРИЧИНА СНОВА НЕ ТА, что здесь стояла. Было: «у соло-функций нет аргумента when, а кривые бенда
   расписываются от AC.currentTime». С слайса S2 это НЕВЕРНО: when есть у leadOn/leadSet/leadOff и у
   scheduleBend (якорь кривой), дрон тоже его принимает. Осталась ОДНА причина, и она поведенческая:
   перевод лида в окно опережения — слышимое изменение (нота начинает ставиться на ~300мс вперёд, а
   гашение слоёв на границе повтора обязано поехать вместе с ней), поэтому он делается ЦЕЛИКОМ и
   проверяется на слух в транспортном слайсе, а не протаскивается попутно. Возможность готова,
   применение отложено СОЗНАТЕЛЬНО. fn[0]==='c' → аккорд;
   slice(0,4)==='bass' → бас; 'drum' → удар. Лид (leadOn/leadSet/leadOff) и дрон — НЕ вперёд. */
const isLayer=fn=> fn[0]==='c' || fn.slice(0,4)==='bass' || fn==='drum';

/* ═══ КУРСОРЫ ПЕРЕИГРОВКИ (слайс S3.2) — стоимость по ОКНУ, а не по всей песне ═══
   Оба цикла переигровки (scheduleLayers и fireNear) обходили ВЕСЬ массив событий, а tick зовёт их
   ОБА каждые SCHED_TICK_MS=25мс. На паре тактов это десятки событий и сорок обходов в секунду —
   бесплатно. На песне в несколько минут это десятки ТЫСЯЧ событий, то есть миллионы чтений полей в
   секунду на том же потоке, где крутятся MediaPipe и синтез. Курсор превращает «весь массив» в
   «события внутри окна».
   ⚠️ ОТСОРТИРОВАН ЛИ МАССИВ — ОТВЕТ: НЕ ЦЕЛИКОМ, И ЭТО ВАЖНО. Сортируют: остановка записи (recStop — её
   зовут и ●, и паника), пауза (onLoop), загрузка аранжировки, а ВО ВРЕМЯ ЗАПИСИ — ещё и каждый путь,
   который зовёт schedInvalidate при идущем взятом (⟳ setRegionOn, отмена, удаление дорожки, снятие
   подложки). Между ними push ДОПИСЫВАЕТ события взятого в конец. Время у них абсолютное, но при
   крутящейся скобе оно СВОРАЧИВАЕТСЯ в неё (songAt), то есть на каждом шве падает обратно к её началу.
   Значит дописанный хвост не отсортирован ни внутри себя, ни относительно тела.
   ⛳ НО ЭТОТ ХВОСТ — РОВНО ТЕКУЩЕЕ ВЗЯТОЕ: push ставит `tk: curTake`, а оба цикла и так пропускают его
   события (`recording && ev.tk===curTake` — их слышно живьём). Поэтому курсоры работают по
   ОТСОРТИРОВАННОМУ ПРЕФИКСУ длиной cursN, а хвост вне его — и не нужен им, и не мешает. Прежний материал
   ВООРУЖЁННОЙ дорожки лежит в префиксе и переигрывается как обычно.
   ⛔ Отсюда условие schedInvalidate: он объявляет префиксом ВЕСЬ массив, поэтому во время записи перед
   ним обязана стоять сортировка (правило #28).
   ⛳ ГЛАВНОЕ СВОЙСТВО БЕЗОПАСНОСТИ: курсор только СУЖАЕТ участок, который смотрим; ЧТО именно сыграть,
   по-прежнему решает явная проверка интервала внутри цикла. Поэтому курсор, вставший СЛИШКОМ РАНО,
   безвреден — лишние события отсеет проверка. Не убирайте эти проверки «раз есть курсор».
   ⚠️ ШОВ ПОВТОРА — НЕ ОСОБЫЙ СЛУЧАЙ, а просто «позиция поехала не туда, где стоит курсор»: при крутящейся
   скобе lo падает к её началу, курсор перепривязывается двоичным поиском. В коде курсора слова «шов» нет
   вовсе; без скобы шва не бывает, и курсор просто идёт вперёд. */
let cursN=0;                        // длина ОТСОРТИРОВАННОГО префикса events (хвост записи — за ним)
const curSched={i:0,at:null};       // курсор scheduleLayers: i — индекс, at — доля, которой он соответствует
const curNear ={i:0,at:null};       // курсор fireNear (своя временнáя база, см. довод у fireNear)
let chaseAt=null, chaseList=null;   // кэш догонялки (S3.5c): доля входа → владельцы, открытые к ней; сбрасывает schedInvalidate, см. chaseFor
let notesView=null;                 // кэш вида «ноты песни» (S4.0): строит songNotes ЛЕНИВО, сбрасывает schedInvalidate — рядом с chaseAt и по той же причине
/* Первый индекс в [0,cursN) с events[i].t >= t. Классический lower_bound. */
function cursLowerBound(t){
  let lo=0, hi=cursN;
  while(lo<hi){ const m=(lo+hi)>>1; if(events[m].t<t) lo=m+1; else hi=m; }
  return lo;
}
/* Поставить курсор на позицию x. Продолжаем с места, если он ровно там; иначе — двоичный поиск.
   Сравнение с допуском 1e-9: соседние сегменты дают ПОБИТОВО равные значения (hi предыдущего —
   то же выражение, что lo следующего), но допуск страхует от дрейфа после смены темпа. */
function cursSeek(c,x){
  /* СТРАХОВКА, О(1), на входе в оба цикла: если бы какой-то путь удалил события, забыв про
     schedInvalidate, cursN оказался бы БОЛЬШЕ массива — и цикл прочитал бы events[i].t у undefined,
     уронив насос звука целиком. Доказано, что таких путей нет (каждое удаление сбрасывает курсоры),
     но цена проверки — одно сравнение на вызов, а цена ошибки — тишина во всём приложении.
     ⛔ Это НЕ замена schedInvalidate: забытый сброс даст лишний обход, а не молчаливо верный результат. */
  if(cursN>events.length) cursN=events.length;
  if(c.at===null || Math.abs(c.at-x)>1e-9){ c.i=cursLowerBound(x); c.at=x; }
  return c.i;
}
/* ⛔ ЕДИНСТВЕННАЯ ТОЧКА СБРОСА КУРСОРОВ — сюда обязан приходить КАЖДЫЙ путь, который делает их
   неверными: правка состава событий (запись, аранжировка, отмена слоя, снятие подложки, очистка),
   пересортировка, и скачок временнóй базы (старт/возобновление транспорта, смена темпа, пауза,
   паника). Позже сюда же придут правка события и перемотка.
   ⛔ НИКАКИХ `curSched.i=0` ПО МЕСТАМ. Разбросанные сбросы — ровно тот способ, которым такая
   оптимизация тихо ломается: один забытый путь даёт пропущенные или удвоенные ноты, причём не сразу.
   Здесь же заново берётся и cursN — длина отсортированного префикса: эта функция вызывается ТОЛЬКО
   когда массив приведён в порядок (сразу после sort/уплотнения/очистки) либо когда запись ещё ничего
   не дописала, поэтому `events.length` в этот момент и есть граница сортированного. */
/* ⛳ ПОКОЛЕНИЕ СОСТАВА СОБЫТИЙ (A1) — счётчик, который поднимает ТОЛЬКО schedInvalidate. Читает его ровно
   один потребитель — глобальная часть ключа мемо подписи свежести (frzGlobalKey). ⚠️ ЗАЧЕМ ОН, ЕСЛИ ЕСТЬ
   events.length: число событий не ловит «сняли N и тут же положили N» — смена подложки (clearJam и
   loadJam подряд) с тем же числом событий, при неподвижных takeFxVer и приколоченном. Одноместное мемо
   этого не замечало лишь по случайности — пока строк на полосе было две, оно пересчитывалось на каждом
   вызове; мемо по слою такой случайности не имеет. А schedInvalidate и так стоит на КАЖДОМ пути,
   меняющем состав событий (правило #28) — второго списка мест не заводим. Запись (push) его не зовёт,
   но она меняет длину на каждом событии. */
let evGen=0;
function schedInvalidate(){ evGen++; cursN=events.length; curSched.at=null; curNear.at=null; chaseAt=null; notesView=null; songLenRecalc(); rgnSync(); }   // notesView (S4.0) — ТОЛЬКО обнуление, не построение: сброс на горячих путях (темп, скоба, старт) стоит одно присваивание   // rgnSync (S3.5b): длина песни могла смениться → «следующая» скоба пересчитывается, «поставленная» поджимается; при повторе опора перепривязывается там же   // ⛳ здесь же пересчитываем ДЛИНУ ПЕСНИ: эта функция и так стоит на каждом пути, меняющем состав событий, поэтому второго списка мест заводить не надо
/* ⛳ УПЛОТНЕНИЕ НА МЕСТЕ вместо splice-в-цикле. Прежде и onUndo, и clearJam удаляли событие за
   событием: каждый splice сдвигает ВЕСЬ хвост, поэтому снятие 10 000 событий из 30 000 — это сотни
   миллионов перемещений, то есть многосекундная заморозка потока, на котором висят и распознавание, и
   синтез. Проход с индексом записи делает ту же работу за ОДИН проход.
   ⛔ ИДЕНТИЧНОСТЬ ССЫЛКИ `events` СВЯЩЕННА: массив объявлен стабильной ссылкой и импортируется
   НАПРЯМУЮ в draw.js (полоса лупера читает его каждый кадр). Поэтому усечение через `.length`, а
   НИКОГДА не `events = …` и не новый массив — иначе draw остался бы с прежним, уже мёртвым.
   Порядок сохраняется, значит отсортированный префикс остаётся отсортированным. */
function compactEvents(drop){
  let w=0;
  for(let r=0;r<events.length;r++){ const e=events[r]; if(!drop(e)) events[w++]=e; }
  const removed=events.length-w;
  events.length=w;                                     // ⛔ усечение, а не подмена массива
  return removed;
}

/* 1) СЛОИ ВПЕРЁД: на каждый опрос планируем события в окне [loop.sched, горизонт) по их ТОЧНОМУ времени
   loop.t0 + доля*spb. Интервал ПОЛУОТКРЫТ [lo,hi): включает начало → доля 0 (сильный удар) не теряется
   на старте. Событие пишущейся дорожки пропускаем. loop.sched — абсолютная доля, монотонно растёт.
   ⛳ S3.3 СНЯЛ ОТСЮДА ПРОЕКЦИЮ ЧЕРЕЗ ЗАВОРОТЫ. Было: внешний `while` резал окно по границам повторов,
   считал номер повтора `rep`, переводил абсолютную долю в долю ВНУТРИ петли и на каждой границе звал
   releaseLoopLayersAt. Со сквозным временем окно НИКОГДА не пересекает границу (её нет), поэтому весь
   цикл схлопнулся в один отрезок, а `guard` (страховка от бесконечного кручения по повторам) стал не
   нужен. Время события — просто `loop.t0 + ev.t*spb`.
   ⛳ S3.4 ВЕРНУЛ СЮДА ПРОЕКЦИЮ — ту же самую, только переанкеренную. Внешний `while` снова режет окно
   по границам проходов, `off` — это прежний `rep*lb`, а `guard` снова страхует от бесконечного
   кручения. Разница ровно одна: проходы отсчитываются не от нуля до длины петли, а от rgn.from до
   rgn.to. ⛔ При выключенной области цикл делает РОВНО ОДИН оборот с off=0 — то есть линейный путь
   S3.3 байт-в-байт, без единого лишнего действия.
   ⛳ И ЭТО ПОДТВЕРЖДАЕТ УСТРОЙСТВО КУРСОРА ИЗ S3.2 ВО ВТОРОЙ РАЗ: заворот в нём НИКОГДА не был особым
   случаем. Монотонный loop.sched вперёд не прыгает, а вот `lo` на границе прохода ПАДАЕТ к rgn.from —
   и cursSeek просто видит «позиция не там, где курсор» и перепривязывается двоичным поиском. Ни одного
   отдельного сброса под заворот не понадобилось. */
function scheduleLayers(){
  const spb=60/loop.bpm;
  const horizon=(AC.currentTime+SCHED_AHEAD-loop.t0)/spb;   // МОНОТОННАЯ доля на горизонте опережения
  const gated=laneGated();                                  // ОДИН раз на вызов: пока никто не заглушён, в цикле остаётся готовый булев
  const frz=frozenOn();                                     // F4: то же «посчитать один раз» — пока ничего не заморожено, цикл не платит ничего
  const R=loop.rgn, cyc=cycling(), L=rgnLen();
  let guard=0;
  while(loop.sched<horizon-1e-9 && guard++<64){
    /* Граница следующего прохода в МОНОТОННЫХ долях и сдвиг «монотонная → песенная» для этого отрезка.
       Без области границы нет (Infinity) и сдвиг нулевой — один оборот до горизонта. */
    const off=cyc ? rgnReps(loop.sched)*L : 0;
    const edge=cyc ? R.to+off : Infinity;
    const segEnd=Math.min(horizon,edge);
    const lo=loop.sched-off, hi=segEnd-off;                  // в ПЕСЕННЫХ долях
    const segT=loop.t0+(lo+off)*spb, rep=cyc?rgnReps(loop.sched):0;   // миг начала отрезка и номер прохода — место ОБОИХ швов заморозки (A2/A2b)
    /* ⛳ A2b: ШОВ ВЫХОДА — ДО СОБЫТИЙ ОТРЕЗКА. Дорожку, чей буфер звучит, но звучать больше не должен
       (устарела от правки или от тоники/A4/темпа, или разморожена на ходу), отдаём событиям с `lo`.
       Порядок несущий: догонялка открывает голоса аккорда/баса по времени шва, а события этого же
       отрезка (их ставит цикл ниже) их ведут — поставь мы их раньше, chordGlide/bassSet ушли бы в пустоту. */
    if(frz) for(const f of frozen.values()) if(f.armedRep!=null && freezeState(f.layer)!=='fresh') frzLeave(f, lo, segT, rep);
    /* КУРСОР: встаём на первое событие с t>=lo (продолжая с места, если оно там же) и идём, пока t<hi.
       Курсор двигаем по ВСЕМ событиям окна, а не только по сыгранным: он — позиция ВО ВРЕМЕНИ, а не
       «сколько нот прозвучало». Явная проверка ev.t>=lo оставлена НАРОЧНО (см. шапку курсоров). */
    let i=cursSeek(curSched,lo);
    for(; i<cursN && events[i].t<hi; i++){
      const ev=events[i];
      if(!isLayer(ev.fn)) continue;
      if(recording&&ev.tk===curTake) continue;               // S3.5c: пропускаем то, что звучит ЖИВЬЁМ (события этого взятого), а не весь слой — старый материал вооружённой дорожки должен звучать
      if(gated&&!laneAudible(ev.layer)) continue;           // дорожка заглушена (или молчит из-за чужого соло) — просто НЕ ПЛАНИРУЕМ её события; сами события НЕ трогаем
      if(frz&&frzLayer(ev.layer)) continue;                 // F4: ЗАМОРОЖЕНА — вместо её событий играет буфер (взводится ниже, на границе прохода)
      if(ev.t>=lo){
        const when=loop.t0+(ev.t+off)*spb;                  // ТОЧНОЕ время: песенная доля события + сдвиг прохода
        ENG[ev.fn](ev.a,ev,{when});                         // ev несёт замороженный лад (§3.4). {when} ИМЕНОВАННО (S2): позиционный третий аргумент раньше значил у разных записей разное — см. шапку ENG
        if(ev.fn==='chOn'||ev.fn==='chSet'){ curChordDeg=ev.a.deg; curChordOct=ev.a.oct; }   // подсветка ведёт на опережение (~до окна) — косметика; регистр лежит в том же событии
        else if(ev.fn==='chOff')curChordDeg=-1;
      }
    }
    curSched.i=i; curSched.at=hi;                           // дошли до hi — следующий отрезок продолжит отсюда без поиска
    /* ⛳ F4: ИСТОЧНИКИ ЗАМОРОЖЕННЫХ — ИЗ ЭТОГО ЖЕ ЦИКЛА И ПО ЭТОЙ ЖЕ ФОРМУЛЕ ВРЕМЕНИ (правило #15).
       `rep` — номер прохода; сменился, значит начался новый круг и нужен НОВЫЙ узел (источник буфера
       одноразов). Взводим по НАЧАЛУ отрезка `lo`: при входе в песню это место входа, на шве — начало
       скобы. Второго пути таймирования не заводим. */
    /* ⛔ УСТАРЕВШУЮ/УХОДЯЩУЮ НЕ ВЗВОДИМ: её отдали событиям швом выхода выше (A2b; прежде здесь буфер
       глушили «сейчас», а события шли с горизонта — дыра до ~300 мс и молчащий аккорд до следующего «вкл»).
       СВЕЖУЮ, ещё не взведённую на этом проходе, — взводим; если до этого её играли СОБЫТИЯ (заморозили на
       ходу, либо снова стала свежей) — сперва шов ВХОДА (A2). */
    if(frz) for(const f of frozen.values()){
      if(freezeState(f.layer)!=='fresh' || f.armedRep===rep) continue;
      if(f.evRun) frzEnter(f, lo, segT, rep);
      frzArm(f, lo, segT, rep); }
    /* ГРАНИЦА ПРОХОДА — гасим голоса дорожек по ЯВНОМУ времени. ⚠️ НЕСУЩЕЕ, а не косметика: события
       АРАНЖИРОВКИ несут открытия без закрытий, и в петле их гасил ровно этот вызов. */
    if(cyc && segEnd>=edge-1e-9){
      releaseLoopLayersAt(loop.t0+edge*spb);
      chasePlay(R.from, loop.t0+edge*spb, false);           // S3.5c: следующий проход начинается с R.from — поднять аккорды/бас, открытые к нему, ПО ТОМУ ЖЕ времени шва и ДО событий прохода (они пойдут следующим оборотом цикла). R.from=0 — пусто и бесплатно
    }
    loop.sched=segEnd;
  }
}
/* Гашение голосов ДОРОЖЕК (owner 'loop:'/'bassloop:'/'leadloop:'), по явному времени. Читает hold СЕЙЧАС.
   ⛳ S3.3 СМЕНИЛ ЕМУ ПОВОД, НЕ УСТРОЙСТВО. Звали его с границы повтора; границы больше нет, и теперь
   зовут ДВА места: заглушение дорожки (S1, с номером слоя) и КОНЕЦ ПЕСНИ (stopAtEnd, без номера).
   ⚠️ КОНЕЦ ПЕСНИ — НЕ КОСМЕТИКА, а необходимость: события АРАНЖИРОВКИ не несут выключений вовсе
   (buildArrangement кладёт chOn/bassOn без пары), и в петле их гасил именно заворот. Без этого вызова
   последний аккорд подложки звенел бы после конца песни бесконечно. Записанные игроком ноты свои
   выключения имеют — это гарантировал слайс S3.1.
   ⛳ layer — НЕОБЯЗАТЕЛЬНЫЙ фильтр (слайс S1): задан — гасим РОВНО этот слой (заглушение дорожки),
   не задан — ВСЕ дорожки разом (конец песни, перемотка). Обход ключей владельцев остаётся ОДИН:
   второй такой же цикл в другом месте рано или поздно разошёлся бы с этим.
   ⚠️ Сравниваем ХВОСТ ключа целиком ('loop:3' → '3') или хвост с двоеточием ('leadloop:3:0' → '3:'),
   а не просто начало: иначе слой 1 забрал бы и слой 12. */
/* ⛳ part (A2) — НЕОБЯЗАТЕЛЬНЫЙ: не задан — всё, как было; 'pool' — только аккорды и бас (их гасят по
   явному времени шва заморозки); 'lead' — только соло (оно «почти сейчас», его гасит tick, когда шов
   наступил). Обход ключей остаётся ОДИН — ради этого параметр, а не второй цикл в frzEnter. */
function releaseLoopLayersAt(when,layer,part){
  const own = layer==null ? null : String(layer);
  const hit = (k,pre)=>{ if(k.slice(0,pre.length)!==pre) return false;
    if(own==null) return true;
    const rest=k.slice(pre.length);
    return rest===own || rest.slice(0,own.length+1)===own+':'; };
  if(part!=='lead'){
    for(const k of Object.keys(chordHold)) if(hit(k,'loop:')) chordOff(k,when);
    for(const k of Object.keys(bassHold))  if(hit(k,'bassloop:')) bassOff(k,when);
  }
  if(part==='pool') return;
  /* СОЛО-СЛОИ гасим тем же обходом — страховка от ноты без пары (её мог оставить слой аранжировки или
     старая запись). Ноты, записанные игроком, свои выключения имеют с S3.1.
     ⛳ `when` СОЛО ПРИНИМАЕТ (S2 дал leadOff явное время), но ЗДЕСЬ МЫ ЕГО НАМЕРЕННО НЕ ПЕРЕДАЁМ: лид
     по-прежнему идёт «почти сейчас» (он не в isLayer), и гасить его по ЗАПЛАНИРОВАННОМУ времени,
     а ставить по стенным часам — значило бы рассинхрон. Перевод лида в планировщик — отдельная,
     СЛЫШИМАЯ работа, и этот слайс её сознательно не делает. */
  for(const k of Object.keys(leadHold))  if(hit(k,'leadloop:')) leadOff(k);
}
/* ═══ ДОГОНЯЛКА (CHASE): ВХОД В ПЕСНЮ НЕ С НАЧАЛА (слайс S3.5c) ═══
   ⚠️ ДЫРА, КОТОРУЮ ЭТО ЗАКРЫВАЕТ. У аккорда и баса ОДИН владелец голоса на слой ('loop:N', 'bassloop:N'),
   и смена аккорда/ступени — это ВЕДЕНИЕ уже звучащего голоса, а не новый: в записи это ОДНО chOn и цепочка
   chSet (защёлка той же плотности зовёт WchSet; бас-рука зовёт WbassOn каждый кадр, и запись всё после
   первого кадра пишет bassSet). А chordGlide / bassSet / leadSet при ОТСУТСТВИИ владельца молча выходят.
   Войди в песню ПОСЛЕ chOn — и все chSet ведут пустоту: роль молчит до следующего «вкл».
   ⛳ ЭТО НЕ ДЕФЕКТ СКОБЫ. Входов «не с начала» четыре, и первый — старше скобы:
     (1) ▶ с паузы посреди песни (S3.3: пауза гасит голоса, пуск продолжает с позиции) — startTransport;
     (2) шов повтора, когда скоба начинается не с такта 1 — scheduleLayers (и tick для соло);
     (3) запуск записи со скобы не с такта 1 — startTransport;
     (4) прыжок скобы на её начало (rgnApply) и seekTo — startTransport/rgnApply.
   Пока область всегда начиналась с 0, (2)–(4) были недостижимы, а (1) просто не замечали; скоба сделала
   дыру ЕЖЕПРОХОДНОЙ.
   СОЛО — ТОЙ ЖЕ ФОРМЫ, но уже: у него «вкл» на КАЖДУЮ ноту, поэтому молчат лишь ноты, ЗАЖАТЫЕ через вход
   (и глиссандо внутри щипка — это leadSet). Ударные — одиночные удары, им догонять нечего. Дрон — УРОВЕНЬ
   с жизненным циклом (droneOn на пуске по droneAudible), а не нота: не затронут.
   ⛳ ЛЕЧЕНИЕ — состояние, которое было бы при игре С НАЧАЛА: для каждого владельца последнее «вкл» до входа и
   последнее «ведение» после него (встреченное «выкл» владельца снимает). Голос поднимается В ЭТОМ состоянии
   ОБЫЧНЫМ ENG.chOn/bassOn/leadOn — по явному времени входа (правило #15), с ЗАМОРОЖЕННЫМ ладом своего
   события (правило #7: ctx — само событие) и с его картой эффектов. ⛔ Второго вывода частоты здесь НЕТ и
   не заводить: частоту выводит ENG, как при любой переигровке.
   ⚠️ Нагрузку склеиваем {...вкл.a, ...ведение.a}: у chSet нет inst (тембр живёт на атаке) — он приходит из
   chOn; всё, что ведение меняет (ступень, регистр, тип, громкость, яркость, эффекты), — из ведения.
   Контекст (лад) — от ведения: это то состояние, что звучало бы на входе.
   ⚠️ «ВЫКЛ» ВНУТРИ СКОБЫ ГАСИТ ДОГНАННЫЙ ГОЛОС КАК ОБЫЧНО: ключ владельца тот же (chaseKey зовёт те же
   chOwnerKey/bassOwnerKey/ldKey, что и ENG), а его chOff/bassOff/leadOff — обычное событие прохода.
   ⚠️ Владелец, у которого РОВНО на доле входа стоит своё «вкл» или «выкл», не догоняется: проход сыграет его
   сам в тот же миг (иначе — лишняя атака, тут же снятая, и украденные голоса пула). */
const chaseRole=f=> f[0]==='c'?'ch' : f[0]==='b'?'bs' : f[0]==='l'?'ld' : null;   // drum/drone — не владельцы голосов
const chaseKind=f=> f[f.length-1];                                                // 'n' — …On, 't' — …Set, 'f' — …Off
const chaseKey=(role,ev)=> role==='ch'?chOwnerKey(ev) : role==='bs'?bassOwnerKey(ev) : ldKey(ev,ev.a);
/* Владельцы, открытые к доле x (события с t<x). ⛳ СТОИМОСТЬ: построение — ОДИН линейный проход по
   отсортированному префиксу до x (O(n) на пятиминутной песне: десятки тысяч событий, доли миллисекунды), и
   ТОЛЬКО когда сменилась доля входа или состав событий. Результат КЭШИРУЕТСЯ по x и сбрасывается в
   schedInvalidate — единственной точке, через которую идёт каждое изменение событий. Поэтому на КАЖДОМ шве
   повтора (скоба не двигается, события те же) стоимость — O(открытых владельцев), то есть число дорожек.
   На тике — НОЛЬ: сюда ходят только шов и запуск, работу по окну из S3.2 это не трогает.
   ⚠️ Проход ВПЕРЁД, а не назад: итог тот же («последнее вкл, затем ведения, выкл снимает»), но одним
   проходом сразу для всех владельцев — обратному пришлось бы всё равно дойти до начала, ведь заранее
   неизвестно, у кого единственное «вкл» лежит на доле 0.
   Хвост записи (за cursN) не входит — это пишущаяся дорожка, её и так не переигрывают; фильтр
   слышимости и пишущегося слоя — при ПРИМЕНЕНИИ (chasePlay), не в кэше: mute/solo меняются без сброса. */
function chaseFor(x){
  if(chaseAt===x) return chaseList;
  const list=[]; chaseAt=x; chaseList=list;
  if(x<=1e-9) return list;                                   // вход с начала песни — догонять нечего, и обход не делаем вовсе
  if(cursN>events.length) cursN=events.length;               // та же страховка, что в cursSeek
  const lb=cursLowerBound(x), st=new Map();
  for(let i=0;i<lb;i++){ const ev=events[i], role=chaseRole(ev.fn); if(!role || (recording&&ev.tk===curTake)) continue;   // S3.5c: события взятого звучат живьём — не догоняем (тот же пропуск, что в переигровке)
    const k=chaseKey(role,ev), kind=chaseKind(ev.fn);
    if(kind==='n') st.set(k,{role,on:ev,set:null});
    else if(kind==='t'){ const s=st.get(k); if(s) s.set=ev; }
    else if(kind==='f') st.delete(k);
  }
  for(let i=lb;i<cursN && events[i].t<=x+1e-9;i++){ const ev=events[i], role=chaseRole(ev.fn); if(!role || (recording&&ev.tk===curTake)) continue;
    const kind=chaseKind(ev.fn); if(kind==='n'||kind==='f') st.delete(chaseKey(role,ev)); }   // своё вкл/выкл ровно на входе — проход сыграет сам
  for(const s of st.values()) list.push(s);
  return list;
}
/* Поднять догнанные голоса к доле x по времени when. lead=false — слои (аккорд/бас: они идут вперёд по
   планировщику), lead=true — соло (оно «почти сейчас», зовётся из tick на шве или со своим when из запуска). */
/* only (A2b) — НЕОБЯЗАТЕЛЬНЫЙ номер слоя: догнать ТОЛЬКО эту дорожку. Шов выхода из заморозки — это вход в
   середину песни для одной дорожки, и догонялка та же самая; сворачивание (chaseFor) при этом общее и
   кэшированное по доле, так что десять дорожек на одном шве стоят одну свёртку. */
function chasePlay(x,when,lead,only){
  const list=chaseFor(x); if(!list.length) return;
  const gated=laneGated();
  for(const s of list){
    if((s.role==='ld')!==lead) continue;
    const ly=s.on.layer;
    if(only!=null && ly!==only) continue;
    /* S3.5c: пропуска «весь пишущийся слой» здесь БОЛЬШЕ НЕТ — он заглушил бы старые аккорды/бас вооружённой
       дорожки на входе. Живое (события взятого) отсеяно ещё при построении (chaseFor), тем же правилом, что
       в переигровке. */
    if(gated&&!laneAudible(ly)) continue;                     // заглушённая / молчащая из-за чужого соло — догнанной ноты у неё быть не должно
    if(frzLayer(ly)||frzBufOwns(ly)) continue;                // F4: ЗАМОРОЖЕННОЙ ДОГОНЯЛКА НЕ НУЖНА — у источника буфера есть СМЕЩЕНИЕ, вход посреди ноты играет с середины сэмпла сам. A2c: и УСТАРЕВШЕЙ, чей буфер ещё звучит (взведён), — её передаст событиям frzLeave на своём шве; догони мы её здесь, голос открылся бы дважды
    const hold=!!(s.set&&s.set.a.hold);                       // терменвокс: ведение с hold несёт ЖИВУЮ ступень, а высоту — бенд от ступени АТАКИ
    const a={...s.on.a, ...(s.set?(s.role==='ld'?s.set.a:noInst(s.set.a)):null)};   // T0-fix: у СОЛО тембр — от последнего ведения (нота переливается живьём, в точке входа звучал он); у баса — от атаки (он печётся на «вкл», ведение его не несёт); у аккорда в chSet тембра нет вовсе
    const ctx=(s.set&&!hold)?s.set:s.on;
    if(s.role==='ch'){ ENG.chOn(a,ctx,{when}); curChordDeg=a.deg; curChordOct=a.oct; }
    else if(s.role==='bs') ENG.bassOn(a,ctx,{when});
    else {
      if(hold){ a.deg=s.on.a.deg; a.oct=s.on.a.oct; }
      /* Кривая бенда — от момента атаки; догоняем её ОСТАТОК: значение на входе становится точкой dt=0,
         дальнейшие точки сдвигаются на прошедшее. Без этого глиссандо начиналось бы заново с атаки. */
      const B=s.on.a.bend;
      if(B&&B.length){ const off=x-s.on.t; let k=-1;
        for(let j=0;j<B.length&&B[j].dt<=off;j++) k=j;
        const nb= k>=0 ? [{dt:0,c:B[k].c}] : [];
        for(let j=k+1;j<B.length;j++) nb.push({dt:B[j].dt-off,c:B[j].c});
        a.bend=nb; }
      ENG.leadOff(a,ctx,{when});                              // хвост прошлого прохода в том же владельце (событие у конца скобы) — снять, чтобы догнанная нота встала СВЕЖЕЙ атакой, а не глиссандо из чужой
      ENG.leadOn(a,ctx,{when});
    }
  }
}
/* ═══ НОТЫ ПЕСНИ: СОБЫТИЯ, СОБРАННЫЕ В НОТЫ (слайс S4.0 — фундамент пиано-ролла) ═══
   ЗАЧЕМ. Нота — НЕ событие: у соло это «вкл», ведения и «выкл», связанные номером a.v; у аккорда и баса — та же
   форма, связанная суффиксом a.k; удар — одиночное событие без пары. Двигать, менять высоту и удалять нельзя, пока
   нельзя спросить «какие события составляют эту ноту», — а снятое «вкл» без его «выкл» оставит голос, который
   нечем погасить. Здесь — ТОЛЬКО ЧТЕНИЕ: ни одного изменения событий, звука, показа; сегодня этого никто не зовёт.
   ⛳ ТОЖДЕСТВО НОТЫ = КЛЮЧ ВЛАДЕЛЬЦА ГОЛОСА, ТОТ ЖЕ, ЧТО У ДВИЖКА: chaseRole/chaseKind/chaseKey → ldKey / chOwnerKey /
   bassOwnerKey. ⛔ Второй формулы спаривания не заводить: разойдись она с ключом движка — редактор показывал бы одну
   ноту, а звучала бы другая.
   ⚠️ ВНУТРИ КЛЮЧА НОТЫ РАЗЛИЧАЕТ ТОЛЬКО ПОРЯДОК ВО ВРЕМЕНИ — номера ноты нет. Для спаривания этого хватает ровно пока
   ноты одного ключа не перекрываются: запись это гарантирует (vBase/takeK), движок этого ТРЕБУЕТ (иначе кража голоса).
   Для ПРАВКИ это условие: нота, сдвинутая поверх соседки того же ключа, перепутает и спаривание, и звук — правка
   обязана развести их a.v/a.k (layerSlotTop/layerTakeTop).
   ⛳ РУЧКА НОТЫ — head, САМ ОБЪЕКТ её «вкл» (у удара — сам удар, у сироты — сама сирота). Сортировка и compactEvents
   переставляют ССЫЛКИ и объектов не пересоздают, поэтому после любой пересборки нота находится по head===прежний.
   Порядковый номер внутри ключа ручкой быть НЕ может: сдвиг или удаление соседки его меняет. Ссылка не
   сериализуется — как и sc (правило #7).
   ⛳ ПРАВИЛА ЧТЕНИЯ — поведение ДВИЖКА, а не пожелание (что не слышно, то и не нота):
     …On при ОТКРЫТОЙ ноте того же ключа — закрывает прежнюю (endBy:'next') и открывает новую. Аккорд так и звучит:
         chordOn сперва chordOff — переатака; так пишет смена плотности защёлки, так лежит подложка (chOn на такт без
         chOff). ⚠️ Бас и соло на том же ключе НЕ переатакуют (bassOn/leadOn при звучащем голосе только ведут, тембр не
         перепекают) — на слух это ведение. Делим всё равно по «вкл»: «нота на такт» подложки — намерение, а разницу
         несёт role. Так же читает догонялка (chaseFor: новое «вкл» затирает прежнее).
     …Set / …Off без открытой ноты — СИРОТА (orphans). Движок её тоже не слышит: chordGlide/bassSet/leadSet/…Off без
         голоса выходят молча.
     «вкл» без «выкл» до конца префикса — ОТКРЫТАЯ нота: end=null, endBy:'open'. НЕ выбрасываем и НЕ выдумываем конец:
         подложка так устроена намеренно, а СЛЫШИМЫЙ конец зависит от транспорта (конец песни и шов скобы гасят голоса
         дорожек — releaseLoopLayersAt), не от событий.
     drum  — нота-удар: end=start, endBy:'hit', key=null.
     drone — НЕ нота, а УРОВЕНЬ (levels): droneOn живёт жизненным циклом (droneAudible), время события после старта
         не читается никем.
     иное fn — other (сегодня пусто; заведётся новое — увидится, а не пропадёт).
     mixedTk — у ноты события РАЗНЫХ взятых: два взятых делят ключ владельца. Запись такого не порождает; признак для
         правки, а не ошибка чтения.
   ⛳ ЧИТАЕМ ТОЛЬКО ОТСОРТИРОВАННЫЙ ПРЕФИКС [0,cursN) — тот же, что у курсоров. Хвост идущего взятого не отсортирован
   (швы сворачивают время) и растёт в push БЕЗ сброса; спаривать его значило бы сортировать копию на каждое чтение
   или сбрасывать кэш из push — то есть вторую точку инвалидации. prefix — сколько событий покрыто: меньше
   events.length бывает только во время записи (и тогда разница — ровно хвост взятого).
   ⛳ ЦЕНА: один линейный проход O(n) + Map открытых ключей (размером с одновременно звучащие ноты), ЛЕНИВО — на первом
   чтении после schedInvalidate, дальше готовый объект. ⛔ НЕ ЗВАТЬ из tick / scheduleLayers / fireNear / chase* / ENG /
   push / rec*: ни один путь звука её не зовёт, а schedInvalidate её лишь ОБНУЛЯЕТ. Проход достаётся потребителю
   (показ/правка), на его кадр.
   ⛳ ИНВАЛИДАЦИЯ — в schedInvalidate, рядом с chaseAt (правило #28). Своей не заводить.
   ТОЛЬКО ЧТЕНИЕ: вид, записи нот и их массивы заморожены. СОБЫТИЯ внутри — живые объекты песни (бенд терменвокса
   дописывается в a.bend по ссылке), и менять их можно только путями рекордера. */
function songNotes(){
  if(notesView) return notesView;
  const N=Math.min(cursN,events.length);                     // та же страховка, что в cursSeek, но БЕЗ записи в cursN: чтение состояния не меняет
  const notes=[], levels=[], orphans=[], other=[], open=new Map();
  for(let i=0;i<N;i++){ const ev=events[i], f=ev.fn, tk=ev.tk||0;
    if(f==='drum'){ notes.push({role:'dr', layer:ev.layer, tk, key:null, head:ev, evs:[ev], start:ev.t, end:ev.t, endBy:'hit', mixedTk:false}); continue; }
    if(f==='drone'){ levels.push(ev); continue; }
    const role=chaseRole(f), kind=chaseKind(f);
    if(!role || (kind!=='n'&&kind!=='t'&&kind!=='f')){ other.push(ev); continue; }
    const k=chaseKey(role,ev); let n=open.get(k);
    if(kind==='n'){
      if(n){ n.end=ev.t; n.endBy='next'; }                    // «вкл» поверх открытой ноты того же ключа — прежняя кончилась здесь
      n={role, layer:ev.layer, tk, key:k, head:ev, evs:[ev], start:ev.t, end:null, endBy:'open', mixedTk:false};
      notes.push(n); open.set(k,n);
    }else if(!n) orphans.push(ev);                            // ведение/«выкл» без «вкл» — сирота
    else { n.evs.push(ev); if(tk!==n.tk) n.mixedTk=true;
      if(kind==='f'){ n.end=ev.t; n.endBy='off'; open.delete(k); } }
  }
  for(const n of notes){ Object.freeze(n.evs); Object.freeze(n); }
  notesView=Object.freeze({ notes:Object.freeze(notes), levels:Object.freeze(levels), orphans:Object.freeze(orphans), other:Object.freeze(other), prefix:N });
  return notesView;
}
/* ═══ СЕГМЕНТЫ: ВЫСОТА ДЕРЖИТСЯ ДО СЛЕДУЮЩЕЙ СМЕНЫ (слайс S5.5) ═══
   ⚠️ ЗАЧЕМ ОТДЕЛЬНО ОТ songNotes, а не вместо неё. songNotes группирует ЖИЗНЬ ГОЛОСА — и это верно для
   звука: одна бас-нота = один голос от «вкл» до «выкл». Но у баса и соло смена высоты внутри ноты — это
   ВЕДЕНИЕ, поэтому бас-линия, сыгранная одним движением, — ОДНА нота на десяток высот. Нарисуй её как
   ноту — получишь одну полосу через всю песню на высоте ПЕРВОЙ ступени, а остальные высоты исчезнут.
   СЕГМЕНТ — то, что музыкант и называет нотой: событие, ЗАДАЮЩЕЕ высоту, и промежуток до следующей смены.
   ⛳ ГРАНИЦА — ТОЛЬКО СМЕНА ВЫСОТЫ. Ведения, меняющие лишь громкость или эффекты, границами НЕ являются:
   они внутри сегмента (иначе одна нота с крещендо рассыпалась бы на десяток «нот» одной высоты).
   ⛳ У КАЖДОГО СЕГМЕНТА СВОЙ ЛАД — тот, что заморожен в ЕГО событии (sc/sev). Это не формальность: ось
   рисуется в ладу показанной группы, и сегмент обязан знать свой собственный.
   ⛳ ИНВАЛИДАЦИЯ — ЧУЖАЯ: мемо на ИДЕНТИЧНОСТЬ объекта songNotes(). Тот пересобирается только в
   schedInvalidate, значит второй точки сброса здесь нет (правило #28) — как и у кэша ролла в draw.
   byEv — обратный указатель «событие → его сегмент»: правке нужно знать, сегмент ли это начала ноты. */
/* ⛳ НОТА ТЕРМЕНВОКСА СОЛО — у её «вкл» есть кривая бенда (recLeadOpen кладёт a.bend=[] и сразу стартовую точку). ОДИН тест на
   весь рекордер: его же берёт перестройка «в ноте» (pnPlan — порождённому ведению hold:true только у такой ноты), и проход
   сегментов (songSegs — такая нота одним сегментом). Разойдись они — полоса считала бы ноту терменвоксом, а ролл резал бы её. */
const ldTherm=n=> n.role==='ld' && !!(n.head && n.head.a && n.head.a.bend && n.head.a.bend.length);
/* ТИП АККОРДА — ПО ЗНАЧЕНИЮ (слайс U1). Записанный аккорд несёт ссылку в CHORD_FAM_SETS, и у одной записи одна ссылка — для него
   «то же значение» и «та же ссылка» совпадают, ничего не меняется. Распавшаяся нота (U2) несёт ЛИТЕРАЛ интервала ([iv]) — свой массив у
   каждого события; сравнение по ссылке резало бы её на ложные сегменты на каждом ведении. null — нетипизированный аккорд. */
const tyEq=(a,b)=> a===b || (!!a && !!b && a.length===b.length && a.every((x,i)=>x===b[i]));
let segView=null;
function songSegs(){
  const V=songNotes();
  if(segView&&segView.view===V) return segView;
  const segs=[], byEv=new Map();
  for(const n of V.notes){
    if(n.role!=='bs'&&n.role!=='ld'&&n.role!=='ch') continue;
    /* ⛳ S0: НОТА ТЕРМЕНВОКСА — ОДИН СЕГМЕНТ. Её высоту несёт кривая бенда от ступени АТАКИ, а ведения с hold:true пишут
       ЖИВУЮ ближайшую ступень (recLeadEv: {...p, hold:true}) — звук её не читает (ENG.leadSet: hold → частоты нет), читает только
       подсветка. Сравни проход их ступени — одна согнутая нота рассыпалась бы на ложные «ноты» по ближайшим ступеням, и правка
       любой из них резала бы глиссандо, которого на этих границах нет. Поэтому внутри такой ноты смен высоты не бывает, а ведение
       hold сменой высоты не считается НИКОГДА (подстраховка: hold пишется только терменвоксом). У баса и аккордов — как было. */
    const therm=ldTherm(n);
    let cur=null;
    for(const ev of n.evs){
      const kind=chaseKind(ev.fn);
      if(kind==='f'){ if(cur){ cur.end=ev.t; cur.endBy='off'; cur.endEv=ev; } continue; }   // «выкл» закрывает последний сегмент
      const a=ev.a||{};
      const pitchChanged = !cur || (!therm && !(n.role==='ld'&&a.hold) &&
                           (a.deg!==cur.deg || (a.oct|0)!==cur.oct || (n.role==='ch'&&!tyEq(a.ty,cur.ty))));   // U1: тип — ПО ЗНАЧЕНИЮ (tyEq)
      if(kind==='n'||pitchChanged){
        if(cur){ cur.end=ev.t; cur.endBy='next'; cur.endEv=ev; }   // S5.6: КАКОЕ событие кончает сегмент — его и двигает изменение длины
        cur={ role:n.role, layer:n.layer, key:n.key, tk:ev.tk||0, note:n, ev, endEv:null,
              first:ev===n.head, start:ev.t, end:null, endBy:'open',
              deg:a.deg, oct:a.oct|0, ty:a.ty, sc:ev.sc, sev:ev.sev, inst:((n.head&&n.head.a)||{}).inst, vol:a.vol };   // T0: тембр сегмента — тембр НОТЫ (её «вкл»): ведения его не несут (у аккорда не несли никогда)
        segs.push(cur); byEv.set(ev,cur);
      }else byEv.set(ev,cur);                                                  // ведение громкости/эффектов — ВНУТРИ сегмента
    }
    /* Нота закрылась «вкл» СОСЕДНЕЙ ноты — хвостовой сегмент кончается там же, но endEv НЕ ставим: то
       событие принадлежит ДРУГОЙ ноте, и тянуть за него длину этой значило бы двигать чужое начало. */
    if(cur&&cur.end==null&&n.end!=null){ cur.end=n.end; cur.endBy=n.endBy; }
  }
  segs.sort((a,b)=>a.start-b.start);
  segView={ view:V, segs, byEv };
  return segView;
}
/* 2) ЛИД/дрон — почти-сейчас (как раньше): события в (a,b] БЕЗ when → AC.currentTime. Слои тут пропускаем.
   ⚠️ УСЛОВИЯ РАЗВЁРНУТЫ В continue-ветки (было одно длинное &&) РАДИ ЧИТАЕМОСТИ ПОСЛЕ ДОБАВЛЕНИЯ
   ГЕЙТА ДОРОЖЕК — набор условий и их смысл не изменились. */
/* ⛳ У fireNear СВОЙ КУРСОР, а не общий со scheduleLayers — и это вынужденно, а не по вкусу. Три
   различия, каждого хватило бы: (1) ВРЕМЕННÁЯ БАЗА другая — здесь позиция ИГРЫ (loop.pos), там
   горизонт ОПЕРЕЖЕНИЯ, и они расходятся на SCHED_AHEAD; (2) интервал полуоткрыт С ДРУГОЙ СТОРОНЫ
   ((a,b] против [lo,hi)). ⛳ Третье различие — «на завороте fireNear зовут ДВАЖДЫ за тик, с прыжком
   назад к нулю» — S3.3 УБРАЛ вместе с заворотом; двух оставшихся по-прежнему достаточно.
   В СТРОЮ они держатся тем, что оба перепривязываются через ОДНУ функцию (schedInvalidate) и делят
   ОДНУ границу отсортированного префикса cursN.
   ⚠️ lower_bound даёт первое t>=a, а нам нужно строгое t>a — разницу снимает ОСТАВЛЕННАЯ явная
   проверка ev.t<=a: курсор может встать на одно событие раньше, и это безвредно по построению. */
function fireNear(a,b,rep=0){                                  // rep (A2b) — номер прохода скобы, к которому принадлежит интервал: шов заморозки сравнивается парой (проход, доля) — см. frzSkipNear
  const gated=laneGated();                                   // как в scheduleLayers: считаем один раз на вызов
  const frz=frozenOn();                                      // F4: так же дёшево, пока ничего не заморожено
  let i=cursSeek(curNear,a);
  for(; i<cursN && events[i].t<=b; i++){
    const ev=events[i];
    if(isLayer(ev.fn)||ev.t<=a) continue;
    if(recording&&ev.tk===curTake) continue;                    // S3.5c: как в scheduleLayers — только события этого взятого
    if(gated&&!laneAudible(ev.layer)) continue;              // заглушённая / молчащая из-за чужого соло дорожка
    if(frz&&frzSkipNear(ev,rep)) continue;                      // F4: заморожена — её соло/дрон играет буфер, а не события. A2/A2b: у швов входа и выхода — по доле шва (см. frzSkipNear)
    ENG[ev.fn](ev.a,ev);
  }
  curNear.i=i; curNear.at=b;                                 // следующий вызов придёт с a===b и продолжит без поиска
}
/* ⛳ ВОССТАНОВЛЕНО В S3.4, И ИМЕННО КАК РЕШЕНИЕ, А НЕ КАК НАСЛЕДСТВО — тумбстоун S3.3 требовал
   решить заново, вот решение и довод.
   ЧТО ДЕЛАЕТ: на границе прохода гасит ЖИВЫЕ голоса руки ('lead:*') и живой бас, чтобы ещё зажатая
   рука ПЕРЕАТАКОВАЛА их с начала следующего прохода. Без этого удержанная нота тянулась бы сквозь шов
   одним непрерывным звуком, а записанный проход начинался бы с уже звучащей ноты — то есть на слух
   «повтор без начала». Для повторяемого участка переатака и есть верное поведение: каждый проход
   должен звучать одинаково, а значит и начинаться одинаково.
   ⛔ ЖИВОЙ АККОРД ('latch') НЕ ТРОГАЕМ — ПРАВИЛО #20. Защёлкнутый или удержанный аккорд принадлежит
   РУКЕ, а не повтору, и обязан пережить сколько угодно границ, пока игрок не отпустит пальцы или не
   сменит аккорд. Лид и бас так можно, а аккорд нельзя, и причина техническая: их зажатая рука
   переатакует со следующего кадра, а живой путь аккорда (WchSet→chordGlide) удалённые голоса НЕ
   ПЕРЕСОБИРАЕТ — погасив, мы бы его потеряли насовсем.
   ⚠️ ЛИД ГАСИМ ИЗБИРАТЕЛЬНО, только 'lead:*': в пуле голый обход снёс бы и переигранные соло-дорожки,
   у которых своя граница (её держит releaseLoopLayersAt).
   ⛳ СОЛО БОЛЬШЕ НЕ ПЛАТИТ (S3.5a-fix): во время записи вместо голого сброса — recFoldRoll, который
   закрывает удержанную ноту НАСТОЯЩИМ leadOff на конце прохода и поднимает базу номеров. Зажатая рука
   переатакует со следующего кадра и откроет НОВУЮ ноту с новым номером. Если кадр жестов успел
   раньше тика, шов уже обработан, и вызов здесь ничего не трогает — открытая нота нового прохода
   ОСТАЁТСЯ открытой (сброс здесь сделал бы её сиротой; поэтому recLeadReset — только вне записи).
   ⛳ БАС БОЛЬШЕ НЕ ПЛАТИТ (S3.5d-fix): здесь стояло «recBass=null без bassOff — удержанный через шов бас оставляет bassOn
   без пары». Починено тем же приёмом, что у соло: при записи бас закрывает recFoldRoll настоящим bassOff на конце прохода
   (см. последнюю строку функции ниже и сам recFoldRoll).
   ⛳ P2: живой бас гасим ПО ВСЕМ ЖИВЫМ ВЛАДЕЛЬЦАМ ('bass' и 'bass:…'), а не одним литералом 'bass': у полифонического баса
   (V2/V3) живых владельцев несколько, и нота второго иначе пережила бы шов. Ключи дорожек ('bassloop:…') не трогаем — у
   них своя граница (releaseLoopLayersAt). В ведущем режиме владелец один — прежнее поведение. */
const isLiveBassOwner=k=> k==='bass' || k.slice(0,5)==='bass:';
function liveWrapRelease(){ if(!AC)return;
  for(const k of Object.keys(leadHold)) if(k.slice(0,5)==='lead:') leadOff(k);
  for(const k of Object.keys(bassHold)) if(isLiveBassOwner(k)) bassOff(k);
  if(recording) recFoldRoll(); else { recLeadReset(); recBass.clear(); }   // S3.5d-fix: при записи бас закрывает recFoldRoll (как соло); голое обнуление здесь осиротило бы бас-ноту, уже открытую в НОВОМ проходе, если кадр жестов успел раньше тика
}
function schedClicks(){                                // щелчки метронома с опережением по AC-часам
  const spb=60/loop.bpm, ahead=AC.currentTime+SCHED_AHEAD;
  while(loop.t0+loop.clickBeat*spb<ahead){
    const bt=loop.t0+loop.clickBeat*spb, inCount=loop.cnt&&loop.clickBeat<loop.lead;   // S3.5b: отсчёт — щелчки ДО доли запуска (при старте с 0 это прежнее clickBeat<0)
    /* Просроченный щелчок (bt в прошлом — зависание ДЛИННЕЕ окна) НАМЕРЕННО пропускаем, а не играем
       поздно: поздний щелчок слышен как «флам»/спотыкание (хуже, чем разовый пропуск, который ухо
       достраивает). С окном 0.30с пропуски редки; слои же наоборот — просроченные играем (звучат
       поздно, но не рвут состояние аккорда/баса; деградация к прежнему поведению на огромных столах). */
    if(bt>=AC.currentTime-0.001&&(inCount||recording))
      metroClick(bt, beatLevel(loop.metre, (((loop.clickBeat%loop.metre)+loop.metre)%loop.metre)));   // акцент по ГРУППЕ, не только по началу такта
    loop.clickBeat++;
  }
}
/* ⛳ ТИК: ЛИНЕЙНЫЙ ПО УМОЛЧАНИЮ, С ЗАВОРОТОМ ОБЛАСТИ КАК ЧАСТНЫМ СЛУЧАЕМ (S3.4).
   S3.3 снял отсюда заворот и три его последствия; S3.4 вернул ровно их, переанкеренными на [from,to):
     (1) `fireNear(loop.pos, rgn.to)` — домести хвост прохода до его конца;
     (2) `liveWrapRelease()` — переатака удержанной руки с начала прохода (воскрешено, см. выше);
     (3) `fireNear(rgn.from-1e-9, p)` — и доиграй от начала прохода.
   Ветка `loop.first` НЕ вернулась и не вернётся: запись останавливают явно, это решение S3.3.
   ⛔ ПРИ ВЫКЛЮЧЕННОЙ ОБЛАСТИ songAt — тождество, `p<loop.pos` не наступает НИКОГДА, и остаётся ровно
   та единственная ветка `else`, что была в S3.3. Линейное поведение байт-в-байт. */
function tick(){
  if(!loop.on||!AC)return;
  schedClicks();
  scheduleLayers();                                   // СЛОИ — вперёд по явному времени (сэмпл-точно)
  const m=(AC.currentTime-loop.t0)*loop.bpm/60;       // МОНОТОННАЯ доля
  if(m<loop.lead)return;                              // отсчёт/разгон: только щелчки/планирование. ⚠️ lead, а не 0 (S3.5b): старт с доли 8 давал «отсчёт» по долям 4..8 ≥0 — с ним лид звучал в отсчёте, а бегунок стартовал с pos=8 при p=4 и тик принимал это за ЗАВОРОТ (гасил живые голоса и мёл хвост скобы). С доли 0 lead=0 — как было
  if(latchOpenAt!=null && recording) recLatchOpen();  // ⛳ первый тик ПОСЛЕ отсчёта: звучащая защёлка ложится в дубль с доли начала записи (см. recLatchOpen)
  const p=songAt(m);                                  // ПЕСЕННАЯ доля (при выключенной области — она же)
  const rep=cycling()?rgnReps(m):0;                   // A2b: номер прохода — для швов заморозки (fireNear/frzNearDone), та же формула, что у планировщика
  if(cycling() && p<loop.pos){                        // заворот области: позиция ушла назад — тот же тест, что был у петли. cycling() — явно (S3.5b): без повтора заворота нет по определению, и ложный «назад» (разгон после старта) не должен гасить живые голоса
    fireNear(loop.pos,loop.rgn.to,rep-1);             // хвост ПРОШЛОГО прохода
    liveWrapRelease();
    chasePlay(loop.rgn.from,undefined,true);          // S3.5c: соло, зажатое через начало скобы, — поднять ДО событий прохода (fireNear ниже), «сейчас», как и весь лид. Скоба с такта 1 — пусто и бесплатно
    fireNear(loop.rgn.from-1e-9,p,rep);
  }else fireNear(loop.pos,p,rep);                     // лид/дрон — «почти сейчас», интервал (pos, p]
  loop.pos=p;
  if(frozen.size) frzNearDone(rep,p);                 // A2/A2b: пройденные швы заморозки — снять отметки (вход: соло-голоса слоя отдать буферу; выход: отпустить разморожённую запись)
  /* ⛳ O-2: ЗАХВАТ — ЗДЕСЬ, И МЕСТО ВЫБРАНО, А НЕ СЛУЧИЛОСЬ. Три свойства даёт именно эта точка:
       • ОТСЧЁТ УЖЕ ОТСЕЯН — выше стоит `if(m<loop.lead)return`, тот же порог, по которому отказывает push:
         автоматика взятого не может начаться раньше его первой ноты;
       • ДОЛЯ ПЕСЕННАЯ (p=songAt(m)), а не монотонная, — значит под крутящейся скобой захват сворачивается
         в неё ровно как события (ту же путаницу двух долей полоса лупера однажды уже пережила);
       • ПЛАНИРОВАНИЕ УЖЕ ОТРАБОТАЛО (schedClicks/scheduleLayers в начале тика) — обход идёт ПОСЛЕ него и
         окна опережения не задевает (правило #15). */
  takeCapSample(p);
  /* ⛳ O-3: и ВЕДЁМ ЗАПИСАННУЮ АВТОМАТИЗАЦИЮ — из того же сердца, по той же ПЕСЕННОЙ доле и после того же
     отсчёта, что и захват. ⛔ ТОЛЬКО НЕ ВО ВРЕМЯ ЗАПИСИ: иначе захват (строкой выше) снял бы наши же
     величины как «сыгранные рукой», и автоматизация писала бы сама себя. Хозяин величины ровно один:
     пока пишем — рука, пока играем — запись. */
  if(!recording) fxPlayDrive(p);
  /* КОНЕЦ ПЕСНИ. Во время записи НЕ останавливаемся: игрок как раз дописывает материал за прежним
     концом. ⛔ И ПРИ ВКЛЮЧЁННОЙ ОБЛАСТИ не останавливаемся никогда — она затем и включена, чтобы
     играть по кругу; иначе транспорт вставал бы на первом же достижении конца песни. */
  if(!recording && !cycling() && m>=songLen) stopAtEnd();
}
/* Останов по достижении конца материала. ⛔ НЕ softAllOff: тот погасил бы и ЖИВЫЕ руки, а человек
   в этот момент может держать ноту — инструмент не обязан замолкать оттого, что кончилась запись.
   Гасим ровно голоса ДОРОЖЕК (у событий аранжировки нет выключений — см. releaseLoopLayersAt) и дрон. */
function stopAtEnd(){
  loop.on=false; clearPump(); fxPlayStop();   // O-3: транспорт встал — состав цепи снова человеческий
  releaseLoopLayersAt();
  frzStopAll();                              // F4: и замороженные источники — конец песни для них тот же
  droneOff();
  schedInvalidate();
  hooks.loop && hooks.loop(false);
}
/* from — АБСОЛЮТНАЯ доля, с которой начинаем. t0 считаем так, чтобы в момент начала (после отсчёта,
   если он есть) позиция была ровно `from`: t0 = сейчас + отсчёт − from·spb. */
function startTransport(countIn, from=0){
  clearPump();
  /* ⛳ ГЛАВНАЯ точка сброса: временнáя база прыгает (pos/sched/t0 переставляются ниже). Покрывает старт
     записи, снятие паузы и старт от аранжировки.
     ⚠️ ПЕРЕНЕСЕНА ДО переустановки опоры (S3.5b): schedInvalidate теперь зовёт rgnSync, а тот при идущем
     транспорте перепривязывает опору по ТЕКУЩИМ t0/sched. Вызов посреди переустановки (sched уже новый,
     t0 ещё старый) испортил бы sched. До неё — опора ещё целиком старая и согласованная, а всё, что
     перепривязка сдвинет, ниже всё равно перезапишется. Сброс курсоров от порядка не зависит. */
  schedInvalidate();
  const spb=60/loop.bpm;
  loop.on=true; loop.lead=from; loop.cnt=!!countIn; loop.pos=from-1e-9; loop.sched=from;   // −1e-9: интервал fireNear полуоткрыт слева, иначе событие ровно в `from` не сыграло бы; lead — до этой доли тик молчит (отсчёт/разгон 60мс)
  loop.t0=AC.currentTime+(countIn?loop.metre*spb:0.06)-from*spb;   // отсчёт — ОДИН такт (loop.metre долей), при любом размере (предсказуемое правило)
  loop.clickBeat=Math.floor(from)-(countIn?loop.metre:0);   // щелчки идут от той же доли; при отсчёте — на такт раньше
  /* S3.5c: вход НЕ с начала песни (▶ с паузы, запись со скобы, seekTo) — догнать открытые к `from` аккорды,
     бас и соло ПО ТОЧНОМУ времени начала игры (после отсчёта/разгона). С доли 0 — не зовём вовсе. */
  if(from>1e-9){ const T=loop.t0+from*spb; chasePlay(from,T,false); chasePlay(from,T,true); }
  /* ⛳ F4: СБРАСЫВАЕМ ВЗВЕДЕНИЕ, А НЕ СТАРТУЕМ ЗДЕСЬ. Узлы поставит планировщик — из своего цикла и
     своей формулой времени (правило #15): armedRep=null заставит его взвести их на ближайшем тике.
     ⛔ Стартовать источники прямо тут значило бы завести ВТОРОЙ путь таймирования рядом с первым. */
  /* A2b: evRun — кто владеет дорожкой в этом прогоне с пуска. Свежую пуск отдаёт буферу (догонялка выше её
     пропустила — голосов нет); устаревшую — событиям (догонялка её подняла), и если она станет свежей на
     ходу, шов ВХОДА погасит эти голоса. Копия списка — frzStopOne отпускает разморожённые на ходу записи. */
  for(const f of [...frozen.values()]){ frzStopOne(f, AC.currentTime); f.evRun=freezeState(f.layer)!=='fresh'; }
  pumpTimer=setInterval(tick,SCHED_TICK_MS);
  hooks.loop && hooks.loop(true);
}
/* ⛳ ПЕРЕМОТКА (S3.3). Минимальная и единственная форма: начало отсчёта времени пересчитывается из
   целевой доли, всё остальное (курсоры, планировщик) подхватывается через schedInvalidate.
   ⚠️ UI СКРАББИНГА В ЭТОМ СЛАЙСЕ НЕТ — возможность выставлена, а ездит по ней пока ровно один путь:
   «доиграли до конца → следующий пуск с начала» (см. onLoop). Полноценная перемотка мышью/пальцем
   придёт вместе с таймлайном редактора.
   ⛔ Во время ЗАПИСИ перемотка запрещена: она разорвала бы уже открытые ноты, у которых выключение
   ещё впереди (их закрывает recAllOff на явной остановке). */
function seekTo(beat){
  if(!AC||recording)return;
  const b=Math.max(0,beat);
  releaseLoopLayersAt();                                   // прыжок во времени — звучащие голоса дорожек к нему не относятся
  frzStopAll();                                            // F4: источник буфера одноразов — прыжок means новый узел, старый глушим
  if(loop.on) startTransport(false,b);                     // играем — перезапускаем насос с новой базой
  else { loop.pos=b-1e-9; loop.sched=b; loop.t0=AC.currentTime-b*60/loop.bpm; schedInvalidate(); }
}

/* Кнопка «● запись» — ТУМБЛЕР: ● начинает запись новой дорожки, ● заканчивает. Прежней развилки
   «пусто → первый круг / играет → овердаб» больше нет: в линейном рекордере это одно и то же действие,
   различается лишь номер дорожки и нужно ли поднимать транспорт. */
/* ⛳ ОСТАНОВКА ЗАПИСИ С ЗАКРЫТИЕМ ВСЕГО УДЕРЖАННОГО — ОДИН ПУТЬ НА ДВЕ КНОПКИ (S3.5d-fix): ● и ■.
   Ровно те четыре строки, что стояли в onRec: recAllOff (концы всему, что звучит под пальцами) СТРОГО ДО
   setRecording(false), затем сортировка (дописанный хвост → в тело) и сброс курсоров.
   ⚠️ ЧТО ● ДЕЛАЕТ СВЕРХ ЭТОГО И ЧЕГО ПАНИКА ДЕЛАТЬ НЕ ДОЛЖНА: зацепки обучения 'overdubStop'/'takeDone'. Паника —
   аварийный выход, а не «записал → услышал»; шаг урока от неё продвигаться не должен. Поэтому зацепки
   остались в onRec, а сюда вынесено только закрытие и остановка. */
function recStop(){ latchOpenAt=null; recAllOff(); setRecording(false); events.sort((x,y)=>x.t-y.t); schedInvalidate(); }   // sort переставил события, а дописанный хвост стал частью отсортированного тела → новая граница cursN
function onRec(){
  if(!AC)return;
  if(editIsOpen())return;   // S5.0: редактор открыт — записывать некуда и незачем (жесты заглушены). ОДИН отказ на все входы: кнопка ●, рука-лупер и всё, что появится позже
  /* ⛳ ОСТАНОВКА — ТЕПЕРЬ ЕДИНСТВЕННЫЙ СПОСОБ ЗАКОНЧИТЬ ЗАПИСЬ (прежде первая запись закрывалась САМА,
     по завершении круга). recAllOff — СТРОГО ДО setRecording(false) (см. его шапку): он закрывает в
     дорожке всё, что осталось звучать под пальцами. */
  if(recording){
    recStop();
    hooks.tutor && hooks.tutor('loop',{ev:'overdubStop'});   // ЗАЦЕПКА ОБУЧЕНИЯ: дорожка дописана — урок «Лупер», шаг наложения
    /* ⛔ ЗАЦЕПКА ОБУЧЕНИЯ, ПЕРЕНАПРАВЛЕННАЯ В ЭТОМ СЛАЙСЕ (правило #24). Прежде шаг «запиши круг»
       ждал события 'loopClosed', которое возникало ТОЛЬКО на завороте петли. Заворота нет — шаг стал
       бы непроходимым, а урок «Лупер» — тупиком. Событие переименовано в 'takeDone' («взятое стало
       дорожкой») и шлётся ОТСЮДА, с явной остановки. Смысл шага сохранён: записал → услышал. */
    hooks.tutor && hooks.tutor('loop',{ev:'takeDone'});
    return;
  }
  /* НАЧАЛО ЗАПИСИ. ⛔ `events.length=0` ОТСЮДА УБРАН: в линейном рекордере «начать запись» НИКОГДА не
     значит «стереть песню» — иначе ● после того, как воспроизведение доехало до конца, уничтожал бы
     всё записанное. Чистит только ✕.
     ⛳ МЕСТО РОЖДЕНИЯ ДОРОЖКИ (см. закон у laneNew): пустая песня → дорожка 0 и сброс настроек дорожек;
     иначе → maxLayer()+1. Номер МОГ УЖЕ ЖИТЬ (его освободила ⤺ отмена), поэтому laneNew обязателен. */
  const fresh=!events.length;
  /* ⛳ S3.5c: ВООРУЖЕНА живая дорожка → пишем В НЕЁ (слияние: её события остаются, новые дописываются рядом).
     laneNew здесь НЕ зовём: он выдал бы свежий id — дорожка потеряла бы свои mute/solo и само вооружение.
     Не вооружена (или id больше никуда не указывает) → новая дорожка, байт-в-байт как раньше. */
  const armLy= fresh ? null : armedLayer();
  if(armLy!=null) loop.layer=armLy;
  else {
    if(fresh){ laneReset(); loop.layer=0; } else loop.layer=maxLayer()+1;
    laneNew(loop.layer);
  }
  /* ⛳ S3.5a: номера соло-нот этого взятого — ВЫШЕ уже лежащих в целевом слое (см. freeSlot). СТРОГО ДО
     setRecording(true): push пишет только при recording, значит ни одна нота не успеет взять старую базу.
     Сегодня слой здесь всегда свежий → vBase=0. Сброс в recLeadReset НЕ нужен и был бы ОШИБКОЙ: база —
     свойство взятого (что лежало в слое ДО него), а не открытых нот; паника/граница повтора посреди
     взятого не меняют того, что лежало раньше. */
  takeSt.clear(); takeSrc.clear(); takeJoin(loop.layer);
  if(armLy!=null){ const k=laneSourceOf(armLy); if(k) takeSrc.set(armLy,k); }   // T2: вооружённая принимает ТОЛЬКО свой источник (сегодня — роль); прочие роли родят новые дорожки. Рождённая на ● — без роли, её займёт первое легшее «вкл»
  // T1: слой взятого вписан — его vBase/vTop, k и стражи (прежде одиночные vBase/takeK/…); СТРОГО ДО setRecording(true), как и было
  curTake=++takeSeq;   // S3.5c: суффикс аккорда/баса взятого; S3.5d: номер взятого (tk всех его событий)
  takeCapStart(curTake);   // O-2: снимок цепей на старте взятого. СТРОГО ПОСЛЕ выдачи curTake и ДО setRecording(true): дорожка автоматизации пишет только при recording и опирается на уже засеянную опору
  recLastT=-Infinity; recHiT=-Infinity;   // vTop/chLastT/bsLast — теперь в записи слоя, их выставил takeJoin   // S4.3: участок и живые ключи рождаются заново вместе со взятым. S3.5a-fix: взятое начинается без выданных номеров и без виденного времени — первый шов распознаётся по первому возврату времени
  setRecording(true); schedInvalidate();   // массив ещё не менялся, но с этого мига push начнёт дописывать ХВОСТ — фиксируем границу cursN здесь, а не «когда-нибудь»
  /* Транспорт стоял → поднимаем его С ОТСЧЁТОМ, от НАЧАЛА СКОБЫ (S3.5b). Нетронутая скоба начинается с 0 —
     запись идёт с начала песни, это заданное умолчание. ⚠️ СМЕНА ПОВЕДЕНИЯ, НАЗВАННАЯ: прежде запись
     стартовала с ТЕКУЩЕЙ позиции (у доигранной песни — с её конца, то есть дописывала ЗА записанным).
     Дописать за концом теперь — поставить скобу туда. rgn уже приведён к материалу schedInvalidate выше.
     Транспорт идёт → пишем поверх С ТЕКУЩЕГО места, без отсчёта и без прыжка: и то и другое сбило бы
     уже звучащее. */
  const wasOn=loop.on;
  if(!loop.on) startTransport(true, loop.rgn.from);
  latchOpenAt = wasOn ? curBeat() : songAt(loop.lead);   // доля начала записи: при идущем транспорте — миг ●, с места — доля запуска после отсчёта (там же, где push перестаёт отказывать). Звучащая защёлка откроется с неё на первом тике (recLatchOpen)
  hooks.tutor && hooks.tutor('loop',{ev: fresh?'recStart':'overdubStart'});   // ЗАЦЕПКА ОБУЧЕНИЯ: старт первой записи / новой дорожки поверх
}
/* Загрузить аранжировку (гармония+бас+ритм) как ОТДЕЛЬНЫЕ слои, замороженные в текущем
   ладу/септаккорде (§3.4). Слои снимаются undo сверху (сначала ритм).
   ⛳ S3.3 СНЯЛ ОТСЮДА ПРОВЕРКУ ДЛИНЫ. Было: на пустой петле длина петли БРАЛАСЬ у прогрессии
   (`loop.bars=arr.bars`), а на непустой аранжировка ОТВЕРГАЛАСЬ, если её длина не совпала с длиной
   петли. Оба правила существовали лишь потому, что у петли была ОДНА длина на всех и заворот обязан
   был приходиться на общую границу. У линейной песни общей длины нет — подложке не с чем совпадать,
   поэтому она просто КЛАДЁТСЯ и играет столько, сколько в ней тактов.
   ⚠️ Подложка ложится ОТ НАЧАЛА ПЕСНИ (t событий приходят из buildArrangement уже от нуля). Класть её
   от плейхеда — осмысленное желание, но это ВЫБОР МЕСТА, а не следствие линейного времени: отдельная
   работа вместе с таймлайном редактора (см. отчёт слайса). */
function loadArrangement(sel, jam=false){
  if(!AC)return false;
  /* drumKitIdx передаём ЯВНО: без него buildArrangement брал дефолт 0 и слои аранжировки всегда играли
     «Стандартом», какой бы кит ни был выбран — паттерны, писанные В РОЛЯХ ради кит-независимости, звучали
     одним китом. bars — ДЛИНА ПОДЛОЖКИ в тактах (loop.bars сменил смысл в S3.3): её берёт путь «только
     ударные», которому длину взять больше неоткуда. */
  const arr=buildArrangement(sel, {chIdx, bassIdx, drumKitIdx, metre:loop.metre, bars:loop.bars});
  if(!arr||!arr.layers.length)return false;
  const base=nextFreeLayer();   // T2: не maxLayer()+1 — посреди записи он не видит ещё пустых дорожек взятого (см. nextFreeLayer)
  /* ⛳ МЕСТО РОЖДЕНИЯ СЛОЯ №3 (и последнее): каждый слой аранжировки/подложки. Номер тем более мог
     быть занят — снятая подложка освобождает свои номера, а следующая берёт их же. */
  arr.layers.forEach((evs,li)=>{ const layer=base+li; laneLen.set(laneNew(layer), arr.bars*loop.metre); const tk=++takeSeq;   // длина материала слоя — все такты подложки (см. laneLen)   // S3.5d: каждый слой подложки — своё взятое → ⤺ снимает их по одному, сначала ритм (как прежде)
    takeCapStart(tk);   // O-2: у слоя подложки тоже своё взятое — значит и свой снимок цепей. Дорожки автоматизации у него не будет (его никто не играл руками), и это верно: у него нет движения, только настройки
    for(const e of evs){ const ev={t:e.t, layer, fn:e.fn, a:e.a, sc:CUR(), sev:seventh, tk};
      if(jam)ev.jam=true;                              // МЕТКА СЛОЯ ДЖЕМА: живёт В САМОМ событии → снять ровно джем, не тронув записи игрока (см. clearJam)
      events.push(ev); } });
  events.sort((x,y)=>x.t-y.t);
  schedInvalidate();                                   // добавили слои и пересортировали → курсоры недействительны (startTransport ниже сбросит ещё раз, если транспорт стоял — это дёшево и безвредно)
  /* ⛳ ПОДЛОЖКА КРУТИТСЯ САМА — КАК ДО S3.3 (починка при слайсе «дрон и центы»). До S3.3 подложка на пустой петле задавала длину петли
     (loop.bars=arr.bars), а петля заворачивала всегда — любая подложка играла по кругу без касаний. S3.3 убрал заворот, и с тех пор
     подложка проигрывалась ОДИН раз и вставала (дрон — сразу: его длина была 0). Возвращаем ровно это поведение средствами линейной
     песни: включаем ПОВТОР (⟳); скоба, следующая за материалом, на пустой песне равна тактам подложки (laneLen) — длина прежней петли.
     Скобу, поставленную человеком, не трогаем; ⟳ уже включён — тоже. ⛔ Во время записи — НЕ включаем: повтор поменял бы смысл
     записываемого (свёртка в скобу), а такого решения человек не принимал. */
  if(!recording && !cycling()){ setRegionOn(true); hooks.loop && hooks.loop(loop.on); }   // hooks.loop — ui обновит кнопку ⟳ (и при уже идущем транспорте, где startTransport ниже не зовётся)
  if(!loop.on)startTransport(false,0);                 // подложка лежит от начала песни — и играть её начинаем оттуда же
  if(droneAudible())droneOn();                         // включаем дрон сразу; ⚠️ именно AUDIBLE, а не ACTIVE: заглушённая дорожка дрона не должна зазвучать от добавления соседних слоёв
  if(jam) hooks.tutor && hooks.tutor('loop',{ev:'jam'});   // ЗАЦЕПКА ОБУЧЕНИЯ: джем реально встал (слои добавлены) — урок «Лупер»; только для джема, не для ручной аранжировки
  return true;                                         // добавили (джем-контроллер по этому знает, что вариант встал)
}
/* Джем — та же аранжировка-shortcut, но её слои ПОМЕЧЕНЫ (e.jam). loadJam кладёт помеченные,
   clearJam снимает РОВНО их. Записи игрока (push никогда не ставит jam) неуязвимы по построению. */
const loadJam=sel=>loadArrangement(sel, true);
function clearJam(){
  if(!events.length)return;
  const removed=compactEvents(e=>e.jam);               // ОДИН проход вместо splice-в-цикле (см. compactEvents)
  if(!removed)return;
  /* S3.5d-fix: при записи — ЗАКРЫТЬ удержанное ДО softAllOff: тот обнуляет состояние записи БЕЗ концов, и ноты взятого
     остались бы с «вкл» без «выкл». Рука, что держит, переатакует со следующего кадра новой нотой. Сортировка — чтобы
     schedInvalidate не объявил несортированный хвост телом (та же причина, что в undo/удалении). */
  if(recording){ recAllOff(); events.sort((x,y)=>x.t-y.t); }
  schedInvalidate();                                   // состав событий изменился → курсоры недействительны
  lanePrune();                                         // у слоёв подложки больше нет событий → снимаем их настройки, чтобы не всплыли на следующем джеме с теми же номерами
  softAllOff(); if(!droneActive())droneOff();          // бухгалтерия как в onUndo: гасим зависшее, ушёл слой-дрон → гасим дрон
  if(!events.length)clearRec(); else hooks.loop&&hooks.loop(loop.on);   // пусто → полный сброс; остались записи игрока → петля играет дальше
}
/* ⟳ — ИГРАТЬ / ПАУЗА. Позиция при паузе СОХРАНЯЕТСЯ, пуск продолжает с неё; если плейхед стоит на
   конце песни (её доиграли или остановили в самом конце) — пуск ПЕРЕМАТЫВАЕТ в начало, потому что
   «играть» в конце значит «сыграй ещё раз с начала», а не «стой на месте».
   ⛳ ЭТО И ЕСТЬ ТОТ ЕДИНСТВЕННЫЙ ПУТЬ, ПО КОТОРОМУ ЕЗДИТ ПЕРЕМОТКА (seekTo) в этом слайсе — отдельного
   органа управления для неё пока нет и заводить его здесь не стали (см. отчёт). */
function onLoop(){
  if(!AC)return;
  if(loop.on){
    /* ⛳ ПАУЗА ТЕПЕРЬ ЗАКРЫВАЕТ ОТКРЫТЫЕ НОТЫ (долг слайса S3.1). Тогда это было НЕВОЗМОЖНО сделать
       правильно: время сворачивалось в петлю, и «конец» удержанной ноты было некуда записать. Со
       сквозным временем у него есть честное место — текущая доля, — поэтому recAllOff здесь уместен
       ровно так же, как на остановке записи. ⛔ СТРОГО ДО setRecording(false) и ДО softAllOff:
       первый гасит запись, второй ВЫБРАСЫВАЕТ состояние открытых нот, не записав их. */
    recAllOff();
    loop.on=false; clearPump(); fxPlayStop(); softAllOff(); droneOff(); setRecording(false);   // O-3: fxPlayStop рядом с clearPump — где встал транспорт, там кончилась и власть записи над ручками
    events.sort((x,y)=>x.t-y.t); schedInvalidate();    // могли дописать выключения → порядок восстановить, курсоры сбросить
    hooks.rec&&hooks.rec(false); hooks.loop&&hooks.loop(false);
  }
  else if(events.length){
    const R=loop.rgn;
    const from = cycling()&&loop.pos>=R.to ? R.from          // повтор включён, а пауза оказалась за концом скобы (край двигали на паузе) → с начала скобы, как сделал бы шов
               : loop.pos>=songLen ? 0 : Math.max(0,loop.pos);   // доиграли до конца → следующий пуск с начала
    startTransport(false,from);
    if(droneAudible())droneOn();                      // ⚠️ AUDIBLE: снятие паузы не должно воскрешать заглушённую дорожку дрона
  }
}
/* ⛳ ⤺ СНИМАЕТ ПОСЛЕДНЕЕ ВЗЯТОЕ (S3.5d), а не слой с наибольшим номером.
   Взятое в НОВУЮ дорожку — уходит вся дорожка, как прежде (без влитых взятых и удалений «наибольший слой» и
   «последнее взятое» — одно и то же: новая дорожка всегда получала maxLayer()+1). Взятое, ВЛИТОЕ в старую
   дорожку, — уходят только его события, дорожка сохраняет прежний материал (lanePrune её не тронет: события
   в слое остались). Повторяемо: каждое нажатие берёт наибольший из ОСТАВШИХСЯ tk.
   Подсказки на экране не нужно: снимается ровно то, что записали последним.
   Всё, что взятое породило, уходит вместе с его событиями: a.k и a.v выводятся из лежащего в слое на
   следующем ●, отдельного состояния у них нет; голоса гасит softAllOff; курсоры/догонялку/длину —
   schedInvalidate. После УДАЛЕНИЯ дорожки с её строки ⤺ снимает последнее из УЦЕЛЕВШИХ взятых: удаление
   в истории не лежит, ничего не воскрешается и ни на что пропавшее не указывает.
   Подложка/джем: каждый их слой — своё взятое (loadArrangement), поэтому ⤺ снимает их послойно, как и
   раньше; clearJam по-прежнему снимает РОВНО помеченное ev.jam, номера взятых ему не нужны. */
function onUndo(){
  if(!events.length)return;
  let top=-Infinity; for(const e of events){ const k=e.tk||0; if(k>top) top=k; }
  /* S3.5d-fix: при записи снимается НЕ текущее взятое (например, слой подложки, положенной посреди записи) — закрыть
     удержанное ДО softAllOff, иначе его «вкл» останутся без «выкл». Если снимается само текущее взятое, закрывать нечего:
     его «вкл» уходят вместе с ним. top посчитан ДО закрытия, поэтому новые «выкл» (tk текущего) его не сдвигают.
     ⚠️ S4.1: ВТОРАЯ ВЕТКА ТЕПЕРЬ ОБЯЗАТЕЛЬНА. Прежде «закрывать нечего» обеспечивал сам softAllOff — он молча выбрасывал
     состояние. Теперь он при записи ЗАКРЫВАЕТ, и для снятого текущего взятого написал бы «выкл» без «вкл» — сирот. Поэтому
     здесь, ДО него, состояние выбрасываем явно: это не вторая политика, а случай, где «вкл» в песне уже нет. */
  if(recording){ if(top!==curTake) recAllOff(); else recDrop(); }
  if(recording) events.sort((x,y)=>x.t-y.t);            // хвост взятого — в отсортированный префикс ДО schedInvalidate
  compactEvents(e=>(e.tk||0)===top);                    // ОДИН проход вместо splice-в-цикле (см. compactEvents)
  schedInvalidate();                                    // состав событий изменился → курсоры недействительны
  lanePrune();                                          // снятая дорожка не должна оставить своё заглушение следующей записи на том же номере
  softAllOff(); if(!droneActive())droneOff();           // сняли слой-дрон → гасим (softAllOff дрон не трогает)
  if(!events.length)clearRec(); else hooks.loop && hooks.loop(loop.on);
  hooks.tutor && hooks.tutor('loop',{ev:'undo'});       // ЗАЦЕПКА ОБУЧЕНИЯ: снят верхний слой — урок «Лупер» (дошли только при непустой петле — ранний выход выше)
}
/* ⛳ КОНТРОЛ «ТАКТЫ» ПЕРЕЖИЛ СМЕНУ МОДЕЛИ, НО СМЕНИЛ РАБОТУ (S3.3, решение по пункту 8).
   Он задавал ДЛИНУ ПЕТЛИ — величину, которой больше не существует: длина песни выводится из материала
   (songLen). Убрать контрол было можно, но тогда у пути «🎵 только ударные» не осталось бы ИСТОЧНИКА
   ДЛИНЫ: там нет прогрессии, и сколько тактов класть, знать неоткуда (см. buildArrangement).
   Поэтому он стал «ДЛИНА ПОДЛОЖКИ» — сколько тактов занимает ДОБАВЛЯЕМАЯ аранжировка. Это настоящая
   работа, видимая сразу: поставил 4 — следующая подложка легла на 4 такта.
   ⛔ И ПОЭТОМУ ЖЕ СНЯТА БЛОКИРОВКА «только на пустой петле»: она защищала времена уже записанных
   событий от переосмысления длиной петли. Длина подложки ничего записанного не трогает — она влияет
   ТОЛЬКО на следующую подложку, значит менять её можно когда угодно.
   ⚠️ Потолок 8 оставлен как есть: это не остаток петли, а разумный предел длины подложки. */
function setLoopBars(n){
  loop.bars=Math.max(1,Math.min(8,n));
}
const METRES=[2,3,4,5,6,7,8,9,10,12,16];               // допустимые размеры (долей в такте) — см. UI
/* Размер такта меняется ТОЛЬКО на пустой песне, и это ОСТАЛОСЬ. Причина у него СВОЯ, не та, что была у
   длины: размер задаёт сетку тактов и акценты метронома, по которым человек играл, — сменить его под
   уже записанным значило бы переосмыслить долевую сетку под нотами, оставив ноты на месте. */
function setLoopMetre(n){
  if(events.length||loop.on)return;
  loop.metre = METRES.includes(+n) ? +n : loop.metre;
}
function setLoopQuant(v){ loop.quant=!!v; }             // общий тумблер квантизации. S4.3: НЕ запрещён во время записи — действует со СЛЕДУЮЩЕЙ ноты (открытые доигрывают по своему правилу, см. recChOn), звука не касается
const SUBS=[4,3];                                       // дробление доли для квантизации ударных: 4 = 16-е, 3 = триоли
function setLoopSub(n){                                 // МОЖНО менять когда угодно: это настройка ЗАПИСИ, а не геометрия петли (в отличие от bars/metre)
  loop.sub = SUBS.includes(+n) ? +n : loop.sub;
}
/* ⛳ СМЕНА ТЕМПА ТЕПЕРЬ ПЕРЕСЧИТЫВАЕТ НАЧАЛО ОТСЧЁТА, ЧТОБЫ ПЛЕЙХЕД ОСТАЛСЯ НА МЕСТЕ (S3.3, пункт 5).
   Доля считается как (now−t0)·bpm/60. Прежде t0 не трогали, поэтому смена bpm меняла ТЕКУЩУЮ ДОЛЮ
   разрывно: при 84→168 позиция мгновенно УДВАИВАЛАСЬ. В петле на 2 такта это было незаметно (прыжок
   внутри восьми долей, и заворот всё равно рядом), а в пятиминутной песне то же самое отшвыривает
   плейхед на минуты — «покрутил темп и потерял место». Держим долю: подбираем t0 так, чтобы при НОВОМ
   темпе она осталась прежней.
   ⚠️ ЭТО НАМЕРЕННОЕ ИЗМЕНЕНИЕ ПОВЕДЕНИЯ, а не побочный эффект: раньше прыгало, теперь нет.
   ⚠️ loop.sched и loop.pos — В ДОЛЯХ, поэтому пересчитывать их не нужно: они и есть то, что мы
   сохраняем. Перепланировать, однако, надо (уже поставленные события расписаны по СТАРОМУ spb) —
   это делает schedInvalidate вместе со сбросом курсоров. */
function setLoopBpm(v){
  const nb=Math.max(40,Math.min(240,+v||loop.bpm));
  if(AC&&loop.on){
    const b=(AC.currentTime-loop.t0)*loop.bpm/60;      // доля СЕЙЧАС, по старому темпу
    loop.t0=AC.currentTime-b*60/nb;                    // …она же по новому
    loop.sched=Math.max(loop.sched,b);                 // окно опережения расписано старым темпом — не планируем прошлое заново
  }
  loop.bpm=nb; schedInvalidate();
}
function clearRec(){
  clearPump(); loop.on=false; fxPlayStop(); events.length=0; loop.rgn.user=false; rgnApply(0,loop.metre,false); schedInvalidate(); laneReset(); setRecording(false); softAllOff(); droneOff();   // S3.5b: loop.on=false ПЕРЕД rgnApply — остановленному транспорту перепривязывать нечего; скоба — снова «следует», повтор выключен (user — не часть временнóй карты, поэтому пишется напрямую)   // ✕ — песни больше нет, значит нет ни дорожек, ни области повтора: помеченный участок пустой песни был бы ложью на экране
  hooks.loop && hooks.loop(false);
}
/* ⚠️ panic НАМЕРЕННО НЕ ТРОГАЕТ настройки дорожек: события переживают панику, значит переживают и
   дорожки. «■» — это «замолчи сейчас», а не «забудь, что я намикшировал».
   ⛳ ТРИ ОСТАНОВКИ — ОДНО ПРАВИЛО (S3.5c):
     ⏸ ПАУЗА  — ДЕРЖИТ позицию (onLoop): в этом весь её смысл.
     ■ ПАНИКА — СБРАСЫВАЕТ: всё глушит, бегунок — на НАЧАЛО СКОБЫ; следующий ▶ играет материал скобы с начала.
                Песню, скобу, mute/solo и вооружение — сохраняет: она глушит и перематывает, а не забывает.
     ✕ ОЧИСТКА — всё в ноль, скоба включительно (clearRec).
   Раньше паника позицию не трогала — ▶ продолжал с места, где её нажали, то есть вела себя как пауза.
   ⛔ ПАНИКА НЕ ИЗОБРЕТАЕТ СОБЫТИЙ: она не добавляет в запись ничего, чего человек не сыграл. Во время записи она
   сперва ОСТАНАВЛИВАЕТ ЗАПИСЬ ОБЫЧНЫМ ПУТЁМ ● (recStop): удержанное получает концы на доле нажатия — это честная
   запись того, что было сыграно до этого мига, тем же проверенным кодом, что у ●, а не второй закрывающий обход.
   ⚠️ СОРТИРОВКА — НЕ ЗАПИСЬ, но она обязательна при записи: schedInvalidate объявляет весь массив
   отсортированным префиксом, а дописанный хвост взятого не отсортирован. Прежде паника во время записи
   этого не делала — курсоры потом бинарным поиском шли по несортированному и теряли события.
   КУРСОРЫ и КЭШ ДОГОНЯЛКИ производны от точки входа — их сбрасывает schedInvalidate здесь, а следующий
   запуск (startTransport с доли начала скобы) ставит их заново и догоняет аккорды/бас оттуда. */
/* ⛳ S3.5d-fix: ПОРЯДОК — 1) закрыть и остановить запись, 2) остановить транспорт, 3) тишина, 4) перемотка.
   (1) ПЕРВЫМ, пока транспорт ещё идёт: концы ложатся на песенную долю НАЖАТИЯ, а recLeadOff/recBassOff при этом ещё
       успевают распознать шов прохода (recFoldRoll) — обе вещи опираются на живую опору t0. recStop — только ЗАПИСЬ
       событий в массив, звука он не издаёт.
   (2) ДО тишины: clearPump снимает насос, loop.on=false — после этого ни scheduleLayers, ни fireNear больше не
       позовутся, то есть ни одна нота дорожки не может быть поставлена ПОСЛЕ шага (3).
   (3) softAllOff гасит всех владельцев — живых и дорожечных, в т.ч. уже поставленные вперёд аккорд/бас (их hold уже
       заведён, и chordOff/bassOff снимают назначенную атаку). droneOff — уровень дрона.
       ⚠️ Честная принятая цена, как у стопа/заглушения: УДАРЫ, уже поставленные в окно SCHED_AHEAD (~300мс), —
       одноразовые осцилляторы, отменить их нечем; они доиграют.
   (4) Перемотка на начало скобы — последней: к ней уже нечего привязывать.
   Прежний вариант S3.5d (выбрасывать незакрытое) снят: защёлкнутая прогрессия без переатак — одна незакрытая нота,
   и паника стирала её целиком. Вне записи паника дословно прежняя. */
function panic(){
  if(recording) recStop();                         // (1) ТОТ ЖЕ путь, что ●, без зацепок обучения
  clearPump(); loop.on=false; fxPlayStop(); schedInvalidate();   // (2) события целы, транспорт остановлен — возобновят его с новой базой; O-3: и живая цепь возвращается человеку
  softAllOff(); droneOff();                        // (3)
  setRecording(false);
  loop.pos=loop.rgn.from;                          // (4) S3.5c: на начало скобы (rgn уже приведён к материалу schedInvalidate выше); onLoop стартует ровно отсюда
  hooks.loop && hooks.loop(false);
}

/* Экспорт: `recording` через export-клаузу — живая связка (её читает draw). */
export {
  WleadOn, WleadOff, WchOn, WchSet, WchOff, WbassOn, WbassOff, WdrumHit,
  softAllOff, panic, inPB, recording,
  onRec, onLoop, onUndo, clearRec, setLoopBars, setLoopMetre, METRES, setLoopSub, SUBS, beatLevel, setLoopQuant, setLoopBpm, loop, events, loopPos,
  songBeats, seekTo,   // S3.3: длина песни в долях (её читает полоса лупера, чтобы вписать таймлайн) и перемотка (пока по ней ездит только «пуск с конца → с начала»)
  setRegionOn, regionOn, cycling, braceTap, braceMove,   // S3.5b: ⟳ только вкл/выкл повтора; скобу двигает тап/перетаскивание (ui), границы и user draw читает из loop.rgn
  loadArrangement, loadJam, clearJam, loopChordDeg, loopChordOct,
  toggleLaneMute, toggleLaneSolo, laneMuted, laneSoloed, laneSoloOn, toggleArm, armedLayer, laneDelTap, laneDelCancel, laneDelPendingLayer,   // дорожки (S1): ПИШЕТ ui (тап по полосе), ЧИТАЕТ draw (вид строки). Адрес — НОМЕР СЛОЯ, id остаётся внутри
  songNotes,      // S4.0: события, собранные в НОТЫ (только чтение) — по ним рисует пиано-ролл
  editOpen, editClose, editIsOpen, editLayer, editSetLayer,   // S5.0: редактор дорожки — ОДИН флаг на все отказы; наружу отдаём НОМЕР СЛОЯ, id остаётся здесь (правило #27)
  editMoveHit, editDeleteHit, editInsertHit, editUndo, editRedo, editCanUndo, editCanRedo, editBackingOpen,   // S5.1/S5.3: правка ударов, отмена и ВОЗВРАТ ПРАВОК (не путать с ⤺ — та снимает взятое)
  songSegs, editMoveSeg, editDeleteSeg, editInsertBass, editResizeSeg,   // S5.5/S5.6: СЕГМЕНТЫ (высота держится до следующей смены), правка баса по ним и ДЛИНА
  editInsertChord,
  editDeleteChordNote, editMoveChordNote, editResizeChordNote,   // U2/U3: правка ОДНОЙ ноты аккорда (удаление, перенос во времени, длина) — аккорд распадается на однонотные (dissolvePlan)
  fxIsDriven,      // O-3.1: правит ли этим адресом запись ПРЯМО СЕЙЧАС — читают столбики, чтобы пометить чужое
  autAddrs, autPoints, autMovePoint, autDeletePoint, autAddPoint, autShapePoint,   // autShapePoint — гладкая автоматизация: форма отрезка, входящего в точку   // O-4 часть 1: ПОЛОСА АВТОМАТИЗАЦИИ — что показать, что нарисовать и три правки
  autChainOf, autChainAdd, autChainRemove, autChainMove,   // O-4 часть 2: цепь САМОЙ ДОРОЖКИ (живая цепь не трогается — см. шапку). ⚠️ fxAddableIds отсюда НЕ реэкспортируем: меню берёт его прямо у audio, где он и объявлен
  laneTimbreOf, editSetTimbre,   // T5: тембр дорожки (индекс тембра роли / набора ударных) и его ЗАМЕНА — одна правка истории
  laneRoleOf, laneLenOf,   // laneLenOf — конец материала слоя подложки (render: длина буфера заморозки).  T4: РОЛЬ ДОРОЖКИ (одна с T2) или null — редактор открывается на ней, а вкладок ролей больше нет
  captureInfoOf,   // O-2: СВОДКА захвата дорожки — единственный сегодняшний читатель реестра (показ в редакторе). Сам реестр наружу не отдаём: его пока некому исполнять
  /* F3 — ОФЛАЙН-РЕНДЕР: та же таблица диспетчеризации против ЧУЖОЙ копии движка · то же слияние ленты автоматизации (⛔ второго не
     писать) · роль события (чья это цепь эффектов) · fxLaneExpand — плавные отрезки ленты, развёрнутые в точки шагом тика (рендер и
     ухо-проба R.live) · КЛЮЧИ ВЛАДЕЛЬЦЕВ ldKey/chOwnerKey/bassOwnerKey — render.trackOpen помнит по ним незакрытые голоса (формулы
     ОДНИ — здесь; вторая копия в рендере разошлась бы с переигровкой).
     ⚠️ ПОЧИНКА: гладкая автоматизация дописала fxLaneExpand и свой комментарий ПОСЕРЕДИНЕ этой строки — три ключа владельцев
     оказались ЗА `//`, то есть перестали экспортироваться, и заморозка любой дорожки с соло/аккордами/басом падала
     («REC.bassOwnerKey is not a function»). Рендер грузится лениво, поэтому поломка видна лишь на ❄. Комментарии в этом
     списке — ОТДЕЛЬНЫМИ строками или блоком над именами, не в хвосте строки, куда допишут следующее имя. */
  makeENG, fxLaneMerge, fxLaneExpand, evRole, FX_CHAIN,
  ldKey, chOwnerKey, bassOwnerKey,
  /* Записанная автоматизация «плавная внутри движения»: переключатель для уха (render.recSteps / aud({recSteps})). В интерфейсе его нет. */
  setAutRecSmooth,
  frzGlobalKey,   // A1 (автозаморозка): дешёвый ГЛОБАЛЬНЫЙ сигнал «могла смениться подпись хоть одной дорожки» — для наблюдателя A3/A4. Чистое чтение; сегодня вызывающих нет
  recLayers, isRecLayer,   // T1: СЛОИ ВЗЯТОГО — полоса и заголовок читают их вместо одиночного loop.layer (в T1 слой один)
  freezeTicket,   // A2: БИЛЕТ заморозки (слой + id дорожки + подпись), снятый ДО рендера; freezeSet ставит буфер только если билет ещё верен
  freezeSet, unfreezeLayer, frozenLayers, frozenInfo, freezeState, frzHas, freezePinCaptures,   // F4/F5: ЗАМОРОЗКА как РЕЖИМ ВОСПРОИЗВЕДЕНИЯ; freezeState — 'none'|'fresh'|'stale' для показа (звук гатится тем же предикатом внутри)
  frzLayer,   // F4: ЗАМОРОЗКА как РЕЖИМ ВОСПРОИЗВЕДЕНИЯ. События не выбрасываются: пока буфер есть, транспорт играет ЕГО вместо событий дорожки. Зовут пока только из консоли (render.js), кнопки в этом слайсе нет
  droneAudible,   // «есть ли СЛЫШИМЫЙ слой-дрон» — снаружи сегодня никем не читается (ui перестраивает дрон droneRetune'ом без уровня, слайс «дрон и центы»); оставлен для консоли и рендера
};
